package main

import (
	"math"
	"strconv"
	"strings"
)

type MT int

const (
	MT_PENDING MT = iota
	MT_ERROR
	MT_ABSENT
	MT_MAP
	MT_ARRAY
	MT_INT
	MT_FLOAT
	MT_BOOLEAN
	MT_VOID
	MT_STRING
	MT_FUNC
)

type Mlrval struct {
	mtype    MT
	printrep string
	prValid  bool
	intval   int64
	floatval float64
	mapval   *Mlrmap
	arrayval []*Mlrval
	funcval  interface{}
	errmsg   string
}

// Inference flags
var inferNone = false
var inferIntAsFloat = false
var inferOctal = false

var ABSENT = &Mlrval{mtype: MT_ABSENT, printrep: "(absent)", prValid: true}
var VOID = &Mlrval{mtype: MT_VOID, printrep: "", prValid: true}
var TRUE = &Mlrval{mtype: MT_BOOLEAN, printrep: "true", prValid: true, intval: 1}
var FALSE = &Mlrval{mtype: MT_BOOLEAN, printrep: "false", prValid: true, intval: 0}

func ERROR() *Mlrval {
	return &Mlrval{mtype: MT_ERROR, printrep: "(error)", prValid: true}
}

func ERRORMSG(msg string) *Mlrval {
	return &Mlrval{mtype: MT_ERROR, printrep: "(error)", prValid: true, errmsg: msg}
}

func MlrvalFromInferred(s string) *Mlrval {
	if s == "" {
		return VOID
	}
	return &Mlrval{mtype: MT_PENDING, printrep: s, prValid: true}
}

func MlrvalFromString(s string) *Mlrval {
	if s == "" {
		return VOID
	}
	return &Mlrval{mtype: MT_STRING, printrep: s, prValid: true}
}

func MlrvalFromInt(i int64) *Mlrval {
	return &Mlrval{mtype: MT_INT, intval: i}
}

func MlrvalFromFloat(f float64) *Mlrval {
	return &Mlrval{mtype: MT_FLOAT, floatval: f}
}

func MlrvalFromBool(b bool) *Mlrval {
	if b {
		return TRUE
	}
	return FALSE
}

func MlrvalFromMap(m *Mlrmap) *Mlrval {
	return &Mlrval{mtype: MT_MAP, mapval: m}
}

func MlrvalFromArray(a []*Mlrval) *Mlrval {
	if a == nil {
		a = make([]*Mlrval, 0)
	}
	return &Mlrval{mtype: MT_ARRAY, arrayval: a}
}

func MlrvalEmptyMap() *Mlrval {
	return &Mlrval{mtype: MT_MAP, mapval: NewMlrmap()}
}

// Int literal from DSL / or from-data with original string
func MlrvalIntWithString(i int64, s string) *Mlrval {
	return &Mlrval{mtype: MT_INT, intval: i, printrep: s, prValid: true}
}
func MlrvalFloatWithString(f float64, s string) *Mlrval {
	return &Mlrval{mtype: MT_FLOAT, floatval: f, printrep: s, prValid: true}
}

func (mv *Mlrval) infer() {
	if mv.mtype != MT_PENDING {
		return
	}
	s := mv.printrep
	if inferNone {
		mv.mtype = MT_STRING
		return
	}
	t, i, f := scanNumber(s, inferOctal)
	switch t {
	case MT_INT:
		if inferIntAsFloat {
			mv.mtype = MT_FLOAT
			mv.floatval = float64(i)
		} else {
			mv.mtype = MT_INT
			mv.intval = i
		}
	case MT_FLOAT:
		mv.mtype = MT_FLOAT
		mv.floatval = f
	default:
		mv.mtype = MT_STRING
	}
}

func isDecDigit(c byte) bool { return c >= '0' && c <= '9' }
func isHexDigit(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

// scanNumber: data-inference of numbers.
func scanNumber(s string, octal bool) (MT, int64, float64) {
	n := len(s)
	if n == 0 {
		return MT_STRING, 0, 0
	}
	c0 := s[0]
	if !(isDecDigit(c0) || c0 == '-' || c0 == '+' || c0 == '.') {
		return MT_STRING, 0, 0
	}
	neg := false
	body := s
	if c0 == '-' || c0 == '+' {
		neg = c0 == '-'
		body = s[1:]
	}
	if len(body) == 0 {
		return MT_STRING, 0, 0
	}
	// Prefixed ints
	if len(body) >= 2 && body[0] == '0' {
		p := body[1]
		var base int
		switch p {
		case 'x', 'X':
			base = 16
		case 'b', 'B':
			base = 2
		case 'o', 'O':
			base = 8
		}
		if base != 0 {
			digits := body[2:]
			if len(digits) == 0 {
				return MT_STRING, 0, 0
			}
			u, err := strconv.ParseUint(digits, base, 64)
			if err != nil {
				return MT_STRING, 0, 0
			}
			i := int64(u)
			if neg {
				i = -i
			}
			return MT_INT, i, 0
		}
	}
	// all decimal digits?
	allDigits := true
	for i := 0; i < len(body); i++ {
		if !isDecDigit(body[i]) {
			allDigits = false
			break
		}
	}
	if allDigits {
		if len(body) > 1 && body[0] == '0' {
			if !octal {
				return MT_STRING, 0, 0
			}
			// octal
			u, err := strconv.ParseUint(body[1:], 8, 64)
			if err != nil {
				f, err2 := strconv.ParseFloat(s, 64)
				if err2 != nil {
					return MT_STRING, 0, 0
				}
				return MT_FLOAT, 0, f
			}
			i := int64(u)
			if neg {
				i = -i
			}
			return MT_INT, i, 0
		}
		i, err := strconv.ParseInt(s, 10, 64)
		if err != nil {
			return MT_STRING, 0, 0
		}
		return MT_INT, i, 0
	}
	// float syntax
	if !isFloatSyntax(body) {
		return MT_STRING, 0, 0
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return MT_STRING, 0, 0
	}
	return MT_FLOAT, 0, f
}

func isFloatSyntax(b string) bool {
	i := 0
	n := len(b)
	nd := 0
	for i < n && isDecDigit(b[i]) {
		i++
		nd++
	}
	if i < n && b[i] == '.' {
		i++
		for i < n && isDecDigit(b[i]) {
			i++
			nd++
		}
	}
	if nd == 0 {
		return false
	}
	if i < n && (b[i] == 'e' || b[i] == 'E') {
		i++
		if i < n && (b[i] == '+' || b[i] == '-') {
			i++
		}
		ne := 0
		for i < n && isDecDigit(b[i]) {
			i++
			ne++
		}
		if ne == 0 {
			return false
		}
	}
	return i == n
}

func (mv *Mlrval) Type() MT {
	if mv.mtype == MT_PENDING {
		mv.infer()
	}
	return mv.mtype
}

func (mv *Mlrval) IsAbsent() bool  { return mv.mtype == MT_ABSENT }
func (mv *Mlrval) IsError() bool   { return mv.mtype == MT_ERROR }
func (mv *Mlrval) IsVoid() bool    { return mv.Type() == MT_VOID }
func (mv *Mlrval) IsMap() bool     { return mv.mtype == MT_MAP }
func (mv *Mlrval) IsArray() bool   { return mv.mtype == MT_ARRAY }
func (mv *Mlrval) IsInt() bool     { return mv.Type() == MT_INT }
func (mv *Mlrval) IsFloat() bool   { return mv.Type() == MT_FLOAT }
func (mv *Mlrval) IsBool() bool    { return mv.mtype == MT_BOOLEAN }
func (mv *Mlrval) IsString() bool  { return mv.Type() == MT_STRING }
func (mv *Mlrval) IsFunc() bool    { return mv.mtype == MT_FUNC }
func (mv *Mlrval) IsNumeric() bool { t := mv.Type(); return t == MT_INT || t == MT_FLOAT }
func (mv *Mlrval) IsStringOrVoid() bool {
	t := mv.Type()
	return t == MT_STRING || t == MT_VOID
}
func (mv *Mlrval) IsCollection() bool { return mv.mtype == MT_MAP || mv.mtype == MT_ARRAY }
func (mv *Mlrval) IsEmptyOrAbsent() bool {
	t := mv.Type()
	return t == MT_VOID || t == MT_ABSENT
}

func (mv *Mlrval) IsTrue() bool {
	return mv.mtype == MT_BOOLEAN && mv.intval != 0
}

func (mv *Mlrval) GetNumericToFloat() float64 {
	switch mv.Type() {
	case MT_INT:
		return float64(mv.intval)
	case MT_FLOAT:
		return mv.floatval
	}
	return 0
}

// Output float formatting
var ofmtGlobal = ""

func formatFloat(f float64) string {
	return strconv.FormatFloat(f, 'f', -1, 64)
}

func (mv *Mlrval) String() string {
	if mv.prValid {
		return mv.printrep
	}
	switch mv.mtype {
	case MT_INT:
		mv.printrep = strconv.FormatInt(mv.intval, 10)
		mv.prValid = true
	case MT_FLOAT:
		mv.printrep = formatFloat(mv.floatval)
		mv.prValid = true
	case MT_BOOLEAN:
		if mv.intval != 0 {
			return "true"
		}
		return "false"
	case MT_MAP, MT_ARRAY:
		return mv.JSONMultiline()
	case MT_FUNC:
		return "(function-literal)"
	case MT_ERROR:
		return "(error)"
	case MT_ABSENT:
		return "(absent)"
	}
	return mv.printrep
}

// For output: apply ofmt to floats.
func (mv *Mlrval) OutputString() string {
	if ofmtGlobal != "" && mv.Type() == MT_FLOAT {
		return formatWithOfmt(mv.floatval, ofmtGlobal)
	}
	return mv.String()
}

func formatWithOfmt(f float64, ofmt string) string {
	fm := GetFormatter(ofmt)
	return fm.FormatFloat(f)
}

func (mv *Mlrval) Copy() *Mlrval {
	switch mv.mtype {
	case MT_MAP:
		return MlrvalFromMap(mv.mapval.Copy())
	case MT_ARRAY:
		a := make([]*Mlrval, len(mv.arrayval))
		for i, e := range mv.arrayval {
			a[i] = e.Copy()
		}
		return MlrvalFromArray(a)
	}
	return mv
}

func typeName(mv *Mlrval) string {
	switch mv.Type() {
	case MT_ERROR:
		return "error"
	case MT_ABSENT:
		return "absent"
	case MT_MAP:
		return "map"
	case MT_ARRAY:
		return "array"
	case MT_INT:
		return "int"
	case MT_FLOAT:
		return "float"
	case MT_BOOLEAN:
		return "boolean"
	case MT_VOID:
		return "empty"
	case MT_STRING:
		return "string"
	case MT_FUNC:
		return "funct"
	}
	return "?"
}

// Number-from-string inference used for DSL "inferred" values (e.g. splitax with inference)
func inferredFromString(s string) *Mlrval {
	return MlrvalFromInferred(s)
}

// Parse DSL int literal
func parseIntLiteral(s string) (int64, bool) {
	neg := false
	b := s
	if strings.HasPrefix(b, "-") {
		neg = true
		b = b[1:]
	} else if strings.HasPrefix(b, "+") {
		b = b[1:]
	}
	var u uint64
	var err error
	if len(b) > 2 && b[0] == '0' && (b[1] == 'x' || b[1] == 'X') {
		u, err = strconv.ParseUint(b[2:], 16, 64)
	} else if len(b) > 2 && b[0] == '0' && (b[1] == 'b' || b[1] == 'B') {
		u, err = strconv.ParseUint(b[2:], 2, 64)
	} else if len(b) > 2 && b[0] == '0' && (b[1] == 'o' || b[1] == 'O') {
		u, err = strconv.ParseUint(b[2:], 8, 64)
	} else if len(b) > 1 && b[0] == '0' {
		u, err = strconv.ParseUint(b[1:], 8, 64)
		if err != nil {
			return 0, false
		}
	} else {
		var i int64
		i, err = strconv.ParseInt(b, 10, 64)
		if err != nil {
			return 0, false
		}
		if neg {
			i = -i
		}
		return i, true
	}
	if err != nil {
		return 0, false
	}
	i := int64(u)
	if neg {
		i = -i
	}
	return i, true
}

func float64IsInt(f float64) bool {
	return f == math.Trunc(f)
}
EOF
echo done"}

