}

func typeName(mv *Mlrval) string {
	switch mv.Type() {
	case MT_ERROR:
		return "error"
	case MT_ABSENT:
		return "absent"
	case MT_MAP:
		return "map"
	case MT_ARRAY:
		return "array"
	case MT_INT:
		return "int"
	case MT_FLOAT:
		return "float"
	case MT_BOOLEAN:
		return "boolean"
	case MT_VOID:
		return "empty"
	case MT_STRING:
		return "string"
	case MT_FUNC:
		return "funct"
	}
	return "?"
}

