func inferredFromString(s string) *Mlrval {
	return MlrvalFromInferred(s)
}

// Parse DSL int literal
func parseIntLiteral(s string) (int64, bool) {
	neg := false
	b := s
	if strings.HasPrefix(b, "-") {
		neg = true
		b = b[1:]
	} else if strings.HasPrefix(b, "+") {
		b = b[1:]
	}
	var u uint64
	var err error
	if len(b) > 2 && b[0] == '0' && (b[1] == 'x' || b[1] == 'X') {
		u, err = strconv.ParseUint(b[2:], 16, 64)
	} else if len(b) > 2 && b[0] == '0' && (b[1] == 'b' || b[1] == 'B') {
		u, err = strconv.ParseUint(b[2:], 2, 64)
	} else if len(b) > 2 && b[0] == '0' && (b[1] == 'o' || b[1] == 'O') {
		u, err = strconv.ParseUint(b[2:], 8, 64)
	} else if len(b) > 1 && b[0] == '0' {
		u, err = strconv.ParseUint(b[1:], 8, 64)
		if err != nil {
			return 0, false
		}
	} else {
		var i int64
		i, err = strconv.ParseInt(b, 10, 64)
		if err != nil {
			return 0, false
		}
		if neg {
			i = -i
		}
		return i, true
	}
	if err != nil {
		return 0, false
	}
	i := int64(u)
	if neg {
		i = -i
	}
	return i, true
}

