		if k == key {
			return i
		}
	}
	return -1
}

func (m *Mlrmap) Has(key string) bool { return m.find(key) >= 0 }

func (m *Mlrmap) Get(key string) *Mlrval {
	i := m.find(key)
	if i < 0 {
		return nil
	}
	return m.vals[i]
}

func (m *Mlrmap) Put(key string, val *Mlrval) {
	i := m.find(key)
	if i >= 0 {
		m.vals[i] = val
		return
	}
	m.keys = append(m.keys, key)
	m.vals = append(m.vals, val)
}

// PutAtEnd: no dedupe check (caller guarantees)
func (m *Mlrmap) PutNew(key string, val *Mlrval) {
	m.keys = append(m.keys, key)
	m.vals = append(m.vals, val)
}

func (m *Mlrmap) PutAtStart(key string, val *Mlrval) {
	i := m.find(key)
	if i >= 0 {
		m.vals[i] = val
		return
	}
	m.keys = append([]string{key}, m.keys...)
	m.vals = append([]*Mlrval{val}, m.vals...)
}

// Moves to start if present, else inserts at start
func (m *Mlrmap) PutAtStartMoving(key string, val *Mlrval) {
	m.Remove(key)
	m.keys = append([]string{key}, m.keys...)
	m.vals = append([]*Mlrval{val}, m.vals...)
}

func (m *Mlrmap) PutAtEndMoving(key string, val *Mlrval) {
	m.Remove(key)
	m.keys = append(m.keys, key)
	m.vals = append(m.vals, val)
}

func (m *Mlrmap) Remove(key string) bool {
	i := m.find(key)
	if i < 0 {
		return false
	}
	m.removeAt(i)
	return true
}

func (m *Mlrmap) removeAt(i int) {
	copy(m.keys[i:], m.keys[i+1:])
	m.keys = m.keys[:len(m.keys)-1]
	copy(m.vals[i:], m.vals[i+1:])
	m.vals[len(m.vals)-1] = nil
	m.vals = m.vals[:len(m.vals)-1]
}

func (m *Mlrmap) Clear() {
	m.keys = m.keys[:0]
	m.vals = m.vals[:0]
}

func (m *Mlrmap) Copy() *Mlrmap {
	n := &Mlrmap{keys: make([]string, len(m.keys), len(m.keys)+4), vals: make([]*Mlrval, len(m.vals), len(m.vals)+4)}
	copy(n.keys, m.keys)
	for i, v := range m.vals {
		n.vals[i] = v.Copy()
	}
	return n
}

// Rename key: keeps position. If newkey exists elsewhere, that one is removed.
func (m *Mlrmap) Rename(oldkey, newkey string) bool {
	i := m.find(oldkey)
	if i < 0 {
		return false
	}
	if oldkey == newkey {
		return true
	}
	j := m.find(newkey)
	if j >= 0 {
		// Overwrite value at j position? Miller: the renamed field takes position of the old one,
		// and the existing newkey field is removed.
		m.keys[i] = newkey
		m.removeAt(j)
		return true
	}
	m.keys[i] = newkey
	return true
}

func (m *Mlrmap) KeysJoined(sep string) string {
	n := 0
	for _, k := range m.keys {
		n += len(k) + len(sep)
	}
	b := make([]byte, 0, n)
	for i, k := range m.keys {
		if i > 0 {
			b = append(b, sep...)
		}
		b = append(b, k...)
	}
	return string(b)
}

func (m *Mlrmap) SameKeys(keys []string) bool {
	if len(keys) != len(m.keys) {
		return false
	}
	for i, k := range m.keys {
		if keys[i] != k {
			return false
		}
	}
	return true
}

func (m *Mlrmap) KeysCopy() []string {
	k := make([]string, len(m.keys))
	copy(k, m.keys)
	return k
}

// Get by 1-up position
func (m *Mlrmap) GetAt(pos int) (string, *Mlrval, bool) {
	if pos < 1 || pos > len(m.keys) {
		return "", nil, false
	}
	return m.keys[pos-1], m.vals[pos-1], true
}

// Insert after/before index
func (m *Mlrmap) InsertAt(idx int, key string, val *Mlrval) {
	m.keys = append(m.keys, "")
	m.vals = append(m.vals, nil)
	copy(m.keys[idx+1:], m.keys[idx:])
	copy(m.vals[idx+1:], m.vals[idx:])
	m.keys[idx] = key
	m.vals[idx] = val
}
