	{OP, OP, ER, VO, L1, ER, ER, ER, ER},
	{ER, ER, ER, ER, AB, ER, ER, ER, ER},
	{VO, VO, ER, VO, AB, ER, ER, ER, ER},
	{Z2, Z2, AB, AB, AB, AB, AB, AB, AB},
	{ER, ER, ER, ER, AB, ER, ER, ER, ER},
	{ER, ER, ER, ER, AB, ER, ER, ER, ER},
	{ER, ER, ER, ER, AB, ER, ER, ER, ER},
	{ER, ER, ER, ER, AB, ER, ER, ER, ER},
