var dispBitwise = dispMatrix{
	{OP, ER, ER, VO, L1, ER, ER, AB, AB},
	{ER, ER, ER, VO, ER, ER, ER, AB, AB},
	{ER, ER, ER, ER, ER, ER, ER, AB, AB},
	{VO, VO, ER, VO, AB, ER, ER, AB, AB},
	{R2, ER, ER, AB, AB, ER, ER, AB, AB},
	{ER, ER, ER, ER, ER, ER, ER, AB, AB},
	{ER, ER, ER, ER, ER, ER, ER, AB, AB},
	{AB, AB, AB, AB, AB, AB, AB, AB, AB},
	{AB, AB, AB, AB, AB, AB, AB, AB, AB},
}

func applyDisp(d *dispMatrix, a, b *Mlrval, op func(a, b *Mlrval) *Mlrval) *Mlrval {
	ia := tix(a)
	ib := tix(b)
	switch d[ia][ib] {
	case D_OP:
		return op(a, b)
	case D_ER:
		return ERROR()
	case D_AB:
		return ABSENT
	case D_VO:
		return VOID
	case D_1:
		return a
	case D_2:
		return b
	case D_N2:
		return unaryMinus(b)
	case D_Z2:
		if ib == TI_FLOAT {
			return MlrvalFromFloat(0)
		}
		return MlrvalFromInt(0)
	}
	return ERROR()
}

func BinaryPlus(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispPlus, a, b, func(a, b *Mlrval) *Mlrval {
		if a.mtype == MT_INT && b.mtype == MT_INT {
			x, y := a.intval, b.intval
			c := x + y
			if (x >= 0) == (y >= 0) && (c >= 0) != (x >= 0) {
				return MlrvalFromFloat(float64(x) + float64(y))
			}
			return MlrvalFromInt(c)
		}
		return MlrvalFromFloat(a.GetNumericToFloat() + b.GetNumericToFloat())
	})
}

func BinaryMinus(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispMinus, a, b, func(a, b *Mlrval) *Mlrval {
		if a.mtype == MT_INT && b.mtype == MT_INT {
			x, y := a.intval, b.intval
			c := x - y
			if (x >= 0) != (y >= 0) && (c >= 0) != (x >= 0) {
				return MlrvalFromFloat(float64(x) - float64(y))
			}
			return MlrvalFromInt(c)
		}
		return MlrvalFromFloat(a.GetNumericToFloat() - b.GetNumericToFloat())
	})
}

func BinaryTimes(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispPlus, a, b, func(a, b *Mlrval) *Mlrval {
		if a.mtype == MT_INT && b.mtype == MT_INT {
			x, y := a.intval, b.intval
			f := float64(x) * float64(y)
			if math.Abs(f) >= 9223372036854774784.0 {
				return MlrvalFromFloat(f)
			}
			return MlrvalFromInt(x * y)
		}
		return MlrvalFromFloat(a.GetNumericToFloat() * b.GetNumericToFloat())
	})
}

func BinaryDivide(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispDivide, a, b, func(a, b *Mlrval) *Mlrval {
		if a.mtype == MT_INT && b.mtype == MT_INT {
			x, y := a.intval, b.intval
			if y == 0 {
				return MlrvalFromFloat(float64(x) / float64(y))
			}
			if y == -1 && x == math.MinInt64 {
				return MlrvalFromFloat(-float64(x))
			}
			if x%y == 0 {
				return MlrvalFromInt(x / y)
			}
			return MlrvalFromFloat(float64(x) / float64(y))
		}
		return MlrvalFromFloat(a.GetNumericToFloat() / b.GetNumericToFloat())
	})
}

func BinaryIntDivide(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispDivide, a, b, func(a, b *Mlrval) *Mlrval {
		if a.mtype == MT_INT && b.mtype == MT_INT {
			x, y := a.intval, b.intval
			if y == 0 {
				return MlrvalFromFloat(float64(x) / float64(y))
			}
			q := x / y
			r := x % y
			if r != 0 && ((r < 0) != (y < 0)) {
				q--
			}
			return MlrvalFromInt(q)
		}
		return MlrvalFromFloat(math.Floor(a.GetNumericToFloat() / b.GetNumericToFloat()))
	})
}

func BinaryMod(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispDivide, a, b, func(a, b *Mlrval) *Mlrval {
		if a.mtype == MT_INT && b.mtype == MT_INT {
			x, y := a.intval, b.intval
			if y == 0 {
				return MlrvalFromFloat(float64(x) / float64(y))
			}
			m := x % y
			if m != 0 && ((m < 0) != (y < 0)) {
				m += y
			}
			return MlrvalFromInt(m)
		}
		x := a.GetNumericToFloat()
		y := b.GetNumericToFloat()
		m := math.Mod(x, y)
		if m != 0 && ((m < 0) != (y < 0)) {
			m += y
		}
		return MlrvalFromFloat(m)
	})
}

func intPow(x, y int64) (int64, bool) {
	// returns result, ok (no overflow)
	result := int64(1)
	base := x
	e := y
	for e > 0 {
		if e&1 == 1 {
			r := result * base
			if base != 0 && (r/base != result || (result == -1 && base == math.MinInt64) || (base == -1 && result == math.MinInt64)) {
				return 0, false
			}
			result = r
		}
		e >>= 1
		if e > 0 {
			nb := base * base
			if base != 0 && nb/base != base {
				return 0, false
			}
			base = nb
		}
	}
	return result, true
}

func BinaryPow(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispPow, a, b, func(a, b *Mlrval) *Mlrval {
		if a.mtype == MT_INT && b.mtype == MT_INT {
			x, y := a.intval, b.intval
			if y >= 0 {
				r, ok := intPow(x, y)
				if ok {
					return MlrvalFromInt(r)
				}
				return MlrvalFromFloat(math.Pow(float64(x), float64(y)))
			}
			f := math.Pow(float64(x), float64(y))
			if !math.IsInf(f, 0) && !math.IsNaN(f) && f == math.Trunc(f) && math.Abs(f) < 9e18 {
				return MlrvalFromInt(int64(f))
			}
			return MlrvalFromFloat(f)
		}
		return MlrvalFromFloat(math.Pow(a.GetNumericToFloat(), b.GetNumericToFloat()))
	})
}

func BinaryDotPlus(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispPlus, a, b, func(a, b *Mlrval) *Mlrval {
		if a.mtype == MT_INT && b.mtype == MT_INT {
			return MlrvalFromInt(a.intval + b.intval)
		}
		return MlrvalFromFloat(a.GetNumericToFloat() + b.GetNumericToFloat())
	})
}

func BinaryDotMinus(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispDotMinus, a, b, func(a, b *Mlrval) *Mlrval {
		if a.mtype == MT_INT && b.mtype == MT_INT {
			return MlrvalFromInt(a.intval - b.intval)
		}
		return MlrvalFromFloat(a.GetNumericToFloat() - b.GetNumericToFloat())
	})
}

func BinaryDotTimes(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispDotTimes, a, b, func(a, b *Mlrval) *Mlrval {
		if a.mtype == MT_INT && b.mtype == MT_INT {
			return MlrvalFromInt(a.intval * b.intval)
		}
		return MlrvalFromFloat(a.GetNumericToFloat() * b.GetNumericToFloat())
	})
}

func BinaryDotDivide(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispDotDivide, a, b, func(a, b *Mlrval) *Mlrval {
		if a.mtype == MT_INT && b.mtype == MT_INT {
			if b.intval == 0 {
				return ERROR()
			}
			return MlrvalFromInt(a.intval / b.intval)
		}
		return MlrvalFromFloat(a.GetNumericToFloat() / b.GetNumericToFloat())
	})
}

func BitwiseAnd(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispBitwise, a, b, func(a, b *Mlrval) *Mlrval { return MlrvalFromInt(a.intval & b.intval) })
}
func BitwiseOr(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispBitwise, a, b, func(a, b *Mlrval) *Mlrval { return MlrvalFromInt(a.intval | b.intval) })
}
func BitwiseXor(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispBitwise, a, b, func(a, b *Mlrval) *Mlrval { return MlrvalFromInt(a.intval ^ b.intval) })
}
func LeftShift(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispBitwise, a, b, func(a, b *Mlrval) *Mlrval { return MlrvalFromInt(a.intval << uint64(b.intval)) })
}
func SignedRightShift(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispBitwise, a, b, func(a, b *Mlrval) *Mlrval { return MlrvalFromInt(a.intval >> uint64(b.intval)) })
}
func UnsignedRightShift(a, b *Mlrval) *Mlrval {
	return applyDisp(&dispBitwise, a, b, func(a, b *Mlrval) *Mlrval {
		return MlrvalFromInt(int64(uint64(a.intval) >> uint64(b.intval)))
	})
}

func unaryMinus(a *Mlrval) *Mlrval {
	switch a.Type() {
	case MT_INT:
		return MlrvalFromInt(-a.intval)
	case MT_FLOAT:
		return MlrvalFromFloat(-a.floatval)
	case MT_VOID:
		return MlrvalFromInt(0)
	case MT_ABSENT, MT_MAP, MT_ARRAY:
		return ABSENT
	}
	return ERROR()
}

func unaryPlus(a *Mlrval) *Mlrval {
	switch a.Type() {
	case MT_INT, MT_FLOAT:
		return a
	case MT_VOID:
		return MlrvalFromInt(0)
	case MT_ABSENT, MT_MAP, MT_ARRAY:
		return ABSENT
	}
	return ERROR()
}

func unaryBitNot(a *Mlrval) *Mlrval {
	switch a.Type() {
	case MT_INT:
		return MlrvalFromInt(^a.intval)
	case MT_VOID:
		return VOID
	case MT_ABSENT, MT_MAP, MT_ARRAY:
		return ABSENT
	}
	return ERROR()
}

func logicalNot(a *Mlrval) *Mlrval {
	if a.Type() == MT_BOOLEAN {
		return MlrvalFromBool(!a.IsTrue())
	}
	return ERROR()
}

func DotOperator(a, b *Mlrval) *Mlrval {
	ta := a.Type()
	tb := b.Type()
	if ta == MT_MAP {
		return ABSENT
	}
	if ta == MT_ARRAY {
		return ERROR()
	}
	if ta == MT_ERROR {
		if tb == MT_MAP || tb == MT_ARRAY {
			return ABSENT
		}
		return ERROR()
	}
	if tb == MT_ERROR {
		return ERROR()
	}
	if tb == MT_MAP || tb == MT_ARRAY {
		if ta == MT_VOID || ta == MT_ABSENT {
			return ABSENT
		}
		return ERROR()
	}
	if ta == MT_ABSENT {
		if tb == MT_ABSENT {
			return ABSENT
		}
		if tb == MT_VOID {
			return VOID
		}
		return MlrvalFromString(b.String())
	}
	if tb == MT_ABSENT {
		if ta == MT_VOID {
			return VOID
		}
		return MlrvalFromString(a.String())
	}
	s := a.String() + b.String()
	return MlrvalFromString(s)
}

// ---------------------------------------------------------------- comparisons

// returns -1,0,1 for numeric compare
func numCmp(a, b *Mlrval) int {
	if a.mtype == MT_INT && b.mtype == MT_INT {
		if a.intval < b.intval {
			return -1
		} else if a.intval > b.intval {
			return 1
		}
		return 0
	}
	x := a.GetNumericToFloat()
	y := b.GetNumericToFloat()
	if x < y {
		return -1
	} else if x > y {
		return 1
	}
	return 0
}

// kind: 0 ==, 1 !=, 2 <, 3 <=, 4 >, 5 >=
func compareOp(kind int, a, b *Mlrval) *Mlrval {
	ta := a.Type()
	tb := b.Type()
	if ta == MT_ERROR || tb == MT_ERROR {
		return ERROR()
	}
	if ta == MT_ABSENT || tb == MT_ABSENT {
		return ABSENT
	}
	aNum := ta == MT_INT || ta == MT_FLOAT
	bNum := tb == MT_INT || tb == MT_FLOAT
	if aNum && bNum {
		if (ta == MT_FLOAT && math.IsNaN(a.floatval)) || (tb == MT_FLOAT && math.IsNaN(b.floatval)) {
			return MlrvalFromBool(kind == 1)
		}
		c := numCmp(a, b)
		return MlrvalFromBool(cmpResult(kind, c))
	}
	if ta == MT_BOOLEAN || tb == MT_BOOLEAN {
		if ta == MT_BOOLEAN && tb == MT_BOOLEAN {
			c := int(a.intval) - int(b.intval)
			return MlrvalFromBool(cmpResult(kind, c))
		}
		return MlrvalFromBool(kind == 1)
	}
	if ta == MT_MAP || ta == MT_ARRAY || tb == MT_MAP || tb == MT_ARRAY {
		if ta == tb {
			if kind == 0 || kind == 1 {
				eq := mlrvalDeepEqual(a, b)
				if kind == 0 {
					return MlrvalFromBool(eq)
				}
				return MlrvalFromBool(!eq)
			}
			return ERROR()
		}
		return MlrvalFromBool(kind == 1)
	}
	c := strings.Compare(a.String(), b.String())
	return MlrvalFromBool(cmpResult(kind, c))
}

func cmpResult(kind int, c int) bool {
	switch kind {
	case 0:
		return c == 0
	case 1:
		return c != 0
	case 2:
		return c < 0
	case 3:
		return c <= 0
	case 4:
		return c > 0
	case 5:
		return c >= 0
	}
	return false
}

func mlrvalDeepEqual(a, b *Mlrval) bool {
	ta := a.Type()
	tb := b.Type()
	if ta == MT_MAP && tb == MT_MAP {
		if a.mapval.Len() != b.mapval.Len() {
			return false
		}
		for i, k := range a.mapval.keys {
			bv := b.mapval.Get(k)
			if bv == nil {
				return false
			}
			if !mlrvalDeepEqual(a.mapval.vals[i], bv) {
				return false
			}
		}
		return true
	}
	if ta == MT_ARRAY && tb == MT_ARRAY {
		if len(a.arrayval) != len(b.arrayval) {
			return false
		}
		for i := range a.arrayval {
			if !mlrvalDeepEqual(a.arrayval[i], b.arrayval[i]) {
				return false
			}
		}
		return true
	}
	r := compareOp(0, a, b)
	return r.IsTrue()
}

// <=> operator
func spaceship(a, b *Mlrval) *Mlrval {
	ta := a.Type()
	tb := b.Type()
	if ta == MT_ERROR || tb == MT_ERROR {
		return ERROR()
	}
	if ta == MT_ABSENT || tb == MT_ABSENT {
		return ABSENT
	}
	return MlrvalFromInt(int64(collateCompare(a, b)))
}

// Ordering for <=> and sorting functions: numerics < booleans < voids < strings
func collateRank(mv *Mlrval) int {
	switch mv.Type() {
	case MT_INT, MT_FLOAT:
		return 0
	case MT_BOOLEAN:
		return 1
	case MT_VOID:
		return 2
	case MT_STRING:
		return 3
	case MT_MAP:
		return 5
	case MT_ARRAY:
		return 4
	}
	return 6
}

func collateCompare(a, b *Mlrval) int {
	ra := collateRank(a)
	rb := collateRank(b)
	if ra != rb {
		if ra < rb {
			return -1
		}
		return 1
	}
	switch ra {
	case 0:
		return numCmp(a, b)
	case 1:
		return int(a.intval) - int(b.intval)
	case 2:
		return 0
	case 3:
		return strings.Compare(a.String(), b.String())
	}
	return 0
}

// ---------------------------------------------------------------- logical
func logicalAnd(a, b *Mlrval) *Mlrval {
	ta := a.Type()
	if ta == MT_BOOLEAN && !a.IsTrue() {
		return FALSE
	}
	if ta == MT_ERROR {
		return ERROR()
	}
	tb := b.Type()
	if !(ta == MT_BOOLEAN || ta == MT_VOID || ta == MT_ABSENT) {
		if tb == MT_ABSENT {
			return ABSENT
		}
		return ERROR()
	}
	if tb == MT_BOOLEAN {
		return b
	}
	if tb == MT_ABSENT {
		return ABSENT
	}
	if tb == MT_VOID && ta == MT_ABSENT {
		return ABSENT
	}
	return ERROR()
}

func logicalOr(a, b *Mlrval) *Mlrval {
	ta := a.Type()
	if ta == MT_BOOLEAN && a.IsTrue() {
		return TRUE
	}
	if ta == MT_ERROR {
		return ERROR()
	}
	tb := b.Type()
	if !(ta == MT_BOOLEAN || ta == MT_VOID || ta == MT_ABSENT) {
		if tb == MT_ABSENT {
			return ABSENT
		}
		return ERROR()
	}
	if tb == MT_BOOLEAN {
		return b
	}
	if tb == MT_ABSENT {
		return ABSENT
	}
	if tb == MT_VOID && ta == MT_ABSENT {
		return ABSENT
	}
	return ERROR()
}

func logicalXor(a, b *Mlrval) *Mlrval {
	if a.Type() == MT_BOOLEAN && b.Type() == MT_BOOLEAN {
		return MlrvalFromBool(a.IsTrue() != b.IsTrue())
	}
	return ERROR()
}
EOF
