func newFormatter(uf string) *Formatter {
	idx := strings.Index(uf, "%")
	if idx < 0 {
		return &Formatter{kind: 3, errmsg: fmt.Sprintf("mlr: unhandled format string \"%s\": no leading \"%%\"", uf)}
	}
