	g = strings.ReplaceAll(g, "llx", "x")
	g = strings.ReplaceAll(g, "ld", "d")
	g = strings.ReplaceAll(g, "lx", "x")
	g = strings.ReplaceAll(g, "lf", "f")
	g = strings.ReplaceAll(g, "le", "e")
	g = strings.ReplaceAll(g, "lg", "g")
	commas := false
	if strings.Contains(g, "_") {
		// Only within the verb spec
		commas = true
		g = strings.Replace(g, "_", "", 1)
	}
	last := g[len(g)-1]
	f := &Formatter{goFormat: g, commas: commas}
	switch last {
	case 'd', 'x':
		f.kind = 0
	case 'f', 'e', 'g':
		f.kind = 1
	default:
		f.kind = 2
	}
	return f
}

func insertCommas(s string) string {
	// insert commas into the first run of digits
	start := -1
	end := -1
	for i := 0; i < len(s); i++ {
		if s[i] >= '0' && s[i] <= '9' {
			if start < 0 {
				start = i
			}
			end = i + 1
		} else if start >= 0 {
			break
		}
	}
	if start < 0 {
		return s
	}
	digits := s[start:end]
	if len(digits) <= 3 {
		return s
	}
	var b strings.Builder
	n := len(digits)
	for i := 0; i < n; i++ {
		if i > 0 && (n-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteByte(digits[i])
	}
	return s[:start] + b.String() + s[end:]
}

func (f *Formatter) postprocess(s string) string {
	if f.commas {
		return insertCommas(s)
	}
	return s
