package main

import (
	"fmt"
	"os"
	"strings"
)

type Formatter struct {
	goFormat string
	kind     int // 0 int, 1 float, 2 string, 3 error
	commas   bool
	errmsg   string
}

var formatterCache = map[string]*Formatter{}

func GetFormatter(userFormat string) *Formatter {
	if f, ok := formatterCache[userFormat]; ok {
		return f
	}
	f := newFormatter(userFormat)
	formatterCache[userFormat] = f
	return f
}

func newFormatter(uf string) *Formatter {
	idx := strings.Index(uf, "%")
	if idx < 0 {
		return &Formatter{kind: 3, errmsg: fmt.Sprintf("mlr: unhandled format string \"%s\": no leading \"%%\"", uf)}
	}
	if strings.Contains(uf[idx+1:], "%") {
		return &Formatter{kind: 3, errmsg: fmt.Sprintf("mlr: unhandled format string \"%s\": needs no \"%%\" after the first", uf)}
	}
	g := uf
	g = strings.ReplaceAll(g, "lld", "d")
	g = strings.ReplaceAll(g, "llx", "x")
	g = strings.ReplaceAll(g, "ld", "d")
	g = strings.ReplaceAll(g, "lx", "x")
	g = strings.ReplaceAll(g, "lf", "f")
	g = strings.ReplaceAll(g, "le", "e")
	g = strings.ReplaceAll(g, "lg", "g")
	commas := false
	if strings.Contains(g, "_") {
		// Only within the verb spec
		commas = true
		g = strings.Replace(g, "_", "", 1)
	}
	last := g[len(g)-1]
	f := &Formatter{goFormat: g, commas: commas}
	switch last {
	case 'd', 'x':
		f.kind = 0
	case 'f', 'e', 'g':
		f.kind = 1
	default:
		f.kind = 2
	}
	return f
}

func insertCommas(s string) string {
	// insert commas into the first run of digits
	start := -1
	end := -1
	for i := 0; i < len(s); i++ {
		if s[i] >= '0' && s[i] <= '9' {
			if start < 0 {
				start = i
			}
			end = i + 1
		} else if start >= 0 {
			break
		}
	}
	if start < 0 {
		return s
	}
	digits := s[start:end]
	if len(digits) <= 3 {
		return s
	}
	var b strings.Builder
	n := len(digits)
	for i := 0; i < n; i++ {
		if i > 0 && (n-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteByte(digits[i])
	}
	return s[:start] + b.String() + s[end:]
}

func (f *Formatter) postprocess(s string) string {
	if f.commas {
		return insertCommas(s)
	}
	return s
}

func (f *Formatter) FormatFloat(x float64) string {
	switch f.kind {
	case 0:
		return f.postprocess(fmt.Sprintf(f.goFormat, int64(x)))
	case 1:
		return f.postprocess(fmt.Sprintf(f.goFormat, x))
	case 2:
		return fmt.Sprintf(f.goFormat, formatFloat(x))
	}
	return "(error)"
}

// Format: returns formatted mlrval (inferred) or error
func (f *Formatter) Format(mv *Mlrval) *Mlrval {
	if f.kind == 3 {
		fmt.Fprintln(os.Stderr, f.errmsg)
		return ERROR()
	}
	t := mv.Type()
	if t != MT_INT && t != MT_FLOAT {
		return ERROR()
	}
	switch f.kind {
	case 0:
		var i int64
		if t == MT_INT {
			i = mv.intval
		} else {
			i = int64(mv.floatval)
		}
		return MlrvalFromInferred(f.postprocess(fmt.Sprintf(f.goFormat, i)))
	case 1:
		x := mv.GetNumericToFloat()
		return MlrvalFromInferred(f.postprocess(fmt.Sprintf(f.goFormat, x)))
	default:
		return MlrvalFromString(fmt.Sprintf(f.goFormat, mv.String()))
	}
}
