// ---------------------------------------------------------------- encoding

func jsonEncodeString(s string) string {
	var b strings.Builder
	b.Grow(len(s) + 2)
	b.WriteByte('"')
	for i := 0; i < len(s); {
		c := s[i]
		if c < 0x80 {
			switch c {
			case '"':
				b.WriteString("\\\"")
			case '\\':
				b.WriteString("\\\\")
			case '\n':
				b.WriteString("\\n")
			case '\r':
				b.WriteString("\\r")
			case '\t':
				b.WriteString("\\t")
			case '\b':
				b.WriteString("\\b")
			case '\f':
				b.WriteString("\\f")
			default:
				if c < 0x20 {
					fmt.Fprintf(&b, "\\u%04x", c)
				} else {
					b.WriteByte(c)
				}
			}
			i++
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 1 {
			b.WriteString("\ufffd")
		} else {
			b.WriteString(s[i : i+size])
		}
		i += size
	}
	b.WriteByte('"')
	return b.String()
}

// scalar JSON encoding
func jsonScalar(mv *Mlrval, quoteAll bool) string {
	if mv.isnull {
		if quoteAll {
			return "\"\""
		}
		return "null"
	}
	switch mv.Type() {
	case MT_INT:
		if quoteAll {
			return jsonEncodeString(mv.String())
		}
		return strconv.FormatInt(mv.intval, 10)
	case MT_FLOAT:
		if quoteAll {
			return jsonEncodeString(mv.OutputString())
		}
		return mv.OutputString()
	case MT_BOOLEAN:
		if quoteAll {
			return jsonEncodeString(mv.String())
		}
		return mv.String()
	case MT_VOID:
		return "\"\""
	case MT_STRING:
		return jsonEncodeString(mv.printrep)
	case MT_ERROR:
		return "(error)"
	case MT_ABSENT:
		return "(absent)"
	case MT_FUNC:
		return "\"(function-literal)\""
	}
	return jsonEncodeString(mv.String())
}

func isScalarForJSON(mv *Mlrval) bool {
	return mv.mtype != MT_MAP && mv.mtype != MT_ARRAY
}

// multi-line encode of a value at given indent level (number of 2-space units for nested content)
func jsonEncodeMultiline(b *strings.Builder, mv *Mlrval, indent int, quoteAll bool) {
	switch mv.mtype {
	case MT_MAP:
		m := mv.mapval
		if m.Len() == 0 {
			b.WriteString("{}")
			return
		}
		b.WriteString("{\n")
		for i, k := range m.keys {
			writeIndent(b, indent+1)
			b.WriteString(jsonEncodeString(k))
			b.WriteString(": ")
			jsonEncodeMultiline(b, m.vals[i], indent+1, quoteAll)
			if i < len(m.keys)-1 {
				b.WriteString(",")
			}
			b.WriteString("\n")
		}
		writeIndent(b, indent)
		b.WriteString("}")
	case MT_ARRAY:
		a := mv.arrayval
		if len(a) == 0 {
			b.WriteString("[]")
			return
		}
		allScalar := true
		for _, e := range a {
			if !isScalarForJSON(e) {
				allScalar = false
				break
			}
		}
		if allScalar {
			b.WriteString("[")
			for i, e := range a {
				if i > 0 {
					b.WriteString(", ")
				}
				b.WriteString(jsonScalar(e, quoteAll))
			}
			b.WriteString("]")
			return
		}
		b.WriteString("[\n")
		for i, e := range a {
			writeIndent(b, indent+1)
			jsonEncodeMultiline(b, e, indent+1, quoteAll)
			if i < len(a)-1 {
				b.WriteString(",")
			}
			b.WriteString("\n")
		}
		writeIndent(b, indent)
		b.WriteString("]")
	default:
		b.WriteString(jsonScalar(mv, quoteAll))
	}
}

func writeIndent(b *strings.Builder, n int) {
	for i := 0; i < n; i++ {
		b.WriteString("  ")
	}
}

func jsonEncodeSingleLine(b *strings.Builder, mv *Mlrval, quoteAll bool) {
	switch mv.mtype {
	case MT_MAP:
		m := mv.mapval
		if m.Len() == 0 {
			b.WriteString("{}")
			return
		}
		b.WriteString("{")
		for i, k := range m.keys {
			if i > 0 {
				b.WriteString(", ")
			}
			b.WriteString(jsonEncodeString(k))
			b.WriteString(": ")
			jsonEncodeSingleLine(b, m.vals[i], quoteAll)
		}
		b.WriteString("}")
	case MT_ARRAY:
		a := mv.arrayval
		b.WriteString("[")
		for i, e := range a {
			if i > 0 {
				b.WriteString(", ")
			}
			jsonEncodeSingleLine(b, e, quoteAll)
		}
		b.WriteString("]")
	default:
		b.WriteString(jsonScalar(mv, quoteAll))
	}
}

func (mv *Mlrval) JSONMultiline() string {
	var b strings.Builder
	jsonEncodeMultiline(&b, mv, 0, false)
	return b.String()
}

func (mv *Mlrval) JSONSingleLine() string {
	var b strings.Builder
	jsonEncodeSingleLine(&b, mv, false)
	return b.String()
}

// ---------------------------------------------------------------- decoding

type jsonParser struct {
	s    string
	pos  int
	line int
}

type jsonError struct {
	msg string
}

func (e *jsonError) Error() string { return e.msg }

func (p *jsonParser) skipWS() {
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == ' ' || c == '\t' || c == '\r' {
			p.pos++
		} else if c == '\n' {
			p.line++
			p.pos++
		} else {
			break
		}
	}
}

func (p *jsonParser) fail(msg string) {
	panic(&jsonError{msg})
}

func (p *jsonParser) parseValue() *Mlrval {
	p.skipWS()
	if p.pos >= len(p.s) {
		p.fail("mlr: JSON parser: unexpected end of input")
	}
	c := p.s[p.pos]
	switch {
	case c == '{':
		return p.parseObject()
	case c == '[':
		return p.parseArray()
	case c == '"':
		s := p.parseString()
		return MlrvalFromString(s)
	case c == 't':
		if strings.HasPrefix(p.s[p.pos:], "true") {
			p.pos += 4
			return TRUE
		}
	case c == 'f':
		if strings.HasPrefix(p.s[p.pos:], "false") {
			p.pos += 5
			return FALSE
		}
	case c == 'n':
		if strings.HasPrefix(p.s[p.pos:], "null") {
			p.pos += 4
			return JSONNULL
		}
	case c == '-' || c == '+' || c == '.' || (c >= '0' && c <= '9'):
		start := p.pos
		for p.pos < len(p.s) {
			d := p.s[p.pos]
			if (d >= '0' && d <= '9') || d == '-' || d == '+' || d == '.' || d == 'e' || d == 'E' || d == 'x' || d == 'X' || (d >= 'a' && d <= 'f') || (d >= 'A' && d <= 'F') || d == 'o' || d == 'b' {
				p.pos++
			} else {
				break
			}
		}
		txt := p.s[start:p.pos]
		mv := MlrvalFromInferred(txt)
		t := mv.Type()
		if t != MT_INT && t != MT_FLOAT {
			p.fail(fmt.Sprintf("mlr: JSON parser: unparseable number \"%s\"", txt))
		}
		return mv
	}
	p.fail(fmt.Sprintf("mlr: JSON parser: syntax error at line %d", p.line))
	return nil
}

func (p *jsonParser) parseString() string {
	// assumes s[pos] == '"'
	p.pos++
	start := p.pos
	// fast path
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == '"' {
			r := p.s[start:p.pos]
			p.pos++
			return r
		}
		if c == '\\' {
			break
		}
		if c == '\n' {
			p.line++
		}
		p.pos++
	}
	var b strings.Builder
	b.WriteString(p.s[start:p.pos])
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == '"' {
			p.pos++
			return b.String()
		}
		if c == '\\' {
			p.pos++
			if p.pos >= len(p.s) {
				break
			}
			e := p.s[p.pos]
			switch e {
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			case '/':
				b.WriteByte('/')
			case 'b':
				b.WriteByte('\b')
			case 'f':
				b.WriteByte('\f')
			case 'n':
				b.WriteByte('\n')
			case 'r':
				b.WriteByte('\r')
			case 't':
				b.WriteByte('\t')
			case 'u':
				if p.pos+4 < len(p.s) {
					v, err := strconv.ParseUint(p.s[p.pos+1:p.pos+5], 16, 32)
					if err == nil {
						p.pos += 4
						r := rune(v)
						if r >= 0xD800 && r < 0xDC00 && p.pos+6 < len(p.s) && p.s[p.pos+1] == '\\' && p.s[p.pos+2] == 'u' {
							v2, err2 := strconv.ParseUint(p.s[p.pos+3:p.pos+7], 16, 32)
							if err2 == nil && v2 >= 0xDC00 && v2 < 0xE000 {
								r = 0x10000 + (r-0xD800)<<10 + (rune(v2) - 0xDC00)
								p.pos += 6
							}
						}
						b.WriteRune(r)
					}
				}
			default:
				b.WriteByte('\\')
				b.WriteByte(e)
			}
			p.pos++
			continue
		}
		if c == '\n' {
			p.line++
		}
		b.WriteByte(c)
		p.pos++
	}
	p.fail("mlr: JSON parser: unterminated string")
	return ""
}

func (p *jsonParser) parseObject() *Mlrval {
	p.pos++ // {
	m := NewMlrmap()
	p.skipWS()
	if p.pos < len(p.s) && p.s[p.pos] == '}' {
		p.pos++
		return MlrvalFromMap(m)
	}
	for {
		p.skipWS()
		if p.pos >= len(p.s) || p.s[p.pos] != '"' {
			p.fail("mlr: JSON parser: expected string key")
		}
		k := p.parseString()
		p.skipWS()
		if p.pos >= len(p.s) || p.s[p.pos] != ':' {
			p.fail("mlr: JSON parser: expected colon")
		}
		p.pos++
		v := p.parseValue()
		m.Put(k, v)
		p.skipWS()
		if p.pos >= len(p.s) {
			p.fail("mlr: JSON parser: unexpected end of input in object")
		}
		if p.s[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.s[p.pos] == '}' {
			p.pos++
			return MlrvalFromMap(m)
		}
		p.fail("mlr: JSON parser: expected comma or close brace")
	}
}

func (p *jsonParser) parseArray() *Mlrval {
	p.pos++ // [
	a := make([]*Mlrval, 0)
	p.skipWS()
	if p.pos < len(p.s) && p.s[p.pos] == ']' {
		p.pos++
		return MlrvalFromArray(a)
	}
	for {
		v := p.parseValue()
		a = append(a, v)
		p.skipWS()
		if p.pos >= len(p.s) {
			p.fail("mlr: JSON parser: unexpected end of input in array")
		}
		if p.s[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.s[p.pos] == ']' {
			p.pos++
			return MlrvalFromArray(a)
		}
		p.fail("mlr: JSON parser: expected comma or close bracket")
	}
}

// Parse a single JSON value from a string
func jsonDecodeValue(s string) (mv *Mlrval, err error) {
	defer func() {
		if r := recover(); r != nil {
			if je, ok := r.(*jsonError); ok {
				err = je
				mv = nil
				return
			}
			panic(r)
		}
	}()
	p := &jsonParser{s: s, line: 1}
	v := p.parseValue()
	p.skipWS()
	if p.pos < len(p.s) {
		return nil, &jsonError{"mlr: JSON parser: trailing characters"}
	}
	return v, nil
}
