type Context struct {
	NR       int64
	FNR      int64
	FILENAME string
	FILENUM  int64
}

type readerError struct {
	msg string
}

func (e *readerError) Error() string { return e.msg }

type RecordSink func(rec *Mlrmap, ctx *Context)

type InputReader struct {
	opts      *ReaderOptions
	ctx       Context
	sink      RecordSink
	passOut   func(s string) // for pass-comments
	stopped   bool
	jsonList  bool
}

var jsonInputHadList = false

func openInput(filename string, ropts *ReaderOptions) ([]byte, error) {
	if filename == "-" {
		return io.ReadAll(os.Stdin)
	}
	if ropts.Prepipe != "" {
		var cmdline string
		if ropts.PrepipeIsRaw {
			cmdline = ropts.Prepipe + " " + filename
		} else {
			cmdline = ropts.Prepipe + " < '" + filename + "'"
		}
		cmd := exec.Command("/bin/sh", "-c", cmdline)
		out, err := cmd.Output()
		if err != nil {
			return nil, err
		}
		return out, nil
	}
	f, err := os.Open(filename)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	var r io.Reader = bufio.NewReader(f)
	dec := ropts.Decompress
	if dec == "" {
		if strings.HasSuffix(filename, ".gz") {
			dec = "gzip"
		} else if strings.HasSuffix(filename, ".bz2") {
			dec = "bz2"
		} else if strings.HasSuffix(filename, ".z") {
			dec = "zlib"
		}
	}
	switch dec {
	case "gzip":
		gz, err := gzip.NewReader(r)
		if err != nil {
			return nil, err
		}
		r = gz
	case "bz2":
		r = bzip2.NewReader(r)
	case "zlib":
		z, err := zlib.NewReader(r)
		if err != nil {
			return nil, err
		}
		r = z
	}
	return io.ReadAll(r)
}

// Split content into lines per IRS
func splitLines(content string, irs string) []string {
	if irs == "\n" || irs == "\r\n" || irs == "" {
		lines := strings.Split(content, "\n")
		if len(lines) > 0 && lines[len(lines)-1] == "" {
			lines = lines[:len(lines)-1]
		}
		for i, l := range lines {
			if strings.HasSuffix(l, "\r") {
				lines[i] = l[:len(l)-1]
			}
		}
		return lines
	}
	lines := strings.Split(content, irs)
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	// Also strip a final trailing newline if irs isn't newline
	if len(lines) > 0 {
		last := lines[len(lines)-1]
		if strings.HasSuffix(last, "\n") {
			lines[len(lines)-1] = strings.TrimSuffix(strings.TrimSuffix(last, "\n"), "\r")
			if lines[len(lines)-1] == "" {
				lines = lines[:len(lines)-1]
			}
		}
	}
	return lines
}

func (ir *InputReader) emit(rec *Mlrmap) {
	ir.ctx.NR++
	ir.ctx.FNR++
	c := ir.ctx
	ir.sink(rec, &c)
}

// returns true if line is a comment (and handles it)
func (ir *InputReader) handleComment(line string) bool {
	if ir.opts.CommentHandling == 0 {
		return false
	}
	if strings.HasPrefix(line, ir.opts.CommentString) {
		if ir.opts.CommentHandling == 2 {
			ir.passOut(line + "\n")
		}
		return true
	}
	return false
}

func (ir *InputReader) splitFields(line string) []string {
	if ir.opts.IFSRegex != nil {
		return ir.opts.IFSRegex.Split(line, -1)
	}
	ifs := ir.opts.IFS
	if ir.opts.AllowRepeatIFS {
		return splitRepeated(line, ifs)
	}
	return strings.Split(line, ifs)
}

func splitRepeated(line, sep string) []string {
	parts := strings.Split(line, sep)
	out := make([]string, 0, len(parts))
	for i, p := range parts {
		if p == "" && i > 0 && i < len(parts)-1 {
			continue
		}
		if p == "" && i > 0 && i == len(parts)-1 {
			// trailing: keep one empty if previous wasn't empty-collapsed
			if len(out) > 0 && out[len(out)-1] == "" {
				continue
			}
		}
		out = append(out, p)
	}
	return out
}

func (ir *InputReader) splitPair(field string) (string, string, bool) {
	if ir.opts.IPSRegex != nil {
		loc := ir.opts.IPSRegex.FindStringIndex(field)
		if loc == nil {
			return "", "", false
		}
		return field[:loc[0]], field[loc[1]:], true
	}
	idx := strings.Index(field, ir.opts.IPS)
	if idx < 0 {
		return "", "", false
	}
	return field[:idx], field[idx+len(ir.opts.IPS):], true
}

func dedupeKey(rec *Mlrmap, key string) string {
	if !rec.Has(key) {
		return key
	}
	for n := 2; ; n++ {
		k := key + "_" + strconv.Itoa(n)
		if !rec.Has(k) {
			return k
		}
	}
}

func (ir *InputReader) putField(rec *Mlrmap, key string, value *Mlrval) {
	if ir.opts.DedupeFieldNames {
		rec.PutNew(dedupeKey(rec, key), value)
	} else {
		rec.Put(key, value)
	}
}

// ---------------------------------------------------------------- DKVP
func (ir *InputReader) readDKVP(content string) {
	lines := splitLines(content, ir.opts.IRS)
	for _, line := range lines {
		if ir.stopped {
			return
		}
		if ir.handleComment(line) {
			continue
		}
		rec := NewMlrmap()
		if line != "" {
			fields := ir.splitFields(line)
			incr := 0
			for i, f := range fields {
				if f == "" {
					continue
				}
				k, v, ok := ir.splitPair(f)
				if !ok {
					incr++
					if ir.opts.IncrKey {
						k = strconv.Itoa(incr)
					} else {
						k = strconv.Itoa(i + 1)
					}
					v = f
				}
				ir.putField(rec, k, MlrvalFromInferred(v))
			}
		}
		ir.emit(rec)
	}
}

// ---------------------------------------------------------------- NIDX
func (ir *InputReader) readNIDX(content string) {
	lines := splitLines(content, ir.opts.IRS)
	for _, line := range lines {
		if ir.stopped {
			return
		}
		if ir.handleComment(line) {
			continue
		}
		rec := NewMlrmap()
		if line != "" {
			fields := ir.splitFields(line)
			for i, f := range fields {
				rec.PutNew(strconv.Itoa(i+1), MlrvalFromInferred(f))
			}
		}
		ir.emit(rec)
	}
}

// ---------------------------------------------------------------- XTAB
func (ir *InputReader) readXTAB(content string) {
	lines := splitLines(content, "\n")
	var rec *Mlrmap
	ips := ir.opts.IPS
	for _, line := range lines {
		if ir.stopped {
			return
		}
		if ir.handleComment(line) {
			continue
		}
		if strings.TrimSpace(line) == "" && line == "" {
			if rec != nil {
				ir.emit(rec)
				rec = nil
			}
			continue
		}
		if rec == nil {
			rec = NewMlrmap()
		}
		var k, v string
		if ir.opts.IPSRegex != nil {
			loc := ir.opts.IPSRegex.FindStringIndex(line)
			if loc == nil {
				k = line
			} else {
				k = line[:loc[0]]
				v = line[loc[1]:]
			}
		} else if ips == " " {
			idx := strings.Index(line, " ")
			if idx < 0 {
				k = line
			} else {
				k = line[:idx]
				rest := line[idx:]
				v = strings.TrimLeft(rest, " ")
			}
		} else {
			idx := strings.Index(line, ips)
			if idx < 0 {
				k = line
			} else {
				k = line[:idx]
				rest := line[idx:]
				for strings.HasPrefix(rest, ips) {
					rest = rest[len(ips):]
				}
				v = rest
			}
		}
		ir.putField(rec, k, MlrvalFromInferred(v))
	}
	if rec != nil {
		ir.emit(rec)
	}
}

// ---------------------------------------------------------------- CSV (full)
func (ir *InputReader) csvError(msg string) {
	panic(&readerError{msg})
}

// parse CSV content into rows of fields. Returns rows and per-row starting line numbers.
func (ir *InputReader) readCSV(content string) {
	if strings.HasPrefix(content, "\xef\xbb\xbf") {
		content = content[3:]
	}
	ifs := ir.opts.IFS
	irs := ir.opts.IRS
	n := len(content)
	pos := 0
	lineno := 0
	var header []string
	rowno := 0
	dataLine := 0
	trimLeading := ir.opts.CSVTrimLeading
	for pos < n {
		if ir.stopped {
			return
		}
		// comment check at line start
		if ir.opts.CommentHandling != 0 && strings.HasPrefix(content[pos:], ir.opts.CommentString) {
			end := strings.Index(content[pos:], "\n")
			var line string
			if end < 0 {
				line = content[pos:]
				pos = n
			} else {
				line = content[pos : pos+end]
				pos += end + 1
			}
			lineno++
			if ir.opts.CommentHandling == 2 {
				ir.passOut(strings.TrimSuffix(line, "\r") + "\n")
			}
			continue
		}
		// parse one record
		fields := make([]string, 0, 16)
		lineno++
		rowno++
		for {
			if trimLeading {
				for pos < n && content[pos] == ' ' {
					pos++
				}
			}
			if pos < n && content[pos] == '"' {
				// quoted field
				pos++
				var b strings.Builder
				for {
					if pos >= n {
						break
					}
					c := content[pos]
					if c == '"' {
						if pos+1 < n && content[pos+1] == '"' {
							b.WriteByte('"')
							pos += 2
							continue
						}
						pos++
						break
					}
					if c == '\n' {
						lineno++
					}
					b.WriteByte(c)
					pos++
				}
				// after closing quote: possibly junk until separator
				fieldStr := b.String()
				for pos < n && !strings.HasPrefix(content[pos:], ifs) && !atRecordEnd(content, pos, irs) {
					fieldStr += string(content[pos])
					pos++
				}
				fields = append(fields, fieldStr)
			} else {
				start := pos
				for pos < n && !strings.HasPrefix(content[pos:], ifs) && !atRecordEnd(content, pos, irs) {
					pos++
				}
				fields = append(fields, content[start:pos])
			}
			if pos >= n {
				break
			}
			if strings.HasPrefix(content[pos:], ifs) {
				pos += len(ifs)
				if pos >= n {
					fields = append(fields, "")
					break
				}
				continue
			}
			// record end
			pos += recordEndLen(content, pos, irs)
			break
		}
		// strip trailing CR on last field if irs newline
		if header == nil && !ir.opts.ImplicitHeader {
			header = fields
			continue
		}
		if header == nil && ir.opts.ImplicitHeader {
			header = make([]string, len(fields))
			for i := range fields {
				header[i] = strconv.Itoa(i + 1)
			}
		}
		dataLine++
		rec := NewMlrmap()
		if len(fields) == len(header) {
			for i, f := range fields {
				ir.putField(rec, header[i], MlrvalFromInferred(f))
			}
		} else if ir.opts.AllowRagged {
			for i, f := range fields {
				if i < len(header) {
					ir.putField(rec, header[i], MlrvalFromInferred(f))
				} else {
					ir.putField(rec, strconv.Itoa(i+1), MlrvalFromInferred(f))
				}
			}
		} else {
			ir.csvError(fmt.Sprintf("mlr: CSV header/data length mismatch %d != %d at filename %s row %d", len(header), len(fields), ir.ctx.FILENAME, rowno))
		}
		ir.emit(rec)
	}
}

func atRecordEnd(content string, pos int, irs string) bool {
	if irs == "\n" || irs == "\r\n" {
		c := content[pos]
		if c == '\n' {
			return true
		}
		if c == '\r' && pos+1 < len(content) && content[pos+1] == '\n' {
			return true
		}
		return false
	}
	return strings.HasPrefix(content[pos:], irs)
}

func recordEndLen(content string, pos int, irs string) int {
	if irs == "\n" || irs == "\r\n" {
		if content[pos] == '\r' {
			return 2
		}
		return 1
	}
	return len(irs)
}

// ---------------------------------------------------------------- CSV-lite / TSV / PPRINT / markdown
// mode: "csvlite", "tsv", "tsvlite", "pprint", "markdown"
func (ir *InputReader) readLite(content string, mode string) {
	if strings.HasPrefix(content, "\xef\xbb\xbf") {
		content = content[3:]
	}
	lines := splitLines(content, ir.opts.IRS)
	var header []string
	lineno := 0
	isTSV := mode == "tsv" || mode == "tsvlite"
	isPPRINT := mode == "pprint"
	isMD := mode == "markdown"
	for _, line := range lines {
		lineno++
		if ir.stopped {
			return
		}
		if ir.handleComment(line) {
			continue
		}
		var fields []string
		if isMD {
			tl := strings.TrimSpace(line)
			if tl == "" {
				header = nil
				continue
			}
			if !strings.HasPrefix(tl, "|") {
				continue
			}
			tl = strings.TrimPrefix(tl, "|")
			tl = strings.TrimSuffix(tl, "|")
			parts := strings.Split(tl, "|")
			for i := range parts {
				parts[i] = strings.TrimSpace(parts[i])
			}
			if header != nil && len(parts) > 0 && isMarkdownSeparator(parts) {
				continue
			}
			fields = parts
		} else if isPPRINT {
			if strings.TrimSpace(line) == "" {
				header = nil
				continue
			}
			tl := line
			if ir.opts.BarredInput || strings.HasPrefix(strings.TrimLeft(tl, " "), "+-") || strings.HasPrefix(strings.TrimLeft(tl, " "), "| ") {
				t2 := strings.TrimSpace(tl)
				if strings.HasPrefix(t2, "+-") {
					continue
				}
				if strings.HasPrefix(t2, "|") {
					t2 = strings.TrimPrefix(t2, "|")
					t2 = strings.TrimSuffix(t2, "|")
					parts := strings.Split(t2, "|")
					for i := range parts {
						parts[i] = strings.TrimSpace(parts[i])
					}
					fields = parts
				}
			}
			if fields == nil {
				fs := ir.splitFields(strings.TrimSpace(tl))
				fields = make([]string, 0, len(fs))
				for _, f := range fs {
					if f != "" {
						fields = append(fields, f)
					}
				}
			}
		} else {
			if line == "" {
				if isTSV && mode == "tsv" {
					if header != nil {
						ir.csvError(fmt.Sprintf("mlr: TSV header/data length mismatch %d != %d at filename %s line %d", len(header), 0, ir.ctx.FILENAME, lineno))
					}
					continue
				}
				header = nil
				continue
			}
			fields = ir.splitFields(line)
			if isTSV {
				for i, f := range fields {
					fields[i] = tsvUnescape(f)
				}
			} else if mode == "csvlite" {
				fields = csvliteDequote(line, ir.opts.IFS, fields)
			}
		}
		if header == nil {
			if ir.opts.ImplicitHeader {
				header = make([]string, len(fields))
				for i := range fields {
					header[i] = strconv.Itoa(i + 1)
				}
			} else {
				header = fields
				continue
			}
		}
		rec := NewMlrmap()
		if len(fields) == len(header) {
			for i, f := range fields {
				if isPPRINT && f == "-" {
					f = ""
				}
				ir.putField(rec, header[i], MlrvalFromInferred(f))
			}
		} else if ir.opts.AllowRagged {
			for i, f := range fields {
				if isPPRINT && f == "-" {
					f = ""
				}
				if i < len(header) {
					ir.putField(rec, header[i], MlrvalFromInferred(f))
				} else {
					ir.putField(rec, strconv.Itoa(i+1), MlrvalFromInferred(f))
				}
			}
		} else {
			if isTSV {
				ir.csvError(fmt.Sprintf("mlr: TSV header/data length mismatch %d != %d at filename %s line %d", len(header), len(fields), ir.ctx.FILENAME, lineno))
			} else {
				ir.csvError(fmt.Sprintf("mlr: mlr: CSV header/data length mismatch %d != %d at filename %s row %d.\n", len(header), len(fields), ir.ctx.FILENAME, lineno))
			}
		}
		ir.emit(rec)
	}
}

func isMarkdownSeparator(parts []string) bool {
	for _, p := range parts {
		if len(p) < 3 {
			return false
		}
		for _, c := range p {
			if c != '-' && c != ':' {
				return false
			}
		}
	}
	return true
}

func tsvUnescape(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			switch s[i+1] {
			case 't':
				b.WriteByte('\t')
				i++
				continue
			case 'n':
				b.WriteByte('\n')
				i++
				continue
			case 'r':
				b.WriteByte('\r')
				i++
				continue
			case '\\':
				b.WriteByte('\\')
				i++
				continue
			}
		}
		b.WriteByte(c)
	}
	return b.String()
}

// csvlite: handle simple double-quoted fields
func csvliteDequote(line string, ifs string, fields []string) []string {
	if !strings.Contains(line, "\"") {
		return fields
	}
	out := make([]string, 0, len(fields))
	pos := 0
	n := len(line)
	for pos <= n {
		if pos < n && line[pos] == '"' {
			pos++
			var b strings.Builder
			for pos < n {
				if line[pos] == '"' {
					if pos+1 < n && line[pos+1] == '"' {
						b.WriteByte('"')
						pos += 2
						continue
					}
					pos++
					break
				}
				b.WriteByte(line[pos])
				pos++
			}
			for pos < n && !strings.HasPrefix(line[pos:], ifs) {
				b.WriteByte(line[pos])
				pos++
			}
			out = append(out, b.String())
		} else {
			idx := strings.Index(line[pos:], ifs)
			if idx < 0 {
				out = append(out, line[pos:])
				pos = n + 1
				break
			}
			out = append(out, line[pos:pos+idx])
			pos += idx
		}
		if pos >= n {
			break
		}
		pos += len(ifs)
		if pos == n {
			out = append(out, "")
			break
		}
	}
	return out
}

// ---------------------------------------------------------------- JSON
func (ir *InputReader) readJSON(content string) {
	// strip comments if requested
	if ir.opts.CommentHandling != 0 {
		var b strings.Builder
		for _, line := range strings.SplitAfter(content, "\n") {
			if strings.HasPrefix(line, ir.opts.CommentString) {
				if ir.opts.CommentHandling == 2 {
					l := line
					if !strings.HasSuffix(l, "\n") {
						l += "\n"
					}
					ir.passOut(l)
				}
				continue
			}
			b.WriteString(line)
		}
		content = b.String()
	}
	p := &jsonParser{s: content, line: 1}
	defer func() {
		if r := recover(); r != nil {
			if je, ok := r.(*jsonError); ok {
				panic(&readerError{je.msg})
			}
			panic(r)
		}
	}()
	for {
		if ir.stopped {
			return
		}
		p.skipWS()
		if p.pos >= len(p.s) {
			break
		}
		c := p.s[p.pos]
		if c == '{' {
			v := p.parseObject()
			ir.emit(v.mapval)
		} else if c == '[' {
			jsonInputHadList = true
			p.pos++
			for {
				p.skipWS()
				if p.pos >= len(p.s) {
					p.fail("mlr: JSON parser: unexpected end of input in array")
				}
				if p.s[p.pos] == ']' {
					p.pos++
					break
				}
				if p.s[p.pos] == ',' {
					p.pos++
					continue
				}
				v := p.parseValue()
				if v.mtype == MT_MAP {
					ir.emit(v.mapval)
				} else {
					p.fail(fmt.Sprintf("mlr: valid but unmillerable JSON. Expected map (JSON object); got %s.", typeName(v)))
				}
				if ir.stopped {
					return
				}
			}
		} else {
			v := p.parseValue()
			p.fail(fmt.Sprintf("mlr: valid but unmillerable JSON. Expected map (JSON object); got %s.", typeName(v)))
		}
	}
}

// ---------------------------------------------------------------- gen
func (ir *InputReader) readGen() {
	start := MlrvalFromInferred(ir.opts.GenStart)
	step := MlrvalFromInferred(ir.opts.GenStep)
	stop := MlrvalFromInferred(ir.opts.GenStop)
	cur := start
	stepSign := numCmp(step, MlrvalFromInt(0))
	for {
		if stepSign > 0 && numCmp(cur, stop) > 0 {
			break
		}
		if stepSign < 0 && numCmp(cur, stop) < 0 {
			break
		}
		rec := NewMlrmap()
		rec.PutNew(ir.opts.GenFieldName, cur)
		ir.emit(rec)
		if stepSign == 0 || ir.stopped {
			break
		}
		cur = BinaryPlus(cur, step)
	}
}

func (ir *InputReader) readContent(content string) {
	switch ir.opts.InputFormat {
	case "dkvp":
		ir.readDKVP(content)
	case "nidx":
		ir.readNIDX(content)
	case "xtab":
		ir.readXTAB(content)
	case "csv":
		if ir.opts.IFSRegex != nil {
			ir.readLite(content, "csvlite")
		} else {
			ir.readCSV(content)
		}
	case "csvlite":
		ir.readLite(content, "csvlite")
	case "tsv":
		ir.readLite(content, "tsv")
	case "tsvlite":
		ir.readLite(content, "tsvlite")
	case "pprint":
		ir.readLite(content, "pprint")
	case "markdown":
		ir.readLite(content, "markdown")
	case "json", "jsonl":
		ir.readJSON(content)
	case "yaml":
		ir.readYAML(content)
	case "dcf":
		ir.readDCF(content)
	default:
		ir.readDKVP(content)
	}
}

// Main reading loop: returns error message or "".
func (ir *InputReader) ReadAll(filenames []string) (errmsg string) {
	defer func() {
		if r := recover(); r != nil {
			if re, ok := r.(*readerError); ok {
				errmsg = re.msg
				return
			}
			panic(r)
		}
	}()
	if ir.opts.InputFormat == "gen" {
		ir.ctx.FILENAME = "(stdin)"
		ir.ctx.FILENUM = 1
		ir.readGen()
		return ""
	}
	if len(filenames) == 0 {
		ir.ctx.FILENAME = "(stdin)"
		ir.ctx.FILENUM = 1
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return "mlr: " + err.Error()
		}
		ir.readContent(string(data))
		return ""
	}
	for i, fn := range filenames {
		if ir.stopped {
			break
		}
		ir.ctx.FILENAME = fn
		ir.ctx.FILENUM = int64(i + 1)
		ir.ctx.FNR = 0
		data, err := openInput(fn, ir.opts)
		if err != nil {
			if pe, ok := err.(*os.PathError); ok {
				return fmt.Sprintf("mlr: open %s: %s", pe.Path, pe.Err.Error())
			}
			return "mlr: " + err.Error()
		}
		ir.readContent(string(data))
	}
	return ""
}

