		return &DCFWriter{w: w}
	}
	return &DKVPWriter{w: w}
}

func strwidth(s string) int {
	return utf8.RuneCountInString(s)
}

// ---------------------------------------------------------------- DKVP
type DKVPWriter struct{ w *WriterOptions }

func (dw *DKVPWriter) Write(rec *Mlrmap, out *bufio.Writer) {
	for i, k := range rec.keys {
		if i > 0 {
			out.WriteString(dw.w.OFS)
		}
		out.WriteString(k)
		out.WriteString(dw.w.OPS)
		out.WriteString(rec.vals[i].OutputString())
	}
	out.WriteString(dw.w.ORS)
}
func (dw *DKVPWriter) Finish(out *bufio.Writer) {}

// ---------------------------------------------------------------- NIDX
type NIDXWriter struct{ w *WriterOptions }

func (nw *NIDXWriter) Write(rec *Mlrmap, out *bufio.Writer) {
	for i := range rec.keys {
		if i > 0 {
			out.WriteString(nw.w.OFS)
		}
		out.WriteString(rec.vals[i].OutputString())
	}
	out.WriteString(nw.w.ORS)
}
func (nw *NIDXWriter) Finish(out *bufio.Writer) {}

// ---------------------------------------------------------------- CSV / TSV
type CSVWriter struct {
	w           *WriterOptions
	tsv         bool
	header      []string
	wroteHeader bool
	justWrote   bool
}

func (cw *CSVWriter) quote(s string) string {
	if cw.tsv {
		return tsvEscape(s)
	}
	if cw.w.QuoteAll {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	if s == "" {
		return s
	}
	needs := strings.Contains(s, cw.w.OFS) || strings.ContainsAny(s, "\"\n\r")
	if needs {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	return s
}

func tsvEscape(s string) string {
	if !strings.ContainsAny(s, "\t\n\r") {
		return s
	}
	s = strings.ReplaceAll(s, "\t", "\\t")
	s = strings.ReplaceAll(s, "\n", "\\n")
	s = strings.ReplaceAll(s, "\r", "\\r")
	return s
}

func (cw *CSVWriter) Write(rec *Mlrmap, out *bufio.Writer) {
	if cw.header == nil {
		if !cw.tsv && len(cw.w.OFS) != 1 {
			fmt.Fprintln(os.Stderr, "mlr: for CSV, OFS can only be a single character")
			out.Flush()
			os.Exit(1)
		}
		cw.header = rec.KeysCopy()
		if !cw.w.HeaderlessOutput {
			for i, k := range cw.header {
				if i > 0 {
					out.WriteString(cw.w.OFS)
				}
				out.WriteString(cw.quote(k))
			}
			out.WriteString(cw.w.ORS)
		}
		cw.writeData(rec, out, len(rec.keys))
		return
	}
	if rec.SameKeys(cw.header) {
		cw.writeData(rec, out, len(rec.keys))
		return
	}
	n := len(rec.keys)
	if len(cw.header) < n {
		n = len(cw.header)
	}
	ok := true
	for i := 0; i < n; i++ {
		if rec.keys[i] != cw.header[i] {
			ok = false
			break
		}
	}
	if !ok {
		out.Flush()
		kind := "CSV"
		if cw.tsv {
			kind = "TSV"
		}
		fmt.Fprintf(os.Stderr, "mlr: %s schema change: first keys \"%s\"; current keys \"%s\"\n", kind,
			strings.Join(cw.header, cw.w.OFS), strings.Join(rec.keys, cw.w.OFS))
		fmt.Fprintf(os.Stderr, "mlr: exiting due to data error\n")
		os.Exit(1)
	}
	if len(rec.keys) < len(cw.header) {
		for i := range cw.header {
			if i > 0 {
				out.WriteString(cw.w.OFS)
			}
			if i < len(rec.keys) {
				out.WriteString(cw.quote(rec.vals[i].OutputString()))
			}
		}
		out.WriteString(cw.w.ORS)
		return
	}
	cw.writeData(rec, out, len(rec.keys))
}

func (cw *CSVWriter) writeData(rec *Mlrmap, out *bufio.Writer, n int) {
	for i := 0; i < n; i++ {
		if i > 0 {
			out.WriteString(cw.w.OFS)
		}
		out.WriteString(cw.quote(rec.vals[i].OutputString()))
	}
	out.WriteString(cw.w.ORS)
}

func (cw *CSVWriter) Finish(out *bufio.Writer) {}

// ---------------------------------------------------------------- CSV-lite / TSV-lite
type CSVLiteWriter struct {
	w      *WriterOptions
	tsv    bool
	header []string
	count  int
}

func (cw *CSVLiteWriter) q(s string) string {
	if cw.tsv {
		return tsvEscape(s)
	}
	if cw.w.QuoteAll {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	if s != "" && (strings.Contains(s, cw.w.OFS) || strings.ContainsAny(s, "\"\n\r")) {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	return s
}

func (cw *CSVLiteWriter) Write(rec *Mlrmap, out *bufio.Writer) {
	if rec.Len() == 0 {
		return
	}
	if cw.header == nil || !rec.SameKeys(cw.header) {
		if cw.header != nil {
			out.WriteString(cw.w.ORS)
		}
		cw.header = rec.KeysCopy()
		if !cw.w.HeaderlessOutput {
			for i, k := range cw.header {
				if i > 0 {
					out.WriteString(cw.w.OFS)
				}
				out.WriteString(cw.q(k))
			}
			out.WriteString(cw.w.ORS)
		}
	}
	for i := range rec.keys {
		if i > 0 {
			out.WriteString(cw.w.OFS)
		}
		out.WriteString(cw.q(rec.vals[i].OutputString()))
	}
	out.WriteString(cw.w.ORS)
}
func (cw *CSVLiteWriter) Finish(out *bufio.Writer) {}

// ---------------------------------------------------------------- JSON
type JSONWriter struct {
	w     *WriterOptions
	count int
}

func (jw *JSONWriter) Write(rec *Mlrmap, out *bufio.Writer) {
	mv := MlrvalFromMap(rec)
	var b strings.Builder
	if jw.w.JSONVStack {
		jsonEncodeMultiline(&b, mv, 0, jw.w.JVQuoteAll)
	} else {
		jsonEncodeSingleLine(&b, mv, jw.w.JVQuoteAll)
	}
	if jw.w.JSONListWrap {
		if jw.count == 0 {
			out.WriteString("[\n")
		} else {
			out.WriteString(",\n")
		}
		out.WriteString(b.String())
	} else {
		out.WriteString(b.String())
		out.WriteString("\n")
	}
	jw.count++
}

func (jw *JSONWriter) Finish(out *bufio.Writer) {
	if jw.w.JSONListWrap {
		if jw.count > 0 {
			out.WriteString("\n]\n")
		} else if jsonInputHadList {
			out.WriteString("[\n]\n")
		}
	}
}

// ---------------------------------------------------------------- XTAB
type XTABWriter struct {
	w     *WriterOptions
	count int
}

func (xw *XTABWriter) Write(rec *Mlrmap, out *bufio.Writer) {
	if xw.count > 0 {
		out.WriteString("\n")
	}
	xw.count++
	if rec.Len() == 0 {
		return
	}
	maxk := 0
	for _, k := range rec.keys {
		if w := strwidth(k); w > maxk {
			maxk = w
		}
	}
	vals := make([]string, len(rec.vals))
	maxv := 0
	for i, v := range rec.vals {
		vals[i] = v.OutputString()
		if xw.w.XvRight {
			if w := strwidth(vals[i]); w > maxv {
				maxv = w
			}
		}
	}
	ops := xw.w.OPS
	for i, k := range rec.keys {
		out.WriteString(k)
		if len(ops) == 1 {
			pad := maxk - strwidth(k) + 1
			for j := 0; j < pad; j++ {
				out.WriteString(ops)
			}
		} else {
			out.WriteString(ops)
		}
		if xw.w.XvRight {
			pad := maxv - strwidth(vals[i])
			for j := 0; j < pad; j++ {
				out.WriteString(" ")
			}
		}
		out.WriteString(vals[i])
		out.WriteString("\n")
	}
}
func (xw *XTABWriter) Finish(out *bufio.Writer) {}

// ---------------------------------------------------------------- PPRINT
type PPRINTWriter struct {
	w       *WriterOptions
	batch   []*Mlrmap
	keys    []string
	nblocks int
}

func (pw *PPRINTWriter) Write(rec *Mlrmap, out *bufio.Writer) {
	if rec.Len() == 0 {
		return
	}
	if pw.keys != nil && !rec.SameKeys(pw.keys) {
		pw.flush(out)
	}
	if pw.keys == nil {
		pw.keys = rec.KeysCopy()
	}
	pw.batch = append(pw.batch, rec)
}

func (pw *PPRINTWriter) flush(out *bufio.Writer) {
	if len(pw.batch) == 0 {
		pw.keys = nil
		return
	}
	if pw.nblocks > 0 {
		out.WriteString("\n")
	}
	pw.nblocks++
	nf := len(pw.keys)
	widths := make([]int, nf)
	cells := make([][]string, len(pw.batch))
	for j, k := range pw.keys {
		widths[j] = strwidth(k)
	}
	barred := pw.w.BarredOutput
	for i, rec := range pw.batch {
		row := make([]string, nf)
		for j := 0; j < nf && j < len(rec.vals); j++ {
			s := rec.vals[j].OutputString()
			if s == "" && !barred {
				s = "-"
			}
			row[j] = s
			if w := strwidth(s); w > widths[j] {
				widths[j] = w
			}
		}
		cells[i] = row
	}
	if barred {
		pw.writeBarred(out, widths, cells)
	} else {
		ofs := pw.w.OFS
		if !pw.w.HeaderlessOutput {
			pw.writeRow(out, pw.keys, widths, ofs)
		}
		for _, row := range cells {
			pw.writeRow(out, row, widths, ofs)
		}
	}
	pw.batch = nil
	pw.keys = nil
}

func (pw *PPRINTWriter) writeRow(out *bufio.Writer, row []string, widths []int, ofs string) {
	n := len(row)
	for j, s := range row {
		pad := widths[j] - strwidth(s)
		if pw.w.RightAlign {
			for k := 0; k < pad; k++ {
				out.WriteString(ofs)
			}
			out.WriteString(s)
			if j < n-1 {
				out.WriteString(ofs)
			}
		} else {
			out.WriteString(s)
			if j < n-1 {
				for k := 0; k < pad; k++ {
					out.WriteString(ofs)
				}
				out.WriteString(ofs)
			}
		}
	}
	out.WriteString(pw.w.ORS)
}

func (pw *PPRINTWriter) writeBarred(out *bufio.Writer, widths []int, cells [][]string) {
	var sep strings.Builder
	sep.WriteString("+")
	for _, w := range widths {
		sep.WriteString(strings.Repeat("-", w+2))
		sep.WriteString("+")
	}
	sepLine := sep.String()
	writeLine := func(row []string) {
		out.WriteString("|")
		for j, s := range row {
			pad := widths[j] - strwidth(s)
			out.WriteString(" ")
			if pw.w.RightAlign {
				out.WriteString(strings.Repeat(" ", pad))
				out.WriteString(s)
			} else {
				out.WriteString(s)
				out.WriteString(strings.Repeat(" ", pad))
			}
			out.WriteString(" |")
		}
		out.WriteString(pw.w.ORS)
	}
	out.WriteString(sepLine)
	out.WriteString(pw.w.ORS)
	if !pw.w.HeaderlessOutput {
		writeLine(pw.keys)
		out.WriteString(sepLine)
		out.WriteString(pw.w.ORS)
	}
	for _, row := range cells {
		writeLine(row)
	}
	out.WriteString(sepLine)
	out.WriteString(pw.w.ORS)
}

func (pw *PPRINTWriter) Finish(out *bufio.Writer) {
	pw.flush(out)
}

// ---------------------------------------------------------------- Markdown
type MarkdownWriter struct {
	w      *WriterOptions
	header []string
	count  int
}

func mdEscape(s string) string {
	return strings.ReplaceAll(s, "|", "\\|")
}

func (mw *MarkdownWriter) Write(rec *Mlrmap, out *bufio.Writer) {
	if rec.Len() == 0 {
		return
	}
	if mw.header == nil || !rec.SameKeys(mw.header) {
		if mw.header != nil {
			out.WriteString("\n")
		}
		mw.header = rec.KeysCopy()
		out.WriteString("|")
		for _, k := range mw.header {
			out.WriteString(" ")
			out.WriteString(mdEscape(k))
			out.WriteString(" |")
		}
		out.WriteString("\n")
		out.WriteString("|")
		for range mw.header {
			out.WriteString(" --- |")
		}
		out.WriteString("\n")
	}
	out.WriteString("|")
	for _, v := range rec.vals {
		out.WriteString(" ")
		out.WriteString(mdEscape(v.OutputString()))
		out.WriteString(" |")
	}
	out.WriteString("\n")
}
func (mw *MarkdownWriter) Finish(out *bufio.Writer) {}

// ---------------------------------------------------------------- DCF
type DCFWriter struct {
	w     *WriterOptions
	count int
}

func (dw *DCFWriter) Write(rec *Mlrmap, out *bufio.Writer) {
	for i, k := range rec.keys {
		out.WriteString(k)
		out.WriteString(": ")
		out.WriteString(rec.vals[i].OutputString())
		out.WriteString("\n")
	}
	out.WriteString("\n")
}
func (dw *DCFWriter) Finish(out *bufio.Writer) {}
