type DKVPWriter struct{ w *WriterOptions }

func (dw *DKVPWriter) Write(rec *Mlrmap, out *bufio.Writer) {
	for i, k := range rec.keys {
		if i > 0 {
			out.WriteString(dw.w.OFS)
		}
		out.WriteString(k)
		out.WriteString(dw.w.OPS)
