// ---------------------------------------------------------------- CSV / TSV
type CSVWriter struct {
	w           *WriterOptions
	tsv         bool
	header      []string
	wroteHeader bool
	justWrote   bool
}

func (cw *CSVWriter) quote(s string) string {
	if cw.tsv {
		return tsvEscape(s)
	}
	if cw.w.QuoteAll {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	if s == "" {
		return s
	}
	needs := strings.Contains(s, cw.w.OFS) || strings.ContainsAny(s, "\"\n\r")
	if needs {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	return s
}

func tsvEscape(s string) string {
	if !strings.ContainsAny(s, "\t\n\r") {
		return s
	}
	s = strings.ReplaceAll(s, "\t", "\\t")
	s = strings.ReplaceAll(s, "\n", "\\n")
	s = strings.ReplaceAll(s, "\r", "\\r")
	return s
}

func (cw *CSVWriter) Write(rec *Mlrmap, out *bufio.Writer) {
	if cw.header == nil {
		if !cw.tsv && len(cw.w.OFS) != 1 {
			fmt.Fprintln(os.Stderr, "mlr: for CSV, OFS can only be a single character")
			out.Flush()
			os.Exit(1)
		}
		cw.header = rec.KeysCopy()
		if !cw.w.HeaderlessOutput {
			for i, k := range cw.header {
				if i > 0 {
					out.WriteString(cw.w.OFS)
				}
				out.WriteString(cw.quote(k))
			}
			out.WriteString(cw.w.ORS)
		}
		cw.writeData(rec, out, len(rec.keys))
		return
	}
	if rec.SameKeys(cw.header) {
		cw.writeData(rec, out, len(rec.keys))
		return
	}
	n := len(rec.keys)
	if len(cw.header) < n {
		n = len(cw.header)
	}
	ok := true
	for i := 0; i < n; i++ {
		if rec.keys[i] != cw.header[i] {
			ok = false
			break
		}
	}
	if !ok {
		out.Flush()
		kind := "CSV"
		if cw.tsv {
			kind = "TSV"
		}
		fmt.Fprintf(os.Stderr, "mlr: %s schema change: first keys \"%s\"; current keys \"%s\"\n", kind,
			strings.Join(cw.header, cw.w.OFS), strings.Join(rec.keys, cw.w.OFS))
		fmt.Fprintf(os.Stderr, "mlr: exiting due to data error\n")
		os.Exit(1)
	}
	if len(rec.keys) < len(cw.header) {
		for i := range cw.header {
			if i > 0 {
				out.WriteString(cw.w.OFS)
			}
			if i < len(rec.keys) {
				out.WriteString(cw.quote(rec.vals[i].OutputString()))
			}
		}
		out.WriteString(cw.w.ORS)
		return
	}
	cw.writeData(rec, out, len(rec.keys))
}

func (cw *CSVWriter) writeData(rec *Mlrmap, out *bufio.Writer, n int) {
	for i := 0; i < n; i++ {
		if i > 0 {
			out.WriteString(cw.w.OFS)
		}
		out.WriteString(cw.quote(rec.vals[i].OutputString()))
	}
	out.WriteString(cw.w.ORS)
