package main

import (
	"bufio"
	"fmt"
	"os"
)

type Transformer interface {
	Process(rec *Mlrmap, ctx *Context, next *ChainLink)
	End(ctx *Context, next *ChainLink)
}

type ChainLink struct {
	t      Transformer
	next   *ChainLink
	writer RecordWriter
	out    *bufio.Writer
	ended  bool
}

func (c *ChainLink) Put(rec *Mlrmap, ctx *Context) {
	if c.t != nil {
		c.t.Process(rec, ctx, c.next)
	} else {
		c.writer.Write(rec, c.out)
		if flushEveryRecord {
			c.out.Flush()
		}
	}
}

func (c *ChainLink) PutString(s string) {
	stdoutWriter.WriteString(s)
}

func (c *ChainLink) End(ctx *Context) {
	if c.ended {
		return
	}
	c.ended = true
	if c.t != nil {
		c.t.End(ctx, c.next)
		c.next.End(ctx)
	} else {
		c.writer.Finish(c.out)
	}
}

var stdoutWriter *bufio.Writer
var flushEveryRecord = false

func buildChain(ts []Transformer, writer RecordWriter, out *bufio.Writer) *ChainLink {
	tail := &ChainLink{writer: writer, out: out}
	head := tail
	for i := len(ts) - 1; i >= 0; i-- {
		head = &ChainLink{t: ts[i], next: head, out: out}
	}
	return head
}

// Pass-through helper transformer base
type passThrough struct{}

func (p *passThrough) End(ctx *Context, next *ChainLink) {}

func fatalf(format string, args ...interface{}) {
	if stdoutWriter != nil {
		stdoutWriter.Flush()
	}
	fmt.Fprintf(os.Stderr, format, args...)
	os.Exit(1)
}

// ---------------------------------------------------------------- auto flatten / unflatten

type FlattenTransformer struct {
	sep    string
	fields map[string]bool
}

func (t *FlattenTransformer) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	flattenRecord(rec, t.sep, t.fields)
	next.Put(rec, ctx)
