package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

const MLR_VERSION = "6.16.0"

func mainUsageShort(f *os.File) {
	fmt.Fprint(f, `Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}

If zero file names are provided, standard input is read, e.g.
  mlr --csv sort -f shape example.csv

Output of one verb may be chained as input to another using "then", e.g.
  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv

Please see 'mlr help topics' for more information.
Please also see https://miller.readthedocs.io
`)
}

var mainOptions *Options

func main() {
	args := os.Args
	stdoutWriter = bufio.NewWriterSize(os.Stdout, 65536)
	defer stdoutWriter.Flush()

	args = expandArgsFile(args)

	if len(args) < 2 {
		mainUsageShort(os.Stderr)
		os.Exit(1)
	}
	if handled := maybeAuxent(args); handled {
		stdoutWriter.Flush()
		os.Exit(0)
	}

	opts := defaultOptions()
	mainOptions = opts
	i := parseMainFlags(args, opts)
	if i >= len(args) {
		fmt.Fprintln(os.Stderr, "mlr: no verb supplied.")
		mainUsageShort(os.Stderr)
		os.Exit(1)
	}

	finalizeReaderOptions(&opts.R)
	finalizeWriterOptions(&opts.W)
	ofmtGlobal = opts.W.OFMT
	if opts.HaveSeed {
		seedRandom(opts.Seed)
	} else {
		seedRandomFromTime()
	}

	transformers, ni := parseVerbChain(args, i, opts)
	for _, a := range args[ni:] {
		opts.FileNames = append(opts.FileNames, a)
	}

	if opts.InPlace {
		runInPlace(opts, args, i)
		return
	}

	rc := runMain(opts, transformers, stdoutWriter)
	stdoutWriter.Flush()
	os.Exit(rc)
}

func expandArgsFile(args []string) []string {
	if len(args) >= 3 && (args[1] == "-s" || args[1] == "--s-no-comment-strip") {
		data, err := os.ReadFile(args[2])
		if err != nil {
			fmt.Fprintf(os.Stderr, "mlr: cannot read %s\n", args[2])
			os.Exit(1)
		}
		lines := strings.Split(string(data), "\n")
		var words []string
		for _, line := range lines {
			if args[1] == "-s" {
				if idx := strings.Index(line, "#"); idx >= 0 {
					line = line[:idx]
				}
			}
			words = append(words, shellSplit(line)...)
		}
		if len(words) > 0 && (words[0] == "mlr" || strings.HasSuffix(words[0], "/mlr")) {
			words = words[1:]
		}
		out := []string{args[0]}
		out = append(out, words...)
		out = append(out, args[3:]...)
		return out
	}
	return args
}

func shellSplit(s string) []string {
	var out []string
	var cur strings.Builder
	inS, inD, have := false, false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inS {
			if c == '\'' {
				inS = false
			} else {
				cur.WriteByte(c)
			}
			continue
		}
		if inD {
			if c == '"' {
				inD = false
			} else if c == '\\' && i+1 < len(s) {
				i++
				cur.WriteByte(s[i])
			} else {
				cur.WriteByte(c)
			}
			continue
		}
		switch c {
		case '\'':
			inS = true
			have = true
		case '"':
			inD = true
			have = true
		case ' ', '\t', '\r':
			if have || cur.Len() > 0 {
				out = append(out, cur.String())
				cur.Reset()
				have = false
			}
		case '\\':
			if i+1 < len(s) {
				i++
				cur.WriteByte(s[i])
			}
		default:
			cur.WriteByte(c)
		}
	}
	if have || cur.Len() > 0 {
		out = append(out, cur.String())
	}
	return out
}

func parseVerbChain(args []string, i int, opts *Options) ([]Transformer, int) {
	var ts []Transformer
	for {
		if i >= len(args) {
			fmt.Fprintln(os.Stderr, "mlr: no verb supplied.")
			mainUsageShort(os.Stderr)
			os.Exit(1)
		}
		verb := args[i]
		spec := lookupVerb(verb)
		if spec == nil {
			fmt.Fprintf(os.Stderr, "mlr: verb \"%s\" not found. Please use \"mlr -l\" for a list.\n", verb)
			os.Exit(1)
		}
		t, ni := spec.parse(args, i, opts)
		ts = append(ts, t)
		i = ni
		if i < len(args) && args[i] == "then" {
			i++
			if i >= len(args) {
				fmt.Fprintln(os.Stderr, "mlr: 'then' must have a verb after it.")
				os.Exit(1)
			}
			continue
		}
		break
	}
	return ts, i
}

func isJSONFormat(f string) bool {
	return f == "json" || f == "jsonl"
}

func appendAutoFlatten(ts []Transformer, opts *Options) []Transformer {
	if !isJSONFormat(opts.W.OutputFormat) {
		if opts.W.AutoFlatten {
			ts = append(ts, &FlattenTransformer{sep: opts.W.FlatSep})
		}
	} else {
		if opts.W.AutoUnflatten && !isJSONFormat(opts.R.InputFormat) {
			ts = append(ts, &UnflattenTransformer{sep: opts.W.FlatSep})
		}
	}
	return ts
}

func runMain(opts *Options, transformers []Transformer, out *bufio.Writer) int {
	ts := appendAutoFlatten(transformers, opts)
	writer := newRecordWriter(&opts.W)
	flushEveryRecord = opts.W.FlushEvery
	chain := buildChain(ts, writer, out)

	var lastCtx Context
	lastCtx.FILENAME = "(stdin)"
	ir := &InputReader{opts: &opts.R}
	ir.passOut = func(s string) { out.WriteString(s) }
	ir.sink = func(rec *Mlrmap, ctx *Context) {
		lastCtx = *ctx
		chain.Put(rec, ctx)
		if stopReading {
			ir.stopped = true
		}
	}
	errmsg := ""
	if !opts.NoInput {
		errmsg = ir.ReadAll(opts.FileNames)
		if ir.ctx.FILENAME != "" {
			lastCtx.FILENAME = ir.ctx.FILENAME
			lastCtx.FILENUM = ir.ctx.FILENUM
			lastCtx.NR = ir.ctx.NR
			lastCtx.FNR = ir.ctx.FNR
		}
	}
	endCtx := lastCtx
	chain.End(&endCtx)
	closeAllRedirects()
	if errmsg != "" {
		out.Flush()
		fmt.Fprintln(os.Stderr, errmsg)
		return 1
	}
	return 0
}

// set by transformers like head when no more input is needed
var stopReading = false

func runInPlace(opts *Options, args []string, verbIndex int) {
	files := opts.FileNames
	if len(files) == 0 {
		fmt.Fprintln(os.Stderr, "mlr: -I option (in-place operation) requires input files.")
		os.Exit(1)
	}
	for _, fn := range files {
		if _, err := os.Stat(fn); err != nil {
			fmt.Fprintf(os.Stderr, "mlr: open %s: no such file or directory.\n", fn)
			os.Exit(1)
		}
		// re-parse the verb chain fresh for each file
		o2 := *opts
		o2.FileNames = []string{fn}
		ts, _ := parseVerbChain(args, verbIndex, &o2)
		tmp := fn + ".mlr-tmp"
		f, err := os.Create(tmp)
		if err != nil {
			fmt.Fprintf(os.Stderr, "mlr: %v\n", err)
			os.Exit(1)
		}
		w := bufio.NewWriter(f)
		jsonInputHadList = false
		rc := runMain(&o2, ts, w)
		w.Flush()
		f.Close()
		if rc != 0 {
			os.Remove(tmp)
			os.Exit(rc)
		}
		os.Rename(tmp, fn)
	}
}
EOF
echo ok"}

