		c := s[i]
		if inS {
			if c == '\'' {
				inS = false
			} else {
				cur.WriteByte(c)
			}
			continue
		}
		if inD {
			if c == '"' {
				inD = false
			} else if c == '\\' && i+1 < len(s) {
				i++
				cur.WriteByte(s[i])
			} else {
				cur.WriteByte(c)
			}
			continue
		}
		switch c {
		case '\'':
			inS = true
			have = true
		case '"':
			inD = true
			have = true
		case ' ', '\t', '\r':
			if have || cur.Len() > 0 {
				out = append(out, cur.String())
				cur.Reset()
				have = false
			}
		case '\\':
			if i+1 < len(s) {
				i++
				cur.WriteByte(s[i])
			}
		default:
			cur.WriteByte(c)
		}
	}
	if have || cur.Len() > 0 {
		out = append(out, cur.String())
	}
	return out
}

func parseVerbChain(args []string, i int, opts *Options) ([]Transformer, int) {
	var ts []Transformer
	for {
		if i >= len(args) {
			fmt.Fprintln(os.Stderr, "mlr: no verb supplied.")
			mainUsageShort(os.Stderr)
			os.Exit(1)
		}
		verb := args[i]
		spec := lookupVerb(verb)
		if spec == nil {
			fmt.Fprintf(os.Stderr, "mlr: verb \"%s\" not found. Please use \"mlr -l\" for a list.\n", verb)
			os.Exit(1)
		}
		t, ni := spec.parse(args, i, opts)
		ts = append(ts, t)
		i = ni
		if i < len(args) && args[i] == "then" {
			i++
			if i >= len(args) {
				fmt.Fprintln(os.Stderr, "mlr: 'then' must have a verb after it.")
				os.Exit(1)
			}
			continue
		}
		break
	}
	return ts, i
}

func isJSONFormat(f string) bool {
	return f == "json" || f == "jsonl"
}

func appendAutoFlatten(ts []Transformer, opts *Options) []Transformer {
	if !isJSONFormat(opts.W.OutputFormat) {
		if opts.W.AutoFlatten {
			ts = append(ts, &FlattenTransformer{sep: opts.W.FlatSep})
		}
	} else {
		if opts.W.AutoUnflatten && !isJSONFormat(opts.R.InputFormat) {
			ts = append(ts, &UnflattenTransformer{sep: opts.W.FlatSep})
		}
	}
	return ts
}

func runMain(opts *Options, transformers []Transformer, out *bufio.Writer) int {
	ts := appendAutoFlatten(transformers, opts)
	writer := newRecordWriter(&opts.W)
	flushEveryRecord = opts.W.FlushEvery
	chain := buildChain(ts, writer, out)

	var lastCtx Context
	lastCtx.FILENAME = "(stdin)"
	ir := &InputReader{opts: &opts.R}
	ir.passOut = func(s string) { out.WriteString(s) }
	ir.sink = func(rec *Mlrmap, ctx *Context) {
		lastCtx = *ctx
		chain.Put(rec, ctx)
		if stopReading {
			ir.stopped = true
		}
	}
	errmsg := ""
	if !opts.NoInput {
		errmsg = ir.ReadAll(opts.FileNames)
		if ir.ctx.FILENAME != "" {
			lastCtx.FILENAME = ir.ctx.FILENAME
			lastCtx.FILENUM = ir.ctx.FILENUM
			lastCtx.NR = ir.ctx.NR
			lastCtx.FNR = ir.ctx.FNR
		}
	}
	endCtx := lastCtx
	chain.End(&endCtx)
	closeAllRedirects()
	if errmsg != "" {
		out.Flush()
		fmt.Fprintln(os.Stderr, errmsg)
		return 1
	}
	return 0
}

// set by transformers like head when no more input is needed
var stopReading = false

func runInPlace(opts *Options, args []string, verbIndex int) {
	files := opts.FileNames
	if len(files) == 0 {
		fmt.Fprintln(os.Stderr, "mlr: -I option (in-place operation) requires input files.")
		os.Exit(1)
	}
	for _, fn := range files {
		if _, err := os.Stat(fn); err != nil {
			fmt.Fprintf(os.Stderr, "mlr: open %s: no such file or directory.\n", fn)
			os.Exit(1)
		}
		// re-parse the verb chain fresh for each file
		o2 := *opts
		o2.FileNames = []string{fn}
		ts, _ := parseVerbChain(args, verbIndex, &o2)
		tmp := fn + ".mlr-tmp"
		f, err := os.Create(tmp)
		if err != nil {
			fmt.Fprintf(os.Stderr, "mlr: %v\n", err)
			os.Exit(1)
		}
		w := bufio.NewWriter(f)
		jsonInputHadList = false
		rc := runMain(&o2, ts, w)
		w.Flush()
		f.Close()
		if rc != 0 {
			os.Remove(tmp)
			os.Exit(rc)
		}
		os.Rename(tmp, fn)
	}
}
EOF
echo ok

