func compileMillerRegex(s string) *regexp.Regexp {
	ci := false
	if len(s) >= 2 && strings.HasPrefix(s, "\"") {
		if strings.HasSuffix(s, "\"i") && len(s) >= 3 {
			s = s[1 : len(s)-2]
			ci = true
		} else if strings.HasSuffix(s, "\"") {
			s = s[1 : len(s)-1]
		}
	}
	if ci {
		s = "(?i)" + s
	}
	re, err := regexp.Compile(s)
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr: could not compile regex \"%s\"\n", s)
		os.Exit(1)
	}
	return re
}

