// ---------------------------------------------------------------- cat
type CatT struct {
	doNum    bool
	name     string
	groupBy  []string
	filename bool
	filenum  bool
	counter  int64
	counts   map[string]int64
}

func parseCat(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("cat", args, i)
	t := &CatT{name: "n", counts: map[string]int64{}}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-n":
			t.doNum = true
		case "-N":
			t.doNum = true
			t.name = va.str(f)
		case "-g":
			t.groupBy = va.list(f)
		case "--filename":
			t.filename = true
		case "--filenum":
			t.filenum = true
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}

func (t *CatT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if t.doNum {
		if t.groupBy == nil {
			t.counter++
			rec.PutAtStart(t.name, MlrvalFromInt(t.counter))
		} else {
			key, ok := groupingKey(rec, t.groupBy)
			if !ok {
				return
			}
			t.counts[key]++
			rec.PutAtStart(t.name, MlrvalFromInt(t.counts[key]))
		}
	} else if t.groupBy != nil {
		if _, ok := groupingKey(rec, t.groupBy); !ok {
			return
		}
	}
	if t.filename {
		rec.PutAtStart("filename", MlrvalFromString(ctx.FILENAME))
	}
	if t.filenum {
		rec.PutAtStart("filenum", MlrvalFromInt(ctx.FILENUM))
	}
	next.Put(rec, ctx)
}
func (t *CatT) End(ctx *Context, next *ChainLink) {}

