	reverse   bool
}

func parseSortWithinRecords(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("sort-within-records", args, i)
	t := &SortWithinRecordsT{}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-r":
			t.recursive = true
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}

func sortMapByKeys(m *Mlrmap, recursive bool, reverse bool) {
	idx := make([]int, len(m.keys))
	for i := range idx {
		idx[i] = i
	}
	sort.SliceStable(idx, func(a, b int) bool {
		if reverse {
			return m.keys[idx[a]] > m.keys[idx[b]]
		}
		return m.keys[idx[a]] < m.keys[idx[b]]
	})
	nk := make([]string, len(idx))
	nv := make([]*Mlrval, len(idx))
	for i, j := range idx {
		nk[i] = m.keys[j]
		nv[i] = m.vals[j]
		if recursive && nv[i].mtype == MT_MAP {
			sortMapByKeys(nv[i].mapval, true, reverse)
		}
	}
	m.keys = nk
	m.vals = nv
}

func (t *SortWithinRecordsT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	sortMapByKeys(rec, t.recursive, t.reverse)
	next.Put(rec, ctx)
}
func (t *SortWithinRecordsT) End(ctx *Context, next *ChainLink) {}

