// ---------------------------------------------------------------- rename
type renamePair struct {
	old   string
	new   string
	re    *regexp.Regexp
}

type RenameT struct {
	pairs   []renamePair
	doRegex bool
	global  bool
}

func parseRename(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("rename", args, i)
	t := &RenameT{}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-r":
			t.doRegex = true
		case "-g":
			t.doRegex = true
			t.global = true
		default:
			va.unrecognized(f)
		}
	}
	names := splitFieldNames(va.positional("old/new name pairs"))
	if len(names)%2 != 0 {
		fmt.Fprintf(os.Stderr, "mlr rename: field-name list must have even length.\n")
		os.Exit(1)
	}
	for j := 0; j < len(names); j += 2 {
		p := renamePair{old: names[j], new: names[j+1]}
		if t.doRegex {
			p.re = compileMillerRegex(names[j])
		}
		t.pairs = append(t.pairs, p)
	}
	return t, va.i
}

func (t *RenameT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if !t.doRegex {
		for _, p := range t.pairs {
			if rec.Has(p.old) {
				rec.Rename(p.old, p.new)
			}
		}
		next.Put(rec, ctx)
		return
	}
	for _, p := range t.pairs {
		keys := rec.KeysCopy()
		for _, k := range keys {
			if !p.re.MatchString(k) {
				continue
			}
			var nk string
			if t.global {
				nk = p.re.ReplaceAllString(k, convertBackrefs(p.new))
			} else {
				nk = regexSubOnce(p.re, k, p.new)
			}
			if nk != k {
				rec.Rename(k, nk)
			}
		}
	}
	next.Put(rec, ctx)
}
func (t *RenameT) End(ctx *Context, next *ChainLink) {}

// convert "\1" style to "${1}" for Go regexp replacement
func convertBackrefs(s string) string {
	if !strings.Contains(s, "\\") && !strings.Contains(s, "$") {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '$' {
			b.WriteString("$$")
			continue
		}
		if c == '\\' && i+1 < len(s) && s[i+1] >= '0' && s[i+1] <= '9' {
			b.WriteString("${")
			b.WriteByte(s[i+1])
			b.WriteString("}")
			i++
			continue
		}
		b.WriteByte(c)
	}
	return b.String()
}

// Replace first match with replacement supporting \1..\9
func regexSubOnce(re *regexp.Regexp, input string, replacement string) string {
	loc := re.FindStringSubmatchIndex(input)
	if loc == nil {
		return input
	}
	var dst []byte
	dst = re.ExpandString(dst, convertBackrefs(replacement), input, loc)
	return input[:loc[0]] + string(dst) + input[loc[1]:]
}

// ---------------------------------------------------------------- reorder
type ReorderT struct {
	fields   []string
	toEnd    bool
	regexes  []*regexp.Regexp
	before   string
	after    string
}

func parseReorder(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("reorder", args, i)
	t := &ReorderT{}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = va.list(f)
		case "-r":
			for _, s := range va.list(f) {
				t.regexes = append(t.regexes, compileMillerRegex(s))
			}
		case "-e":
			t.toEnd = true
		case "-b":
			t.before = va.str(f)
		case "-a":
			t.after = va.str(f)
		default:
			va.unrecognized(f)
		}
	}
	if t.fields == nil && t.regexes == nil {
		va.usageError("option -f is required.")
	}
	return t, va.i
}

func (t *ReorderT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if t.regexes != nil {
		var matched []string
		for _, k := range rec.keys {
			for _, re := range t.regexes {
				if re.MatchString(k) {
					matched = append(matched, k)
					break
				}
			}
		}
		if t.toEnd {
			for _, k := range matched {
				v := rec.Get(k)
				rec.PutAtEndMoving(k, v)
			}
		} else {
			for j := len(matched) - 1; j >= 0; j-- {
				k := matched[j]
				v := rec.Get(k)
				rec.PutAtStartMoving(k, v)
			}
		}
		next.Put(rec, ctx)
		return
	}
	if t.before != "" || t.after != "" {
		pivot := t.before
		if pivot == "" {
			pivot = t.after
		}
		if !rec.Has(pivot) {
			next.Put(rec, ctx)
			return
		}
		var moved []string
		var movedVals []*Mlrval
		for _, f := range t.fields {
			if f == pivot {
				continue
			}
			v := rec.Get(f)
			if v != nil {
				moved = append(moved, f)
				movedVals = append(movedVals, v)
				rec.Remove(f)
			}
		}
		idx := rec.find(pivot)
		if t.after != "" {
			idx++
		}
		for j := range moved {
			rec.InsertAt(idx+j, moved[j], movedVals[j])
		}
		next.Put(rec, ctx)
		return
	}
	if t.toEnd {
		for _, f := range t.fields {
			v := rec.Get(f)
			if v != nil {
				rec.PutAtEndMoving(f, v)
			}
		}
	} else {
		for j := len(t.fields) - 1; j >= 0; j-- {
			f := t.fields[j]
			v := rec.Get(f)
			if v != nil {
				rec.PutAtStartMoving(f, v)
			}
		}
	}
	next.Put(rec, ctx)
}
func (t *ReorderT) End(ctx *Context, next *ChainLink) {}

// ---------------------------------------------------------------- cut
type CutT struct {
	fields     []string
	fieldSet   map[string]bool
	ordered    bool
	complement bool
	regexes    []*regexp.Regexp
}

func parseCut(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("cut", args, i)
	t := &CutT{}
	doRegex := false
	var fields []string
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			fields = va.list(f)
		case "-o":
			t.ordered = true
		case "-x", "--complement":
			t.complement = true
		case "-r":
			doRegex = true
		default:
			va.unrecognized(f)
		}
	}
	if fields == nil {
		fmt.Fprintf(os.Stderr, "mlr cut: option -f is required.\n")
		fmt.Fprintf(os.Stderr, "Please run 'mlr cut --help' for usage information.\n")
		os.Exit(1)
	}
	if doRegex {
		for _, s := range fields {
			t.regexes = append(t.regexes, compileMillerRegex(s))
		}
	} else {
		t.fields = fields
		t.fieldSet = stringSet(fields)
	}
	return t, va.i
}

func (t *CutT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if t.regexes != nil {
		out := NewMlrmap()
		for i, k := range rec.keys {
			m := false
			for _, re := range t.regexes {
				if re.MatchString(k) {
					m = true
					break
				}
			}
			if m != t.complement {
				out.PutNew(k, rec.vals[i])
			}
		}
		next.Put(out, ctx)
		return
	}
	if t.complement {
		out := NewMlrmap()
		for i, k := range rec.keys {
			if !t.fieldSet[k] {
				out.PutNew(k, rec.vals[i])
			}
		}
		next.Put(out, ctx)
		return
	}
	out := NewMlrmap()
	if t.ordered {
		for _, f := range t.fields {
			v := rec.Get(f)
			if v != nil {
				out.Put(f, v)
			}
		}
	} else {
		for i, k := range rec.keys {
			if t.fieldSet[k] {
				out.PutNew(k, rec.vals[i])
			}
		}
	}
	next.Put(out, ctx)
}
func (t *CutT) End(ctx *Context, next *ChainLink) {}

// ---------------------------------------------------------------- having-fields
type HavingFieldsT struct {
	kind   string
	fields []string
	set    map[string]bool
	re     *regexp.Regexp
}

func parseHavingFields(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("having-fields", args, i)
	t := &HavingFieldsT{}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "--at-least", "--which-are", "--at-most", "--all-defined", "--any-defined":
			t.kind = f
			t.fields = va.list(f)
			t.set = stringSet(t.fields)
		case "--all-matching", "--any-matching", "--none-matching":
			t.kind = f
			t.re = compileMillerRegex(va.str(f))
		default:
			va.unrecognized(f)
		}
	}
	if t.kind == "" {
		va.usageError("option is required.")
	}
	return t, va.i
}

func (t *HavingFieldsT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	pass := false
	switch t.kind {
	case "--at-least":
		pass = true
		for _, f := range t.fields {
			if !rec.Has(f) {
				pass = false
				break
			}
		}
	case "--which-are":
		pass = rec.Len() == len(t.set)
		if pass {
			for _, k := range rec.keys {
				if !t.set[k] {
					pass = false
					break
				}
			}
		}
	case "--at-most":
		pass = true
		for _, k := range rec.keys {
			if !t.set[k] {
				pass = false
				break
			}
		}
	case "--all-defined":
		pass = true
		for _, f := range t.fields {
			v := rec.Get(f)
			if v == nil || v.IsVoid() {
				pass = false
				break
			}
		}
	case "--any-defined":
		for _, f := range t.fields {
			v := rec.Get(f)
			if v != nil && !v.IsVoid() {
				pass = true
				break
			}
		}
	case "--all-matching":
		pass = rec.Len() > 0
		for _, k := range rec.keys {
			if !t.re.MatchString(k) {
				pass = false
				break
			}
		}
	case "--any-matching":
		for _, k := range rec.keys {
			if t.re.MatchString(k) {
				pass = true
				break
			}
		}
	case "--none-matching":
		pass = true
		for _, k := range rec.keys {
			if t.re.MatchString(k) {
				pass = false
				break
			}
		}
	}
	if pass {
		next.Put(rec, ctx)
	}
}
