	haveKey bool
}

func parseGap(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("gap", args, i)
	t := &GapT{}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-n":
			t.n = va.int(f)
		case "-g":
			t.groupBy = va.list(f)
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}
func (t *GapT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if t.groupBy != nil {
		key, _ := groupingKey(rec, t.groupBy)
		if t.haveKey && key != t.lastKey {
			next.Put(NewMlrmap(), ctx)
		}
		t.lastKey = key
		t.haveKey = true
		next.Put(rec, ctx)
		return
	}
	if t.n > 0 && t.count > 0 && t.count%t.n == 0 {
		next.Put(NewMlrmap(), ctx)
	}
	t.count++
	next.Put(rec, ctx)
}
