func parseUnspace(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("unspace", args, i)
	t := &UnspaceT{filler: "_", keys: true, values: true}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.filler = va.str(f)
		case "-k":
			t.keys = true
			t.values = false
		case "-v":
			t.keys = false
			t.values = true
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
