func (t *UnspaceT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	out := NewMlrmap()
	for i, k := range rec.keys {
		v := rec.vals[i]
		if t.keys {
			k = strings.ReplaceAll(k, " ", t.filler)
		}
		if t.values && (v.Type() == MT_STRING) {
			s := v.String()
			if strings.Contains(s, " ") {
				v = MlrvalFromInferred(strings.ReplaceAll(s, " ", t.filler))
