// ---------------------------------------------------------------- template
type TemplateT struct {
	fields []string
	fill   *Mlrval
}

func parseTemplate(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("template", args, i)
	t := &TemplateT{fill: VOID}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = append(t.fields, va.list(f)...)
		case "-t":
			fn := va.str(f)
			data, err := os.ReadFile(fn)
			if err != nil {
				fmt.Fprintf(os.Stderr, "mlr template: could not read \"%s\".\n", fn)
				os.Exit(1)
			}
			line := strings.SplitN(string(data), "\n", 2)[0]
			line = strings.TrimSuffix(line, "\r")
			t.fields = append(t.fields, strings.Split(line, ",")...)
		case "--fill-with":
			t.fill = MlrvalFromInferred(va.str(f))
		default:
			va.unrecognized(f)
		}
	}
	if t.fields == nil {
		va.usageError("one of -f or -t is required.")
	}
	return t, va.i
}
func (t *TemplateT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	out := NewMlrmap()
	for _, f := range t.fields {
		v := rec.Get(f)
		if v == nil {
			out.Put(f, t.fill)
		} else {
			out.Put(f, v)
		}
	}
	next.Put(out, ctx)
}
