// ---------------------------------------------------------------- seqgen
type SeqgenT struct {
	field             string
	start, stop, step *Mlrval
}

func parseSeqgen(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("seqgen", args, i)
	t := &SeqgenT{field: "i", start: MlrvalFromInt(1), stop: MlrvalFromInt(100), step: MlrvalFromInt(1)}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.field = va.str(f)
		case "--start":
			t.start = MlrvalFromInferred(va.str(f))
		case "--stop":
			t.stop = MlrvalFromInferred(va.str(f))
		case "--step":
			t.step = MlrvalFromInferred(va.str(f))
		default:
			va.unrecognized(f)
		}
	}
	for _, x := range []*Mlrval{t.start, t.stop, t.step} {
		if !x.IsNumeric() {
			fmt.Fprintf(os.Stderr, "mlr seqgen: start, stop, and step must be numeric; got \"%s\".\n", x.String())
			os.Exit(1)
		}
	}
	return t, va.i
}
func (t *SeqgenT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {}
func (t *SeqgenT) End(ctx *Context, next *ChainLink) {
	stepSign := numCmp(t.step, MlrvalFromInt(0))
	cmpSS := numCmp(t.start, t.stop)
	if stepSign == 0 {
		if cmpSS == 0 {
			rec := NewMlrmap()
			rec.PutNew(t.field, t.start)
			c := *ctx
			c.NR = 1
			c.FNR = 1
			next.Put(rec, &c)
			return
		}
		fmt.Fprintf(os.Stderr, "mlr seqgen: step must not be zero unless start == stop.\n")
		os.Exit(1)
	}
	cur := t.start
	var n int64
	for {
		if stepSign > 0 && numCmp(cur, t.stop) > 0 {
			break
		}
		if stepSign < 0 && numCmp(cur, t.stop) < 0 {
			break
		}
		n++
		rec := NewMlrmap()
		rec.PutNew(t.field, cur)
		c := *ctx
		c.NR = n
		c.FNR = n
		next.Put(rec, &c)
		cur = BinaryPlus(cur, t.step)
	}
}

// ---------------------------------------------------------------- repeat
type RepeatT struct {
	n     int64
	field string
}

func parseRepeat(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("repeat", args, i)
	t := &RepeatT{n: 1}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-n":
			t.n = va.int(f)
		case "-f":
			t.field = va.str(f)
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}
func (t *RepeatT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	n := t.n
	if t.field != "" {
		v := rec.Get(t.field)
		if v == nil {
			return
		}
		if v.Type() == MT_INT {
			n = v.intval
		} else if v.Type() == MT_FLOAT {
			n = int64(v.floatval)
		} else {
			return
		}
	}
	for j := int64(0); j < n; j++ {
		if j == 0 {
			next.Put(rec, ctx)
		} else {
			next.Put(rec.Copy(), ctx)
		}
	}
}
func (t *RepeatT) End(ctx *Context, next *ChainLink) {}
