	}
	return &RegularizeT{sortedToOriginal: map[string][]string{}}, va.i
}
func (t *RegularizeT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	keys := rec.KeysCopy()
	sk := append([]string{}, keys...)
	sort.Strings(sk)
	skey := strings.Join(sk, ",")
	prev, ok := t.sortedToOriginal[skey]
	if !ok {
		t.sortedToOriginal[skey] = keys
		next.Put(rec, ctx)
		return
	}
	if rec.SameKeys(prev) {
		next.Put(rec, ctx)
		return
	}
	n := NewMlrmap()
	for _, k := range prev {
		n.PutNew(k, rec.Get(k))
	}
	next.Put(n, ctx)
}
func (t *RegularizeT) End(ctx *Context, next *ChainLink) {}

