	reverse bool
}

func parseSortWithinRecordsValues(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("sort-within-records-values", args, i)
	t := &SortWithinRecordsValuesT{}
	for va.hasFlag() {
