}
func (t *SortWithinRecordsValuesT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	idx := make([]int, len(rec.keys))
	for i := range idx {
		idx[i] = i
	}
	sort.SliceStable(idx, func(a, b int) bool {
		c := collateCompare(rec.vals[idx[a]], rec.vals[idx[b]])
		if t.reverse {
			return c > 0
		}
		return c < 0
	})
	nk := make([]string, len(idx))
	nv := make([]*Mlrval, len(idx))
	for i, j := range idx {
		nk[i] = rec.keys[j]
		nv[i] = rec.vals[j]
	}
	rec.keys = nk
	rec.vals = nv
	next.Put(rec, ctx)
}
func (t *SortWithinRecordsValuesT) End(ctx *Context, next *ChainLink) {}

