type FillDownT struct {
	fields       []string
	all          bool
	onlyIfBlank  bool
	onlyIfAbsent bool
	last         map[string]*Mlrval
}

func parseFillDown(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("fill-down", args, i)
	t := &FillDownT{last: map[string]*Mlrval{}}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = va.list(f)
		case "-a", "--all":
			if f == "--all" {
				t.all = true
			} else {
				t.onlyIfAbsent = true
			}
		case "--only-if-blank":
			t.onlyIfBlank = true
		case "--only-if-any-blank":
			t.onlyIfBlank = true
		default:
			va.unrecognized(f)
		}
	}
	if t.fields == nil && !t.all {
		fmt.Fprintf(os.Stderr, "mlr fill-down: no field names given.\n")
		os.Exit(1)
	}
	return t, va.i
}

func (t *FillDownT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	fields := t.fields
	if t.all {
		fields = rec.keys
	}
	for _, f := range fields {
		v := rec.Get(f)
		missing := false
		if t.onlyIfAbsent {
			missing = v == nil
		} else if t.onlyIfBlank {
			missing = v != nil && v.IsVoid()
		} else {
			missing = v == nil || v.IsVoid()
		}
		if missing {
			if prev, ok := t.last[f]; ok {
				rec.Put(f, prev)
			}
		} else if v != nil {
			t.last[f] = v
		}
	}
	next.Put(rec, ctx)
}
func (t *FillDownT) End(ctx *Context, next *ChainLink) {}

