	keyUnion  *lhmsi
}

func parseUnsparsify(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("unsparsify", args, i)
	t := &UnsparsifyT{fill: VOID, keyUnion: newLhm()}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "--fill-with":
			t.fill = MlrvalFromInferred(va.str(f))
		case "-f":
			t.fields = append(t.fields, va.list(f)...)
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}

func (t *UnsparsifyT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if t.fields != nil {
		for _, f := range t.fields {
			if !rec.Has(f) {
				rec.PutNew(f, t.fill)
			}
		}
		next.Put(rec, ctx)
		return
	}
	for _, k := range rec.keys {
		t.keyUnion.put(k, true)
	}
	t.recs = append(t.recs, recctx{rec, *ctx})
}

func (t *UnsparsifyT) End(ctx *Context, next *ChainLink) {
	if t.fields != nil {
		return
	}
	for _, rc := range t.recs {
		out := NewMlrmap()
		for _, k := range t.keyUnion.keys {
			v := rc.rec.Get(k)
			if v == nil {
				out.PutNew(k, t.fill)
			} else {
				out.PutNew(k, v)
			}
		}
		c := rc.ctx
		next.Put(out, &c)
	}
}

