	haveKey bool
}

func parseGap(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("gap", args, i)
	t := &GapT{}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-n":
			t.n = va.int(f)
		case "-g":
			t.groupBy = va.list(f)
