// ---------------------------------------------------------------- grep
type GrepT struct {
	re         *regexp.Regexp
	invert     bool
	valuesOnly bool
}

func parseGrep(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("grep", args, i)
	t := &GrepT{}
	ci := false
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-i":
			ci = true
		case "-v":
			t.invert = true
		case "-a":
			t.valuesOnly = true
		default:
			va.unrecognized(f)
		}
	}
	pat := va.positional("regular expression")
	if ci {
		pat = "(?i)" + pat
	}
	re, err := regexp.Compile(pat)
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr grep: could not compile regex \"%s\"\n", pat)
		os.Exit(1)
	}
	t.re = re
	return t, va.i
}
func (t *GrepT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	var b strings.Builder
	for i, k := range rec.keys {
		if i > 0 {
			if t.valuesOnly {
				b.WriteString(" ")
			} else {
				b.WriteString(",")
			}
		}
		if !t.valuesOnly {
			b.WriteString(k)
			b.WriteString("=")
		}
		b.WriteString(rec.vals[i].String())
	}
	m := t.re.MatchString(b.String())
	if m != t.invert {
		next.Put(rec, ctx)
	}
}
func (t *GrepT) End(ctx *Context, next *ChainLink) {}

