func (t *RepeatT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	n := t.n
	if t.field != "" {
		v := rec.Get(t.field)
		if v == nil {
			return
		}
		if v.Type() == MT_INT {
			n = v.intval
		} else if v.Type() == MT_FLOAT {
			n = int64(v.floatval)
		} else {
			return
		}
	}
	for j := int64(0); j < n; j++ {
		if j == 0 {
			next.Put(rec, ctx)
		} else {
			next.Put(rec.Copy(), ctx)
		}
	}
}
