func yamlQuoteIfNeeded(s string, mv *Mlrval) string {
	if mv != nil {
		t := mv.Type()
		if t == MT_INT || t == MT_FLOAT || t == MT_BOOLEAN {
			return mv.OutputString()
		}
		if t == MT_VOID {
			return "null"
		}
	}
	if s == "" {
		return "\"\""
	}
	lower := strings.ToLower(s)
	switch lower {
	case "y", "n", "yes", "no", "on", "off", "true", "false", "null", "~":
		return "\"" + s + "\""
	}
	if MlrvalFromInferred(s).IsNumeric() {
		return "\"" + s + "\""
	}
	if s == "[]" || s == "{}" {
		return "'" + s + "'"
	}
	needs := false
	if strings.ContainsAny(s[:1], "!&*-?|>'\"%@`[]{},#") && !(s[0] == '-' && len(s) > 1 && s[1] != ' ') {
