	line := 1
	col := 1
	n := len(src)
	advance := func(k int) {
		for j := 0; j < k; j++ {
			if src[pos] == '\n' {
				line++
				col = 1
			} else {
				col++
			}
			pos++
		}
	}
	for pos < n {
		c := src[pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			advance(1)
			continue
		}
		if c == '#' {
			for pos < n && src[pos] != '\n' {
				advance(1)
			}
			continue
		}
		startLine, startCol, startPos := line, col, pos
		mk := func(t TokType, text string) {
			toks = append(toks, Token{typ: t, text: text, line: startLine, col: startCol, src: src[startPos:pos]})
		}
		if c == '$' || c == '@' {
			isField := c == '$'
			if pos+1 < n && src[pos+1] == '{' {
				end := strings.IndexByte(src[pos+2:], '}')
				if end < 0 {
					return nil, &parseError{fmt.Sprintf("mlr: cannot parse DSL expression.\nmlr: Parse error on token \"%s\" at line %d column %d.", src[pos:], line, col)}
				}
				name := src[pos+2 : pos+2+end]
				advance(end + 3)
				if isField {
					mk(TK_FIELD, name)
				} else {
					mk(TK_OOSVAR, name)
				}
				continue
			}
			if pos+1 < n && src[pos+1] == '*' {
				advance(2)
				if isField {
					mk(TK_FIELD_STAR, "$*")
				} else {
					mk(TK_OOSVAR_STAR, "@*")
				}
				continue
			}
			if pos+1 < n && src[pos+1] == '[' {
				if isField {
					if strings.HasPrefix(src[pos+1:], "[[[") {
						advance(4)
						mk(TK_FIELD_BRACKET3, "$[[[")
					} else if strings.HasPrefix(src[pos+1:], "[[") {
						advance(3)
						mk(TK_FIELD_BRACKET2, "$[[")
					} else {
						advance(2)
						mk(TK_FIELD_BRACKET, "$[")
					}
				} else {
					advance(2)
					mk(TK_OOSVAR_BRACKET, "@[")
				}
				continue
			}
