			j := pos + 1
			for j < n {
				r, sz := utf8.DecodeRuneInString(src[j:])
				if isIdentChar(r) {
					j += sz
				} else {
					break
				}
			}
			if j == pos+1 {
				return nil, &parseError{fmt.Sprintf("mlr: cannot parse DSL expression.\nmlr: Parse error on token \"%c\" at line %d column %d.", c, line, col)}
			}
			name := src[pos+1 : j]
			advance(j - pos)
			if isField {
				mk(TK_FIELD, name)
			} else {
				mk(TK_OOSVAR, name)
			}
			continue
		}
		if c == '"' {
			// string literal
			j := pos + 1
			for j < n {
				if src[j] == '\\' && j+1 < n {
					e := src[j+1]
					if strings.IndexByte(allowedEscapes, e) < 0 {
						return nil, &parseError{fmt.Sprintf("mlr: cannot parse DSL expression.\nmlr: Parse error on token \"%s\" at line %d column %d.", src[pos:j+1], line, col)}
					}
					j += 2
					continue
				}
				if src[j] == '"' {
					break
				}
				j++
			}
			if j >= n {
				return nil, &parseError{fmt.Sprintf("mlr: cannot parse DSL expression.\nmlr: Parse error on token \"%s\" at line %d column %d.", src[pos:], line, col)}
			}
			text := src[pos+1 : j]
			if j+1 < n && src[j+1] == 'i' && !(j+2 < n && isIdentByte(src[j+2])) {
				advance(j + 2 - pos)
				mk(TK_REGEXI, text)
			} else {
				advance(j + 1 - pos)
				mk(TK_STRING, text)
			}
			continue
		}
		// numbers
		if isDecDigit(c) || (c == '.' && pos+1 < n && isDecDigit(src[pos+1])) {
			j := pos
			isFloat := false
			if c == '0' && pos+1 < n && (src[pos+1] == 'x' || src[pos+1] == 'X') {
				j = pos + 2
				for j < n && isHexDigit(src[j]) {
					j++
				}
			} else if c == '0' && pos+1 < n && (src[pos+1] == 'b' || src[pos+1] == 'B') && pos+2 < n && (src[pos+2] == '0' || src[pos+2] == '1') {
				j = pos + 2
				for j < n && (src[j] == '0' || src[j] == '1') {
					j++
				}
			} else if c == '0' && pos+1 < n && (src[pos+1] == 'o' || src[pos+1] == 'O') {
				j = pos + 2
				for j < n && src[j] >= '0' && src[j] <= '7' {
					j++
				}
			} else {
				for j < n && isDecDigit(src[j]) {
					j++
				}
				if j < n && src[j] == '.' && !(j+1 < n && (src[j+1] == '+' || src[j+1] == '-' || src[j+1] == '*' || src[j+1] == '/')) {
					isFloat = true
					j++
					for j < n && isDecDigit(src[j]) {
						j++
					}
				}
				if j < n && (src[j] == 'e' || src[j] == 'E') {
					k := j + 1
					if k < n && (src[k] == '+' || src[k] == '-') {
						k++
					}
					if k < n && isDecDigit(src[k]) {
						for k < n && isDecDigit(src[k]) {
							k++
						}
						j = k
						isFloat = true
					}
				}
			}
			// identifier chars immediately following make it a parse error
			if j < n && (isIdentByte(src[j])) {
				k := j
				for k < n && isIdentByte(src[k]) {
					k++
				}
				return nil, &parseError{fmt.Sprintf("mlr: cannot parse DSL expression.\nmlr: Parse error on token \"%s\" at line %d column %d.", src[j:k], line, col+(j-pos))}
			}
			text := src[pos:j]
			advance(j - pos)
			if isFloat {
				mk(TK_FLOAT, text)
			} else {
				mk(TK_INT, text)
			}
			continue
		}
		r, sz := utf8.DecodeRuneInString(src[pos:])
		if isIdentStart(r) {
			j := pos + sz
			for j < n {
				r2, sz2 := utf8.DecodeRuneInString(src[j:])
				if isIdentChar(r2) {
					j += sz2
				} else {
					break
				}
			}
			text := src[pos:j]
			advance(j - pos)
			mk(TK_IDENT, text)
			continue
		}
		matched := false
		for _, p := range punctList {
			if strings.HasPrefix(src[pos:], p) {
				advance(len(p))
				mk(TK_PUNCT, p)
				matched = true
				break
			}
		}
		if !matched {
			return nil, &parseError{fmt.Sprintf("mlr: cannot parse DSL expression.\nmlr: Parse error on token \"%c\" at line %d column %d.", c, line, col)}
		}
	}
	toks = append(toks, Token{typ: TK_EOF, text: "", line: line, col: col})
	return toks, nil
}

func isIdentByte(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}
