cd /workspace/src && cat > dsl_parser.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

type ASTNode struct {
	Type     string
	Text     string
	Children []*ASTNode
	tok      *Token
}

func newNode(typ, text string, children ...*ASTNode) *ASTNode {
	return &ASTNode{Type: typ, Text: text, Children: children}
}

func (n *ASTNode) hasText() bool {
	switch n.Type {
	case "statement block", "begin block", "end block", "if-chain", "parameter list", "parameter",
		"emittable list", "emit keys", "no-op", "cond block", "bare boolean":
		return false
	case "function callsite":
		return n.Text != ""
	}
	return true
}

func (n *ASTNode) Print(b *strings.Builder, depth int) {
	for i := 0; i < depth; i++ {
		b.WriteString("    ")
	}
	b.WriteString("* ")
	b.WriteString(n.Type)
	if n.hasText() {
		b.WriteString(" \"")
		b.WriteString(n.Text)
		b.WriteString("\"")
	}
	b.WriteString("\n")
	for _, c := range n.Children {
		c.Print(b, depth+1)
	}
}

func (n *ASTNode) PrintParex(b *strings.Builder, depth int, oneLine bool) {
	// parenthesized format
	if len(n.Children) == 0 {
		if !oneLine {
			for i := 0; i < depth; i++ {
				b.WriteString("    ")
			}
		}
		b.WriteString(n.parexText())
		if !oneLine {
			b.WriteString("\n")
		}
		return
	}
	if !oneLine {
		for i := 0; i < depth; i++ {
			b.WriteString("    ")
		}
	}
	b.WriteString("(")
	b.WriteString(n.parexText())
	if !oneLine {
		b.WriteString("\n")
	}
	for _, c := range n.Children {
		if oneLine {
			b.WriteString(" ")
		}
		c.PrintParex(b, depth+1, oneLine)
	}
	if !oneLine {
		for i := 0; i < depth; i++ {
			b.WriteString("    ")
		}
	}
	b.WriteString(")")
	if !oneLine {
		b.WriteString("\n")
	}
}

func (n *ASTNode) parexText() string {
	if n.hasText() {
		return n.Text
	}
	return n.Type
}

type Parser struct {
	toks []Token
	pos  int
	src  string
}

func (p *Parser) peek() *Token {
	return &p.toks[p.pos]
}
func (p *Parser) peekAt(k int) *Token {
	if p.pos+k < len(p.toks) {
		return &p.toks[p.pos+k]
	}
	return &p.toks[len(p.toks)-1]
}
func (p *Parser) advance() *Token {
	t := &p.toks[p.pos]
	if p.pos < len(p.toks)-1 {
		p.pos++
	}
	return t
}

func (p *Parser) isPunct(s string) bool {
	t := p.peek()
	return t.typ == TK_PUNCT && t.text == s
}
func (p *Parser) isIdent(s string) bool {
	t := p.peek()
	return t.typ == TK_IDENT && t.text == s
}

func (p *Parser) fail() {
	t := p.peek()
	var tokText string
	if t.typ == TK_EOF {
		tokText = ""
		panic(&parseError{"mlr: cannot parse DSL expression.\nmlr: Parse error on token \"\" at line " + fmt.Sprint(t.line) + " column " + fmt.Sprint(t.col) + "."})
	}
	tokText = t.src
	panic(&parseError{fmt.Sprintf("mlr: cannot parse DSL expression.\nmlr: Parse error on token \"%s\" at line %d column %d.", tokText, t.line, t.col)})
}

func (p *Parser) expectPunct(s string) {
	if !p.isPunct(s) {
		p.fail()
	}
	p.advance()
}

func parseDSL(src string) (root *ASTNode, err error) {
	toks, lerr := lexDSL(src)
	if lerr != nil {
		return nil, lerr
	}
	p := &Parser{toks: toks, src: src}
	defer func() {
		if r := recover(); r != nil {
			if pe, ok := r.(*parseError); ok {
				err = pe
				root = nil
				return
			}
			panic(r)
		}
	}()
	root = p.parseStatementList(true)
	if p.peek().typ != TK_EOF {
		p.fail()
	}
	return root, nil
}

// Parses statements until '}' or EOF
func (p *Parser) parseStatementList(topLevel bool) *ASTNode {
	block := newNode("statement block", "")
	for {
		for p.isPunct(";") {
			p.advance()
		}
		t := p.peek()
		if t.typ == TK_EOF || (t.typ == TK_PUNCT && t.text == "}") {
			break
		}
		stmt, braced := p.parseStatement(topLevel)
		block.Children = append(block.Children, stmt)
		t = p.peek()
		if t.typ == TK_EOF || (t.typ == TK_PUNCT && t.text == "}") {
			break
		}
		if p.isPunct(";") {
			continue
		}
		if braced {
			continue
		}
		p.fail()
	}
	return block
}

func (p *Parser) parseBracedBlock() *ASTNode {
	p.expectPunct("{")
	b := p.parseStatementList(false)
	p.expectPunct("}")
	return b
}

var typeDeclNames = map[string]bool{"var": true, "str": true, "num": true, "int": true, "float": true, "bool": true, "map": true, "arr": true, "funct": true, "any": true}

// returns statement node and whether it ended with a closing brace
func (p *Parser) parseStatement(topLevel bool) (*ASTNode, bool) {
	t := p.peek()
	if t.typ == TK_IDENT {
		switch t.text {
		case "begin":
			if p.peekAt(1).typ == TK_PUNCT && p.peekAt(1).text == "{" {
				p.advance()
				b := p.parseBracedBlock()
				return newNode("begin block", "", b), true
			}
		case "end":
			if p.peekAt(1).typ == TK_PUNCT && p.peekAt(1).text == "{" {
				p.advance()
				b := p.parseBracedBlock()
				return newNode("end block", "", b), true
			}
		case "func":
			if p.peekAt(1).typ == TK_IDENT {
				return p.parseFuncDef(), true
			}
		case "subr":
			return p.parseSubrDef(), true
		case "call":
			p.advance()
			name := p.advance()
			if name.typ != TK_IDENT {
				p.pos--
				p.fail()
			}
			n := newNode("subroutine callsite", name.text)
			p.expectPunct("(")
			n.Children = p.parseArgList(")")
			return n, false
		case "if":
			return p.parseIfChain(), true
		case "while":
			p.advance()
			p.expectPunct("(")
			cond := p.parseExpr()
			p.expectPunct(")")
			body := p.parseBracedBlock()
			return newNode("while loop", "while", cond, body), true
		case "do":
			p.advance()
			body := p.parseBracedBlock()
			if !p.isIdent("while") {
				p.fail()
			}
			p.advance()
			p.expectPunct("(")
			cond := p.parseExpr()
			p.expectPunct(")")
			return newNode("do-while`loop", "do", body, cond), false
		case "for":
			return p.parseFor(), true
		case "break":
			p.advance()
			return newNode("break", "break"), false
		case "continue":
			p.advance()
			return newNode("continue", "continue"), false
		case "return":
			p.advance()
			n := newNode("return", "return")
			if !p.isPunct(";") && !p.isPunct("}") && p.peek().typ != TK_EOF {
				n.Children = append(n.Children, p.parseExpr())
			}
			return n, false
		case "filter":
			p.advance()
			e := p.parseExpr()
			return newNode("filter statement", "filter", e), false
		case "unset":
			p.advance()
			n := newNode("unset", "unset")
			for {
				n.Children = append(n.Children, p.parseExpr())
				if p.isPunct(",") {
					p.advance()
					continue
				}
				break
			}
			return n, false
		case "emit", "emitp":
			return p.parseEmit(t.text), false
		case "emitf":
			return p.parseEmitf(), false
		case "emit1":
			p.advance()
			e := p.parseExpr()
			return newNode("emit1 statement", "emit1", e), false
		case "tee":
			p.advance()
			redir := p.parseRedirect()
			if redir == nil {
				p.fail()
			}
			p.expectPunct(",")
			e := p.parseExpr()
			return newNode("tee statement", "tee", e, redir), false
		case "print", "printn", "eprint", "eprintn":
			return p.parsePrint(t.text), false
		case "dump", "edump":
			return p.parseDump(t.text), false
		}
		if typeDeclNames[t.text] && p.peekAt(1).typ == TK_IDENT {
			// local declaration
			typ := p.advance().text
			name := p.advance().text
			lv := newNode("local variable", name, newNode("type declaration", typ))
			if !p.isPunct("=") {
				p.fail()
			}
			p.advance()
			rhs := p.parseExpr()
			return newNode("assignment", "=", lv, rhs), false
		}
	}
	// expression-based: assignment, bare boolean, cond block
	lhs := p.parseExpr()
	if p.peek().typ == TK_PUNCT {
		op := p.peek().text
		if op == "=" {
			p.advance()
			rhs := p.parseExpr()
			return newNode("assignment", "=", lhs, rhs), false
		}
		if strings.HasSuffix(op, "=") && len(op) >= 2 && op != "==" && op != "!=" && op != "<=" && op != ">=" {
			base := op[:len(op)-1]
			p.advance()
			rhs := p.parseExpr()
			var opnode *ASTNode
			if base == "." {
				opnode = newNode("dot operator", ".", lhs, rhs)
			} else {
				opnode = newNode("operator", base, lhs, rhs)
			}
			return newNode("assignment", "=", lhs, opnode), false
		}
		if op == "{" {
			b := p.parseBracedBlock()
			return newNode("cond block", "", lhs, b), true
		}
	}
	return newNode("bare boolean", "", lhs), false
}

func (p *Parser) parseArgList(closer string) []*ASTNode {
	var args []*ASTNode
	if p.isPunct(closer) {
		p.advance()
		return args
	}
	for {
		args = append(args, p.parseExpr())
		if p.isPunct(",") {
			p.advance()
			continue
		}
		if p.isPunct(closer) {
			p.advance()
			return args
		}
		p.fail()
	}
}

func (p *Parser) parseParamList() *ASTNode {
	pl := newNode("parameter list", "")
	p.expectPunct("(")
	if p.isPunct(")") {
		p.advance()
		return pl
	}
	for {
		t := p.advance()
		if t.typ != TK_IDENT {
			p.pos--
			p.fail()
		}
		var pn *ASTNode
		if typeDeclNames[t.text] && p.peek().typ == TK_IDENT {
			name := p.advance()
			pn = newNode("parameter name", name.text, newNode("type declaration", t.text))
		} else {
			pn = newNode("parameter name", t.text)
		}
		pl.Children = append(pl.Children, newNode("parameter", "", pn))
		if p.isPunct(",") {
			p.advance()
			continue
		}
		if p.isPunct(")") {
			p.advance()
			return pl
		}
		p.fail()
	}
}

func (p *Parser) parseFuncDef() *ASTNode {
	p.advance() // func
	name := p.advance().text
	pl := p.parseParamList()
	var rettype *ASTNode
	if p.isPunct(":") {
		p.advance()
		t := p.advance()
		if t.typ != TK_IDENT || !typeDeclNames[t.text] {
			p.pos--
			p.fail()
		}
		rettype = newNode("type declaration", t.text)
	}
	body := p.parseBracedBlock()
	n := newNode("function definition", name, pl, body)
	if rettype != nil {
		n.Children = append(n.Children, rettype)
	}
	return n
}

func (p *Parser) parseFuncLiteral() *ASTNode {
	p.advance() // func
	pl := p.parseParamList()
	var rettype *ASTNode
	if p.isPunct(":") {
		p.advance()
		t := p.advance()
		if t.typ != TK_IDENT || !typeDeclNames[t.text] {
			p.pos--
			p.fail()
		}
		rettype = newNode("type declaration", t.text)
	}
	body := p.parseBracedBlock()
	n := newNode("function literal", "func", pl, body)
	if rettype != nil {
		n.Children = append(n.Children, rettype)
	}
	return n
}

func (p *Parser) parseSubrDef() *ASTNode {
	p.advance() // subr
	t := p.advance()
	if t.typ != TK_IDENT {
		p.pos--
		p.fail()
	}
	pl := p.parseParamList()
	body := p.parseBracedBlock()
	return newNode("subroutine definition", t.text, pl, body)
}

func (p *Parser) parseIfChain() *ASTNode {
	chain := newNode("if-chain", "")
	p.advance() // if
	p.expectPunct("(")
	cond := p.parseExpr()
	p.expectPunct(")")
	body := p.parseBracedBlock()
	chain.Children = append(chain.Children, newNode("if-item", "if", cond, body))
	for {
		if p.isIdent("elif") {
			p.advance()
			p.expectPunct("(")
			c := p.parseExpr()
			p.expectPunct(")")
			b := p.parseBracedBlock()
			chain.Children = append(chain.Children, newNode("if-item", "elif", c, b))
			continue
		}
		if p.isIdent("else") {
			p.advance()
			b := p.parseBracedBlock()
			chain.Children = append(chain.Children, newNode("if-item", "else", b))
		}
		break
	}
	return chain
}

func (p *Parser) parseFor() *ASTNode {
	p.advance() // for
	p.expectPunct("(")
	// multi-variable: ((k1,k2),v in ...)
	if p.isPunct("(") {
		p.advance()
		pl := newNode("parameter list", "")
		for {
			t := p.advance()
			if t.typ != TK_IDENT {
				p.pos--
				p.fail()
			}
			pl.Children = append(pl.Children, newNode("local variable", t.text))
			if p.isPunct(",") {
				p.advance()
				continue
			}
			if p.isPunct(")") {
				p.advance()
				break
			}
			p.fail()
		}
		p.expectPunct(",")
		v := p.advance()
		if v.typ != TK_IDENT {
			p.pos--
			p.fail()
		}
		if !p.isIdent("in") {
			p.fail()
		}
		p.advance()
		iter := p.parseExpr()
		p.expectPunct(")")
		body := p.parseBracedBlock()
		return newNode("multi-variable for-loop", "for", pl, newNode("local variable", v.text), iter, body)
	}
	// single or double variable: ident [, ident] in
	if p.peek().typ == TK_IDENT && !typeDeclNames[p.peek().text] {
		if p.peekAt(1).typ == TK_IDENT && p.peekAt(1).text == "in" {
			k := p.advance().text
			p.advance() // in
			iter := p.parseExpr()
			p.expectPunct(")")
			body := p.parseBracedBlock()
			return newNode("single-variable for-loop", "for", newNode("local variable", k), iter, body)
		}
		if p.peekAt(1).typ == TK_PUNCT && p.peekAt(1).text == "," && p.peekAt(2).typ == TK_IDENT && p.peekAt(3).typ == TK_IDENT && p.peekAt(3).text == "in" {
			k := p.advance().text
			p.advance()
			v := p.advance().text
			p.advance() // in
			iter := p.parseExpr()
			p.expectPunct(")")
			body := p.parseBracedBlock()
			return newNode("double-variable for-loop", "for", newNode("local variable", k), newNode("local variable", v), iter, body)
		}
	}
	// triple-for
	init := newNode("statement block", "")
	for !p.isPunct(";") {
		s, _ := p.parseStatement(false)
		if s.Type != "assignment" {
			p.fail()
		}
		init.Children = append(init.Children, s)
		if p.isPunct(",") {
			p.advance()
			continue
		}
		if !p.isPunct(";") {
			p.fail()
		}
	}
	p.advance()
	cond := newNode("statement block", "")
	if !p.isPunct(";") {
		e := p.parseExpr()
		cond.Children = append(cond.Children, newNode("bare boolean", "", e))
	}
	p.expectPunct(";")
	update := newNode("statement block", "")
	for !p.isPunct(")") {
		s, _ := p.parseStatement(false)
		if s.Type != "assignment" {
			p.fail()
		}
		update.Children = append(update.Children, s)
		if p.isPunct(",") {
			p.advance()
			continue
		}
		if !p.isPunct(")") {
			p.fail()
		}
	}
	p.advance()
	body := p.parseBracedBlock()
	return newNode("triple-for loop", "for", init, cond, update, body)
}

// Redirect: > target | >> target | | target
func (p *Parser) parseRedirect() *ASTNode {
	t := p.peek()
	if t.typ != TK_PUNCT {
		return nil
	}
	var typ string
	switch t.text {
	case ">":
		typ = "redirect write"
	case ">>":
		typ = "redirect append"
	case "|":
		typ = "redirect pipe"
	default:
		return nil
	}
	p.advance()
	var target *ASTNode
	if p.isIdent("stdout") {
		p.advance()
		target = newNode("stdout redirect target", "stdout")
	} else if p.isIdent("stderr") {
		p.advance()
		target = newNode("stderr redirect target", "stderr")
	} else {
		target = p.parseExpr()
	}
	return newNode(typ, t.text, target)
}

func (p *Parser) parsePrint(kw string) *ASTNode {
	p.advance()
	n := newNode(kw+" statement", kw)
	redir := p.parseRedirect()
	if redir != nil {
		p.expectPunct(",")
	}
	if p.isPunct(";") || p.isPunct("}") || p.peek().typ == TK_EOF {
		n.Children = append(n.Children, newNode("no-op", ""))
	} else {
		args := newNode("function callsite", "")
		for {
			args.Children = append(args.Children, p.parseExpr())
			if p.isPunct(",") {
				p.advance()
				continue
			}
			break
		}
		n.Children = append(n.Children, args)
	}
	if redir != nil {
		n.Children = append(n.Children, redir)
	} else {
		n.Children = append(n.Children, newNode("no-op", ""))
	}
	return n
}

func (p *Parser) parseDump(kw string) *ASTNode {
	p.advance()
	n := newNode(kw+" statement", kw)
	redir := p.parseRedirect()
	if redir != nil {
		p.expectPunct(",")
	}
	if p.isPunct(";") || p.isPunct("}") || p.peek().typ == TK_EOF {
		n.Children = append(n.Children, newNode("no-op", ""))
	} else {
		args := newNode("function callsite", "")
		for {
			args.Children = append(args.Children, p.parseExpr())
			if p.isPunct(",") {
				p.advance()
				continue
			}
			break
		}
		n.Children = append(n.Children, args)
	}
	if redir != nil {
		n.Children = append(n.Children, redir)
	} else {
		n.Children = append(n.Children, newNode("no-op", ""))
	}
	return n
}

func (p *Parser) parseEmittable() *ASTNode {
	t := p.peek()
	switch t.typ {
	case TK_OOSVAR:
		p.advance()
		return newNode("direct oosvar value", t.text)
	case TK_OOSVAR_STAR:
		p.advance()
		return newNode("full oosvar", "@*")
	case TK_FIELD_STAR:
		p.advance()
		return newNode("full record", "$*")
	case TK_FIELD:
		p.advance()
		return newNode("direct field value", t.text)
	case TK_IDENT:
		if t.text == "all" {
			p.advance()
			return newNode("full oosvar", "all")
		}
		if isKeywordIdent(t.text) {
			p.fail()
		}
		p.advance()
		return newNode("local variable", t.text)
	case TK_PUNCT:
		if t.text == "{" {
			return p.parseMapLiteral()
		}
	}
	p.fail()
	return nil
}

func (p *Parser) parseEmit(kw string) *ASTNode {
	p.advance()
	n := newNode(kw+" statement", kw)
	redir := p.parseRedirect()
	if redir != nil {
		p.expectPunct(",")
	}
	list := newNode("emittable list", "")
	if p.isPunct("(") {
		p.advance()
		for {
			list.Children = append(list.Children, p.parseEmittable())
			if p.isPunct(",") {
				p.advance()
				continue
			}
			p.expectPunct(")")
			break
		}
	} else {
		list.Children = append(list.Children, p.parseEmittable())
	}
	n.Children = append(n.Children, list)
	if p.isPunct(",") {
		p.advance()
		keys := newNode("emit keys", "")
		for {
			keys.Children = append(keys.Children, p.parseExpr())
			if p.isPunct(",") {
				p.advance()
				continue
			}
			break
		}
		n.Children = append(n.Children, keys)
	} else {
		n.Children = append(n.Children, newNode("no-op", ""))
	}
	if redir != nil {
		n.Children = append(n.Children, redir)
	} else {
		n.Children = append(n.Children, newNode("no-op", ""))
	}
	return n
}

func (p *Parser) parseEmitf() *ASTNode {
	p.advance()
	n := newNode("emitf statement", "emitf")
	redir := p.parseRedirect()
	if redir != nil {
		p.expectPunct(",")
	}
	list := newNode("emittable list", "")
	for {
		list.Children = append(list.Children, p.parseEmittable())
		if p.isPunct(",") {
			p.advance()
			continue
		}
		break
	}
	n.Children = append(n.Children, list)
	if redir != nil {
		n.Children = append(n.Children, redir)
	} else {
		n.Children = append(n.Children, newNode("no-op", ""))
	}
	return n
}

// ---------------------------------------------------------------- expressions

func (p *Parser) parseExpr() *ASTNode {
	return p.parseTernary()
}

func (p *Parser) parseTernary() *ASTNode {
	c := p.parseLogicalOr()
	if p.isPunct("?") {
		p.advance()
		a := p.parseTernary()
		p.expectPunct(":")
		b := p.parseTernary()
		return newNode("operator", "?:", c, a, b)
	}
	return c
}

func (p *Parser) parseBinaryLeft(ops []string, sub func() *ASTNode) *ASTNode {
	left := sub()
	for {
		t := p.peek()
		if t.typ != TK_PUNCT {
			return left
		}
		found := false
		for _, op := range ops {
			if t.text == op {
				found = true
				break
			}
		}
		if !found {
			return left
		}
		p.advance()
		right := sub()
		if t.text == "." {
			left = newNode("dot operator", ".", left, right)
		} else {
			left = newNode("operator", t.text, left, right)
		}
	}
}

func (p *Parser) parseLogicalOr() *ASTNode {
	return p.parseBinaryLeft([]string{"||"}, p.parseLogicalXor)
}
func (p *Parser) parseLogicalXor() *ASTNode {
	return p.parseBinaryLeft([]string{"^^"}, p.parseLogicalAnd)
}
func (p *Parser) parseLogicalAnd() *ASTNode {
	return p.parseBinaryLeft([]string{"&&"}, p.parseEqne)
}
func (p *Parser) parseEqne() *ASTNode {
	return p.parseBinaryLeft([]string{"=~", "!=~", "==", "!=", "<=>"}, p.parseCmp)
}
func (p *Parser) parseCmp() *ASTNode {
	return p.parseBinaryLeft([]string{">", ">=", "<", "<="}, p.parseBitOr)
}
func (p *Parser) parseBitOr() *ASTNode {
	return p.parseBinaryLeft([]string{"|"}, p.parseBitXor)
}
func (p *Parser) parseBitXor() *ASTNode {
	return p.parseBinaryLeft([]string{"^"}, p.parseBitAnd)
}
func (p *Parser) parseBitAnd() *ASTNode {
	return p.parseBinaryLeft([]string{"&"}, p.parseShift)
}
func (p *Parser) parseShift() *ASTNode {
	return p.parseBinaryLeft([]string{"<<", ">>", ">>>"}, p.parseAddSub)
}
func (p *Parser) parseAddSub() *ASTNode {
	return p.parseBinaryLeft([]string{"+", "-", ".+", ".-"}, p.parseMulDiv)
}
func (p *Parser) parseMulDiv() *ASTNode {
	return p.parseBinaryLeft([]string{"*", "/", "//", "%", ".*", "./", ".//"}, p.parseDot)
}
func (p *Parser) parseDot() *ASTNode {
	return p.parseBinaryLeft([]string{"."}, p.parseUnary)
}

func isUnaryOp(t *Token) bool {
	if t.typ != TK_PUNCT {
		return false
	}
	switch t.text {
	case "-", "+", ".+", ".-", "!", "~":
		return true
	}
	return false
}

func (p *Parser) parseUnary() *ASTNode {
	t := p.peek()
	if isUnaryOp(t) {
		p.advance()
		operand := p.parseUnary()
		return newNode("operator", t.text, operand)
	}
	return p.parseAbsentCoalesce()
}

func (p *Parser) parseAbsentCoalesce() *ASTNode {
	return p.parseBinaryLeft([]string{"??"}, p.parseAbsentEmptyCoalesce)
}
func (p *Parser) parseAbsentEmptyCoalesce() *ASTNode {
	return p.parseBinaryLeft([]string{"???"}, p.parsePow)
}

func (p *Parser) parsePow() *ASTNode {
	base := p.parsePostfix()
	if p.isPunct("**") {
		p.advance()
		rhs := p.parsePowRHS()
		return newNode("operator", "**", base, rhs)
	}
	return base
}

func (p *Parser) parsePowRHS() *ASTNode {
	t := p.peek()
	if isUnaryOp(t) {
		p.advance()
		operand := p.parsePowRHS()
		return newNode("operator", t.text, operand)
	}
	return p.parsePow()
}

func (p *Parser) parsePostfix() *ASTNode {
	n := p.parsePrimary()
	for {
		t := p.peek()
		if t.typ != TK_PUNCT {
			return n
		}
		switch t.text {
		case "[":
			p.advance()
			// slice or index
			if p.isPunct(":") {
				p.advance()
				var hi *ASTNode
				if p.isPunct("]") {
					hi = newNode("int literal", "")
				} else {
					hi = p.parseExpr()
				}
				p.expectPunct("]")
				n = newNode("array-slice access", "[]", n, newNode("int literal", ""), hi)
				continue
			}
			idx := p.parseExpr()
			if p.isPunct(":") {
				p.advance()
				var hi *ASTNode
				if p.isPunct("]") {
					hi = newNode("int literal", "")
				} else {
					hi = p.parseExpr()
				}
				p.expectPunct("]")
				n = newNode("array-slice access", "[]", n, idx, hi)
				continue
			}
			p.expectPunct("]")
			n = newNode("array or map index access", "[]", n, idx)
		case "[[":
			p.advance()
			idx := p.parseExpr()
			p.expectPunct("]")
			p.expectPunct("]")
			n = newNode("positionally-indexed map key", "[]", n, idx)
		case "[[[":
			p.advance()
			idx := p.parseExpr()
			p.expectPunct("]")
			p.expectPunct("]")
			p.expectPunct("]")
			n = newNode("positionally-indexed map value", "[]", n, idx)
		default:
			return n
		}
	}
}

var contextVars = map[string]bool{"NR": true, "FNR": true, "NF": true, "FILENAME": true, "FILENUM": true,
	"IPS": true, "IFS": true, "IRS": true, "OPS": true, "OFS": true, "ORS": true, "FLATSEP": true}

var keywordIdents = map[string]bool{
	"begin": true, "end": true, "if": true, "elif": true, "else": true, "for": true, "while": true, "do": true,
	"break": true, "continue": true, "func": true, "subr": true, "call": true, "return": true, "filter": true,
	"unset": true, "emit": true, "emitp": true, "emitf": true, "emit1": true, "tee": true, "print": true,
	"printn": true, "eprint": true, "eprintn": true, "dump": true, "edump": true, "in": true, "all": true,
	"stdout": true, "stderr": true, "true": true, "false": true, "ENV": true, "M_PI": true, "M_E": true,
	"var": true, "str": true, "num": true, "int": true, "float": true, "bool": true, "map": true, "arr": true, "funct": true,
}

func isKeywordIdent(s string) bool {
	return keywordIdents[s] || contextVars[s]
}

func (p *Parser) parseMapLiteral() *ASTNode {
	p.expectPunct("{")
	n := newNode("map literal", "{}")
	if p.isPunct("}") {
		p.advance()
		return n
	}
	for {
		k := p.parseExpr()
		p.expectPunct(":")
		v := p.parseExpr()
		n.Children = append(n.Children, newNode("map-literal key-value pair", ":", k, v))
		if p.isPunct(",") {
			p.advance()
			if p.isPunct("}") {
				p.advance()
				return n
			}
			continue
		}
		p.expectPunct("}")
		return n
	}
}

func (p *Parser) parsePrimary() *ASTNode {
	t := p.peek()
	switch t.typ {
	case TK_FIELD:
		p.advance()
		return newNode("direct field value", t.text)
	case TK_FIELD_STAR:
		p.advance()
		return newNode("full record", "$*")
	case TK_FIELD_BRACKET:
		p.advance()
		e := p.parseExpr()
		p.expectPunct("]")
		return newNode("indirect field value", "$[]", e)
	case TK_FIELD_BRACKET2:
		p.advance()
		e := p.parseExpr()
		p.expectPunct("]")
		p.expectPunct("]")
		return newNode("positionally-indexed field name", "$[]", e)
	case TK_FIELD_BRACKET3:
		p.advance()
		e := p.parseExpr()
		p.expectPunct("]")
		p.expectPunct("]")
		p.expectPunct("]")
		return newNode("positionally-indexed field value", "$[]", e)
	case TK_OOSVAR:
		p.advance()
		return newNode("direct oosvar value", t.text)
	case TK_OOSVAR_STAR:
		p.advance()
		return newNode("full oosvar", "@*")
	case TK_OOSVAR_BRACKET:
		p.advance()
		e := p.parseExpr()
		p.expectPunct("]")
		return newNode("indirect oosvar value", "@[]", e)
	case TK_INT:
		p.advance()
		return newNode("int literal", t.text)
	case TK_FLOAT:
		p.advance()
		return newNode("float literal", t.text)
	case TK_STRING:
		p.advance()
		return newNode("string literal", t.text)
	case TK_REGEXI:
		p.advance()
		return newNode("case-insensitive regular expression", "\""+t.text+"\"i")
	case TK_PUNCT:
		switch t.text {
		case "(":
			p.advance()
			e := p.parseExpr()
			p.expectPunct(")")
			return e
		case "{":
			return p.parseMapLiteral()
		case "[":
			p.advance()
			n := newNode("array literal", "[]")
			if p.isPunct("]") {
				p.advance()
				return n
			}
			for {
				n.Children = append(n.Children, p.parseExpr())
				if p.isPunct(",") {
					p.advance()
					if p.isPunct("]") {
						p.advance()
						return n
					}
					continue
				}
				p.expectPunct("]")
				return n
			}
		}
	case TK_IDENT:
		switch t.text {
		case "true", "false":
			p.advance()
			return newNode("bool literal", t.text)
		case "M_PI", "M_E":
			p.advance()
			return newNode("mathematical constant", t.text)
		case "ENV":
			p.advance()
			if !p.isPunct("[") {
				p.fail()
			}
			p.advance()
			e := p.parseExpr()
			p.expectPunct("]")
			return newNode("environment variable", "ENV", e)
		case "all":
			p.advance()
			return newNode("full oosvar", "all")
		case "func":
			return p.parseFuncLiteral()
		}
		if contextVars[t.text] {
			p.advance()
			return newNode("context variable", t.text)
		}
		if keywordIdents[t.text] {
			p.fail()
		}
		p.advance()
		if p.isPunct("(") {
			p.advance()
			n := newNode("function callsite", t.text)
			n.Children = p.parseArgList(")")
			return n
		}
		return newNode("local variable", t.text)
	}
	p.fail()
	return nil
}
EOF
