cd /workspace/src && cat > dsl_interp.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"strings"
)

type flowCode int

const (
	FLOW_NORMAL flowCode = iota
	FLOW_BREAK
	FLOW_CONTINUE
	FLOW_RETURN
)

type Evaluator func(st *State) *Mlrval
type Executor func(st *State) flowCode

type LocalVar struct {
	val *Mlrval
	typ string
}

type Scope struct {
	vars map[string]*LocalVar
}

type Frame struct {
	scopes []*Scope
}

func newFrame() *Frame {
	return &Frame{scopes: []*Scope{{vars: map[string]*LocalVar{}}}}
}

func (f *Frame) push() {
	f.scopes = append(f.scopes, &Scope{vars: nil})
}
func (f *Frame) pop() {
	f.scopes = f.scopes[:len(f.scopes)-1]
}
func (f *Frame) lookup(name string) *LocalVar {
	for i := len(f.scopes) - 1; i >= 0; i-- {
		s := f.scopes[i]
		if s.vars != nil {
			if v, ok := s.vars[name]; ok {
				return v
			}
		}
	}
	return nil
}
func (f *Frame) defineLocal(name string, lv *LocalVar) {
	s := f.scopes[len(f.scopes)-1]
	if s.vars == nil {
		s.vars = map[string]*LocalVar{}
	}
	s.vars[name] = lv
}

type State struct {
	rec          *Mlrmap
	ctx          *Context
	oosvars      *Mlrmap
	frame        *Frame
	captures     []string
	filterResult *Mlrval
	retval       *Mlrval
	prog         *Program
	emitRecord   func(rec *Mlrmap)
	emitString   func(s string)
	inBeginEnd   bool
}

type UDF struct {
	name     string
	params   []string
	ptypes   []string
	rettype  string
	body     Executor
	isSubr   bool
	node     *ASTNode
}

type Program struct {
	beginBlocks []Executor
	mainBlock   Executor
	endBlocks   []Executor
	udfs        map[string]*UDF
	subrs       map[string]*UDF
	isFilter    bool
	opts        *Options
	hasMain     bool
	pendingCalls []*pendingCall
}

type pendingCall struct {
	name  string
	nargs int
	slot  **UDF
	isSubr bool
}

type dslRuntimeError struct {
	msg string
}

func runtimeFatal(format string, args ...interface{}) {
	panic(&dslRuntimeError{fmt.Sprintf(format, args...)})
}

func compileFatal(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, format, args...)
	if !strings.HasSuffix(format, "\n") {
		fmt.Fprintln(os.Stderr)
	}
	os.Exit(1)
}

// ---------------------------------------------------------------- compile

type compiler struct {
	prog       *Program
	inBeginEnd bool
	inFunc     bool
	inLoop     int
	funcName   string
}

func compileProgram(root *ASTNode, opts *Options, isFilter bool) *Program {
	prog := &Program{udfs: map[string]*UDF{}, subrs: map[string]*UDF{}, isFilter: isFilter, opts: opts}
	c := &compiler{prog: prog}
	// first pass: register function signatures (hoisting)
	for _, stmt := range root.Children {
		if stmt.Type == "function definition" {
			if _, exists := prog.udfs[stmt.Text]; exists {
				compileFatal("mlr: function named \"%s\" has already been defined.", stmt.Text)
			}
			if builtinExists(stmt.Text) {
				compileFatal("mlr: function name \"%s\" must not be a built-in function.", stmt.Text)
			}
			prog.udfs[stmt.Text] = &UDF{name: stmt.Text, node: stmt}
		} else if stmt.Type == "subroutine definition" {
			if _, exists := prog.subrs[stmt.Text]; exists {
				compileFatal("mlr: subroutine named \"%s\" has already been defined.", stmt.Text)
			}
			prog.subrs[stmt.Text] = &UDF{name: stmt.Text, node: stmt, isSubr: true}
		}
	}
	var mainStmts []Executor
	for _, stmt := range root.Children {
		switch stmt.Type {
		case "begin block":
			c.inBeginEnd = true
			prog.beginBlocks = append(prog.beginBlocks, c.compileBlock(stmt.Children[0], true))
			c.inBeginEnd = false
		case "end block":
			c.inBeginEnd = true
			prog.endBlocks = append(prog.endBlocks, c.compileBlock(stmt.Children[0], true))
			c.inBeginEnd = false
		case "function definition":
			c.compileUDF(prog.udfs[stmt.Text], stmt, false)
		case "subroutine definition":
			c.compileUDF(prog.subrs[stmt.Text], stmt, true)
		default:
			mainStmts = append(mainStmts, c.compileStatement(stmt))
			prog.hasMain = true
		}
	}
	prog.mainBlock = func(st *State) flowCode {
		for _, s := range mainStmts {
			f := s(st)
			if f != FLOW_NORMAL {
				return f
			}
		}
		return FLOW_NORMAL
	}
	return prog
}

func (c *compiler) compileUDF(udf *UDF, node *ASTNode, isSubr bool) {
	pl := node.Children[0]
	for _, p := range pl.Children {
		pn := p.Children[0]
		udf.params = append(udf.params, pn.Text)
		typ := "any"
		if len(pn.Children) > 0 {
			typ = pn.Children[0].Text
		}
		udf.ptypes = append(udf.ptypes, typ)
	}
	if len(node.Children) > 2 {
		udf.rettype = node.Children[2].Text
	}
	save := c.inFunc
	saveName := c.funcName
	c.inFunc = true
	c.funcName = udf.name
	if !isSubr {
		checkReturnsHaveValues(node.Children[1])
	}
	udf.body = c.compileBlock(node.Children[1], false)
	c.inFunc = save
	c.funcName = saveName
}

func checkReturnsHaveValues(n *ASTNode) {
	if n.Type == "function literal" {
		return
	}
	if n.Type == "return" && len(n.Children) == 0 {
		compileFatal("mlr: return statements in func blocks must return a value.")
	}
	for _, ch := range n.Children {
		checkReturnsHaveValues(ch)
	}
}

// compileBlock: a curly-braced block with its own scope
func (c *compiler) compileBlock(node *ASTNode, isTopBlock bool) Executor {
	stmts := make([]Executor, 0, len(node.Children))
	for _, s := range node.Children {
		stmts = append(stmts, c.compileStatement(s))
	}
	return func(st *State) flowCode {
		st.frame.push()
		for _, s := range stmts {
			f := s(st)
			if f != FLOW_NORMAL {
				st.frame.pop()
				return f
			}
		}
		st.frame.pop()
		return FLOW_NORMAL
	}
}

func (c *compiler) compileStatement(node *ASTNode) Executor {
	switch node.Type {
	case "assignment":
		return c.compileAssignment(node)
	case "bare boolean":
		ev := c.compileExpr(node.Children[0])
		if c.prog.isFilter {
			return func(st *State) flowCode {
				st.filterResult = ev(st)
				return FLOW_NORMAL
			}
		}
		return func(st *State) flowCode {
			ev(st)
			return FLOW_NORMAL
		}
	case "filter statement":
		if c.prog.isFilter {
			compileFatal("mlr: filter expressions must not also contain the \"filter\" keyword.")
		}
		ev := c.compileExpr(node.Children[0])
		return func(st *State) flowCode {
			v := ev(st)
			st.filterResult = v
			return FLOW_NORMAL
		}
	case "if-chain":
		return c.compileIfChain(node)
	case "cond block":
		cond := c.compileExpr(node.Children[0])
		body := c.compileBlock(node.Children[1], false)
		return func(st *State) flowCode {
			v := cond(st)
			if v.IsAbsent() {
				return FLOW_NORMAL
			}
			if v.Type() != MT_BOOLEAN {
				runtimeFatal("mlr: conditional expression did not evaluate to boolean.")
			}
			if v.IsTrue() {
				return body(st)
			}
			return FLOW_NORMAL
		}
	case "while loop":
		cond := c.compileExpr(node.Children[0])
		c.inLoop++
		body := c.compileBlock(node.Children[1], false)
		c.inLoop--
		return func(st *State) flowCode {
			for {
				v := cond(st)
				if v.Type() != MT_BOOLEAN {
					if v.IsAbsent() {
						return FLOW_NORMAL
					}
					runtimeFatal("mlr: conditional expression did not evaluate to boolean.")
				}
				if !v.IsTrue() {
					return FLOW_NORMAL
				}
				f := body(st)
				if f == FLOW_BREAK {
					return FLOW_NORMAL
				}
				if f == FLOW_RETURN {
					return f
				}
			}
		}
	case "do-while`loop":
		c.inLoop++
		body := c.compileBlock(node.Children[0], false)
		c.inLoop--
		cond := c.compileExpr(node.Children[1])
		return func(st *State) flowCode {
			for {
				f := body(st)
				if f == FLOW_BREAK {
					return FLOW_NORMAL
				}
				if f == FLOW_RETURN {
					return f
				}
				v := cond(st)
				if v.Type() != MT_BOOLEAN {
					if v.IsAbsent() {
						return FLOW_NORMAL
					}
					runtimeFatal("mlr: conditional expression did not evaluate to boolean.")
				}
				if !v.IsTrue() {
					return FLOW_NORMAL
				}
			}
		}
	case "single-variable for-loop":
		return c.compileForSingle(node)
	case "double-variable for-loop":
		return c.compileForDouble(node)
	case "multi-variable for-loop":
		return c.compileForMulti(node)
	case "triple-for loop":
		return c.compileForTriple(node)
	case "break":
		return func(st *State) flowCode { return FLOW_BREAK }
	case "continue":
		return func(st *State) flowCode { return FLOW_CONTINUE }
	case "return":
		if len(node.Children) == 0 {
			return func(st *State) flowCode {
				st.retval = ABSENT
				return FLOW_RETURN
			}
		}
		ev := c.compileExpr(node.Children[0])
		return func(st *State) flowCode {
			st.retval = ev(st)
			return FLOW_RETURN
		}
	case "unset":
		return c.compileUnset(node)
	case "print statement", "printn statement", "eprint statement", "eprintn statement":
		return c.compilePrint(node)
	case "dump statement", "edump statement":
		return c.compileDump(node)
	case "tee statement":
		return c.compileTee(node)
	case "emit statement", "emitp statement":
		return c.compileEmit(node)
	case "emitf statement":
		return c.compileEmitf(node)
	case "emit1 statement":
		return c.compileEmit1(node)
	case "subroutine callsite":
		return c.compileSubrCall(node)
	case "begin block", "end block":
		compileFatal("mlr: begin blocks may only be at top level.")
	case "function definition":
		compileFatal("mlr: func blocks may only be at top level.")
	case "subroutine definition":
		compileFatal("mlr: subr blocks may only be at top level.")
	}
	compileFatal("mlr: unhandled statement type %s", node.Type)
	return nil
}

func condToBool(v *Mlrval) bool {
	if v.Type() != MT_BOOLEAN {
		if v.IsAbsent() {
			return false
		}
		runtimeFatal("mlr: conditional expression did not evaluate to boolean.")
	}
	return v.IsTrue()
}

func (c *compiler) compileIfChain(node *ASTNode) Executor {
	type item struct {
		cond Evaluator
		body Executor
	}
	var items []item
	for _, it := range node.Children {
		if it.Text == "else" {
			items = append(items, item{nil, c.compileBlock(it.Children[0], false)})
		} else {
			items = append(items, item{c.compileExpr(it.Children[0]), c.compileBlock(it.Children[1], false)})
		}
	}
	return func(st *State) flowCode {
		for _, it := range items {
			if it.cond == nil {
				return it.body(st)
			}
			v := it.cond(st)
			if v.IsAbsent() {
				continue
			}
			if v.Type() != MT_BOOLEAN {
				runtimeFatal("mlr: conditional expression did not evaluate to boolean.")
			}
			if v.IsTrue() {
				return it.body(st)
			}
		}
		return FLOW_NORMAL
	}
}

func (c *compiler) compileForSingle(node *ASTNode) Executor {
	name := node.Children[0].Text
	iter := c.compileExpr(node.Children[1])
	c.inLoop++
	body := c.compileBlock(node.Children[2], false)
	c.inLoop--
	return func(st *State) flowCode {
		v := iter(st)
		if v.IsAbsent() {
			return FLOW_NORMAL
		}
		var items []*Mlrval
		if v.mtype == MT_MAP {
			for _, k := range v.mapval.keys {
				items = append(items, MlrvalFromString(k))
			}
		} else if v.mtype == MT_ARRAY {
			items = append(items, v.arrayval...)
		} else {
			runtimeFatal("mlr: looped-over item is not a map or array; got %s", typeName(v))
		}
		st.frame.push()
		defer st.frame.pop()
		for _, it := range items {
			st.frame.defineLocal(name, &LocalVar{val: it.Copy(), typ: "any"})
			f := body(st)
			if f == FLOW_BREAK {
				break
			}
			if f == FLOW_RETURN {
				return f
			}
		}
		return FLOW_NORMAL
	}
}

func keyMlrval(k string) *Mlrval {
	return MlrvalFromInferred(k)
}

func (c *compiler) compileForDouble(node *ASTNode) Executor {
	kname := node.Children[0].Text
	vname := node.Children[1].Text
	iter := c.compileExpr(node.Children[2])
	c.inLoop++
	body := c.compileBlock(node.Children[3], false)
	c.inLoop--
	return func(st *State) flowCode {
		v := iter(st)
		if v.IsAbsent() {
			return FLOW_NORMAL
		}
		var ks []*Mlrval
		var vs []*Mlrval
		if v.mtype == MT_MAP {
			for i, k := range v.mapval.keys {
				ks = append(ks, MlrvalFromString(k))
				vs = append(vs, v.mapval.vals[i])
			}
		} else if v.mtype == MT_ARRAY {
			for i, e := range v.arrayval {
				ks = append(ks, MlrvalFromInt(int64(i+1)))
				vs = append(vs, e)
			}
		} else {
			runtimeFatal("mlr: looped-over item is not a map or array; got %s", typeName(v))
		}
		st.frame.push()
		defer st.frame.pop()
		for i := range ks {
			st.frame.defineLocal(kname, &LocalVar{val: ks[i], typ: "any"})
			st.frame.defineLocal(vname, &LocalVar{val: vs[i].Copy(), typ: "any"})
			f := body(st)
			if f == FLOW_BREAK {
				break
			}
			if f == FLOW_RETURN {
				return f
			}
		}
		return FLOW_NORMAL
	}
}

func (c *compiler) compileForMulti(node *ASTNode) Executor {
	var knames []string
	for _, k := range node.Children[0].Children {
		knames = append(knames, k.Text)
	}
	vname := node.Children[1].Text
	iter := c.compileExpr(node.Children[2])
	c.inLoop++
	body := c.compileBlock(node.Children[3], false)
	c.inLoop--
	var walk func(st *State, v *Mlrval, depth int, keys []*Mlrval) flowCode
	walk = func(st *State, v *Mlrval, depth int, keys []*Mlrval) flowCode {
		if depth == len(knames) {
			for i, k := range keys {
				st.frame.defineLocal(knames[i], &LocalVar{val: k, typ: "any"})
			}
			st.frame.defineLocal(vname, &LocalVar{val: v.Copy(), typ: "any"})
			return body(st)
		}
		if v.mtype != MT_MAP {
			return FLOW_NORMAL
		}
		for i, k := range v.mapval.keys {
			f := walk(st, v.mapval.vals[i], depth+1, append(keys, MlrvalFromString(k)))
			if f == FLOW_BREAK || f == FLOW_RETURN {
				return f
			}
		}
		return FLOW_NORMAL
	}
	return func(st *State) flowCode {
		v := iter(st)
		if v.IsAbsent() {
			return FLOW_NORMAL
		}
		st.frame.push()
		defer st.frame.pop()
		f := walk(st, v.Copy(), 0, nil)
		if f == FLOW_RETURN {
			return f
		}
		return FLOW_NORMAL
	}
}

func (c *compiler) compileForTriple(node *ASTNode) Executor {
	var inits []Executor
	for _, s := range node.Children[0].Children {
		inits = append(inits, c.compileStatement(s))
	}
	var cond Evaluator
	if len(node.Children[1].Children) > 0 {
		cond = c.compileExpr(node.Children[1].Children[0].Children[0])
	}
	var updates []Executor
	for _, s := range node.Children[2].Children {
		updates = append(updates, c.compileStatement(s))
	}
	c.inLoop++
	body := c.compileBlock(node.Children[3], false)
	c.inLoop--
	return func(st *State) flowCode {
		st.frame.push()
		defer st.frame.pop()
		for _, s := range inits {
			s(st)
		}
		for {
			if cond != nil {
				v := cond(st)
				if v.Type() != MT_BOOLEAN {
					runtimeFatal("mlr: for-loop condition did not evaluate to boolean.")
				}
				if !v.IsTrue() {
					break
				}
			}
			f := body(st)
			if f == FLOW_BREAK {
				break
			}
			if f == FLOW_RETURN {
				return f
			}
			for _, s := range updates {
				s(st)
			}
		}
		return FLOW_NORMAL
	}
}

func (c *compiler) compileSubrCall(node *ASTNode) Executor {
	name := node.Text
	var args []Evaluator
	for _, a := range node.Children {
		args = append(args, c.compileExpr(a))
	}
	udf, ok := c.prog.subrs[name]
	if !ok {
		compileFatal("mlr: subroutine name not found: %s", name)
	}
	if len(udf.node.Children[0].Children) != len(args) {
		compileFatal("mlr: subroutine %s invoked with %d argument(s); expected %d", name, len(args), len(udf.node.Children[0].Children))
	}
	return func(st *State) flowCode {
		vals := make([]*Mlrval, len(args))
		for i, a := range args {
			vals[i] = a(st)
		}
		callUDF(st, udf, vals)
		return FLOW_NORMAL
	}
}

func typeCheck(typ string, v *Mlrval) bool {
	switch typ {
	case "", "any", "var":
		return true
	case "str":
		t := v.Type()
		return t == MT_STRING || t == MT_VOID || t == MT_ABSENT
	case "num":
		t := v.Type()
		return t == MT_INT || t == MT_FLOAT || t == MT_ABSENT
	case "int":
		t := v.Type()
		return t == MT_INT || t == MT_ABSENT
	case "float":
		t := v.Type()
		return t == MT_FLOAT || t == MT_ABSENT
	case "bool":
		t := v.Type()
		return t == MT_BOOLEAN || t == MT_ABSENT
	case "map":
		t := v.Type()
		return t == MT_MAP || t == MT_ABSENT
	case "arr":
		t := v.Type()
		return t == MT_ARRAY || t == MT_ABSENT
	case "funct":
		t := v.Type()
		return t == MT_FUNC || t == MT_ABSENT
	}
	return true
}

func callUDF(st *State, udf *UDF, args []*Mlrval) *Mlrval {
	saveFrame := st.frame
	st.frame = newFrame()
	for i, p := range udf.params {
		if !typeCheck(udf.ptypes[i], args[i]) {
			runtimeFatal("mlr: couldn't define variable %s %s from value %s", udf.ptypes[i], p, args[i].String())
		}
		st.frame.defineLocal(p, &LocalVar{val: args[i], typ: udf.ptypes[i]})
	}
	st.retval = ABSENT
	udf.body(st)
	ret := st.retval
	st.retval = nil
	st.frame = saveFrame
	if ret == nil {
		ret = ABSENT
	}
	if !udf.isSubr && udf.rettype != "" {
		if !typeCheck(udf.rettype, ret) || (ret.IsAbsent() && udf.rettype != "any" && udf.rettype != "var") {
			runtimeFatal("mlr: couldn't define variable %s function return value from value %s", udf.rettype, ret.String())
		}
	}
	return ret
}
