package main

import (
	"math"
	"os"
	"regexp"
	"strconv"
	"strings"
)

// ---------------------------------------------------------------- string literal processing

// unbackslash for string literals (non-regex contexts)
func unbackslashStringLiteral(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '\\' || i+1 >= len(s) {
			b.WriteByte(c)
			continue
		}
		n := s[i+1]
		switch n {
		case 't':
			b.WriteByte('\t')
			i++
		case 'n':
			b.WriteByte('\n')
			i++
		case 'r':
			b.WriteByte('\r')
			i++
		case '"':
			b.WriteByte('"')
			i++
		case '\\':
			b.WriteByte('\\')
			i++
		case 'a':
			b.WriteByte('\a')
			i++
		case 'b':
			b.WriteByte('\b')
			i++
		case 'f':
			b.WriteByte('\f')
			i++
		case 'v':
			b.WriteByte('\v')
			i++
		case 'u':
			if i+5 < len(s)+0 && i+6 <= len(s) {
				v, err := strconv.ParseUint(s[i+2:i+6], 16, 32)
				if err == nil {
					b.WriteRune(rune(v))
					i += 5
					continue
				}
			}
			b.WriteByte(c)
		case 'x':
			if i+4 <= len(s) {
				v, err := strconv.ParseUint(s[i+2:i+4], 16, 8)
				if err == nil {
					b.WriteByte(byte(v))
					i += 3
					continue
				}
			}
			b.WriteByte(c)
		default:
			b.WriteByte(c)
		}
	}
	return b.String()
}

var captureRefRegex = regexp.MustCompile(`\\[0-9]`)

func hasCaptureRefs(s string) bool {
	return captureRefRegex.MatchString(s)
}

func interpolateCaptures(s string, captures []string) string {
	if captures == nil {
		return s
	}
	return captureRefRegex.ReplaceAllStringFunc(s, func(m string) string {
		idx := int(m[1] - '0')
		if idx < len(captures) {
			return captures[idx]
		}
		return ""
	})
}

// ---------------------------------------------------------------- regex cache
var regexCache = map[string]*regexp.Regexp{}

func getRegex(s string) *regexp.Regexp {
	if re, ok := regexCache[s]; ok {
		return re
	}
	re, err := regexp.Compile(s)
	if err != nil {
		// try quoting
		re2, err2 := regexp.Compile(regexp.QuoteMeta(s))
		if err2 != nil {
			fatalf("mlr: could not compile regex \"%s\"\n", s)
		}
		re = re2
	}
	regexCache[s] = re
	return re
}

// regex literal from AST string literal (regex context): returns the regex string
func regexStringFromLiteralNode(n *ASTNode) (string, bool) {
	if n.Type == "string literal" {
		return regexLiteralUnbackslash(n.Text), true
	}
	if n.Type == "case-insensitive regular expression" {
		t := n.Text
		inner := t[1 : len(t)-2]
		return "(?i)" + regexLiteralUnbackslash(inner), true
	}
	return "", false
}

// In regex literals, keep backslash sequences for regex engine, but convert \t, \n, \" etc.
func regexLiteralUnbackslash(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			n := s[i+1]
			if n == '"' {
				b.WriteByte('"')
				i++
				continue
			}
			b.WriteByte(c)
			b.WriteByte(n)
			i++
			continue
		}
		b.WriteByte(c)
	}
	return b.String()
}

// ---------------------------------------------------------------- expressions

func (c *compiler) checkRecordAccess(node *ASTNode) {
	if c.inBeginEnd {
		compileFatal("mlr: begin/end blocks cannot refer to records via $x, $*, etc.")
	}
}

func (c *compiler) compileExpr(node *ASTNode) Evaluator {
	switch node.Type {
	case "int literal":
		i, ok := parseIntLiteral(node.Text)
		var v *Mlrval
		if ok {
			v = MlrvalIntWithString(i, node.Text)
		} else {
			f, err := strconv.ParseFloat(node.Text, 64)
			if err != nil {
				v = MlrvalFromString(node.Text)
			} else {
				v = MlrvalFloatWithString(f, node.Text)
			}
		}
		return func(st *State) *Mlrval { return v }
	case "float literal":
		f, _ := strconv.ParseFloat(node.Text, 64)
		v := MlrvalFloatWithString(f, node.Text)
		return func(st *State) *Mlrval { return v }
	case "string literal":
		s := unbackslashStringLiteral(node.Text)
		if hasCaptureRefs(s) {
			return func(st *State) *Mlrval {
				if st.captures == nil {
					return MlrvalFromString(s)
				}
				return MlrvalFromString(interpolateCaptures(s, st.captures))
			}
		}
		v := MlrvalFromString(s)
		return func(st *State) *Mlrval { return v }
	case "case-insensitive regular expression":
		t := node.Text
		inner := t[1 : len(t)-2]
		v := MlrvalFromString("(?i)" + regexLiteralUnbackslash(inner))
		return func(st *State) *Mlrval { return v }
	case "bool literal":
		v := MlrvalFromBool(node.Text == "true")
		return func(st *State) *Mlrval { return v }
	case "mathematical constant":
		var v *Mlrval
		if node.Text == "M_PI" {
			v = MlrvalFromFloat(math.Pi)
		} else {
			v = MlrvalFromFloat(math.E)
		}
		return func(st *State) *Mlrval { return v }
	case "context variable":
		return c.compileContextVar(node.Text)
	case "environment variable":
		key := c.compileExpr(node.Children[0])
		return func(st *State) *Mlrval {
			k := key(st).String()
			v, ok := os.LookupEnv(k)
			if !ok {
				return ABSENT
			}
			return MlrvalFromInferred(v)
		}
	case "direct field value":
		c.checkRecordAccess(node)
		name := node.Text
		return func(st *State) *Mlrval {
			if st.rec == nil {
				return ABSENT
			}
			v := st.rec.Get(name)
			if v == nil {
				return ABSENT
			}
			return v
		}
	case "indirect field value":
		c.checkRecordAccess(node)
		key := c.compileExpr(node.Children[0])
		return func(st *State) *Mlrval {
			if st.rec == nil {
				return ABSENT
			}
			k := key(st)
			v := st.rec.Get(k.String())
			if v == nil {
				return ABSENT
			}
			return v
		}
	case "positionally-indexed field name":
		c.checkRecordAccess(node)
		idx := c.compileExpr(node.Children[0])
		return func(st *State) *Mlrval {
			if st.rec == nil {
				return ABSENT
			}
			i := idx(st)
			if i.Type() != MT_INT {
				return ABSENT
			}
			k, _, ok := st.rec.GetAt(int(i.intval))
			if !ok {
				return ABSENT
			}
			return MlrvalFromString(k)
		}
	case "positionally-indexed field value":
		c.checkRecordAccess(node)
		idx := c.compileExpr(node.Children[0])
		return func(st *State) *Mlrval {
			if st.rec == nil {
				return ABSENT
			}
			i := idx(st)
			if i.Type() != MT_INT {
				return ABSENT
			}
			_, v, ok := st.rec.GetAt(int(i.intval))
			if !ok {
				return ABSENT
			}
			return v
		}
	case "full record":
		c.checkRecordAccess(node)
		return func(st *State) *Mlrval {
			if st.rec == nil {
				return ABSENT
			}
			return MlrvalFromMap(st.rec)
		}
	case "direct oosvar value":
		name := node.Text
		return func(st *State) *Mlrval {
			v := st.oosvars.Get(name)
			if v == nil {
				return ABSENT
			}
			return v
		}
	case "indirect oosvar value":
		key := c.compileExpr(node.Children[0])
		return func(st *State) *Mlrval {
			v := st.oosvars.Get(key(st).String())
			if v == nil {
				return ABSENT
			}
			return v
		}
	case "full oosvar":
		return func(st *State) *Mlrval {
			return MlrvalFromMap(st.oosvars)
		}
	case "local variable":
		name := node.Text
		if _, ok := c.prog.udfs[name]; ok {
			udf := c.prog.udfs[name]
			fv := &Mlrval{mtype: MT_FUNC, funcval: udf, printrep: name, prValid: true}
			return func(st *State) *Mlrval {
				lv := st.frame.lookup(name)
				if lv != nil {
					return lv.val
				}
				return fv
			}
		}
		return func(st *State) *Mlrval {
			lv := st.frame.lookup(name)
			if lv == nil {
				return ABSENT
			}
			return lv.val
		}
	case "map literal":
		type kv struct {
			k, v Evaluator
		}
		var pairs []kv
		for _, p := range node.Children {
			pairs = append(pairs, kv{c.compileExpr(p.Children[0]), c.compileExpr(p.Children[1])})
		}
		return func(st *State) *Mlrval {
			m := NewMlrmap()
			for _, p := range pairs {
				k := p.k(st)
				v := p.v(st)
				if v.IsAbsent() {
					continue
				}
				m.Put(k.String(), v.Copy())
			}
			return MlrvalFromMap(m)
		}
	case "array literal":
		var elems []Evaluator
		for _, e := range node.Children {
			elems = append(elems, c.compileExpr(e))
		}
		return func(st *State) *Mlrval {
			a := make([]*Mlrval, 0, len(elems))
			for _, e := range elems {
