		base := c.compileExpr(node.Children[0])
		var lo, hi Evaluator
		if node.Children[1].Type != "array-slice empty lower index" {
			lo = c.compileExpr(node.Children[1])
		}
		if node.Children[2].Type != "array-slice empty upper index" {
			hi = c.compileExpr(node.Children[2])
		}
		return func(st *State) *Mlrval {
			b := base(st)
			var l, h *Mlrval
			if lo != nil {
				l = lo(st)
			}
			if hi != nil {
				h = hi(st)
			}
			return sliceValue(b, l, h)
		}
