		base := c.compileExpr(node.Children[0])
		idx := c.compileExpr(node.Children[1])
		return func(st *State) *Mlrval {
			b := base(st)
			i := idx(st)
			if b.mtype != MT_MAP || i.Type() != MT_INT {
				return ABSENT
			}
			k, _, ok := b.mapval.GetAt(int(i.intval))
			if !ok {
				return ABSENT
			}
			return MlrvalFromString(k)
		}
	case "positionally-indexed map value":
		base := c.compileExpr(node.Children[0])
		idx := c.compileExpr(node.Children[1])
		return func(st *State) *Mlrval {
			b := base(st)
			i := idx(st)
			if b.mtype != MT_MAP || i.Type() != MT_INT {
				return ABSENT
			}
			_, v, ok := b.mapval.GetAt(int(i.intval))
			if !ok {
				return ABSENT
			}
			return v
		}
	case "operator":
		return c.compileOperator(node)
	case "dot operator":
		a := c.compileExpr(node.Children[0])
		b := c.compileExpr(node.Children[1])
		return func(st *State) *Mlrval { return DotOperator(a(st), b(st)) }
	case "function callsite":
		return c.compileFunctionCall(node)
	case "function literal":
		return c.compileFunctionLiteral(node)
	}
	compileFatal("mlr: unhandled expression node type \"%s\".", node.Type)
	return nil
}

func (c *compiler) compileContextVar(name string) Evaluator {
	switch name {
	case "NR":
		return func(st *State) *Mlrval { return MlrvalFromInt(st.ctx.NR) }
	case "FNR":
		return func(st *State) *Mlrval { return MlrvalFromInt(st.ctx.FNR) }
	case "FILENUM":
		return func(st *State) *Mlrval { return MlrvalFromInt(st.ctx.FILENUM) }
	case "FILENAME":
		return func(st *State) *Mlrval {
			if st.ctx.FILENAME == "" {
				return ABSENT
			}
			return MlrvalFromString(st.ctx.FILENAME)
		}
	case "NF":
		return func(st *State) *Mlrval {
			if st.rec == nil {
				return ABSENT
			}
			return MlrvalFromInt(int64(st.rec.Len()))
		}
	case "IPS":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.R.IPS) }
	case "IFS":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.R.IFS) }
	case "IRS":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.R.IRS) }
	case "OPS":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.W.OPS) }
	case "OFS":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.W.OFS) }
	case "ORS":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.W.ORS) }
	case "FLATSEP":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.W.FlatSep) }
	}
	return func(st *State) *Mlrval { return ABSENT }
}

// index into map/array/string
func indexValue(b, i *Mlrval) *Mlrval {
	switch b.mtype {
	case MT_MAP:
		if i.IsAbsent() {
			return ABSENT
		}
		if i.Type() == MT_ERROR {
			return ERROR()
		}
		v := b.mapval.Get(i.String())
		if v == nil {
			return ABSENT
		}
		return v
	case MT_ARRAY:
		if i.Type() != MT_INT {
			if i.IsAbsent() {
				return ABSENT
			}
			return ERROR()
		}
		n := int64(len(b.arrayval))
		idx := i.intval
		if idx < 0 {
			idx += n + 1
		}
		if idx < 1 || idx > n {
			return ABSENT
		}
		return b.arrayval[idx-1]
	case MT_ABSENT:
		return ABSENT
	case MT_ERROR:
		return ERROR()
	}
	t := b.Type()
	if t == MT_STRING || t == MT_VOID || t == MT_INT || t == MT_FLOAT {
		if i.Type() != MT_INT {
			return ERROR()
		}
		runes := []rune(b.String())
		n := int64(len(runes))
		idx := i.intval
		if idx < 0 {
			idx += n + 1
		}
		if idx < 1 || idx > n {
			return ERROR()
		}
		return MlrvalFromString(string(runes[idx-1]))
	}
	return ABSENT
}

func sliceValue(b, lo, hi *Mlrval) *Mlrval {
	if b.mtype == MT_ARRAY {
		n := int64(len(b.arrayval))
		l, h := int64(1), n
		if lo != nil {
			if lo.Type() != MT_INT {
				return ERROR()
			}
			l = lo.intval
		}
		if hi != nil {
			if hi.Type() != MT_INT {
				return ERROR()
			}
			h = hi.intval
		}
		if l < 0 {
			l += n + 1
		}
		if h < 0 {
			h += n + 1
		}
		if l < 1 {
			l = 1
		}
		if h > n {
			h = n
		}
		out := make([]*Mlrval, 0)
		for k := l; k <= h; k++ {
			out = append(out, b.arrayval[k-1].Copy())
		}
		return MlrvalFromArray(out)
	}
	if b.IsAbsent() {
		return ABSENT
	}
	if b.mtype == MT_MAP {
		return ERROR()
	}
	s := b.String()
	runes := []rune(s)
	n := int64(len(runes))
	l, h := int64(1), n
	if lo != nil {
		if lo.Type() != MT_INT {
			return ERROR()
		}
		l = lo.intval
	}
	if hi != nil {
		if hi.Type() != MT_INT {
			return ERROR()
		}
		h = hi.intval
	}
	if l < 0 {
		l += n + 1
	}
	if h < 0 {
		h += n + 1
	}
	if l < 1 || h > n || l > h {
		if l > h {
			return VOID
		}
		return ERROR()
	}
	return MlrvalFromString(string(runes[l-1 : h]))
}

func (c *compiler) compileOperator(node *ASTNode) Evaluator {
	op := node.Text
	if len(node.Children) == 1 {
		a := c.compileExpr(node.Children[0])
		switch op {
		case "-":
			return func(st *State) *Mlrval { return unaryMinus(a(st)) }
		case "+":
			return func(st *State) *Mlrval { return unaryPlus(a(st)) }
		case "!":
			return func(st *State) *Mlrval { return logicalNot(a(st)) }
		case "~":
			return func(st *State) *Mlrval { return unaryBitNot(a(st)) }
		}
		compileFatal("mlr: function %s invoked with 1 argument; expected 2", op)
	}
	if len(node.Children) == 3 {
		cnd := c.compileExpr(node.Children[0])
		a := c.compileExpr(node.Children[1])
		b := c.compileExpr(node.Children[2])
		return func(st *State) *Mlrval {
			v := cnd(st)
			if v.Type() != MT_BOOLEAN {
				runtimeFatal("mlr: ternary condition did not evaluate to boolean.")
			}
			if v.IsTrue() {
				return a(st)
			}
			return b(st)
		}
	}
	a := c.compileExpr(node.Children[0])
	// regex operators
	if op == "=~" || op == "!=~" {
		var reStatic *regexp.Regexp
		if rs, ok := regexStringFromLiteralNode(node.Children[1]); ok && !hasCaptureRefs(rs) {
			reStatic = getRegex(rs)
		}
		b := c.compileExpr(node.Children[1])
		negate := op == "!=~"
		return func(st *State) *Mlrval {
			l := a(st)
			var re *regexp.Regexp
			if reStatic != nil {
				re = reStatic
			} else {
				r := b(st)
				if r.Type() != MT_STRING && r.Type() != MT_VOID {
					return ERROR()
				}
				re = getRegex(r.String())
			}
			if l.IsAbsent() {
				return ABSENT
			}
			lt := l.Type()
			if lt == MT_MAP || lt == MT_ARRAY || lt == MT_ERROR {
				return ERROR()
			}
			m := re.FindStringSubmatch(l.String())
			if m == nil {
				st.captures = make([]string, 10)
				return MlrvalFromBool(negate)
			}
			caps := make([]string, 10)
			for k := 0; k < len(m) && k < 10; k++ {
				caps[k] = m[k]
			}
			st.captures = caps
			return MlrvalFromBool(!negate)
		}
	}
	b := c.compileExpr(node.Children[1])
	switch op {
	case "&&":
		return func(st *State) *Mlrval {
			l := a(st)
			if l.Type() == MT_BOOLEAN && !l.IsTrue() {
				return FALSE
			}
			if l.Type() == MT_ERROR {
				return ERROR()
			}
			return logicalAnd(l, b(st))
		}
	case "||":
		return func(st *State) *Mlrval {
			l := a(st)
			if l.Type() == MT_BOOLEAN && l.IsTrue() {
				return TRUE
			}
			if l.Type() == MT_ERROR {
				return ERROR()
			}
			return logicalOr(l, b(st))
		}
	case "^^":
		return func(st *State) *Mlrval { return logicalXor(a(st), b(st)) }
	case "??":
		return func(st *State) *Mlrval {
			l := a(st)
			if l.IsAbsent() {
				return b(st)
			}
			return l
		}
	case "???":
		return func(st *State) *Mlrval {
			l := a(st)
			if l.IsAbsent() || (l.Type() == MT_VOID && !l.isnull) {
				return b(st)
			}
			return l
		}
	}
	f := binaryOpFunc(op)
	if f == nil {
		compileFatal("mlr: unhandled operator %s", op)
	}
	return func(st *State) *Mlrval { return f(a(st), b(st)) }
}

func binaryOpFunc(op string) func(a, b *Mlrval) *Mlrval {
	switch op {
	case "+":
		return BinaryPlus
	case "-":
		return BinaryMinus
	case "*":
		return BinaryTimes
	case "/":
		return BinaryDivide
	case "//":
		return BinaryIntDivide
	case "%":
		return BinaryMod
	case "**":
		return BinaryPow
	case ".+":
		return BinaryDotPlus
	case ".-":
		return BinaryDotMinus
	case ".*":
		return BinaryDotTimes
	case "./":
		return BinaryDotDivide
	case "&":
		return BitwiseAnd
	case "|":
		return BitwiseOr
	case "^":
		return BitwiseXor
	case "<<":
		return LeftShift
	case ">>":
		return SignedRightShift
	case ">>>":
		return UnsignedRightShift
	case "==":
		return func(a, b *Mlrval) *Mlrval { return compareOp(0, a, b) }
	case "!=":
		return func(a, b *Mlrval) *Mlrval { return compareOp(1, a, b) }
	case "<":
		return func(a, b *Mlrval) *Mlrval { return compareOp(2, a, b) }
	case "<=":
		return func(a, b *Mlrval) *Mlrval { return compareOp(3, a, b) }
	case ">":
		return func(a, b *Mlrval) *Mlrval { return compareOp(4, a, b) }
	case ">=":
		return func(a, b *Mlrval) *Mlrval { return compareOp(5, a, b) }
	case "<=>":
		return spaceship
	case "&&":
		return logicalAnd
	case "||":
		return logicalOr
	case "^^":
		return logicalXor
	case ".":
		return DotOperator
	}
	return nil
}

type FuncLiteral struct {
	udf *UDF
}

func (c *compiler) compileFunctionLiteral(node *ASTNode) Evaluator {
	udf := &UDF{name: "function-literal", node: node}
	c.compileUDF(udf, node, false)
	fv := &Mlrval{mtype: MT_FUNC, funcval: udf, printrep: "(function-literal)", prValid: true}
	return func(st *State) *Mlrval { return fv }
}
