package main

import (
	"math"
	"os"
	"regexp"
	"strconv"
	"strings"
)

// ---------------------------------------------------------------- string literal processing

// unbackslash for string literals (non-regex contexts)
func unbackslashStringLiteral(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '\\' || i+1 >= len(s) {
			b.WriteByte(c)
			continue
		}
		n := s[i+1]
		switch n {
		case 't':
			b.WriteByte('\t')
			i++
		case 'n':
			b.WriteByte('\n')
			i++
		case 'r':
			b.WriteByte('\r')
			i++
		case '"':
			b.WriteByte('"')
			i++
		case '\\':
			b.WriteByte('\\')
			i++
		case 'a':
			b.WriteByte('\a')
			i++
		case 'b':
			b.WriteByte('\b')
			i++
		case 'f':
			b.WriteByte('\f')
			i++
		case 'v':
			b.WriteByte('\v')
			i++
		case 'u':
			if i+5 < len(s)+0 && i+6 <= len(s) {
				v, err := strconv.ParseUint(s[i+2:i+6], 16, 32)
				if err == nil {
					b.WriteRune(rune(v))
					i += 5
					continue
				}
			}
			b.WriteByte(c)
		case 'x':
			if i+4 <= len(s) {
				v, err := strconv.ParseUint(s[i+2:i+4], 16, 8)
				if err == nil {
					b.WriteByte(byte(v))
					i += 3
					continue
				}
			}
			b.WriteByte(c)
		default:
			b.WriteByte(c)
		}
	}
	return b.String()
}

var captureRefRegex = regexp.MustCompile(`\\[0-9]`)

func hasCaptureRefs(s string) bool {
	return captureRefRegex.MatchString(s)
}

func interpolateCaptures(s string, captures []string) string {
	if captures == nil {
		return s
	}
	return captureRefRegex.ReplaceAllStringFunc(s, func(m string) string {
		idx := int(m[1] - '0')
		if idx < len(captures) {
			return captures[idx]
		}
		return ""
	})
}

// ---------------------------------------------------------------- regex cache
var regexCache = map[string]*regexp.Regexp{}

func getRegex(s string) *regexp.Regexp {
	if re, ok := regexCache[s]; ok {
		return re
	}
	re, err := regexp.Compile(s)
	if err != nil {
		// try quoting
		re2, err2 := regexp.Compile(regexp.QuoteMeta(s))
		if err2 != nil {
			fatalf("mlr: could not compile regex \"%s\"\n", s)
		}
		re = re2
	}
	regexCache[s] = re
	return re
}

// regex literal from AST string literal (regex context): returns the regex string
func regexStringFromLiteralNode(n *ASTNode) (string, bool) {
	if n.Type == "string literal" {
		return regexLiteralUnbackslash(n.Text), true
	}
	if n.Type == "case-insensitive regular expression" {
		t := n.Text
		inner := t[1 : len(t)-2]
		return "(?i)" + regexLiteralUnbackslash(inner), true
	}
	return "", false
}

// In regex literals, keep backslash sequences for regex engine, but convert \t, \n, \" etc.
func regexLiteralUnbackslash(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			n := s[i+1]
			if n == '"' {
				b.WriteByte('"')
				i++
				continue
			}
			b.WriteByte(c)
			b.WriteByte(n)
			i++
			continue
		}
		b.WriteByte(c)
	}
	return b.String()
}

// ---------------------------------------------------------------- expressions

func (c *compiler) checkRecordAccess(node *ASTNode) {
	if c.inBeginEnd {
		compileFatal("mlr: begin/end blocks cannot refer to records via $x, $*, etc.")
	}
}

func (c *compiler) compileExpr(node *ASTNode) Evaluator {
	switch node.Type {
	case "int literal":
		i, ok := parseIntLiteral(node.Text)
		var v *Mlrval
		if ok {
			v = MlrvalIntWithString(i, node.Text)
		} else {
			f, err := strconv.ParseFloat(node.Text, 64)
			if err != nil {
				v = MlrvalFromString(node.Text)
			} else {
				v = MlrvalFloatWithString(f, node.Text)
			}
		}
		return func(st *State) *Mlrval { return v }
	case "float literal":
		f, _ := strconv.ParseFloat(node.Text, 64)
		v := MlrvalFloatWithString(f, node.Text)
		return func(st *State) *Mlrval { return v }
	case "string literal":
		s := unbackslashStringLiteral(node.Text)
		if hasCaptureRefs(s) {
			return func(st *State) *Mlrval {
				if st.captures == nil {
					return MlrvalFromString(s)
				}
				return MlrvalFromString(interpolateCaptures(s, st.captures))
			}
		}
		v := MlrvalFromString(s)
		return func(st *State) *Mlrval { return v }
	case "case-insensitive regular expression":
		t := node.Text
		inner := t[1 : len(t)-2]
		v := MlrvalFromString("(?i)" + regexLiteralUnbackslash(inner))
		return func(st *State) *Mlrval { return v }
	case "bool literal":
		v := MlrvalFromBool(node.Text == "true")
		return func(st *State) *Mlrval { return v }
	case "mathematical constant":
		var v *Mlrval
		if node.Text == "M_PI" {
			v = MlrvalFromFloat(math.Pi)
		} else {
			v = MlrvalFromFloat(math.E)
		}
		return func(st *State) *Mlrval { return v }
	case "context variable":
		return c.compileContextVar(node.Text)
	case "environment variable":
		key := c.compileExpr(node.Children[0])
		return func(st *State) *Mlrval {
			k := key(st).String()
			v, ok := os.LookupEnv(k)
			if !ok {
				return ABSENT
			}
			return MlrvalFromInferred(v)
		}
	case "direct field value":
		c.checkRecordAccess(node)
		name := node.Text
		return func(st *State) *Mlrval {
			if st.rec == nil {
				return ABSENT
			}
			v := st.rec.Get(name)
			if v == nil {
				return ABSENT
			}
			return v
		}
	case "indirect field value":
		c.checkRecordAccess(node)
		key := c.compileExpr(node.Children[0])
		return func(st *State) *Mlrval {
			if st.rec == nil {
				return ABSENT
			}
			k := key(st)
			v := st.rec.Get(k.String())
			if v == nil {
				return ABSENT
			}
			return v
		}
	case "positionally-indexed field name":
		c.checkRecordAccess(node)
		idx := c.compileExpr(node.Children[0])
		return func(st *State) *Mlrval {
			if st.rec == nil {
				return ABSENT
			}
			i := idx(st)
			if i.Type() != MT_INT {
				return ABSENT
			}
			k, _, ok := st.rec.GetAt(int(i.intval))
			if !ok {
				return ABSENT
			}
			return MlrvalFromString(k)
		}
	case "positionally-indexed field value":
		c.checkRecordAccess(node)
		idx := c.compileExpr(node.Children[0])
		return func(st *State) *Mlrval {
			if st.rec == nil {
				return ABSENT
			}
			i := idx(st)
			if i.Type() != MT_INT {
				return ABSENT
			}
			_, v, ok := st.rec.GetAt(int(i.intval))
			if !ok {
				return ABSENT
			}
			return v
		}
	case "full record":
		c.checkRecordAccess(node)
		return func(st *State) *Mlrval {
			if st.rec == nil {
				return ABSENT
			}
			return MlrvalFromMap(st.rec)
		}
	case "direct oosvar value":
		name := node.Text
		return func(st *State) *Mlrval {
			v := st.oosvars.Get(name)
			if v == nil {
				return ABSENT
			}
			return v
		}
	case "indirect oosvar value":
		key := c.compileExpr(node.Children[0])
		return func(st *State) *Mlrval {
			v := st.oosvars.Get(key(st).String())
			if v == nil {
				return ABSENT
			}
			return v
		}
	case "full oosvar":
		return func(st *State) *Mlrval {
			return MlrvalFromMap(st.oosvars)
		}
	case "local variable":
		name := node.Text
		if _, ok := c.prog.udfs[name]; ok {
			udf := c.prog.udfs[name]
			fv := &Mlrval{mtype: MT_FUNC, funcval: udf, printrep: name, prValid: true}
			return func(st *State) *Mlrval {
				lv := st.frame.lookup(name)
				if lv != nil {
					return lv.val
				}
				return fv
			}
		}
		return func(st *State) *Mlrval {
			lv := st.frame.lookup(name)
			if lv == nil {
				return ABSENT
			}
			return lv.val
		}
	case "map literal":
		type kv struct {
			k, v Evaluator
		}
		var pairs []kv
		for _, p := range node.Children {
			pairs = append(pairs, kv{c.compileExpr(p.Children[0]), c.compileExpr(p.Children[1])})
		}
		return func(st *State) *Mlrval {
			m := NewMlrmap()
			for _, p := range pairs {
				k := p.k(st)
				v := p.v(st)
				if v.IsAbsent() {
					continue
				}
				m.Put(k.String(), v.Copy())
			}
			return MlrvalFromMap(m)
		}
	case "array literal":
		var elems []Evaluator
		for _, e := range node.Children {
			elems = append(elems, c.compileExpr(e))
		}
		return func(st *State) *Mlrval {
			a := make([]*Mlrval, 0, len(elems))
			for _, e := range elems {
				a = append(a, e(st).Copy())
			}
			return MlrvalFromArray(a)
		}
	case "array or map index access":
		base := c.compileExpr(node.Children[0])
		idx := c.compileExpr(node.Children[1])
		return func(st *State) *Mlrval {
			return indexValue(base(st), idx(st))
		}
	case "array-slice access":
		base := c.compileExpr(node.Children[0])
		var lo, hi Evaluator
		if node.Children[1].Type != "array-slice empty lower index" {
			lo = c.compileExpr(node.Children[1])
		}
		if node.Children[2].Type != "array-slice empty upper index" {
			hi = c.compileExpr(node.Children[2])
		}
		return func(st *State) *Mlrval {
			b := base(st)
			var l, h *Mlrval
			if lo != nil {
				l = lo(st)
			}
			if hi != nil {
				h = hi(st)
			}
			return sliceValue(b, l, h)
		}
	case "positionally-indexed map key":
		base := c.compileExpr(node.Children[0])
		idx := c.compileExpr(node.Children[1])
		return func(st *State) *Mlrval {
			b := base(st)
			i := idx(st)
			if b.mtype != MT_MAP || i.Type() != MT_INT {
				return ABSENT
			}
			k, _, ok := b.mapval.GetAt(int(i.intval))
			if !ok {
				return ABSENT
			}
			return MlrvalFromString(k)
		}
	case "positionally-indexed map value":
		base := c.compileExpr(node.Children[0])
		idx := c.compileExpr(node.Children[1])
		return func(st *State) *Mlrval {
			b := base(st)
			i := idx(st)
			if b.mtype != MT_MAP || i.Type() != MT_INT {
				return ABSENT
			}
			_, v, ok := b.mapval.GetAt(int(i.intval))
			if !ok {
				return ABSENT
			}
			return v
		}
	case "operator":
		return c.compileOperator(node)
	case "dot operator":
		a := c.compileExpr(node.Children[0])
		b := c.compileExpr(node.Children[1])
		return func(st *State) *Mlrval { return DotOperator(a(st), b(st)) }
	case "function callsite":
		return c.compileFunctionCall(node)
	case "function literal":
		return c.compileFunctionLiteral(node)
	}
	compileFatal("mlr: unhandled expression node type \"%s\".", node.Type)
	return nil
}

func (c *compiler) compileContextVar(name string) Evaluator {
	switch name {
	case "NR":
		return func(st *State) *Mlrval { return MlrvalFromInt(st.ctx.NR) }
	case "FNR":
		return func(st *State) *Mlrval { return MlrvalFromInt(st.ctx.FNR) }
	case "FILENUM":
		return func(st *State) *Mlrval { return MlrvalFromInt(st.ctx.FILENUM) }
	case "FILENAME":
		return func(st *State) *Mlrval {
			if st.ctx.FILENAME == "" {
				return ABSENT
			}
			return MlrvalFromString(st.ctx.FILENAME)
		}
	case "NF":
		return func(st *State) *Mlrval {
			if st.rec == nil {
				return ABSENT
			}
			return MlrvalFromInt(int64(st.rec.Len()))
		}
	case "IPS":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.R.IPS) }
	case "IFS":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.R.IFS) }
	case "IRS":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.R.IRS) }
	case "OPS":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.W.OPS) }
	case "OFS":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.W.OFS) }
	case "ORS":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.W.ORS) }
	case "FLATSEP":
		return func(st *State) *Mlrval { return MlrvalFromString(st.prog.opts.W.FlatSep) }
	}
	return func(st *State) *Mlrval { return ABSENT }
}

// index into map/array/string
func indexValue(b, i *Mlrval) *Mlrval {
	switch b.mtype {
	case MT_MAP:
		if i.IsAbsent() {
			return ABSENT
		}
		if i.Type() == MT_ERROR {
			return ERROR()
		}
		v := b.mapval.Get(i.String())
		if v == nil {
			return ABSENT
		}
		return v
	case MT_ARRAY:
		if i.Type() != MT_INT {
			if i.IsAbsent() {
				return ABSENT
			}
			return ERROR()
		}
		n := int64(len(b.arrayval))
		idx := i.intval
		if idx < 0 {
			idx += n + 1
		}
		if idx < 1 || idx > n {
			return ABSENT
		}
		return b.arrayval[idx-1]
	case MT_ABSENT:
		return ABSENT
	case MT_ERROR:
		return ERROR()
	}
	t := b.Type()
	if t == MT_STRING || t == MT_VOID || t == MT_INT || t == MT_FLOAT {
		if i.Type() != MT_INT {
			return ERROR()
		}
		runes := []rune(b.String())
		n := int64(len(runes))
		idx := i.intval
		if idx < 0 {
			idx += n + 1
		}
		if idx < 1 || idx > n {
			return ERROR()
		}
		return MlrvalFromString(string(runes[idx-1]))
	}
	return ABSENT
}

func sliceValue(b, lo, hi *Mlrval) *Mlrval {
	if b.mtype == MT_ARRAY {
		n := int64(len(b.arrayval))
		l, h := int64(1), n
		if lo != nil {
			if lo.Type() != MT_INT {
				return ERROR()
			}
			l = lo.intval
		}
		if hi != nil {
			if hi.Type() != MT_INT {
				return ERROR()
			}
			h = hi.intval
		}
		if l < 0 {
			l += n + 1
		}
		if h < 0 {
			h += n + 1
		}
		if l < 1 {
			l = 1
		}
		if h > n {
			h = n
		}
		out := make([]*Mlrval, 0)
		for k := l; k <= h; k++ {
			out = append(out, b.arrayval[k-1].Copy())
		}
		return MlrvalFromArray(out)
	}
	if b.IsAbsent() {
		return ABSENT
	}
	if b.mtype == MT_MAP {
		return ERROR()
	}
	s := b.String()
	runes := []rune(s)
	n := int64(len(runes))
	l, h := int64(1), n
	if lo != nil {
		if lo.Type() != MT_INT {
			return ERROR()
		}
		l = lo.intval
	}
	if hi != nil {
		if hi.Type() != MT_INT {
			return ERROR()
		}
		h = hi.intval
	}
	if l < 0 {
		l += n + 1
	}
	if h < 0 {
		h += n + 1
	}
	if l < 1 || h > n || l > h {
		if l > h {
			return VOID
		}
		return ERROR()
	}
	return MlrvalFromString(string(runes[l-1 : h]))
}

func (c *compiler) compileOperator(node *ASTNode) Evaluator {
	op := node.Text
	if len(node.Children) == 1 {
		a := c.compileExpr(node.Children[0])
		switch op {
		case "-":
			return func(st *State) *Mlrval { return unaryMinus(a(st)) }
		case "+":
			return func(st *State) *Mlrval { return unaryPlus(a(st)) }
		case "!":
			return func(st *State) *Mlrval { return logicalNot(a(st)) }
		case "~":
			return func(st *State) *Mlrval { return unaryBitNot(a(st)) }
		}
		compileFatal("mlr: function %s invoked with 1 argument; expected 2", op)
	}
	if len(node.Children) == 3 {
		cnd := c.compileExpr(node.Children[0])
		a := c.compileExpr(node.Children[1])
		b := c.compileExpr(node.Children[2])
		return func(st *State) *Mlrval {
			v := cnd(st)
			if v.Type() != MT_BOOLEAN {
				runtimeFatal("mlr: ternary condition did not evaluate to boolean.")
			}
			if v.IsTrue() {
				return a(st)
			}
			return b(st)
		}
	}
	a := c.compileExpr(node.Children[0])
	// regex operators
	if op == "=~" || op == "!=~" {
		var reStatic *regexp.Regexp
		if rs, ok := regexStringFromLiteralNode(node.Children[1]); ok && !hasCaptureRefs(rs) {
			reStatic = getRegex(rs)
		}
		b := c.compileExpr(node.Children[1])
		negate := op == "!=~"
		return func(st *State) *Mlrval {
			l := a(st)
			var re *regexp.Regexp
			if reStatic != nil {
				re = reStatic
			} else {
				r := b(st)
				if r.Type() != MT_STRING && r.Type() != MT_VOID {
					return ERROR()
				}
				re = getRegex(r.String())
			}
			if l.IsAbsent() {
				return ABSENT
			}
			lt := l.Type()
			if lt == MT_MAP || lt == MT_ARRAY || lt == MT_ERROR {
				return ERROR()
			}
			m := re.FindStringSubmatch(l.String())
			if m == nil {
				st.captures = make([]string, 10)
				return MlrvalFromBool(negate)
			}
			caps := make([]string, 10)
			for k := 0; k < len(m) && k < 10; k++ {
				caps[k] = m[k]
			}
			st.captures = caps
			return MlrvalFromBool(!negate)
		}
	}
	b := c.compileExpr(node.Children[1])
	switch op {
	case "&&":
		return func(st *State) *Mlrval {
			l := a(st)
			if l.Type() == MT_BOOLEAN && !l.IsTrue() {
				return FALSE
			}
			if l.Type() == MT_ERROR {
				return ERROR()
			}
			return logicalAnd(l, b(st))
		}
	case "||":
		return func(st *State) *Mlrval {
			l := a(st)
			if l.Type() == MT_BOOLEAN && l.IsTrue() {
				return TRUE
			}
			if l.Type() == MT_ERROR {
				return ERROR()
			}
			return logicalOr(l, b(st))
		}
	case "^^":
		return func(st *State) *Mlrval { return logicalXor(a(st), b(st)) }
	case "??":
		return func(st *State) *Mlrval {
			l := a(st)
			if l.IsAbsent() {
				return b(st)
			}
			return l
		}
	case "???":
		return func(st *State) *Mlrval {
			l := a(st)
			if l.IsAbsent() || (l.Type() == MT_VOID && !l.isnull) {
				return b(st)
			}
			return l
		}
	}
	f := binaryOpFunc(op)
	if f == nil {
		compileFatal("mlr: unhandled operator %s", op)
	}
	return func(st *State) *Mlrval { return f(a(st), b(st)) }
}

func binaryOpFunc(op string) func(a, b *Mlrval) *Mlrval {
	switch op {
	case "+":
		return BinaryPlus
	case "-":
		return BinaryMinus
	case "*":
		return BinaryTimes
	case "/":
		return BinaryDivide
	case "//":
		return BinaryIntDivide
	case "%":
		return BinaryMod
	case "**":
		return BinaryPow
	case ".+":
		return BinaryDotPlus
	case ".-":
		return BinaryDotMinus
	case ".*":
		return BinaryDotTimes
	case "./":
		return BinaryDotDivide
	case "&":
		return BitwiseAnd
	case "|":
		return BitwiseOr
	case "^":
		return BitwiseXor
	case "<<":
		return LeftShift
	case ">>":
		return SignedRightShift
	case ">>>":
		return UnsignedRightShift
	case "==":
		return func(a, b *Mlrval) *Mlrval { return compareOp(0, a, b) }
	case "!=":
		return func(a, b *Mlrval) *Mlrval { return compareOp(1, a, b) }
	case "<":
		return func(a, b *Mlrval) *Mlrval { return compareOp(2, a, b) }
	case "<=":
		return func(a, b *Mlrval) *Mlrval { return compareOp(3, a, b) }
	case ">":
		return func(a, b *Mlrval) *Mlrval { return compareOp(4, a, b) }
	case ">=":
		return func(a, b *Mlrval) *Mlrval { return compareOp(5, a, b) }
	case "<=>":
		return spaceship
	case "&&":
		return logicalAnd
	case "||":
		return logicalOr
	case "^^":
		return logicalXor
	case ".":
		return DotOperator
	}
	return nil
}

type FuncLiteral struct {
	udf *UDF
}

func (c *compiler) compileFunctionLiteral(node *ASTNode) Evaluator {
	udf := &UDF{name: "function-literal", node: node}
	c.compileUDF(udf, node, false)
	fv := &Mlrval{mtype: MT_FUNC, funcval: udf, printrep: "(function-literal)", prValid: true}
	return func(st *State) *Mlrval { return fv }
}
