		return &lvalue{kind: "oosvar", name: node.Text}
	case "indirect oosvar value":
		return &lvalue{kind: "ioosvar", nameEval: c.compileExpr(node.Children[0])}
	case "full oosvar":
		return &lvalue{kind: "fulloos"}
	case "local variable":
		lv := &lvalue{kind: "local", name: node.Text, typ: "any"}
		if len(node.Children) > 0 {
			lv.typ = node.Children[0].Text
			lv.declare = true
		}
		return lv
	case "environment variable":
		return &lvalue{kind: "env", nameEval: c.compileExpr(node.Children[0])}
	case "array or map index access":
		// flatten chain
		var idxNodes []*ASTNode
		n := node
		for n.Type == "array or map index access" {
			idxNodes = append([]*ASTNode{n.Children[1]}, idxNodes...)
			n = n.Children[0]
		}
		base := c.compileLvalue(n)
		lv := &lvalue{kind: "indexed", base: base}
		for _, in := range idxNodes {
			lv.indices = append(lv.indices, c.compileExpr(in))
		}
