		lv := &lvalue{kind: "indexed", base: base}
		for _, in := range idxNodes {
			lv.indices = append(lv.indices, c.compileExpr(in))
		}
		return lv
	}
	compileFatal("mlr: unassignable expression of type \"%s\".", node.Type)
	return nil
}

func (c *compiler) compileAssignment(node *ASTNode) Executor {
	lv := c.compileLvalue(node.Children[0])
	rhs := c.compileExpr(node.Children[1])
	return func(st *State) flowCode {
		v := rhs(st)
		lv.assign(st, v)
		return FLOW_NORMAL
	}
}

func (lv *lvalue) get(st *State) *Mlrval {
	switch lv.kind {
	case "field":
		if st.rec == nil {
			return ABSENT
		}
		v := st.rec.Get(lv.name)
		if v == nil {
			return ABSENT
		}
		return v
	case "ifield":
		if st.rec == nil {
			return ABSENT
		}
		v := st.rec.Get(lv.nameEval(st).String())
		if v == nil {
			return ABSENT
		}
		return v
	case "fullrec":
		if st.rec == nil {
			return ABSENT
		}
		return MlrvalFromMap(st.rec)
	case "oosvar":
		v := st.oosvars.Get(lv.name)
		if v == nil {
			return ABSENT
		}
		return v
	case "ioosvar":
		v := st.oosvars.Get(lv.nameEval(st).String())
		if v == nil {
			return ABSENT
		}
		return v
	case "fulloos":
		return MlrvalFromMap(st.oosvars)
	case "local":
		l := st.frame.lookup(lv.name)
		if l == nil {
			return ABSENT
		}
		return l.val
	case "posvalue":
		if st.rec == nil {
			return ABSENT
		}
		i := lv.nameEval(st)
		if i.Type() != MT_INT {
			return ABSENT
		}
		_, v, ok := st.rec.GetAt(int(i.intval))
		if !ok {
			return ABSENT
		}
		return v
	}
	return ABSENT
}

func (lv *lvalue) assign(st *State, v *Mlrval) {
	switch lv.kind {
	case "field":
		if v.IsAbsent() {
			return
		}
		if st.rec == nil {
			return
		}
		st.rec.Put(lv.name, v.Copy())
	case "ifield":
		if v.IsAbsent() || st.rec == nil {
			return
		}
		st.rec.Put(lv.nameEval(st).String(), v.Copy())
	case "posname":
		if v.IsAbsent() || st.rec == nil {
			return
		}
		i := lv.nameEval(st)
		if i.Type() != MT_INT {
			return
		}
		k, _, ok := st.rec.GetAt(int(i.intval))
		if !ok {
			return
		}
		st.rec.Rename(k, v.String())
	case "posvalue":
		if v.IsAbsent() || st.rec == nil {
			return
		}
		i := lv.nameEval(st)
		if i.Type() != MT_INT {
			return
		}
		idx := int(i.intval)
		if idx >= 1 && idx <= st.rec.Len() {
			st.rec.vals[idx-1] = v.Copy()
		}
	case "fullrec":
		if v.IsAbsent() || st.rec == nil {
			return
		}
		if v.mtype != MT_MAP {
			runtimeFatal("mlr: $* assignment from non-map value.")
		}
		m := v.mapval.Copy()
		st.rec.keys = m.keys
		st.rec.vals = m.vals
	case "oosvar":
		if v.IsAbsent() {
			return
		}
		st.oosvars.Put(lv.name, v.Copy())
	case "ioosvar":
		if v.IsAbsent() {
			return
		}
		st.oosvars.Put(lv.nameEval(st).String(), v.Copy())
	case "fulloos":
		if v.IsAbsent() {
			return
		}
		if v.mtype != MT_MAP {
			return
		}
		m := v.mapval.Copy()
		st.oosvars.keys = m.keys
		st.oosvars.vals = m.vals
	case "local":
		if lv.declare {
			if !typeCheck(lv.typ, v) {
				runtimeFatal("mlr: couldn't define variable %s %s from value %s", lv.typ, lv.name, v.String())
			}
			st.frame.defineLocal(lv.name, &LocalVar{val: v.Copy(), typ: lv.typ})
			return
		}
		if v.IsAbsent() {
			return
		}
		l := st.frame.lookup(lv.name)
		if l != nil {
			if !typeCheck(l.typ, v) {
				runtimeFatal("mlr: couldn't assign variable %s %s from value %s", l.typ, lv.name, v.String())
			}
			l.val = v.Copy()
			return
		}
		st.frame.defineLocal(lv.name, &LocalVar{val: v.Copy(), typ: "any"})
	case "env":
		if v.IsAbsent() {
			return
		}
		os.Setenv(lv.nameEval(st).String(), v.String())
	case "indexed":
		if v.IsAbsent() {
			return
		}
		idx := make([]*Mlrval, len(lv.indices))
		for i, e := range lv.indices {
			idx[i] = e(st)
			if idx[i].IsAbsent() {
				return
			}
		}
		lv.assignIndexed(st, idx, v.Copy())
	}
}

func (lv *lvalue) assignIndexed(st *State, idx []*Mlrval, v *Mlrval) {
	b := lv.base
	var container *Mlrval
	switch b.kind {
	case "fullrec":
		if st.rec == nil {
			return
		}
		container = MlrvalFromMap(st.rec)
	case "fulloos":
		container = MlrvalFromMap(st.oosvars)
	default:
		container = b.get(st)
		if container.mtype != MT_MAP && container.mtype != MT_ARRAY {
			if container.IsAbsent() {
				container = MlrvalEmptyMap()
			} else if idx[0].Type() == MT_INT {
				container = MlrvalFromArray(nil)
			} else {
				container = MlrvalEmptyMap()
			}
			b.assignRaw(st, container)
			// re-fetch since assign copies
			container = b.get(st)
		}
	}
	putIndexed(container, idx, v)
}

// assign without copy (for container creation)
func (lv *lvalue) assignRaw(st *State, v *Mlrval) {
	switch lv.kind {
	case "field":
		if st.rec != nil {
			st.rec.Put(lv.name, v)
		}
	case "ifield":
		if st.rec != nil {
			st.rec.Put(lv.nameEval(st).String(), v)
		}
	case "oosvar":
		st.oosvars.Put(lv.name, v)
	case "ioosvar":
		st.oosvars.Put(lv.nameEval(st).String(), v)
	case "local":
		l := st.frame.lookup(lv.name)
		if l != nil {
			l.val = v
		} else {
			st.frame.defineLocal(lv.name, &LocalVar{val: v, typ: "any"})
		}
	case "posvalue":
		lv.assign(st, v)
	}
}

func putIndexed(container *Mlrval, idx []*Mlrval, v *Mlrval) {
	cur := container
	for i, k := range idx {
		last := i == len(idx)-1
		switch cur.mtype {
		case MT_MAP:
			ks := k.String()
			if last {
				cur.mapval.Put(ks, v)
				return
			}
			nxt := cur.mapval.Get(ks)
			if nxt == nil || (nxt.mtype != MT_MAP && nxt.mtype != MT_ARRAY) {
				if nxt != nil && idx[i+1].Type() == MT_INT {
					nxt = MlrvalFromArray(nil)
				} else {
					nxt = MlrvalEmptyMap()
				}
				cur.mapval.Put(ks, nxt)
			}
			cur = nxt
		case MT_ARRAY:
			if k.Type() != MT_INT {
				runtimeFatal("mlr: array index must be an int; got %s.", typeName(k))
			}
			n := int64(len(cur.arrayval))
			p := k.intval
			if p == 0 {
				runtimeFatal("mlr: zero indices are not supported. Indices are 1-up")
			}
			if p < 0 {
				p += n + 1
				if p < 1 {
					runtimeFatal("mlr: array index %d out of bounds 1..%d", k.intval, n)
				}
			}
			for int64(len(cur.arrayval)) < p {
				cur.arrayval = append(cur.arrayval, JSONNULL)
			}
			if last {
				cur.arrayval[p-1] = v
				return
			}
			nxt := cur.arrayval[p-1]
			if nxt.mtype != MT_MAP && nxt.mtype != MT_ARRAY {
				if idx[i+1].Type() == MT_INT {
					nxt = MlrvalFromArray(nil)
				} else {
					nxt = MlrvalEmptyMap()
				}
				cur.arrayval[p-1] = nxt
			}
			cur = nxt
		default:
			return
		}
	}
}

func (c *compiler) compileUnset(node *ASTNode) Executor {
	var lvs []*lvalue
	for _, ch := range node.Children {
		lvs = append(lvs, c.compileLvalue(ch))
	}
	return func(st *State) flowCode {
		for _, lv := range lvs {
			lv.unset(st)
		}
		return FLOW_NORMAL
	}
}

func (lv *lvalue) unset(st *State) {
	switch lv.kind {
	case "field":
		if st.rec != nil {
			st.rec.Remove(lv.name)
		}
	case "ifield":
		if st.rec != nil {
			st.rec.Remove(lv.nameEval(st).String())
		}
	case "posname", "posvalue":
		if st.rec != nil {
			i := lv.nameEval(st)
			if i.Type() == MT_INT {
				k, _, ok := st.rec.GetAt(int(i.intval))
				if ok {
					st.rec.Remove(k)
				}
			}
		}
	case "fullrec":
		if st.rec != nil {
			st.rec.Clear()
		}
	case "oosvar":
		st.oosvars.Remove(lv.name)
	case "ioosvar":
		st.oosvars.Remove(lv.nameEval(st).String())
	case "fulloos":
		st.oosvars.Clear()
	case "local":
		l := st.frame.lookup(lv.name)
		if l != nil {
			l.val = ABSENT
		}
	case "env":
		os.Unsetenv(lv.nameEval(st).String())
	case "indexed":
		idx := make([]*Mlrval, len(lv.indices))
		for i, e := range lv.indices {
			idx[i] = e(st)
		}
		var container *Mlrval
		switch lv.base.kind {
		case "fullrec":
			if st.rec == nil {
				return
			}
			container = MlrvalFromMap(st.rec)
		case "fulloos":
			container = MlrvalFromMap(st.oosvars)
		default:
			container = lv.base.get(st)
		}
		cur := container
		for i, k := range idx {
			last := i == len(idx)-1
			switch cur.mtype {
			case MT_MAP:
				if last {
					cur.mapval.Remove(k.String())
					return
				}
				nxt := cur.mapval.Get(k.String())
				if nxt == nil {
					return
				}
				cur = nxt
			case MT_ARRAY:
				if k.Type() != MT_INT {
					return
				}
				n := int64(len(cur.arrayval))
				p := k.intval
				if p < 0 {
					p += n + 1
				}
				if p < 1 || p > n {
					return
				}
				if last {
					cur.arrayval = append(cur.arrayval[:p-1], cur.arrayval[p:]...)
					return
				}
				cur = cur.arrayval[p-1]
			default:
				return
			}
		}
	}
}
