cd /workspace/src && cat > dsl_output.go <<'EOF'
package main

import (
	"bufio"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// ---------------------------------------------------------------- redirects

type redirTarget struct {
	kind   string // "stdout", "stderr", "write", "append", "pipe"
	target Evaluator
}

type openRedirect struct {
	file   *os.File
	w      *bufio.Writer
	cmd    *exec.Cmd
	writer RecordWriter
}

var openRedirects = map[string]*openRedirect{}
var openRedirectOrder []string

func closeAllRedirects() {
	for _, name := range openRedirectOrder {
		r := openRedirects[name]
		if r.writer != nil {
			r.writer.Finish(r.w)
		}
		r.w.Flush()
		if r.file != nil {
			r.file.Close()
		}
		if r.cmd != nil {
			if wc, ok := r.cmd.Stdin.(interface{ Close() error }); ok {
				wc.Close()
			}
			r.cmd.Wait()
		}
	}
	openRedirects = map[string]*openRedirect{}
	openRedirectOrder = nil
}

func getRedirect(kind string, name string, wopts *WriterOptions) *openRedirect {
	key := kind + ":" + name
	if kind == "write" || kind == "append" {
		key = "file:" + name
	}
	if r, ok := openRedirects[key]; ok {
		return r
	}
	r := &openRedirect{}
	switch kind {
	case "write", "append":
		flags := os.O_CREATE | os.O_WRONLY
		if kind == "append" {
			flags |= os.O_APPEND
		} else {
			flags |= os.O_TRUNC
		}
		f, err := os.OpenFile(name, flags, 0644)
		if err != nil {
			fatalf("mlr: could not open \"%s\" for write.\n", name)
		}
		r.file = f
		r.w = bufio.NewWriter(f)
	case "pipe":
		stdoutWriter.Flush()
		cmd := exec.Command("/bin/sh", "-c", name)
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		pw, err := cmd.StdinPipe()
		if err != nil {
			fatalf("mlr: could not open pipe \"%s\".\n", name)
		}
		if err := cmd.Start(); err != nil {
			fatalf("mlr: could not start \"%s\".\n", name)
		}
		r.cmd = cmd
		r.w = bufio.NewWriter(pw)
		cmd.Stdin = nil
		r.cmd.Stdin = nil
		r.file = nil
		r.pipeCloser = pw
	}
	if wopts != nil {
		r.writer = newRecordWriter(wopts)
	}
	openRedirects[key] = r
	openRedirectOrder = append(openRedirectOrder, key)
	return r
}

func (c *compiler) compileRedirect(node *ASTNode) *redirTarget {
	if node.Type == "no-op" {
		return nil
	}
	rt := &redirTarget{}
	switch node.Type {
	case "redirect write":
		rt.kind = "write"
	case "redirect append":
		rt.kind = "append"
	case "redirect pipe":
		rt.kind = "pipe"
	}
	tgt := node.Children[0]
	if tgt.Type == "stdout redirect target" {
		rt.kind = "stdout"
	} else if tgt.Type == "stderr redirect target" {
		rt.kind = "stderr"
	} else {
		rt.target = c.compileExpr(tgt)
	}
	return rt
}

var stderrWriter = bufio.NewWriter(os.Stderr)

func writeTextTo(st *State, rt *redirTarget, s string) {
	if rt == nil || rt.kind == "stdout" {
		st.emitString(s)
		return
	}
	if rt.kind == "stderr" {
		stdoutWriter.Flush()
		os.Stderr.WriteString(s)
		return
	}
	name := rt.target(st).String()
	r := getRedirect(rt.kind, name, nil)
	r.w.WriteString(s)
}

func writeRecordTo(st *State, rt *redirTarget, rec *Mlrmap) {
	opts := st.prog.opts
	if rt.kind == "stdout" || rt.kind == "stderr" {
		w := newRecordWriter(&opts.W)
		var b strings.Builder
		bw := bufio.NewWriter(&b)
		r := rec.Copy()
		if !isJSONFormat(opts.W.OutputFormat) {
			flattenRecord(r, opts.W.FlatSep, nil)
		}
		w.Write(r, bw)
		w.Finish(bw)
		bw.Flush()
		if rt.kind == "stdout" {
			st.emitString(b.String())
		} else {
			stdoutWriter.Flush()
			os.Stderr.WriteString(b.String())
		}
		return
	}
	name := rt.target(st).String()
	r := getRedirect(rt.kind, name, &opts.W)
	rc := rec.Copy()
	if !isJSONFormat(opts.W.OutputFormat) {
		flattenRecord(rc, opts.W.FlatSep, nil)
	}
	r.writer.Write(rc, r.w)
}

// ---------------------------------------------------------------- print

func (c *compiler) compilePrint(node *ASTNode) Executor {
	kw := node.Text
	var args []Evaluator
	if node.Children[0].Type != "no-op" {
		for _, a := range node.Children[0].Children {
			args = append(args, c.compileExpr(a))
		}
	}
	rt := c.compileRedirect(node.Children[1])
	newline := kw == "print" || kw == "eprint"
	toStderr := kw == "eprint" || kw == "eprintn"
	return func(st *State) flowCode {
		var b strings.Builder
		for i, a := range args {
			if i > 0 {
				b.WriteString(" ")
			}
			v := a(st)
			if v.IsAbsent() {
				continue
			}
			b.WriteString(v.String())
		}
		if newline {
			b.WriteString("\n")
		}
		if toStderr {
			stdoutWriter.Flush()
			os.Stderr.WriteString(b.String())
			return FLOW_NORMAL
		}
		writeTextTo(st, rt, b.String())
		return FLOW_NORMAL
	}
}

func (c *compiler) compileDump(node *ASTNode) Executor {
	kw := node.Text
	var args []Evaluator
	if node.Children[0].Type != "no-op" {
		for _, a := range node.Children[0].Children {
			args = append(args, c.compileExpr(a))
		}
	}
	rt := c.compileRedirect(node.Children[1])
	return func(st *State) flowCode {
		var s string
		if len(args) == 0 {
			s = MlrvalFromMap(st.oosvars).JSONMultiline() + "\n"
		} else {
			var b strings.Builder
			for _, a := range args {
				v := a(st)
				if v.mtype == MT_MAP || v.mtype == MT_ARRAY {
					b.WriteString(v.JSONMultiline())
				} else {
					b.WriteString(v.String())
				}
				b.WriteString("\n")
			}
			s = b.String()
		}
		if kw == "edump" {
			stdoutWriter.Flush()
			os.Stderr.WriteString(s)
			return FLOW_NORMAL
		}
		writeTextTo(st, rt, s)
		return FLOW_NORMAL
	}
}

func (c *compiler) compileTee(node *ASTNode) Executor {
	ev := c.compileExpr(node.Children[0])
	rt := c.compileRedirect(node.Children[1])
	return func(st *State) flowCode {
		v := ev(st)
		if v.mtype != MT_MAP {
			return FLOW_NORMAL
		}
		writeRecordTo(st, rt, v.mapval)
		return FLOW_NORMAL
	}
}

// ---------------------------------------------------------------- emit

type emittable struct {
	name    string
	ev      Evaluator
	isAll   bool // @*, all, $*: iterate over entries
}

func (c *compiler) compileEmittable(n *ASTNode) emittable {
	switch n.Type {
	case "direct oosvar value", "local variable", "direct field value":
		return emittable{name: n.Text, ev: c.compileExpr(n)}
	case "full oosvar", "full record":
		return emittable{name: "", ev: c.compileExpr(n), isAll: true}
	case "map literal":
		return emittable{name: "", ev: c.compileExpr(n)}
	}
	return emittable{name: "", ev: c.compileExpr(n)}
}

func (c *compiler) compileEmit(node *ASTNode) Executor {
	isP := node.Text == "emitp"
	var ems []emittable
	for _, e := range node.Children[0].Children {
		if len(node.Children[0].Children) > 1 {
			switch e.Type {
			case "direct oosvar value", "local variable", "direct field value":
			default:
				what := e.Type
				compileFatal("mlr: lashed-emit node types must be local variables, field names, or oosvars; got %s.", what)
			}
		}
		ems = append(ems, c.compileEmittable(e))
	}
	var keys []Evaluator
	if node.Children[1].Type == "emit keys" {
		for _, k := range node.Children[1].Children {
			keys = append(keys, c.compileExpr(k))
		}
	}
	rt := c.compileRedirect(node.Children[2])
	lashed := len(ems) > 1
	return func(st *State) flowCode {
		emitFn := func(rec *Mlrmap) {
			if rt == nil {
				st.emitRecord(rec)
			} else {
				writeRecordTo(st, rt, rec)
			}
		}
		keyVals := make([]string, len(keys))
		for i, k := range keys {
			keyVals[i] = k(st).String()
		}
		if !lashed {
			e := ems[0]
			v := e.ev(st)
			if e.isAll {
				if v.mtype != MT_MAP {
					return FLOW_NORMAL
				}
				m := v.mapval.Copy()
				for i, k := range m.keys {
					emitNonLashed(k, m.vals[i], keyVals, isP, emitFn)
				}
				return FLOW_NORMAL
			}
			emitNonLashed(e.name, v.Copy(), keyVals, isP, emitFn)
			return FLOW_NORMAL
		}
		names := make([]string, 0, len(ems))
		vals := make([]*Mlrval, 0, len(ems))
		for _, e := range ems {
			v := e.ev(st)
			if v.IsAbsent() {
				continue
			}
			names = append(names, e.name)
			vals = append(vals, v.Copy())
		}
		if len(keyVals) == 0 {
			if isP {
				rec := NewMlrmap()
				for i, n := range names {
					rec.Put(n, vals[i])
				}
				emitFn(rec)
			} else {
				if len(vals) == 0 {
					emitFn(NewMlrmap())
				}
				for i, n := range names {
					emitNonLashed(n, vals[i], nil, false, emitFn)
				}
			}
			return FLOW_NORMAL
		}
		emitLashedHelper(NewMlrmap(), names, vals, keyVals, isP, 0, emitFn)
		return FLOW_NORMAL
	}
}

func emitNonLashed(name string, v *Mlrval, keys []string, isP bool, emitFn func(*Mlrmap)) {
	if v.IsAbsent() {
		return
	}
	if v.mtype != MT_MAP {
		if len(keys) == 0 {
			rec := NewMlrmap()
			rec.Put(name, v)
			emitFn(rec)
		}
		return
	}
	if len(keys) == 0 {
		if isP {
			if name == "" {
				emitFn(v.mapval)
			} else {
				rec := NewMlrmap()
				rec.Put(name, v)
				emitFn(rec)
			}
			return
		}
		emitNonPrefixedRecursive(v.mapval, emitFn)
		return
	}
	emitHelper(NewMlrmap(), name, v.mapval, keys, isP, 0, emitFn)
}

func emitNonPrefixedRecursive(m *Mlrmap, emitFn func(*Mlrmap)) {
	allMaps := m.Len() > 0
	for _, v := range m.vals {
		if v.mtype != MT_MAP {
			allMaps = false
			break
		}
	}
	if !allMaps {
		emitFn(m)
		return
	}
	for _, v := range m.vals {
		emitNonPrefixedRecursive(v.mapval, emitFn)
	}
}

func emitHelper(template *Mlrmap, name string, m *Mlrmap, keys []string, isP bool, depth int, emitFn func(*Mlrmap)) {
	K := keys[0]
	for i, k := range m.keys {
		v := m.vals[i]
		t := template.Copy()
		t.Put(K, MlrvalFromString(k))
		if len(keys) == 1 {
			if v.mtype == MT_MAP {
				if isP || depth > 0 {
					if name == "" {
						for j, kk := range v.mapval.keys {
							t.Put(kk, v.mapval.vals[j])
						}
					} else {
						t.Put(name, v)
					}
				} else {
					for j, kk := range v.mapval.keys {
						t.Put(kk, v.mapval.vals[j])
					}
				}
			} else {
				t.Put(name, v)
			}
			emitFn(t)
		} else {
			if v.mtype == MT_MAP {
				emitHelper(t, name, v.mapval, keys[1:], isP, depth+1, emitFn)
			}
		}
	}
}

func emitLashedHelper(template *Mlrmap, names []string, vals []*Mlrval, keys []string, isP bool, depth int, emitFn func(*Mlrmap)) {
	if len(vals) == 0 || vals[0].mtype != MT_MAP {
		return
	}
	K := keys[0]
	lead := vals[0].mapval
	for _, k := range lead.keys {
		t := template.Copy()
		t.Put(K, MlrvalFromString(k))
		var subNames []string
		var subVals []*Mlrval
		for i, v := range vals {
			if v.mtype != MT_MAP {
				continue
			}
			sv := v.mapval.Get(k)
			if sv == nil {
				continue
			}
			subNames = append(subNames, names[i])
			subVals = append(subVals, sv)
		}
		if len(keys) == 1 {
			for i, sv := range subVals {
				if sv.mtype == MT_MAP && !(isP || depth > 0) {
					for j, kk := range sv.mapval.keys {
						t.Put(kk, sv.mapval.vals[j])
					}
				} else {
					t.Put(subNames[i], sv)
				}
			}
			emitFn(t)
		} else {
			emitLashedHelper(t, subNames, subVals, keys[1:], isP, depth+1, emitFn)
		}
	}
}

func (c *compiler) compileEmitf(node *ASTNode) Executor {
	var ems []emittable
	for _, e := range node.Children[0].Children {
		ems = append(ems, c.compileEmittable(e))
	}
	rt := c.compileRedirect(node.Children[1])
	return func(st *State) flowCode {
		rec := NewMlrmap()
		for _, e := range ems {
			v := e.ev(st)
			if v.IsAbsent() {
				continue
			}
			rec.Put(e.name, v.Copy())
		}
		if rt == nil {
			st.emitRecord(rec)
		} else {
			writeRecordTo(st, rt, rec)
		}
		return FLOW_NORMAL
	}
}

func (c *compiler) compileEmit1(node *ASTNode) Executor {
	ev := c.compileExpr(node.Children[0])
	return func(st *State) flowCode {
		v := ev(st)
		if v.mtype == MT_MAP {
			st.emitRecord(v.mapval.Copy())
		}
		return FLOW_NORMAL
	}
}

