package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type PutT struct {
	prog      *Program
	st        *State
	isFilter  bool
	invert    bool
	suppress  bool
	began     bool
	presets   [][2]string
	next      *ChainLink
	ctx       *Context
}

func init() {
	initVerbsList = append(initVerbsList, func() {
		registerVerb("put", func(args []string, i int, opts *Options) (Transformer, int) {
			return parsePutOrFilter(args, i, opts, false)
		})
		registerVerb("filter", func(args []string, i int, opts *Options) (Transformer, int) {
			return parsePutOrFilter(args, i, opts, true)
		})
	})
}

func loadDSLFile(path string) []string {
	st, err := os.Stat(path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr: cannot load DSL expression from file \"%s\": open %s: no such file or directory\n", path, path)
		os.Exit(1)
	}
	if st.IsDir() {
		entries, _ := os.ReadDir(path)
		var names []string
		for _, e := range entries {
			if strings.HasSuffix(e.Name(), ".mlr") {
				names = append(names, filepath.Join(path, e.Name()))
			}
		}
		sort.Strings(names)
		var out []string
		for _, n := range names {
			data, _ := os.ReadFile(n)
			out = append(out, string(data))
		}
		return out
	}
	data, err := os.ReadFile(path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr: cannot load DSL expression from file \"%s\"\n", path)
		os.Exit(1)
	}
	return []string{string(data)}
}

func parsePutOrFilter(args []string, i int, opts *Options, isFilter bool) (Transformer, int) {
	verb := "put"
	if isFilter {
		verb = "filter"
	}
	va := newVargs(verb, args, i)
	t := &PutT{isFilter: isFilter}
	var exprs []string
	haveExpr := false
	printAST := false
	printParex := false
	printParexOneLine := false
	echoExpr := false
	exitAfterParse := false
	for _, pre := range opts.DSLPreloads {
		exprs = append(exprs, loadDSLFile(pre)...)
	}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			exprs = append(exprs, loadDSLFile(va.str(f))...)
			haveExpr = true
		case "-e":
			exprs = append(exprs, va.str(f))
			haveExpr = true
		case "-s":
			s := va.str(f)
			idx := strings.Index(s, "=")
			if idx < 0 {
				fmt.Fprintf(os.Stderr, "mlr %s: -s requires name=value; got %s\n", verb, s)
				os.Exit(1)
			}
			t.presets = append(t.presets, [2]string{s[:idx], s[idx+1:]})
		case "-x":
			t.invert = true
		case "-q":
			t.suppress = true
		case "-S", "-F":
		case "-v":
			printAST = true
			echoExpr = true
		case "-p":
			printAST = true
		case "-d":
			printParex = true
		case "-D":
			printParexOneLine = true
		case "-E":
			echoExpr = true
		case "-X":
			exitAfterParse = true
		case "-w", "-W", "-z":
		default:
			va.unrecognized(f)
		}
	}
	if !haveExpr {
		if va.i >= len(va.args) {
			fmt.Fprintf(os.Stderr, "mlr %s: needs an expression.\n", verb)
			os.Exit(1)
		}
		exprs = append(exprs, va.next())
	}
	root := newNode("statement block", "")
	for _, e := range exprs {
		ast, err := parseDSL(e)
		if err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(1)
		}
		if echoExpr {
			fmt.Print("DSL EXPRESSION:\n")
			fmt.Print(e)
			if !strings.HasSuffix(e, "\n") {
				fmt.Print("\n")
			}
			fmt.Print("\n")
		}
		if printAST {
			var b strings.Builder
			ast.Print(&b, 0)
			fmt.Print("AST:\n")
			fmt.Print(b.String())
			fmt.Print("\n")
		}
		if printParex {
			var b strings.Builder
			ast.PrintParex(&b, 0, false)
			fmt.Print(b.String())
			fmt.Print("\n")
		}
		if printParexOneLine {
			var b strings.Builder
			ast.PrintParex(&b, 0, true)
			fmt.Print(b.String())
			fmt.Print("\n\n")
		}
		root.Children = append(root.Children, ast.Children...)
	}
	if exitAfterParse {
		os.Exit(0)
	}
	t.prog = compileProgram(root, opts, isFilter)
	t.st = &State{oosvars: NewMlrmap(), frame: newFrame(), prog: t.prog}
	for _, p := range t.presets {
		t.st.oosvars.Put(p[0], MlrvalFromInferred(p[1]))
	}
	return t, va.i
}

func (t *PutT) runWithRecovery(f func()) {
	defer func() {
		if r := recover(); r != nil {
			if re, ok := r.(*dslRuntimeError); ok {
				stdoutWriter.Flush()
				fmt.Fprintln(os.Stderr, re.msg)
				os.Exit(1)
			}
			panic(r)
		}
	}()
	f()
}

func (t *PutT) setEmitters(next *ChainLink, ctx *Context) {
	t.next = next
	t.ctx = ctx
	st := t.st
	st.emitRecord = func(rec *Mlrmap) {
		c := *t.ctx
		next.Put(rec, &c)
	}
	st.emitString = func(s string) {
		next.PutString(s)
	}
}

func (t *PutT) runBegin(next *ChainLink, ctx *Context) {
	if t.began {
		return
	}
	t.began = true
	st := t.st
	bctx := &Context{FILENAME: ctx.FILENAME, FILENUM: ctx.FILENUM}
	if bctx.FILENAME == "" {
		bctx.FILENAME = "(stdin)"
	}
	t.setEmitters(next, bctx)
	st.ctx = bctx
	st.rec = nil
	st.inBeginEnd = true
	for _, b := range t.prog.beginBlocks {
		t.runWithRecovery(func() { b(st) })
	}
	st.inBeginEnd = false
}

func (t *PutT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if !t.began {
		t.runBegin(next, ctx)
	}
	st := t.st
	t.setEmitters(next, ctx)
	st.rec = rec
	st.ctx = ctx
	st.captures = nil
	st.filterResult = nil
	if t.prog.hasMain {
		t.runWithRecovery(func() { t.prog.mainBlock(st) })
	}
	pass := true
	fr := st.filterResult
	if fr != nil {
		if fr.Type() == MT_BOOLEAN {
			pass = fr.IsTrue()
		} else if fr.IsAbsent() {
			pass = false
		} else if t.isFilter {
			stdoutWriter.Flush()
			fmt.Fprintf(os.Stderr, "Filter expression did not evaluate to boolean: got %s value %s", fr.String(), typeName(fr))
			os.Exit(1)
		}
	} else if t.isFilter {
		pass = true
	}
	if t.invert {
		pass = !pass
	}
	if pass && !t.suppress {
		next.Put(st.rec, ctx)
	}
	st.rec = nil
}

func (t *PutT) End(ctx *Context, next *ChainLink) {
	if !t.began {
		t.runBegin(next, ctx)
	}
	st := t.st
	t.setEmitters(next, ctx)
	st.ctx = ctx
	st.rec = nil
	st.inBeginEnd = true
	for _, b := range t.prog.endBlocks {
		t.runWithRecovery(func() { b(st) })
	}
}
