{"command":"cd /workspace/src && cat > dsl_builtins.go <<'EOF'
package main

import (
	"crypto/md5"
	"crypto/sha1"
	"crypto/sha256"
	"crypto/sha512"
	"fmt"
	"hash/crc32"
	"math"
	"math/bits"
	"os"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type BuiltinFunc func(st *State, args []*Mlrval) *Mlrval

type BuiltinInfo struct {
	name    string
	minArgs int
	maxArgs int // -1 variadic
	fn      BuiltinFunc
	regexArg int // index of arg that is a regex (for literal handling), -1 none
}

var builtinTable map[string]*BuiltinInfo

func reg(name string, minArgs, maxArgs int, fn BuiltinFunc) {
	builtinTable[name] = &BuiltinInfo{name: name, minArgs: minArgs, maxArgs: maxArgs, fn: fn, regexArg: -1}
}

func regRegex(name string, minArgs, maxArgs int, regexArg int, fn BuiltinFunc) {
	builtinTable[name] = &BuiltinInfo{name: name, minArgs: minArgs, maxArgs: maxArgs, fn: fn, regexArg: regexArg}
}

func builtinExists(name string) bool {
	initBuiltins()
	_, ok := builtinTable[name]
	return ok
}

func (c *compiler) compileFunctionCall(node *ASTNode) Evaluator {
	name := node.Text
	initBuiltins()
	var args []Evaluator
	if udf, ok := c.prog.udfs[name]; ok {
		for _, a := range node.Children {
			args = append(args, c.compileExpr(a))
		}
		nparams := len(udf.node.Children[0].Children)
		if nparams != len(args) {
			compileFatal("mlr: function %s invoked with %d argument%s; expected %d", name, len(args), plural(len(args)), nparams)
		}
		return func(st *State) *Mlrval {
			vals := make([]*Mlrval, len(args))
			for i, a := range args {
				vals[i] = a(st)
			}
			return callUDF(st, udf, vals)
		}
	}
	bi, ok := builtinTable[name]
	if !ok {
		// maybe a local variable holding a function
		lname := name
		for _, a := range node.Children {
			args = append(args, c.compileExpr(a))
		}
		_ = lname
		return func(st *State) *Mlrval {
			lv := st.frame.lookup(lname)
			if lv != nil && lv.val.mtype == MT_FUNC {
				udf := lv.val.funcval.(*UDF)
				vals := make([]*Mlrval, len(args))
				for i, a := range args {
					vals[i] = a(st)
				}
				return callUDF(st, udf, vals)
			}
			runtimeFatal("mlr: function name not found: %s", lname)
			return nil
		}
	}
	nargs := len(node.Children)
	if nargs < bi.minArgs || (bi.maxArgs >= 0 && nargs > bi.maxArgs) {
		if bi.maxArgs == bi.minArgs {
			compileFatal("mlr: function %s invoked with %d argument%s; expected %d", name, nargs, plural(nargs), bi.minArgs)
		} else if bi.maxArgs < 0 {
			compileFatal("mlr: function %s invoked with %d argument%s; expected at least %d", name, nargs, plural(nargs), bi.minArgs)
		} else {
			compileFatal("mlr: function %s invoked with %d argument%s; expected %d to %d", name, nargs, plural(nargs), bi.minArgs, bi.maxArgs)
		}
	}
	for i, a := range node.Children {
		if i == bi.regexArg {
			if rs, ok := regexStringFromLiteralNode(a); ok {
				if hasCaptureRefs(rs) {
					args = append(args, func(st *State) *Mlrval {
						return MlrvalFromString(interpolateCaptures(rs, st.captures))
					})
				} else {
					v := MlrvalFromString(rs)
					args = append(args, func(st *State) *Mlrval { return v })
				}
				continue
			}
		}
		args = append(args, c.compileExpr(a))
	}
	fn := bi.fn
	switch len(args) {
	case 0:
		return func(st *State) *Mlrval { return fn(st, nil) }
	case 1:
		a0 := args[0]
		return func(st *State) *Mlrval { return fn(st, []*Mlrval{a0(st)}) }
	case 2:
		a0, a1 := args[0], args[1]
		return func(st *State) *Mlrval { return fn(st, []*Mlrval{a0(st), a1(st)}) }
	}
	return func(st *State) *Mlrval {
		vals := make([]*Mlrval, len(args))
		for i, a := range args {
			vals[i] = a(st)
		}
		return fn(st, vals)
	}
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

// ---------------------------------------------------------------- math helpers

// math unary returning float
func mathUnaryFloat(f func(float64) float64) BuiltinFunc {
	return func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_INT:
			return MlrvalFromFloat(f(float64(a.intval)))
		case MT_FLOAT:
			return MlrvalFromFloat(f(a.floatval))
		case MT_VOID:
			return VOID
		case MT_ABSENT, MT_MAP, MT_ARRAY:
			return ABSENT
		}
		return ERROR()
	}
}

func mathUnaryIntPreserving(fi func(int64) int64, ff func(float64) float64) BuiltinFunc {
	return func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_INT:
			return MlrvalFromInt(fi(a.intval))
		case MT_FLOAT:
			return MlrvalFromFloat(ff(a.floatval))
		case MT_VOID:
			return VOID
		case MT_ABSENT, MT_MAP, MT_ARRAY:
			return ABSENT
		}
		return ERROR()
	}
}

func roundHalfAway(x float64) float64 {
	return math.Round(x)
}

// qnorm, invqnorm
func qnorm(x float64) float64 {
	return 0.5 * math.Erfc(-x/math.Sqrt2)
}

// Acklam's algorithm with refinement
func invqnorm(p float64) float64 {
	if p <= 0 || p >= 1 {
		return 0
	}
	a := []float64{-3.969683028665376e+01, 2.209460984245205e+02, -2.759285104469687e+02, 1.383577518672690e+02, -3.066479806614716e+01, 2.506628277459239e+00}
	b := []float64{-5.447609879822406e+01, 1.615858368580409e+02, -1.556989798598866e+02, 6.680131188771972e+01, -1.328068155288572e+01}
	c := []float64{-7.784894002430293e-03, -3.223964580411365e-01, -2.400758277161838e+00, -2.549732539343734e+00, 4.374664141464968e+00, 2.938163982698783e+00}
	d := []float64{7.784695709041462e-03, 3.224671290700398e-01, 2.445134137142996e+00, 3.754408661907416e+00}
	plow := 0.02425
	phigh := 1 - plow
	var x float64
	if p < plow {
		q := math.Sqrt(-2 * math.Log(p))
		x = (((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q + c[5]) / ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q + 1)
	} else if p <= phigh {
		q := p - 0.5
		r := q * q
		x = (((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r + a[5]) * q / (((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r + 1)
	} else {
		q := math.Sqrt(-2 * math.Log(1-p))
		x = -(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q + c[5]) / ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q + 1)
	}
	// refinement step
	e := 0.5*math.Erfc(-x/math.Sqrt2) - p
	u := e * math.Sqrt(2*math.Pi) * math.Exp(x*x/2)
	x = x - u/(1+x*u/2)
	return x
}

func isStringish(mv *Mlrval) bool {
	t := mv.Type()
	return t == MT_STRING || t == MT_VOID
}

// string function: applies to strings; passes through other types; error->error
func stringUnary(f func(string) string) BuiltinFunc {
	return func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_STRING:
			return MlrvalFromString(f(a.printrep))
		case MT_VOID:
			return a
		case MT_ERROR:
			return ERROR()
		}
		return a
	}
}

func intArg(mv *Mlrval) (int64, bool) {
	switch mv.Type() {
	case MT_INT:
		return mv.intval, true
	case MT_FLOAT:
		return int64(mv.floatval), true
	}
	return 0, false
}

var whitespaceRun = regexp.MustCompile(`\s+`)

func initBuiltins() {
	if builtinTable != nil {
		return
	}
	builtinTable = map[string]*BuiltinInfo{}

	// ---- math
	reg("abs", 1, 1, mathUnaryIntPreserving(func(i int64) int64 {
		if i < 0 {
			return -i
		}
		return i
	}, math.Abs))
	reg("ceil", 1, 1, mathUnaryIntPreserving(func(i int64) int64 { return i }, math.Ceil))
	reg("floor", 1, 1, mathUnaryIntPreserving(func(i int64) int64 { return i }, math.Floor))
	reg("round", 1, 1, mathUnaryIntPreserving(func(i int64) int64 { return i }, roundHalfAway))
	reg("sgn", 1, 1, mathUnaryIntPreserving(func(i int64) int64 {
		if i > 0 {
			return 1
		} else if i < 0 {
			return -1
		}
		return 0
	}, func(f float64) float64 {
		if f > 0 {
			return 1
		} else if f < 0 {
			return -1
		}
		return 0
	}))
	reg("acos", 1, 1, mathUnaryFloat(math.Acos))
	reg("acosh", 1, 1, mathUnaryFloat(math.Acosh))
	reg("asin", 1, 1, mathUnaryFloat(math.Asin))
	reg("asinh", 1, 1, mathUnaryFloat(math.Asinh))
	reg("atan", 1, 1, mathUnaryFloat(math.Atan))
	reg("atanh", 1, 1, mathUnaryFloat(math.Atanh))
	reg("cbrt", 1, 1, mathUnaryFloat(math.Cbrt))
	reg("cos", 1, 1, mathUnaryFloat(math.Cos))
	reg("cosh", 1, 1, mathUnaryFloat(math.Cosh))
	reg("erf", 1, 1, mathUnaryFloat(math.Erf))
	reg("erfc", 1, 1, mathUnaryFloat(math.Erfc))
	reg("exp", 1, 1, mathUnaryFloat(math.Exp))
	reg("expm1", 1, 1, mathUnaryFloat(math.Expm1))
	reg("invqnorm", 1, 1, mathUnaryFloat(invqnorm))
	reg("log", 1, 1, mathUnaryFloat(math.Log))
	reg("log10", 1, 1, mathUnaryFloat(math.Log10))
	reg("log1p", 1, 1, mathUnaryFloat(math.Log1p))
	reg("qnorm", 1, 1, mathUnaryFloat(qnorm))
	reg("sin", 1, 1, mathUnaryFloat(math.Sin))
	reg("sinh", 1, 1, mathUnaryFloat(math.Sinh))
	reg("sqrt", 1, 1, mathUnaryFloat(math.Sqrt))
	reg("tan", 1, 1, mathUnaryFloat(math.Tan))
	reg("tanh", 1, 1, mathUnaryFloat(math.Tanh))
	reg("bitcount", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_INT:
			return MlrvalFromInt(int64(bits.OnesCount64(uint64(a.intval))))
		case MT_VOID:
			return VOID
		case MT_ABSENT, MT_MAP, MT_ARRAY:
			return ABSENT
		}
		return ERROR()
	})
	reg("atan2", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		return mathBinaryFloat(args[0], args[1], math.Atan2)
	})
	reg("pow", 2, 2, func(st *State, args []*Mlrval) *Mlrval { return BinaryPow(args[0], args[1]) })
	reg("roundm", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		x, m := args[0], args[1]
		if x.Type() == MT_INT && m.Type() == MT_INT {
			if m.intval == 0 {
				return ERROR()
			}
			q := float64(x.intval) / float64(m.intval)
			return MlrvalFromInt(int64(math.Round(q)) * m.intval)
		}
		if x.IsNumeric() && m.IsNumeric() {
			xf, mf := x.GetNumericToFloat(), m.GetNumericToFloat()
			return MlrvalFromFloat(math.Round(xf/mf) * mf)
		}
		if x.IsAbsent() {
			return ABSENT
		}
		if x.IsVoid() {
			return VOID
		}
		return ERROR()
	})
	reg("logifit", 3, 3, func(st *State, args []*Mlrval) *Mlrval {
		x, m, b := args[0], args[1], args[2]
		if !x.IsNumeric() || !m.IsNumeric() || !b.IsNumeric() {
			if x.IsAbsent() {
				return ABSENT
			}
			if x.IsVoid() {
				return VOID
			}
			return ERROR()
		}
		return MlrvalFromFloat(1.0 / (1.0 + math.Exp(-m.GetNumericToFloat()*x.GetNumericToFloat()-b.GetNumericToFloat())))
	})
	modOp := func(f func(a, b, m int64) int64) BuiltinFunc {
		return func(st *State, args []*Mlrval) *Mlrval {
			a, b, m := args[0], args[1], args[2]
			if a.Type() != MT_INT || b.Type() != MT_INT || m.Type() != MT_INT {
				return ERROR()
			}
			if m.intval == 0 {
				return ERROR()
			}
			return MlrvalFromInt(f(a.intval, b.intval, m.intval))
		}
	}
	pymod := func(a, m int64) int64 {
		r := a % m
		if r != 0 && (r < 0) != (m < 0) {
			r += m
		}
		return r
	}
	reg("madd", 3, 3, modOp(func(a, b, m int64) int64 { return pymod(a+b, m) }))
	reg("msub", 3, 3, modOp(func(a, b, m int64) int64 { return pymod(a-b, m) }))
	reg("mmul", 3, 3, modOp(func(a, b, m int64) int64 {
		var r big3
		return r.mulmod(a, b, m)
	}))
	reg("mexp", 3, 3, modOp(func(a, b, m int64) int64 {
		var r big3
		return r.expmod(a, b, m)
	}))
	reg("min", 0, -1, func(st *State, args []*Mlrval) *Mlrval { return variadicMinMax(args, false) })
	reg("max", 0, -1, func(st *State, args []*Mlrval) *Mlrval { return variadicMinMax(args, true) })
	reg("urand", 0, 0, func(st *State, args []*Mlrval) *Mlrval { return MlrvalFromFloat(rng.Float64()) })
	reg("urand32", 0, 0, func(st *State, args []*Mlrval) *Mlrval { return MlrvalFromInt(int64(rng.Uint32())) })
	reg("urandint", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		a, ok1 := intArg(args[0])
		b, ok2 := intArg(args[1])
		if !ok1 || !ok2 {
			return ERROR()
		}
		if b < a {
			a, b = b, a
		}
		return MlrvalFromInt(a + rng.Int63n(b-a+1))
	})
	reg("urandrange", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		if !args[0].IsNumeric() || !args[1].IsNumeric() {
			return ERROR()
		}
		a := args[0].GetNumericToFloat()
		b := args[1].GetNumericToFloat()
		return MlrvalFromFloat(a + (b-a)*rng.Float64())
	})
	reg("urandelement", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		if a.mtype != MT_ARRAY || len(a.arrayval) == 0 {
			return ERROR()
		}
		return a.arrayval[rng.Intn(len(a.arrayval))]
	})

	// ---- boolean/typing
	typePred := func(name string, f func(mv *Mlrval) bool) {
		reg("is_"+name, 1, 1, func(st *State, args []*Mlrval) *Mlrval { return MlrvalFromBool(f(args[0])) })
		reg("asserting_"+name, 1, 1, func(st *State, args []*Mlrval) *Mlrval {
			if !f(args[0]) {
				runtimeFatal("mlr: is_%s type-assertion failed at NR=%d FNR=%d FILENAME=%s", name, st.ctx.NR, st.ctx.FNR, st.ctx.FILENAME)
			}
			return args[0]
		})
	}
	typePred("absent", func(mv *Mlrval) bool { return mv.IsAbsent() })
	typePred("array", func(mv *Mlrval) bool { return mv.mtype == MT_ARRAY })
	typePred("bool", func(mv *Mlrval) bool { return mv.mtype == MT_BOOLEAN })
	typePred("boolean", func(mv *Mlrval) bool { return mv.mtype == MT_BOOLEAN })
	typePred("empty", func(mv *Mlrval) bool { return mv.Type() == MT_VOID && !mv.isnull })
	typePred("empty_map", func(mv *Mlrval) bool { return mv.mtype == MT_MAP && mv.mapval.Len() == 0 })
	typePred("error", func(mv *Mlrval) bool { return mv.mtype == MT_ERROR })
	typePred("float", func(mv *Mlrval) bool { return mv.Type() == MT_FLOAT })
	typePred("int", func(mv *Mlrval) bool { return mv.Type() == MT_INT })
	typePred("map", func(mv *Mlrval) bool { return mv.mtype == MT_MAP })
	typePred("nonempty_map", func(mv *Mlrval) bool { return mv.mtype == MT_MAP && mv.mapval.Len() > 0 })
	typePred("not_array", func(mv *Mlrval) bool { return mv.mtype != MT_ARRAY })
	typePred("not_empty", func(mv *Mlrval) bool {
		t := mv.Type()
		return !(t == MT_VOID && !mv.isnull) && t != MT_ABSENT
	})
	typePred("not_map", func(mv *Mlrval) bool { return mv.mtype != MT_MAP })
	typePred("not_null", func(mv *Mlrval) bool {
		t := mv.Type()
		return t != MT_VOID && t != MT_ABSENT
	})
	typePred("null", func(mv *Mlrval) bool {
		t := mv.Type()
		return t == MT_VOID || t == MT_ABSENT
	})
	typePred("numeric", func(mv *Mlrval) bool { return mv.IsNumeric() })
	typePred("present", func(mv *Mlrval) bool { return !mv.IsAbsent() })
	typePred("string", func(mv *Mlrval) bool {
		t := mv.Type()
		return (t == MT_STRING || t == MT_VOID) && !mv.isnull
	})
	reg("is_nan", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		return MlrvalFromBool(args[0].Type() == MT_FLOAT && math.IsNaN(args[0].floatval))
	})
	reg("typeof", 1, 1, func(st *State, args []*Mlrval) *Mlrval { return MlrvalFromString(typeName(args[0])) })
	reg("asserting_absent", 1, 1, builtinTable["asserting_absent"].fn)

	// ---- strings
	reg("strlen", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		t := a.Type()
		if t == MT_STRING || t == MT_VOID {
			return MlrvalFromInt(int64(utf8.RuneCountInString(a.printrep)))
		}
		return ERROR()
	})
	reg("toupper", 1, 1, stringUnary(strings.ToUpper))
	reg("tolower", 1, 1, stringUnary(strings.ToLower))
	reg("capitalize", 1, 1, stringUnary(func(s string) string {
		r, size := utf8.DecodeRuneInString(s)
		return string(unicode.ToUpper(r)) + s[size:]
	}))
	reg("lstrip", 1, 1, stringUnary(func(s string) string { return strings.TrimLeft(s, " \t\n\r") }))
	reg("rstrip", 1, 1, stringUnary(func(s string) string { return strings.TrimRight(s, " \t\n\r") }))
	reg("strip", 1, 1, stringUnary(func(s string) string { return strings.Trim(s, " \t\n\r") }))
	reg("collapse_whitespace", 1, 1, stringUnary(func(s string) string { return whitespaceRun.ReplaceAllString(s, " ") }))
	reg("clean_whitespace", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		if a.Type() == MT_VOID {
			return a
		}
		s := a.String()
		s = strings.Trim(whitespaceRun.ReplaceAllString(s, " "), " \t\n\r")
		return MlrvalFromInferred(s)
	})
	reg("truncate", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		a, n := args[0], args[1]
		if a.IsAbsent() {
			return ABSENT
		}
		if a.Type() == MT_ERROR {
			return ERROR()
		}
		if n.Type() != MT_INT {
			return ERROR()
		}
		if !isStringish(a) {
			return ERROR()
		}
		if n.intval < 0 {
			return ERROR()
		}
		runes := []rune(a.printrep)
		if int64(len(runes)) <= n.intval {
			return a
		}
		return MlrvalFromString(string(runes[:n.intval]))
	})
	reg("leftpad", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return padFunc(args, true) })
	reg("rightpad", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return padFunc(args, false) })
	reg("format", 0, -1, func(st *State, args []*Mlrval) *Mlrval {
		if len(args) == 0 {
			return ERROR()
		}
		f := args[0]
		if f.IsAbsent() {
			return ABSENT
		}
		fs := f.String()
		var b strings.Builder
		k := 1
		for i := 0; i < len(fs); i++ {
			if fs[i] == '{' && i+1 < len(fs) && fs[i+1] == '}' {
				if k < len(args) {
					b.WriteString(args[k].String())
				}
				k++
				i++
				continue
			}
			b.WriteByte(fs[i])
		}
		return MlrvalFromString(b.String())
	})
	reg("unformat", 2, 2, func(st *State, args []*Mlrval) *Mlrval { return unformatFunc(args, true) })
	reg("unformatx", 2, 2, func(st *State, args []*Mlrval) *Mlrval { return unformatFunc(args, false) })
	reg("contains", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		if args[0].IsAbsent() {
			return ABSENT
		}
		if args[0].Type() == MT_ERROR {
			return ERROR()
		}
		return MlrvalFromBool(strings.Contains(args[0].String(), args[1].String()))
	})
	reg("index", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		if args[0].IsAbsent() {
			return ABSENT
		}
		if args[0].Type() == MT_ERROR {
			return ERROR()
		}
		s := args[0].String()
		t := args[1].String()
		idx := strings.Index(s, t)
		if idx < 0 {
			return MlrvalFromInt(-1)
		}
		return MlrvalFromInt(int64(utf8.RuneCountInString(s[:idx]) + 1))
	})
	reg("substr", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return substrFunc(args, 0) })
	reg("substr0", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return substrFunc(args, 0) })
	reg("substr1", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return substrFunc(args, 1) })
	regRegex("sub", 3, 3, 1, func(st *State, args []*Mlrval) *Mlrval { return subFunc(args, false) })
	regRegex("gsub", 3, 3, 1, func(st *State, args []*Mlrval) *Mlrval { return subFunc(args, true) })
	reg("ssub", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return ssubFunc(args, false) })
	reg("gssub", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return ssubFunc(args, true) })
	regRegex("regextract", 2, 2, 1, func(st *State, args []*Mlrval) *Mlrval {
		a, r := args[0], args[1]
		if a.IsAbsent() {
			return ABSENT
		}
		if a.Type() == MT_ERROR || a.IsCollection() {
			return ERROR()
		}
		re := getRegex(r.String())
		m := re.FindString(a.String())
		loc := re.FindStringIndex(a.String())
		if loc == nil {
			return ERROR()
		}
		return MlrvalFromString(m)
	})
	regRegex("regextract_or_else", 3, 3, 1, func(st *State, args []*Mlrval) *Mlrval {
		a, r := args[0], args[1]
		if a.IsAbsent() {
			return ABSENT
		}
		if a.Type() == MT_ERROR || a.IsCollection() {
			return ERROR()
		}
		re := getRegex(r.String())
		loc := re.FindStringIndex(a.String())
		if loc == nil {
			return args[2]
		}
		return MlrvalFromString(a.String()[loc[0]:loc[1]])
	})
	regRegex("strmatch", 2, 2, 1, func(st *State, args []*Mlrval) *Mlrval {
		a, r := args[0], args[1]
		if a.IsAbsent() {
			return ABSENT
		}
		if a.Type() == MT_ERROR || a.IsCollection() {
			return ERROR()
		}
		if !isStringish(r) {
			return ERROR()
		}
		return MlrvalFromBool(getRegex(r.String()).MatchString(a.String()))
	})
	regRegex("strmatchx", 2, 2, 1, func(st *State, args []*Mlrval) *Mlrval { return strmatchxFunc(args) })
	reg("latin1_to_utf8", 1, 1, func(st *State, args []*Mlrval) *Mlrval { return recurseStrings(args[0], latin1ToUTF8) })
	reg("utf8_to_latin1", 1, 1, func(st *State, args []*Mlrval) *Mlrval { return recurseStrings(args[0], utf8ToLatin1) })

	// ---- hashing
	hashFn := func(f func([]byte) string) BuiltinFunc {
		return func(st *State, args []*Mlrval) *Mlrval {
			a := args[0]
			if !isStringish(a) {
				return ERROR()
			}
			return MlrvalFromString(f([]byte(a.printrep)))
		}
	}
	reg("md5", 1, 1, hashFn(func(b []byte) string { return fmt.Sprintf("%x", md5.Sum(b)) }))
	reg("sha1", 1, 1, hashFn(func(b []byte) string { return fmt.Sprintf("%x", sha1.Sum(b)) }))
	reg("sha256", 1, 1, hashFn(func(b []byte) string { return fmt.Sprintf("%x", sha256.Sum256(b)) }))
	reg("sha512", 1, 1, hashFn(func(b []byte) string { return fmt.Sprintf("%x", sha512.Sum512(b)) }))
	reg("crc32", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		if !isStringish(a) {
			return ERROR()
		}
		return MlrvalFromInt(int64(crc32.ChecksumIEEE([]byte(a.printrep))))
	})

	// ---- conversion
	reg("string", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		if a.Type() == MT_VOID {
			return a
		}
		return MlrvalFromString(a.String())
	})
	reg("boolean", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_BOOLEAN:
			return a
		case MT_INT:
			return MlrvalFromBool(a.intval != 0)
		case MT_FLOAT:
			return MlrvalFromBool(a.floatval != 0)
		case MT_VOID:
			return VOID
		case MT_ABSENT:
			return ABSENT
		case MT_STRING:
			if a.printrep == "true" {
				return TRUE
			}
			if a.printrep == "false" {
				return FALSE
			}
			return ERROR()
		}
		return ERROR()
	})
	reg("float", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_INT:
			return MlrvalFromFloat(float64(a.intval))
		case MT_FLOAT:
			return a
		case MT_BOOLEAN:
			if a.IsTrue() {
				return MlrvalFromFloat(1)
			}
			return MlrvalFromFloat(0)
		case MT_VOID:
			return VOID
		case MT_ABSENT:
			return ABSENT
		}
		return ERROR()
	})
	reg("int", 1, 2, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		if len(args) == 2 && (a.mtype == MT_STRING || (a.mtype == MT_PENDING) || a.prValid) && a.Type() != MT_FLOAT && a.Type() != MT_BOOLEAN {
			if a.Type() == MT_STRING || (a.Type() == MT_INT && a.prValid) {
				b, ok := intArg(args[1])
				if ok {
					s := a.printrep
					neg := false
					if strings.HasPrefix(s, "-") {
						neg = true
						s = s[1:]
					}
					sl := strings.ToLower(s)
					if b == 16 {
						sl = strings.TrimPrefix(sl, "0x")
					} else if b == 2 {
						sl = strings.TrimPrefix(sl, "0b")
					} else if b == 8 {
						sl = strings.TrimPrefix(sl, "0o")
					}
					u, err := strconv.ParseUint(sl, int(b), 64)
					if err != nil {
						return ERROR()
					}
					i := int64(u)
					if neg {
						i = -i
					}
					return MlrvalFromInt(i)
				}
			}
		}
		switch a.Type() {
		case MT_INT:
			if a.prValid {
				return MlrvalFromInt(a.intval)
			}
			return a
		case MT_FLOAT:
			return MlrvalFromInt(int64(a.floatval))
		case MT_BOOLEAN:
			if a.IsTrue() {
				return MlrvalFromInt(1)
			}
			return MlrvalFromInt(0)
		case MT_VOID:
			return VOID
		case MT_ABSENT:
			return ABSENT
		}
		return ERROR()
	})
	reg("fmtnum", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		return fmtnumRecursive(args[0], args[1], false)
	})
	reg("fmtifnum", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		return fmtnumRecursive(args[0], args[1], true)
	})
	reg("hexfmt", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		if a.Type() == MT_INT {
			return MlrvalFromString(fmt.Sprintf("0x%x", uint64(a.intval)))
		}
		return a
	})
	reg("joink", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		m, sep := args[0], args[1].String()
		if m.mtype == MT_MAP {
			return MlrvalFromString(strings.Join(m.mapval.keys, sep))
		}
		if m.mtype == MT_ARRAY {
			var parts []string
			for i := range m.arrayval {
				parts = append(parts, strconv.Itoa(i+1))
			}
			return MlrvalFromString(strings.Join(parts, sep))
		}
		if m.IsAbsent() {
			return ABSENT
		}
		return ERROR()
	})
	reg("joinv", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		m, sep := args[0], args[1].String()
		var parts []string
		if m.mtype == MT_MAP {
			for _, v := range m.mapval.vals {
				parts = append(parts, v.String())
			}
		} else if m.mtype == MT_ARRAY {
			for _, v := range m.arrayval {
				parts = append(parts, v.String())
			}
		} else {
			if m.IsAbsent() {
				return ABSENT
			}
			return ERROR()
		}
		return MlrvalFromString(strings.Join(parts, sep))
	})
	reg("joinkv", 3, 3, func(st *State, args []*Mlrval) *Mlrval {
		m, ps, fs := args[0], args[1].String(), args[2].String()
		var parts []string
		if m.mtype == MT_MAP {
			for i, k := range m.mapval.keys {
				parts = append(parts, k+ps+m.mapval.vals[i].String())
			}
		} else if m.mtype == MT_ARRAY {
			for i, v := range m.arrayval {
				parts = append(parts, strconv.Itoa(i+1)+ps+v.String())
			}
		} else {
			if m.IsAbsent() {
				return ABSENT
			}
			return ERROR()
		}
		return MlrvalFromString(strings.Join(parts, fs))
	})
	splitHelper := func(s *Mlrval, sep string) ([]string, bool) {
		if s.IsAbsent() {
			return nil, false
		}
		str := s.String()
		if str == "" {
			return []string{}, true
		}
		if sep == "" {
			var out []string
			for _, r := range str {
				out = append(out, string(r))
			}
			return out, true
		}
		return strings.Split(str, sep), true
	}
	reg("splitax", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		if args[0].IsCollection() {
			return ERROR()
		}
		parts, ok := splitHelper(args[0], args[1].String())
		if !ok {
			return ABSENT
		}
		a := make([]*Mlrval, len(parts))
		for i, p := range parts {
			a[i] = MlrvalFromString(p)
		}
		return MlrvalFromArray(a)
	})
	reg("splita", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		if args[0].IsCollection() {
			return ERROR()
		}
		parts, ok := splitHelper(args[0], args[1].String())
		if !ok {
			return ABSENT
		}
		a := make([]*Mlrval, len(parts))
		for i, p := range parts {
			a[i] = MlrvalFromInferred(p)
		}
		return MlrvalFromArray(a)
	})
	reg("splitnv", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		parts, ok := splitHelper(args[0], args[1].String())
		if !ok {
			return ABSENT
		}
		m := NewMlrmap()
		for i, p := range parts {
			m.Put(strconv.Itoa(i+1), MlrvalFromInferred(p))
		}
		return MlrvalFromMap(m)
	})
	reg("splitnvx", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		parts, ok := splitHelper(args[0], args[1].String())
		if !ok {
			return ABSENT
		}
		m := NewMlrmap()
		for i, p := range parts {
			m.Put(strconv.Itoa(i+1), MlrvalFromString(p))
		}
		return MlrvalFromMap(m)
	})
	splitkv := func(args []*Mlrval, infer bool) *Mlrval {
		parts, ok := splitHelper(args[0], args[2].String())
		if !ok {
			return ABSENT
		}
		ps := args[1].String()
		m := NewMlrmap()
		for i, p := range parts {
			idx := strings.Index(p, ps)
			var k, v string
			if idx < 0 || ps == "" {
				k = strconv.Itoa(i + 1)
				v = p
			} else {
				k = p[:idx]
				v = p[idx+len(ps):]
			}
			if infer {
				m.Put(k, MlrvalFromInferred(v))
			} else {
				m.Put(k, MlrvalFromString(v))
			}
		}
		return MlrvalFromMap(m)
	}
	reg("splitkv", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return splitkv(args, true) })
	reg("splitkvx", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return splitkv(args, false) })

	// ---- system
	reg("hostname", 0, 0, func(st *State, args []*Mlrval) *Mlrval {
		h, err := os.Hostname()
		if err != nil {
			return ERROR()
		}
		return MlrvalFromString(h)
	})
	reg("os", 0, 0, func(st *State, args []*Mlrval) *Mlrval { return MlrvalFromString(runtime.GOOS) })
	reg("version", 0, 0, func(st *State, args []*Mlrval) *Mlrval { return MlrvalFromString(MLR_VERSION) })
	reg("system", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		if !isStringish(args[0]) {
			return ERROR()
		}
		stdoutWriter.Flush()
		out, err := exec.Command("/bin/sh", "-c", args[0].printrep).Output()
		if err != nil && len(out) == 0 {
			return ERROR()
		}
		return MlrvalFromString(strings.TrimRight(string(out), "\n"))
	})
	reg("exec", 1, 3, func(st *State, args []*Mlrval) *Mlrval { return execFunc(args) })

	initBuiltins2()
	initTimeBuiltins()
}

type big3 struct{}

func (big3) mulmod(a, b, m int64) int64 {
	hi, lo := bits.Mul64(uint64(absI(a)), uint64(absI(b)))
	_, rem := bits.Div64(hi%uint64(absI(m)), lo, uint64(absI(m)))
	r := int64(rem)
	if (a < 0) != (b < 0) && r != 0 {
		r = absI(m) - r
	}
	if m < 0 && r != 0 {
		r += m
	}
	return r
}

func (bb big3) expmod(a, e, m int64) int64 {
	if e < 0 {
		return 0
	}
	result := int64(1) % absI(m)
	base := a % m
	if base < 0 {
		base += absI(m)
	}
	for e > 0 {
		if e&1 == 1 {
			result = bb.mulmod(result, base, m)
		}
		base = bb.mulmod(base, base, m)
		e >>= 1
	}
	return result
}

func absI(a int64) int64 {
	if a < 0 {
		return -a
	}
	return a
}

func mathBinaryFloat(a, b *Mlrval, f func(float64, float64) float64) *Mlrval {
	if a.IsNumeric() && b.IsNumeric() {
		return MlrvalFromFloat(f(a.GetNumericToFloat(), b.GetNumericToFloat()))
	}
	if a.IsAbsent() || b.IsAbsent() {
		if a.IsAbsent() && b.IsAbsent() {
			return ABSENT
		}
		if a.IsAbsent() {
			return b
		}
		return a
	}
	if a.IsVoid() || b.IsVoid() {
		return VOID
	}
	return ERROR()
}

// min/max with mixed types: numerics < booleans < voids < strings (for max); min reverse
func variadicMinMax(args []*Mlrval, isMax bool) *Mlrval {
	if len(args) == 0 {
		return VOID
	}
	var best *Mlrval
	for _, a := range args {
		var v *Mlrval
		if a.mtype == MT_MAP || a.mtype == MT_ARRAY {
			v = collectionMinMax(a, isMax)
			if v == nil {
				continue
			}
		} else {
			v = a
		}
		if v.IsAbsent() {
			continue
		}
		if best == nil {
			best = v
			continue
		}
		best = minMax2(best, v, isMax)
	}
	if best == nil {
		return ABSENT
	}
	return best
}

func collectionMinMax(a *Mlrval, isMax bool) *Mlrval {
	var vals []*Mlrval
	if a.mtype == MT_MAP {
		vals = a.mapval.vals
	} else {
		vals = a.arrayval
	}
	if len(vals) == 0 {
		return nil
	}
	r := variadicMinMax(vals, isMax)
	return r
}

func minMaxRank(v *Mlrval) int {
	switch v.Type() {
	case MT_INT, MT_FLOAT:
		return 1
	case MT_BOOLEAN:
		return 2
	case MT_VOID:
		return 0
	case MT_STRING:
		return 3
	case MT_ERROR:
		return 4
	}
	return 5
}

func minMax2(a, b *Mlrval, isMax bool) *Mlrval {
	ta, tb := a.Type(), b.Type()
	if ta == MT_ERROR {
		return a
	}
	if tb == MT_ERROR {
		return b
	}
	// void loses
	if ta == MT_VOID && tb != MT_VOID {
		return b
	}
	if tb == MT_VOID && ta != MT_VOID {
		return a
	}
	ra, rb := minMaxRank(a), minMaxRank(b)
	if ra != rb {
		if isMax {
			if ra > rb {
				return a
			}
			return b
		}
		if ra < rb {
			return a
		}
		return b
	}
	switch ta {
	case MT_INT, MT_FLOAT:
		if ta == MT_INT && tb == MT_INT {
			if isMax {
				if b.intval > a.intval {
					return b
				}
				return a
			}
			if b.intval < a.intval {
				return b
			}
			return a
		}
		x, y := a.GetNumericToFloat(), b.GetNumericToFloat()
		if isMax {
			if y > x {
				return MlrvalFromFloat(y)
			}
			return MlrvalFromFloat(x)
		}
		if y < x {
			return MlrvalFromFloat(y)
		}
		return MlrvalFromFloat(x)
	case MT_BOOLEAN:
		if isMax {
			if b.IsTrue() {
				return b
			}
			return a
		}
		if !b.IsTrue() {
			return b
		}
		return a
	case MT_STRING:
		if isMax {
			if b.printrep > a.printrep {
				return b
			}
			return a
		}
		if b.printrep < a.printrep {
			return b
		}
		return a
	}
	return a
}

func padFunc(args []*Mlrval, left bool) *Mlrval {
	a, n, p := args[0], args[1], args[2]
	if a.IsAbsent() {
		return ABSENT
	}
	if a.Type() == MT_ERROR {
		return ERROR()
	}
	if n.Type() != MT_INT {
		return ERROR()
	}
	if !isStringish(p) {
		return ERROR()
	}
	s := a.String()
	pad := p.printrep
	slen := utf8.RuneCountInString(s)
	plen := utf8.RuneCountInString(pad)
	if plen == 0 {
		return MlrvalFromString(s)
	}
	var b strings.Builder
	cur := slen
	reps := 0
	for cur+plen <= int(n.intval) {
		reps++
		cur += plen
	}
	if left {
		for i := 0; i < reps; i++ {
			b.WriteString(pad)
		}
		b.WriteString(s)
	} else {
		b.WriteString(s)
		for i := 0; i < reps; i++ {
			b.WriteString(pad)
		}
	}
	return MlrvalFromString(b.String())
}

func substrFunc(args []*Mlrval, base int64) *Mlrval {
	a, m, n := args[0], args[1], args[2]
	if a.IsAbsent() {
		return ABSENT
	}
	if a.Type() == MT_ERROR || a.IsCollection() {
		return ERROR()
	}
	mi, ok1 := intArgStrict(m)
	ni, ok2 := intArgStrict(n)
	if !ok1 || !ok2 {
		return ERROR()
	}
	runes := []rune(a.String())
	l := int64(len(runes))
	// convert to 0-up
	if base == 1 {
		if mi < 0 {
			mi += l + 1
		}
		if ni < 0 {
			ni += l + 1
		}
		mi--
		ni--
	} else {
		if mi < 0 {
			mi += l
		}
		if ni < 0 {
			ni += l
		}
	}
	if mi < 0 || ni >= l || mi > ni {
		if mi > ni && mi >= 0 && ni < l {
			return VOID
		}
		if l == 0 {
			return VOID
		}
		return ERROR()
	}
	return MlrvalFromString(string(runes[mi : ni+1]))
}

func intArgStrict(mv *Mlrval) (int64, bool) {
	if mv.Type() == MT_INT {
		return mv.intval, true
	}
	return 0, false
}

func subFunc(args []*Mlrval, global bool) *Mlrval {
	a, r, rep := args[0], args[1], args[2]
	if a.IsAbsent() {
		return ABSENT
	}
	if a.Type() == MT_ERROR || a.IsCollection() {
		return ERROR()
	}
	if !isStringish(r) || r.IsAbsent() {
		return ERROR()
	}
	if rep.IsAbsent() || rep.IsCollection() || rep.Type() == MT_ERROR {
		return ERROR()
	}
	re := getRegex(r.String())
	s := a.String()
	repl := rep.String()
	if global {
		return MlrvalFromString(re.ReplaceAllString(s, convertBackrefs(repl)))
	}
	return MlrvalFromString(regexSubOnce(re, s, repl))
}

func ssubFunc(args []*Mlrval, global bool) *Mlrval {
	a, old, nw := args[0], args[1], args[2]
	if a.IsAbsent() {
		return ABSENT
	}
	if a.Type() == MT_ERROR || a.IsCollection() {
		return ERROR()
	}
	if global {
		return MlrvalFromString(strings.ReplaceAll(a.String(), old.String(), nw.String()))
	}
	return MlrvalFromString(strings.Replace(a.String(), old.String(), nw.String(), 1))
}

func strmatchxFunc(args []*Mlrval) *Mlrval {
	a, r := args[0], args[1]
	if a.IsAbsent() {
		return ABSENT
	}
	if a.Type() == MT_ERROR || a.IsCollection() {
		return ERROR()
	}
	if !isStringish(r) {
		return ERROR()
	}
	re := getRegex(r.String())
	s := a.String()
	m := NewMlrmap()
	loc := re.FindStringSubmatchIndex(s)
	if loc == nil {
		m.Put("matched", FALSE)
		return MlrvalFromMap(m)
	}
	m.Put("matched", TRUE)
	m.Put("full_capture", MlrvalFromString(s[loc[0]:loc[1]]))
	m.Put("full_start", MlrvalFromInt(int64(utf8.RuneCountInString(s[:loc[0]])+1)))
	m.Put("full_end", MlrvalFromInt(int64(utf8.RuneCountInString(s[:loc[1]]))))
	if len(loc) > 2 {
		var caps, starts, ends []*Mlrval
		for i := 2; i+1 < len(loc); i += 2 {
			if loc[i] < 0 {
				caps = append(caps, VOID)
				starts = append(starts, MlrvalFromInt(-1))
				ends = append(ends, MlrvalFromInt(-1))
				continue
			}
			caps = append(caps, MlrvalFromInferred(s[loc[i]:loc[i+1]]))
			starts = append(starts, MlrvalFromInt(int64(utf8.RuneCountInString(s[:loc[i]])+1)))
			ends = append(ends, MlrvalFromInt(int64(utf8.RuneCountInString(s[:loc[i+1]]))))
		}
		m.Put("captures", MlrvalFromArray(caps))
		m.Put("starts", MlrvalFromArray(starts))
		m.Put("ends", MlrvalFromArray(ends))
	}
	return MlrvalFromMap(m)
}

func unformatFunc(args []*Mlrval, infer bool) *Mlrval {
	f, s := args[0], args[1]
	if f.IsAbsent() || s.IsAbsent() {
		return ABSENT
	}
	fs := f.String()
	ss := s.String()
	// build regex from format
	var b strings.Builder
	b.WriteString("^")
	parts := strings.Split(fs, "{}")
	for i, p := range parts {
		b.WriteString(regexp.QuoteMeta(p))
		if i < len(parts)-1 {
			b.WriteString("(.*?)")
		}
	}
	b.WriteString("$")
	re := regexp.MustCompile(b.String())
	m := re.FindStringSubmatch(ss)
	if m == nil {
		return ERROR()
	}
	out := make([]*Mlrval, 0, len(m)-1)
	for _, g := range m[1:] {
		if infer {
			out = append(out, MlrvalFromInferred(g))
		} else {
			out = append(out, MlrvalFromString(g))
		}
	}
	return MlrvalFromArray(out)
}

func recurseStrings(mv *Mlrval, f func(string) string) *Mlrval {
	switch mv.mtype {
	case MT_MAP:
		m := NewMlrmap()
		for i, k := range mv.mapval.keys {
			m.Put(f(k), recurseStrings(mv.mapval.vals[i], f))
		}
		return MlrvalFromMap(m)
	case MT_ARRAY:
		a := make([]*Mlrval, len(mv.arrayval))
		for i, e := range mv.arrayval {
			a[i] = recurseStrings(e, f)
		}
		return MlrvalFromArray(a)
	}
	if mv.Type() == MT_STRING {
		return MlrvalFromString(f(mv.printrep))
	}
	return mv
}

func latin1ToUTF8(s string) string {
	if utf8.ValidString(s) {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		b.WriteRune(rune(s[i]))
	}
	return b.String()
}

func utf8ToLatin1(s string) string {
	if !utf8.ValidString(s) {
		return s
	}
	var b []byte
	for _, r := range s {
		if r > 255 {
			return s
		}
		b = append(b, byte(r))
	}
	return string(b)
}

func fmtnumRecursive(v, f *Mlrval, ifnum bool) *Mlrval {
	switch v.mtype {
	case MT_MAP:
		m := NewMlrmap()
		for i, k := range v.mapval.keys {
			m.Put(k, fmtnumRecursive(v.mapval.vals[i], f, ifnum))
		}
		return MlrvalFromMap(m)
	case MT_ARRAY:
		a := make([]*Mlrval, len(v.arrayval))
		for i, e := range v.arrayval {
			a[i] = fmtnumRecursive(e, f, ifnum)
		}
		return MlrvalFromArray(a)
	}
	if v.IsAbsent() {
		return ABSENT
	}
	if !v.IsNumeric() {
		if ifnum {
			return v
		}
		return ERROR()
	}
	if !isStringish(f) {
		return ERROR()
	}
	fm := GetFormatter(f.printrep)
	r := fm.Format(v)
	if ifnum && r.IsError() {
		return v
	}
	return r
}

func execFunc(args []*Mlrval) *Mlrval {
	cmdName := args[0].String()
	var cmdArgs []string
	if len(args) >= 2 {
		if args[1].mtype == MT_ARRAY {
			for _, e := range args[1].arrayval {
				cmdArgs = append(cmdArgs, e.String())
			}
		}
	}
	cmd := exec.Command(cmdName, cmdArgs...)
	combined := false
	if len(args) >= 3 && args[2].mtype == MT_MAP {
		opts := args[2].mapval
		if e := opts.Get("env"); e != nil {
			if e.mtype == MT_ARRAY {
				for _, x := range e.arrayval {
					cmd.Env = append(cmd.Env, x.String())
				}
			} else {
				cmd.Env = append(cmd.Env, e.String())
			}
		}
		if d := opts.Get("dir"); d != nil {
			cmd.Dir = d.String()
		}
		if s := opts.Get("stdin_string"); s != nil {
			cmd.Stdin = strings.NewReader(s.String())
		}
		if c := opts.Get("combined_output"); c != nil && c.IsTrue() {
			combined = true
		}
	}
	stdoutWriter.Flush()
	var out []byte
	var err error
	if combined {
		out, err = cmd.CombinedOutput()
	} else {
		out, err = cmd.Output()
	}
	if err != nil && len(out) == 0 {
		return ERROR()
	}
	return MlrvalFromString(strings.TrimRight(string(out), "\n"))
}
