type BuiltinFunc func(st *State, args []*Mlrval) *Mlrval

type BuiltinInfo struct {
	name    string
	minArgs int
	maxArgs int // -1 variadic
	fn      BuiltinFunc
	regexArg int // index of arg that is a regex (for literal handling), -1 none
}

var builtinTable map[string]*BuiltinInfo

func reg(name string, minArgs, maxArgs int, fn BuiltinFunc) {
	builtinTable[name] = &BuiltinInfo{name: name, minArgs: minArgs, maxArgs: maxArgs, fn: fn, regexArg: -1}
}

func regRegex(name string, minArgs, maxArgs int, regexArg int, fn BuiltinFunc) {
	builtinTable[name] = &BuiltinInfo{name: name, minArgs: minArgs, maxArgs: maxArgs, fn: fn, regexArg: regexArg}
}

func builtinExists(name string) bool {
	initBuiltins()
	_, ok := builtinTable[name]
	return ok
}

func (c *compiler) compileFunctionCall(node *ASTNode) Evaluator {
	name := node.Text
	initBuiltins()
	var args []Evaluator
	if udf, ok := c.prog.udfs[name]; ok {
		for _, a := range node.Children {
			args = append(args, c.compileExpr(a))
		}
		nparams := len(udf.node.Children[0].Children)
		if nparams != len(args) {
			compileFatal("mlr: function %s invoked with %d argument%s; expected %d", name, len(args), plural(len(args)), nparams)
		}
		return func(st *State) *Mlrval {
			vals := make([]*Mlrval, len(args))
			for i, a := range args {
				vals[i] = a(st)
			}
			return callUDF(st, udf, vals)
		}
	}
	bi, ok := builtinTable[name]
	if !ok {
		// maybe a local variable holding a function
		lname := name
		for _, a := range node.Children {
			args = append(args, c.compileExpr(a))
		}
		_ = lname
		return func(st *State) *Mlrval {
			lv := st.frame.lookup(lname)
			if lv != nil && lv.val.mtype == MT_FUNC {
				udf := lv.val.funcval.(*UDF)
				vals := make([]*Mlrval, len(args))
				for i, a := range args {
					vals[i] = a(st)
				}
				return callUDF(st, udf, vals)
			}
			runtimeFatal("mlr: function name not found: %s", lname)
			return nil
		}
	}
	nargs := len(node.Children)
	if nargs < bi.minArgs || (bi.maxArgs >= 0 && nargs > bi.maxArgs) {
		if bi.maxArgs == bi.minArgs {
			compileFatal("mlr: function %s invoked with %d argument%s; expected %d", name, nargs, plural(nargs), bi.minArgs)
		} else if bi.maxArgs < 0 {
			compileFatal("mlr: function %s invoked with %d argument%s; expected at least %d", name, nargs, plural(nargs), bi.minArgs)
		} else {
			compileFatal("mlr: function %s invoked with %d argument%s; expected %d to %d", name, nargs, plural(nargs), bi.minArgs, bi.maxArgs)
		}
	}
	for i, a := range node.Children {
		if i == bi.regexArg {
			if rs, ok := regexStringFromLiteralNode(a); ok {
				if hasCaptureRefs(rs) {
					args = append(args, func(st *State) *Mlrval {
						return MlrvalFromString(interpolateCaptures(rs, st.captures))
					})
				} else {
					v := MlrvalFromString(rs)
					args = append(args, func(st *State) *Mlrval { return v })
				}
				continue
			}
		}
		args = append(args, c.compileExpr(a))
	}
	fn := bi.fn
	switch len(args) {
	case 0:
		return func(st *State) *Mlrval { return fn(st, nil) }
	case 1:
		a0 := args[0]
		return func(st *State) *Mlrval { return fn(st, []*Mlrval{a0(st)}) }
	case 2:
		a0, a1 := args[0], args[1]
		return func(st *State) *Mlrval { return fn(st, []*Mlrval{a0(st), a1(st)}) }
	}
	return func(st *State) *Mlrval {
		vals := make([]*Mlrval, len(args))
		for i, a := range args {
			vals[i] = a(st)
		}
		return fn(st, vals)
	}
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

// ---------------------------------------------------------------- math helpers

// math unary returning float
func mathUnaryFloat(f func(float64) float64) BuiltinFunc {
	return func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_INT:
			return MlrvalFromFloat(f(float64(a.intval)))
		case MT_FLOAT:
			return MlrvalFromFloat(f(a.floatval))
		case MT_VOID:
			return VOID
		case MT_ABSENT, MT_MAP, MT_ARRAY:
			return ABSENT
		}
		return ERROR()
	}
}

func mathUnaryIntPreserving(fi func(int64) int64, ff func(float64) float64) BuiltinFunc {
	return func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_INT:
			return MlrvalFromInt(fi(a.intval))
		case MT_FLOAT:
			return MlrvalFromFloat(ff(a.floatval))
		case MT_VOID:
			return VOID
		case MT_ABSENT, MT_MAP, MT_ARRAY:
			return ABSENT
		}
		return ERROR()
	}
}

func roundHalfAway(x float64) float64 {
	return math.Round(x)
}

// qnorm, invqnorm
func qnorm(x float64) float64 {
	return 0.5 * math.Erfc(-x/math.Sqrt2)
}

// Acklam's algorithm with refinement
func invqnorm(p float64) float64 {
	if p <= 0 || p >= 1 {
		return 0
	}
	a := []float64{-3.969683028665376e+01, 2.209460984245205e+02, -2.759285104469687e+02, 1.383577518672690e+02, -3.066479806614716e+01, 2.506628277459239e+00}
	b := []float64{-5.447609879822406e+01, 1.615858368580409e+02, -1.556989798598866e+02, 6.680131188771972e+01, -1.328068155288572e+01}
	c := []float64{-7.784894002430293e-03, -3.223964580411365e-01, -2.400758277161838e+00, -2.549732539343734e+00, 4.374664141464968e+00, 2.938163982698783e+00}
	d := []float64{7.784695709041462e-03, 3.224671290700398e-01, 2.445134137142996e+00, 3.754408661907416e+00}
	plow := 0.02425
	phigh := 1 - plow
	var x float64
	if p < plow {
		q := math.Sqrt(-2 * math.Log(p))
		x = (((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q + c[5]) / ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q + 1)
	} else if p <= phigh {
		q := p - 0.5
		r := q * q
		x = (((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r + a[5]) * q / (((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r + 1)
	} else {
		q := math.Sqrt(-2 * math.Log(1-p))
		x = -(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q + c[5]) / ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q + 1)
	}
	// refinement step
	e := 0.5*math.Erfc(-x/math.Sqrt2) - p
	u := e * math.Sqrt(2*math.Pi) * math.Exp(x*x/2)
	x = x - u/(1+x*u/2)
	return x
}

func isStringish(mv *Mlrval) bool {
	t := mv.Type()
	return t == MT_STRING || t == MT_VOID
}

// string function: applies to strings; passes through other types; error->error
func stringUnary(f func(string) string) BuiltinFunc {
	return func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_STRING:
			return MlrvalFromString(f(a.printrep))
		case MT_VOID:
			return a
		case MT_ERROR:
			return ERROR()
		}
		return a
	}
}

func intArg(mv *Mlrval) (int64, bool) {
	switch mv.Type() {
	case MT_INT:
		return mv.intval, true
	case MT_FLOAT:
		return int64(mv.floatval), true
	}
	return 0, false
}

var whitespaceRun = regexp.MustCompile(`\s+`)

func initBuiltins() {
	if builtinTable != nil {
		return
	}
	builtinTable = map[string]*BuiltinInfo{}

	// ---- math
	reg("abs", 1, 1, mathUnaryIntPreserving(func(i int64) int64 {
		if i < 0 {
			return -i
		}
		return i
	}, math.Abs))
	reg("ceil", 1, 1, mathUnaryIntPreserving(func(i int64) int64 { return i }, math.Ceil))
	reg("floor", 1, 1, mathUnaryIntPreserving(func(i int64) int64 { return i }, math.Floor))
	reg("round", 1, 1, mathUnaryIntPreserving(func(i int64) int64 { return i }, roundHalfAway))
	reg("sgn", 1, 1, mathUnaryIntPreserving(func(i int64) int64 {
		if i > 0 {
			return 1
		} else if i < 0 {
			return -1
		}
		return 0
	}, func(f float64) float64 {
		if f > 0 {
			return 1
		} else if f < 0 {
			return -1
		}
		return 0
	}))
	reg("acos", 1, 1, mathUnaryFloat(math.Acos))
	reg("acosh", 1, 1, mathUnaryFloat(math.Acosh))
	reg("asin", 1, 1, mathUnaryFloat(math.Asin))
	reg("asinh", 1, 1, mathUnaryFloat(math.Asinh))
	reg("atan", 1, 1, mathUnaryFloat(math.Atan))
	reg("atanh", 1, 1, mathUnaryFloat(math.Atanh))
	reg("cbrt", 1, 1, mathUnaryFloat(math.Cbrt))
	reg("cos", 1, 1, mathUnaryFloat(math.Cos))
	reg("cosh", 1, 1, mathUnaryFloat(math.Cosh))
	reg("erf", 1, 1, mathUnaryFloat(math.Erf))
	reg("erfc", 1, 1, mathUnaryFloat(math.Erfc))
	reg("exp", 1, 1, mathUnaryFloat(math.Exp))
	reg("expm1", 1, 1, mathUnaryFloat(math.Expm1))
	reg("invqnorm", 1, 1, mathUnaryFloat(invqnorm))
	reg("log", 1, 1, mathUnaryFloat(math.Log))
	reg("log10", 1, 1, mathUnaryFloat(math.Log10))
	reg("log1p", 1, 1, mathUnaryFloat(math.Log1p))
	reg("qnorm", 1, 1, mathUnaryFloat(qnorm))
	reg("sin", 1, 1, mathUnaryFloat(math.Sin))
	reg("sinh", 1, 1, mathUnaryFloat(math.Sinh))
	reg("sqrt", 1, 1, mathUnaryFloat(math.Sqrt))
	reg("tan", 1, 1, mathUnaryFloat(math.Tan))
	reg("tanh", 1, 1, mathUnaryFloat(math.Tanh))
	reg("bitcount", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_INT:
			return MlrvalFromInt(int64(bits.OnesCount64(uint64(a.intval))))
		case MT_VOID:
			return VOID
		case MT_ABSENT, MT_MAP, MT_ARRAY:
			return ABSENT
		}
		return ERROR()
	})
	reg("atan2", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		return mathBinaryFloat(args[0], args[1], math.Atan2)
	})
	reg("pow", 2, 2, func(st *State, args []*Mlrval) *Mlrval { return BinaryPow(args[0], args[1]) })
	reg("roundm", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		x, m := args[0], args[1]
		if x.Type() == MT_INT && m.Type() == MT_INT {
			if m.intval == 0 {
				return ERROR()
			}
			q := float64(x.intval) / float64(m.intval)
			return MlrvalFromInt(int64(math.Round(q)) * m.intval)
		}
		if x.IsNumeric() && m.IsNumeric() {
			xf, mf := x.GetNumericToFloat(), m.GetNumericToFloat()
			return MlrvalFromFloat(math.Round(xf/mf) * mf)
		}
		if x.IsAbsent() {
			return ABSENT
		}
		if x.IsVoid() {
			return VOID
		}
		return ERROR()
	})
	reg("logifit", 3, 3, func(st *State, args []*Mlrval) *Mlrval {
		x, m, b := args[0], args[1], args[2]
		if !x.IsNumeric() || !m.IsNumeric() || !b.IsNumeric() {
			if x.IsAbsent() {
				return ABSENT
			}
			if x.IsVoid() {
				return VOID
			}
			return ERROR()
		}
		return MlrvalFromFloat(1.0 / (1.0 + math.Exp(-m.GetNumericToFloat()*x.GetNumericToFloat()-b.GetNumericToFloat())))
	})
	modOp := func(f func(a, b, m int64) int64) BuiltinFunc {
		return func(st *State, args []*Mlrval) *Mlrval {
			a, b, m := args[0], args[1], args[2]
			if a.Type() != MT_INT || b.Type() != MT_INT || m.Type() != MT_INT {
				return ERROR()
			}
			if m.intval == 0 {
				return ERROR()
			}
			return MlrvalFromInt(f(a.intval, b.intval, m.intval))
		}
	}
	pymod := func(a, m int64) int64 {
		r := a % m
		if r != 0 && (r < 0) != (m < 0) {
			r += m
		}
		return r
	}
	reg("madd", 3, 3, modOp(func(a, b, m int64) int64 { return pymod(a+b, m) }))
	reg("msub", 3, 3, modOp(func(a, b, m int64) int64 { return pymod(a-b, m) }))
	reg("mmul", 3, 3, modOp(func(a, b, m int64) int64 {
		var r big3
		return r.mulmod(a, b, m)
	}))
	reg("mexp", 3, 3, modOp(func(a, b, m int64) int64 {
		var r big3
		return r.expmod(a, b, m)
	}))
	reg("min", 0, -1, func(st *State, args []*Mlrval) *Mlrval { return variadicMinMax(args, false) })
	reg("max", 0, -1, func(st *State, args []*Mlrval) *Mlrval { return variadicMinMax(args, true) })
	reg("urand", 0, 0, func(st *State, args []*Mlrval) *Mlrval { return MlrvalFromFloat(rng.Float64()) })
	reg("urand32", 0, 0, func(st *State, args []*Mlrval) *Mlrval { return MlrvalFromInt(int64(rng.Uint32())) })
	reg("urandint", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		a, ok1 := intArg(args[0])
		b, ok2 := intArg(args[1])
		if !ok1 || !ok2 {
			return ERROR()
		}
		if b < a {
			a, b = b, a
		}
		return MlrvalFromInt(a + rng.Int63n(b-a+1))
	})
	reg("urandrange", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		if !args[0].IsNumeric() || !args[1].IsNumeric() {
			return ERROR()
		}
		a := args[0].GetNumericToFloat()
		b := args[1].GetNumericToFloat()
		return MlrvalFromFloat(a + (b-a)*rng.Float64())
	})
	reg("urandelement", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		if a.mtype != MT_ARRAY || len(a.arrayval) == 0 {
			return ERROR()
		}
		return a.arrayval[rng.Intn(len(a.arrayval))]
	})

	// ---- boolean/typing
	typePred := func(name string, f func(mv *Mlrval) bool) {
		reg("is_"+name, 1, 1, func(st *State, args []*Mlrval) *Mlrval { return MlrvalFromBool(f(args[0])) })
		reg("asserting_"+name, 1, 1, func(st *State, args []*Mlrval) *Mlrval {
			if !f(args[0]) {
				runtimeFatal("mlr: is_%s type-assertion failed at NR=%d FNR=%d FILENAME=%s", name, st.ctx.NR, st.ctx.FNR, st.ctx.FILENAME)
			}
			return args[0]
		})
	}
	typePred("absent", func(mv *Mlrval) bool { return mv.IsAbsent() })
	typePred("array", func(mv *Mlrval) bool { return mv.mtype == MT_ARRAY })
	typePred("bool", func(mv *Mlrval) bool { return mv.mtype == MT_BOOLEAN })
	typePred("boolean", func(mv *Mlrval) bool { return mv.mtype == MT_BOOLEAN })
	typePred("empty", func(mv *Mlrval) bool { return mv.Type() == MT_VOID && !mv.isnull })
	typePred("empty_map", func(mv *Mlrval) bool { return mv.mtype == MT_MAP && mv.mapval.Len() == 0 })
	typePred("error", func(mv *Mlrval) bool { return mv.mtype == MT_ERROR })
	typePred("float", func(mv *Mlrval) bool { return mv.Type() == MT_FLOAT })
	typePred("int", func(mv *Mlrval) bool { return mv.Type() == MT_INT })
	typePred("map", func(mv *Mlrval) bool { return mv.mtype == MT_MAP })
	typePred("nonempty_map", func(mv *Mlrval) bool { return mv.mtype == MT_MAP && mv.mapval.Len() > 0 })
	typePred("not_array", func(mv *Mlrval) bool { return mv.mtype != MT_ARRAY })
	typePred("not_empty", func(mv *Mlrval) bool {
		t := mv.Type()
		return !(t == MT_VOID && !mv.isnull) && t != MT_ABSENT
	})
	typePred("not_map", func(mv *Mlrval) bool { return mv.mtype != MT_MAP })
	typePred("not_null", func(mv *Mlrval) bool {
		t := mv.Type()
		return t != MT_VOID && t != MT_ABSENT
	})
	typePred("null", func(mv *Mlrval) bool {
		t := mv.Type()
		return t == MT_VOID || t == MT_ABSENT
	})
	typePred("numeric", func(mv *Mlrval) bool { return mv.IsNumeric() })
	typePred("present", func(mv *Mlrval) bool { return !mv.IsAbsent() })
	typePred("string", func(mv *Mlrval) bool {
		t := mv.Type()
		return (t == MT_STRING || t == MT_VOID) && !mv.isnull
	})
	reg("is_nan", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		return MlrvalFromBool(args[0].Type() == MT_FLOAT && math.IsNaN(args[0].floatval))
	})
	reg("typeof", 1, 1, func(st *State, args []*Mlrval) *Mlrval { return MlrvalFromString(typeName(args[0])) })
	reg("asserting_absent", 1, 1, builtinTable["asserting_absent"].fn)

	// ---- strings
	reg("strlen", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		t := a.Type()
		if t == MT_STRING || t == MT_VOID {
			return MlrvalFromInt(int64(utf8.RuneCountInString(a.printrep)))
		}
		return ERROR()
	})
	reg("toupper", 1, 1, stringUnary(strings.ToUpper))
	reg("tolower", 1, 1, stringUnary(strings.ToLower))
	reg("capitalize", 1, 1, stringUnary(func(s string) string {
		r, size := utf8.DecodeRuneInString(s)
		return string(unicode.ToUpper(r)) + s[size:]
	}))
	reg("lstrip", 1, 1, stringUnary(func(s string) string { return strings.TrimLeft(s, " \t\n\r") }))
	reg("rstrip", 1, 1, stringUnary(func(s string) string { return strings.TrimRight(s, " \t\n\r") }))
	reg("strip", 1, 1, stringUnary(func(s string) string { return strings.Trim(s, " \t\n\r") }))
	reg("collapse_whitespace", 1, 1, stringUnary(func(s string) string { return whitespaceRun.ReplaceAllString(s, " ") }))
	reg("clean_whitespace", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		if a.Type() == MT_VOID {
			return a
		}
		s := a.String()
		s = strings.Trim(whitespaceRun.ReplaceAllString(s, " "), " \t\n\r")
		return MlrvalFromInferred(s)
	})
	reg("truncate", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		a, n := args[0], args[1]
		if a.IsAbsent() {
			return ABSENT
		}
		if a.Type() == MT_ERROR {
			return ERROR()
		}
		if n.Type() != MT_INT {
			return ERROR()
		}
		if !isStringish(a) {
			return ERROR()
		}
		if n.intval < 0 {
			return ERROR()
		}
		runes := []rune(a.printrep)
		if int64(len(runes)) <= n.intval {
			return a
		}
		return MlrvalFromString(string(runes[:n.intval]))
	})
	reg("leftpad", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return padFunc(args, true) })
	reg("rightpad", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return padFunc(args, false) })
	reg("format", 0, -1, func(st *State, args []*Mlrval) *Mlrval {
		if len(args) == 0 {
			return ERROR()
		}
		f := args[0]
		if f.IsAbsent() {
			return ABSENT
		}
		fs := f.String()
		var b strings.Builder
		k := 1
		for i := 0; i < len(fs); i++ {
			if fs[i] == '{' && i+1 < len(fs) && fs[i+1] == '}' {
				if k < len(args) {
					b.WriteString(args[k].String())
				}
				k++
				i++
				continue
			}
			b.WriteByte(fs[i])
		}
		return MlrvalFromString(b.String())
	})
	reg("unformat", 2, 2, func(st *State, args []*Mlrval) *Mlrval { return unformatFunc(args, true) })
	reg("unformatx", 2, 2, func(st *State, args []*Mlrval) *Mlrval { return unformatFunc(args, false) })
	reg("contains", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		if args[0].IsAbsent() {
			return ABSENT
		}
		if args[0].Type() == MT_ERROR {
			return ERROR()
		}
		return MlrvalFromBool(strings.Contains(args[0].String(), args[1].String()))
	})
	reg("index", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		if args[0].IsAbsent() {
			return ABSENT
		}
		if args[0].Type() == MT_ERROR {
			return ERROR()
		}
		s := args[0].String()
		t := args[1].String()
		idx := strings.Index(s, t)
		if idx < 0 {
			return MlrvalFromInt(-1)
		}
		return MlrvalFromInt(int64(utf8.RuneCountInString(s[:idx]) + 1))
	})
	reg("substr", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return substrFunc(args, 0) })
	reg("substr0", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return substrFunc(args, 0) })
	reg("substr1", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return substrFunc(args, 1) })
	regRegex("sub", 3, 3, 1, func(st *State, args []*Mlrval) *Mlrval { return subFunc(args, false) })
	regRegex("gsub", 3, 3, 1, func(st *State, args []*Mlrval) *Mlrval { return subFunc(args, true) })
	reg("ssub", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return ssubFunc(args, false) })
	reg("gssub", 3, 3, func(st *State, args []*Mlrval) *Mlrval { return ssubFunc(args, true) })
	regRegex("regextract", 2, 2, 1, func(st *State, args []*Mlrval) *Mlrval {
		a, r := args[0], args[1]
		if a.IsAbsent() {
			return ABSENT
		}
		if a.Type() == MT_ERROR || a.IsCollection() {
			return ERROR()
		}
		re := getRegex(r.String())
		m := re.FindString(a.String())
		loc := re.FindStringIndex(a.String())
		if loc == nil {
			return ERROR()
		}
		return MlrvalFromString(m)
	})
	regRegex("regextract_or_else", 3, 3, 1, func(st *State, args []*Mlrval) *Mlrval {
		a, r := args[0], args[1]
		if a.IsAbsent() {
			return ABSENT
		}
		if a.Type() == MT_ERROR || a.IsCollection() {
			return ERROR()
		}
		re := getRegex(r.String())
		loc := re.FindStringIndex(a.String())
		if loc == nil {
			return args[2]
		}
		return MlrvalFromString(a.String()[loc[0]:loc[1]])
	})
	regRegex("strmatch", 2, 2, 1, func(st *State, args []*Mlrval) *Mlrval {
		a, r := args[0], args[1]
		if a.IsAbsent() {
			return ABSENT
		}
		if a.Type() == MT_ERROR || a.IsCollection() {
			return ERROR()
		}
		if !isStringish(r) {
			return ERROR()
		}
		return MlrvalFromBool(getRegex(r.String()).MatchString(a.String()))
	})
	regRegex("strmatchx", 2, 2, 1, func(st *State, args []*Mlrval) *Mlrval { return strmatchxFunc(args) })
