	reg("boolean", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_BOOLEAN:
			return a
		case MT_INT:
			return MlrvalFromBool(a.intval != 0)
		case MT_FLOAT:
			return MlrvalFromBool(a.floatval != 0)
		case MT_VOID:
			return VOID
		case MT_ABSENT:
			return ABSENT
