	reg("int", 1, 2, func(st *State, args []*Mlrval) *Mlrval {
		a := args[0]
		if len(args) == 2 && (a.mtype == MT_STRING || (a.mtype == MT_PENDING) || a.prValid) && a.Type() != MT_FLOAT && a.Type() != MT_BOOLEAN {
			if a.Type() == MT_STRING || (a.Type() == MT_INT && a.prValid) {
				b, ok := intArg(args[1])
				if ok {
					s := a.printrep
					neg := false
					if strings.HasPrefix(s, "-") {
						neg = true
						s = s[1:]
					}
					sl := strings.ToLower(s)
					if b == 16 {
						sl = strings.TrimPrefix(sl, "0x")
					} else if b == 2 {
						sl = strings.TrimPrefix(sl, "0b")
					} else if b == 8 {
						sl = strings.TrimPrefix(sl, "0o")
					}
					u, err := strconv.ParseUint(sl, int(b), 64)
					if err != nil {
						return ERROR()
					}
					i := int64(u)
					if neg {
						i = -i
					}
					return MlrvalFromInt(i)
				}
			}
		}
		switch a.Type() {
		case MT_INT:
			if a.prValid {
				return MlrvalFromInt(a.intval)
			}
			return a
		case MT_FLOAT:
			return MlrvalFromInt(int64(a.floatval))
		case MT_BOOLEAN:
			if a.IsTrue() {
				return MlrvalFromInt(1)
			}
			return MlrvalFromInt(0)
