	reg("joinv", 2, 2, func(st *State, args []*Mlrval) *Mlrval {
		m, sep := args[0], args[1].String()
		var parts []string
		if m.mtype == MT_MAP {
			for _, v := range m.mapval.vals {
				parts = append(parts, v.String())
			}
		} else if m.mtype == MT_ARRAY {
			for _, v := range m.arrayval {
				parts = append(parts, v.String())
			}
		} else {
			if m.IsAbsent() {
				return ABSENT
			}
			return ERROR()
		}
		return MlrvalFromString(strings.Join(parts, sep))
