type big3 struct{}

func (big3) mulmod(a, b, m int64) int64 {
	hi, lo := bits.Mul64(uint64(absI(a)), uint64(absI(b)))
	_, rem := bits.Div64(hi%uint64(absI(m)), lo, uint64(absI(m)))
	r := int64(rem)
	if (a < 0) != (b < 0) && r != 0 {
		r = absI(m) - r
	}
	if m < 0 && r != 0 {
		r += m
	}
	return r
}

func (bb big3) expmod(a, e, m int64) int64 {
	if e < 0 {
		return 0
	}
	result := int64(1) % absI(m)
	base := a % m
	if base < 0 {
		base += absI(m)
	}
	for e > 0 {
		if e&1 == 1 {
			result = bb.mulmod(result, base, m)
		}
		base = bb.mulmod(base, base, m)
		e >>= 1
	}
	return result
}

func absI(a int64) int64 {
	if a < 0 {
		return -a
	}
	return a
}

func mathBinaryFloat(a, b *Mlrval, f func(float64, float64) float64) *Mlrval {
	if a.IsNumeric() && b.IsNumeric() {
		return MlrvalFromFloat(f(a.GetNumericToFloat(), b.GetNumericToFloat()))
	}
	if a.IsAbsent() || b.IsAbsent() {
		if a.IsAbsent() && b.IsAbsent() {
			return ABSENT
		}
		if a.IsAbsent() {
			return b
		}
		return a
	}
	if a.IsVoid() || b.IsVoid() {
		return VOID
	}
	return ERROR()
}

// min/max with mixed types: numerics < booleans < voids < strings (for max); min reverse
func variadicMinMax(args []*Mlrval, isMax bool) *Mlrval {
	if len(args) == 0 {
		return VOID
	}
	var best *Mlrval
	for _, a := range args {
		var v *Mlrval
		if a.mtype == MT_MAP || a.mtype == MT_ARRAY {
			v = collectionMinMax(a, isMax)
			if v == nil {
				continue
			}
		} else {
			v = a
		}
		if v.IsAbsent() {
			continue
		}
		if best == nil {
			best = v
			continue
		}
		best = minMax2(best, v, isMax)
	}
	if best == nil {
		return ABSENT
	}
	return best
}

func collectionMinMax(a *Mlrval, isMax bool) *Mlrval {
	var vals []*Mlrval
	if a.mtype == MT_MAP {
		vals = a.mapval.vals
	} else {
		vals = a.arrayval
	}
	if len(vals) == 0 {
		return nil
	}
	r := variadicMinMax(vals, isMax)
	return r
}

func minMaxRank(v *Mlrval) int {
	switch v.Type() {
	case MT_INT, MT_FLOAT:
		return 1
	case MT_BOOLEAN:
		return 2
	case MT_VOID:
		return 0
	case MT_STRING:
		return 3
	case MT_ERROR:
		return 4
	}
	return 5
}

func minMax2(a, b *Mlrval, isMax bool) *Mlrval {
	ta, tb := a.Type(), b.Type()
	if ta == MT_ERROR {
		return a
	}
	if tb == MT_ERROR {
		return b
	}
	// void loses
	if ta == MT_VOID && tb != MT_VOID {
		return b
	}
	if tb == MT_VOID && ta != MT_VOID {
		return a
	}
	ra, rb := minMaxRank(a), minMaxRank(b)
	if ra != rb {
		if isMax {
			if ra > rb {
				return a
			}
			return b
		}
		if ra < rb {
			return a
		}
		return b
	}
	switch ta {
	case MT_INT, MT_FLOAT:
		if ta == MT_INT && tb == MT_INT {
			if isMax {
				if b.intval > a.intval {
					return b
				}
				return a
			}
			if b.intval < a.intval {
				return b
			}
			return a
		}
		x, y := a.GetNumericToFloat(), b.GetNumericToFloat()
		if isMax {
			if y > x {
				return MlrvalFromFloat(y)
			}
			return MlrvalFromFloat(x)
		}
		if y < x {
			return MlrvalFromFloat(y)
		}
		return MlrvalFromFloat(x)
	case MT_BOOLEAN:
		if isMax {
			if b.IsTrue() {
				return b
			}
			return a
		}
		if !b.IsTrue() {
			return b
		}
		return a
	case MT_STRING:
		if isMax {
			if b.printrep > a.printrep {
				return b
			}
			return a
		}
		if b.printrep < a.printrep {
			return b
		}
		return a
	}
	return a
}

func padFunc(args []*Mlrval, left bool) *Mlrval {
	a, n, p := args[0], args[1], args[2]
	if a.IsAbsent() {
		return ABSENT
	}
	if a.Type() == MT_ERROR {
		return ERROR()
	}
	if n.Type() != MT_INT {
		return ERROR()
	}
	if !isStringish(p) {
		return ERROR()
	}
	s := a.String()
	pad := p.printrep
	slen := utf8.RuneCountInString(s)
	plen := utf8.RuneCountInString(pad)
	if plen == 0 {
		return MlrvalFromString(s)
	}
	var b strings.Builder
	cur := slen
	reps := 0
	for cur+plen <= int(n.intval) {
		reps++
		cur += plen
	}
	if left {
		for i := 0; i < reps; i++ {
			b.WriteString(pad)
		}
		b.WriteString(s)
	} else {
		b.WriteString(s)
		for i := 0; i < reps; i++ {
			b.WriteString(pad)
		}
	}
	return MlrvalFromString(b.String())
}

func substrFunc(args []*Mlrval, base int64) *Mlrval {
	a, m, n := args[0], args[1], args[2]
	if a.IsAbsent() {
		return ABSENT
	}
	if a.Type() == MT_ERROR || a.IsCollection() {
		return ERROR()
	}
	mi, ok1 := intArgStrict(m)
	ni, ok2 := intArgStrict(n)
	if !ok1 || !ok2 {
		return ERROR()
	}
	runes := []rune(a.String())
	l := int64(len(runes))
	// convert to 0-up
	if base == 1 {
		if mi < 0 {
			mi += l + 1
		}
		if ni < 0 {
			ni += l + 1
		}
		mi--
		ni--
	} else {
		if mi < 0 {
			mi += l
		}
		if ni < 0 {
			ni += l
		}
	}
	if mi < 0 || ni >= l || mi > ni {
		if mi > ni && mi >= 0 && ni < l {
			return VOID
		}
		if l == 0 {
			return VOID
		}
		return ERROR()
	}
	return MlrvalFromString(string(runes[mi : ni+1]))
}

func intArgStrict(mv *Mlrval) (int64, bool) {
	if mv.Type() == MT_INT {
		return mv.intval, true
	}
	return 0, false
}

func subFunc(args []*Mlrval, global bool) *Mlrval {
	a, r, rep := args[0], args[1], args[2]
	if a.IsAbsent() {
		return ABSENT
	}
	if a.Type() == MT_ERROR || a.IsCollection() {
		return ERROR()
	}
	if !isStringish(r) || r.IsAbsent() {
		return ERROR()
	}
	if rep.IsAbsent() || rep.IsCollection() || rep.Type() == MT_ERROR {
		return ERROR()
	}
	re := getRegex(r.String())
	s := a.String()
	repl := rep.String()
	if global {
		return MlrvalFromString(re.ReplaceAllString(s, convertBackrefs(repl)))
	}
	return MlrvalFromString(regexSubOnce(re, s, repl))
}

func ssubFunc(args []*Mlrval, global bool) *Mlrval {
	a, old, nw := args[0], args[1], args[2]
	if a.IsAbsent() {
		return ABSENT
	}
	if a.Type() == MT_ERROR || a.IsCollection() {
		return ERROR()
	}
	if global {
		return MlrvalFromString(strings.ReplaceAll(a.String(), old.String(), nw.String()))
	}
	return MlrvalFromString(strings.Replace(a.String(), old.String(), nw.String(), 1))
}

func strmatchxFunc(args []*Mlrval) *Mlrval {
	a, r := args[0], args[1]
	if a.IsAbsent() {
		return ABSENT
	}
	if a.Type() == MT_ERROR || a.IsCollection() {
		return ERROR()
	}
	if !isStringish(r) {
		return ERROR()
	}
	re := getRegex(r.String())
	s := a.String()
	m := NewMlrmap()
	loc := re.FindStringSubmatchIndex(s)
	if loc == nil {
		m.Put("matched", FALSE)
		return MlrvalFromMap(m)
	}
	m.Put("matched", TRUE)
	m.Put("full_capture", MlrvalFromString(s[loc[0]:loc[1]]))
	m.Put("full_start", MlrvalFromInt(int64(utf8.RuneCountInString(s[:loc[0]])+1)))
	m.Put("full_end", MlrvalFromInt(int64(utf8.RuneCountInString(s[:loc[1]]))))
	if len(loc) > 2 {
		var caps, starts, ends []*Mlrval
		for i := 2; i+1 < len(loc); i += 2 {
			if loc[i] < 0 {
				caps = append(caps, VOID)
				starts = append(starts, MlrvalFromInt(-1))
				ends = append(ends, MlrvalFromInt(-1))
				continue
			}
			caps = append(caps, MlrvalFromInferred(s[loc[i]:loc[i+1]]))
			starts = append(starts, MlrvalFromInt(int64(utf8.RuneCountInString(s[:loc[i]])+1)))
			ends = append(ends, MlrvalFromInt(int64(utf8.RuneCountInString(s[:loc[i+1]]))))
		}
		m.Put("captures", MlrvalFromArray(caps))
		m.Put("starts", MlrvalFromArray(starts))
		m.Put("ends", MlrvalFromArray(ends))
	}
	return MlrvalFromMap(m)
}

func unformatFunc(args []*Mlrval, infer bool) *Mlrval {
	f, s := args[0], args[1]
	if f.IsAbsent() || s.IsAbsent() {
		return ABSENT
	}
	fs := f.String()
	ss := s.String()
	// build regex from format
	var b strings.Builder
	b.WriteString("^")
	parts := strings.Split(fs, "{}")
	for i, p := range parts {
		b.WriteString(regexp.QuoteMeta(p))
		if i < len(parts)-1 {
			b.WriteString("(.*?)")
		}
	}
	b.WriteString("$")
	re := regexp.MustCompile(b.String())
	m := re.FindStringSubmatch(ss)
	if m == nil {
		return ERROR()
	}
	out := make([]*Mlrval, 0, len(m)-1)
	for _, g := range m[1:] {
		if infer {
			out = append(out, MlrvalFromInferred(g))
		} else {
			out = append(out, MlrvalFromString(g))
		}
	}
	return MlrvalFromArray(out)
}

func recurseStrings(mv *Mlrval, f func(string) string) *Mlrval {
	switch mv.mtype {
	case MT_MAP:
		m := NewMlrmap()
		for i, k := range mv.mapval.keys {
			m.Put(f(k), recurseStrings(mv.mapval.vals[i], f))
		}
		return MlrvalFromMap(m)
	case MT_ARRAY:
		a := make([]*Mlrval, len(mv.arrayval))
		for i, e := range mv.arrayval {
			a[i] = recurseStrings(e, f)
		}
		return MlrvalFromArray(a)
	}
	if mv.Type() == MT_STRING {
		return MlrvalFromString(f(mv.printrep))
	}
	return mv
}

func latin1ToUTF8(s string) string {
	if utf8.ValidString(s) {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		b.WriteRune(rune(s[i]))
	}
	return b.String()
}

func utf8ToLatin1(s string) string {
	if !utf8.ValidString(s) {
		return s
	}
	var b []byte
	for _, r := range s {
		if r > 255 {
			return s
		}
		b = append(b, byte(r))
	}
	return string(b)
}

func fmtnumRecursive(v, f *Mlrval, ifnum bool) *Mlrval {
	switch v.mtype {
	case MT_MAP:
		m := NewMlrmap()
		for i, k := range v.mapval.keys {
			m.Put(k, fmtnumRecursive(v.mapval.vals[i], f, ifnum))
		}
		return MlrvalFromMap(m)
	case MT_ARRAY:
		a := make([]*Mlrval, len(v.arrayval))
		for i, e := range v.arrayval {
			a[i] = fmtnumRecursive(e, f, ifnum)
		}
		return MlrvalFromArray(a)
	}
	if v.IsAbsent() {
		return ABSENT
	}
	if !v.IsNumeric() {
		if ifnum {
			return v
		}
		return ERROR()
	}
	if !isStringish(f) {
		return ERROR()
	}
	fm := GetFormatter(f.printrep)
	r := fm.Format(v)
	if ifnum && r.IsError() {
		return v
	}
	return r
}

func execFunc(args []*Mlrval) *Mlrval {
	cmdName := args[0].String()
	var cmdArgs []string
	if len(args) >= 2 {
		if args[1].mtype == MT_ARRAY {
			for _, e := range args[1].arrayval {
				cmdArgs = append(cmdArgs, e.String())
			}
		}
	}
	cmd := exec.Command(cmdName, cmdArgs...)
	combined := false
	if len(args) >= 3 && args[2].mtype == MT_MAP {
		opts := args[2].mapval
		if e := opts.Get("env"); e != nil {
			if e.mtype == MT_ARRAY {
				for _, x := range e.arrayval {
					cmd.Env = append(cmd.Env, x.String())
				}
			} else {
				cmd.Env = append(cmd.Env, e.String())
			}
		}
		if d := opts.Get("dir"); d != nil {
			cmd.Dir = d.String()
		}
		if s := opts.Get("stdin_string"); s != nil {
			cmd.Stdin = strings.NewReader(s.String())
		}
		if c := opts.Get("combined_output"); c != nil && c.IsTrue() {
			combined = true
		}
	}
	stdoutWriter.Flush()
	var out []byte
	var err error
	if combined {
		out, err = cmd.CombinedOutput()
	} else {
		out, err = cmd.Output()
	}
	if err != nil && len(out) == 0 {
		return ERROR()
	}
	return MlrvalFromString(strings.TrimRight(string(out), "\n"))
}
