	reg("maxlen", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		vals, ok := collectionValues(args[0])
		if !ok {
			return ERROR()
		}
		if len(vals) == 0 {
			return VOID
		}
		best := int64(-1)
		for _, v := range vals {
			n := int64(utf8.RuneCountInString(v.String()))
			if n > best {
				best = n
			}
		}
		return MlrvalFromInt(best)
	})
	reg("null_count", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		vals, ok := collectionValues(args[0])
		if !ok {
			return ERROR()
		}
		n := 0
		for _, v := range vals {
			if v.Type() == MT_VOID {
				n++
			}
		}
		return MlrvalFromInt(int64(n))
	})
	reg("distinct_count", 1, 1, func(st *State, args []*Mlrval) *Mlrval {
		vals, ok := collectionValues(args[0])
		if !ok {
			return ERROR()
		}
		seen := map[string]bool{}
		for _, v := range vals {
			seen[v.String()] = true
		}
		return MlrvalFromInt(int64(len(seen)))
	})
	modeFn := func(anti bool) BuiltinFunc {
		return func(st *State, args []*Mlrval) *Mlrval {
			vals, ok := collectionValues(args[0])
			if !ok {
				return ERROR()
			}
			if len(vals) == 0 {
				return ERROR()
			}
			counts := map[string]int{}
			first := map[string]*Mlrval{}
			var order []string
			for _, v := range vals {
				s := v.String()
				if _, ok := counts[s]; !ok {
					order = append(order, s)
					first[s] = v
				}
				counts[s]++
			}
			best := order[0]
			for _, s := range order[1:] {
				if anti {
					if counts[s] < counts[best] {
						best = s
					}
				} else {
					if counts[s] > counts[best] {
						best = s
					}
				}
			}
			return first[best]
		}
	}
	reg("mode", 1, 1, modeFn(false))
	reg("antimode", 1, 1, modeFn(true))
}

