		return args[i]
	}
	return nil
}

func depthOf(v *Mlrval) int {
	switch v.mtype {
	case MT_MAP:
		max := 0
		for _, e := range v.mapval.vals {
			d := depthOf(e)
			if d > max {
				max = d
			}
		}
		return max + 1
	case MT_ARRAY:
		max := 0
		for _, e := range v.arrayval {
			d := depthOf(e)
			if d > max {
				max = d
			}
		}
		return max + 1
	}
	return 0
}

func leafCount(v *Mlrval) int {
	switch v.mtype {
	case MT_MAP:
		n := 0
		for _, e := range v.mapval.vals {
			n += leafCount(e)
		}
		return n
	case MT_ARRAY:
		n := 0
		for _, e := range v.arrayval {
			n += leafCount(e)
		}
		return n
	}
	return 1
}

func unflattenRecordAll(rec *Mlrmap, sep string) {
