}

func collectionValues(v *Mlrval) ([]*Mlrval, bool) {
	if v.mtype == MT_ARRAY {
		return v.arrayval, true
	}
	if v.mtype == MT_MAP {
		return v.mapval.vals, true
	}
	return nil, false
}

func statsPowerSum(c *Mlrval, p int) *Mlrval {
	vals, ok := collectionValues(c)
	if !ok {
		return ERROR()
	}
	acc := MlrvalFromInt(0)
	for _, v := range vals {
		var t *Mlrval
		switch p {
		case 1:
			t = v
		case 2:
			t = BinaryTimes(v, v)
		case 3:
			t = BinaryTimes(v, BinaryTimes(v, v))
		case 4:
			sq := BinaryTimes(v, v)
			t = BinaryTimes(sq, sq)
		}
		acc = BinaryPlus(acc, t)
	}
	return acc
}

// variance etc using Miller's accumulation formulas
func varianceLike(c *Mlrval, kind string) *Mlrval {
	vals, ok := collectionValues(c)
	if !ok {
		return ERROR()
	}
	n := len(vals)
	var sumx, sumx2, sumx3, sumx4 float64
	for _, v := range vals {
		x := v.GetNumericToFloat()
		sumx += x
		sumx2 += x * x
		sumx3 += x * x * x
		sumx4 += x * x * x * x
	}
	return varianceFromSums(kind, int64(n), sumx, sumx2, sumx3, sumx4)
}

func varianceFromSums(kind string, n int64, sumx, sumx2, sumx3, sumx4 float64) *Mlrval {
	if kind == "var" || kind == "stddev" || kind == "meaneb" {
		if n < 2 {
			return VOID
		}
		mean := sumx / float64(n)
		numerator := sumx2 - mean*(2.0*sumx-float64(n)*mean)
		if numerator < 0.0 {
			numerator = 0.0
		}
		denominator := float64(n) - 1.0
		v := numerator / denominator
		switch kind {
		case "var":
			return MlrvalFromFloat(v)
		case "stddev":
			return MlrvalFromFloat(math.Sqrt(v))
		case "meaneb":
			return MlrvalFromFloat(math.Sqrt(v / float64(n)))
		}
	}
	if kind == "skewness" {
		if n < 2 {
			return VOID
		}
		nf := float64(n)
		mean := sumx / nf
		numer := sumx3 - mean*(3.0*sumx2-2.0*nf*sumx*mean) - nf*mean*mean*mean
		numer = numer / nf
		denom := math.Pow((sumx2/nf - mean*mean), 1.5)
		return MlrvalFromFloat(numer / denom)
	}
	if kind == "kurtosis" {
		if n < 2 {
			return VOID
		}
		nf := float64(n)
		mean := sumx / nf
		numer := sumx4 - mean*(4.0*sumx3-mean*(6.0*sumx2-3.0*nf*sumx*mean))
		numer = numer / nf
		denom := (sumx2/nf - mean*mean)
		denom = denom * denom
		return MlrvalFromFloat(numer/denom - 3.0)
	}
	return ERROR()
}

func percentileOptions(opts *Mlrval) (interp bool, oa bool, ais bool) {
	if opts == nil || opts.mtype != MT_MAP {
		return
	}
	for i, k := range opts.mapval.keys {
		v := opts.mapval.vals[i].IsTrue()
		switch k {
		case "interpolate_linearly", "il":
			interp = v
		case "output_array_not_map", "oa":
			oa = v
		case "array_is_sorted", "ais":
			ais = v
		}
	}
	return
}

func sortedForPercentiles(c *Mlrval, ais bool) ([]*Mlrval, bool) {
	vals, ok := collectionValues(c)
	if !ok {
		return nil, false
	}
	s := make([]*Mlrval, len(vals))
	copy(s, vals)
	if !ais {
		sort.SliceStable(s, func(i, j int) bool { return collateCompare(s[i], s[j]) < 0 })
	}
	return s, true
}

func percentileOfSorted(s []*Mlrval, p float64, interp bool) *Mlrval {
	n := len(s)
	if n == 0 {
		return VOID
	}
	if !interp {
		idx := p / 100.0 * float64(n)
		i := int64(idx)
		if idx < 0 {
			i = 0
		}
		if i >= int64(n) {
			i = int64(n) - 1
		}
		if i < 0 {
			i = 0
		}
		return s[i]
	}
	findex := (p / 100.0) * float64(n-1)
	if findex < 0.0 {
		findex = 0.0
	}
	iidx := int64(findex)
	if iidx+1 < int64(n) {
		frac := findex - float64(iidx)
		lo := s[iidx]
		hi := s[iidx+1]
		if !lo.IsNumeric() || !hi.IsNumeric() {
			return ERROR()
		}
		diff := BinaryMinus(hi, lo)
		prod := BinaryTimes(MlrvalFromFloat(frac), diff)
		return BinaryPlus(lo, prod)
	}
	return s[n-1]
}

func percentileFunc(c, p, opts *Mlrval) *Mlrval {
	interp, _, ais := percentileOptions(opts)
	s, ok := sortedForPercentiles(c, ais)
	if !ok {
		return ERROR()
	}
	if !p.IsNumeric() {
		return ERROR()
	}
	return percentileOfSorted(s, p.GetNumericToFloat(), interp)
}

func percentilesFunc(c, ps, opts *Mlrval) *Mlrval {
	interp, oa, ais := percentileOptions(opts)
	s, ok := sortedForPercentiles(c, ais)
	if !ok {
		return ERROR()
	}
	var plist []*Mlrval
	if ps.mtype == MT_ARRAY {
		plist = ps.arrayval
	} else if ps.mtype == MT_MAP {
		plist = ps.mapval.vals
	} else {
		plist = []*Mlrval{ps}
	}
	if oa {
		out := make([]*Mlrval, 0, len(plist))
		for _, p := range plist {
			if !p.IsNumeric() {
				out = append(out, ERROR())
				continue
			}
			out = append(out, percentileOfSorted(s, p.GetNumericToFloat(), interp))
		}
		return MlrvalFromArray(out)
	}
	m := NewMlrmap()
	for _, p := range plist {
		if !p.IsNumeric() {
			m.Put(p.String(), ERROR())
			continue
		}
		m.Put(p.String(), percentileOfSorted(s, p.GetNumericToFloat(), interp))
	}
	return MlrvalFromMap(m)
}

// ---------------------------------------------------------------- sort function

func naturalLess(a, b string) bool {
	// natural sort: digits compared numerically
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		ca, cb := a[i], b[j]
		if isDecDigit(ca) && isDecDigit(cb) {
			si := i
			for i < len(a) && isDecDigit(a[i]) {
				i++
			}
			sj := j
			for j < len(b) && isDecDigit(b[j]) {
				j++
			}
			na := strings.TrimLeft(a[si:i], "0")
			nb := strings.TrimLeft(b[sj:j], "0")
			if len(na) != len(nb) {
				return len(na) < len(nb)
			}
			if na != nb {
				return na < nb
			}
			continue
		}
		if ca != cb {
			return ca < cb
		}
		i++
		j++
	}
	return len(a)-i < len(b)-j
}

func sortFunc(st *State, args []*Mlrval) *Mlrval {
	c := args[0]
	if c.mtype != MT_MAP && c.mtype != MT_ARRAY {
		return c
	}
	if len(args) == 2 && args[1].mtype == MT_FUNC {
		f := args[1]
		if c.mtype == MT_ARRAY {
			a := make([]*Mlrval, len(c.arrayval))
			copy(a, c.arrayval)
			sort.SliceStable(a, func(i, j int) bool {
				r := callFuncValue(st, f, []*Mlrval{a[i], a[j]})
				return r.GetNumericToFloat() < 0
			})
			return MlrvalFromArray(a).Copy()
		}
		m := c.mapval
		idx := make([]int, m.Len())
		for i := range idx {
			idx[i] = i
		}
		sort.SliceStable(idx, func(i, j int) bool {
			r := callFuncValue(st, f, []*Mlrval{MlrvalFromString(m.keys[idx[i]]), m.vals[idx[i]], MlrvalFromString(m.keys[idx[j]]), m.vals[idx[j]]})
			return r.GetNumericToFloat() < 0
		})
		out := NewMlrmap()
		for _, i := range idx {
			out.Put(m.keys[i], m.vals[i].Copy())
		}
		return MlrvalFromMap(out)
	}
	flags := ""
	if len(args) == 2 {
		flags = args[1].String()
	}
	reverse := strings.Contains(flags, "r")
	byValue := strings.Contains(flags, "v")
	mode := "n"
	for _, ch := range flags {
		switch ch {
		case 'f':
			mode = "f"
		case 'c':
			mode = "c"
		case 't':
			mode = "t"
		case 'n':
			mode = "n"
		}
	}
	less := func(a, b *Mlrval) bool {
		switch mode {
		case "f":
			return a.String() < b.String()
		case "c":
			return strings.ToLower(a.String()) < strings.ToLower(b.String())
		case "t":
			return naturalLess(a.String(), b.String())
		}
		return collateCompare(a, b) < 0
	}
	if c.mtype == MT_ARRAY {
		a := make([]*Mlrval, len(c.arrayval))
		copy(a, c.arrayval)
		sort.SliceStable(a, func(i, j int) bool {
			if reverse {
				return less(a[j], a[i])
			}
			return less(a[i], a[j])
		})
		return MlrvalFromArray(a).Copy()
	}
	m := c.mapval
	idx := make([]int, m.Len())
	for i := range idx {
		idx[i] = i
	}
	keyOf := func(i int) *Mlrval {
		if byValue {
			return m.vals[i]
		}
		return MlrvalFromInferred(m.keys[i])
	}
	sort.SliceStable(idx, func(i, j int) bool {
		if reverse {
			return less(keyOf(idx[j]), keyOf(idx[i]))
		}
		return less(keyOf(idx[i]), keyOf(idx[j]))
	})
	out := NewMlrmap()
	for _, i := range idx {
		out.Put(m.keys[i], m.vals[i].Copy())
	}
	return MlrvalFromMap(out)
}
