// seconds (float or int) to time
func timeFromSeconds(mv *Mlrval) (time.Time, bool) {
	switch mv.Type() {
	case MT_INT:
		return time.Unix(mv.intval, 0), true
	case MT_FLOAT:
		f := mv.floatval
		if math.IsNaN(f) || math.IsInf(f, 0) {
			return time.Time{}, false
		}
		sec := math.Floor(f)
		frac := f - sec
		return time.Unix(int64(sec), int64(math.Round(frac*1e9))), true
	}
	return time.Time{}, false
}

func timeFromNanos(mv *Mlrval) (time.Time, bool) {
	switch mv.Type() {
	case MT_INT:
		return time.Unix(0, mv.intval), true
	case MT_FLOAT:
		return time.Unix(0, int64(mv.floatval)), true
	}
	return time.Time{}, false
}

var weekdayNames = []string{"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"}
var monthNames = []string{"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"}

// strftime implementation. Returns ok=false on unsupported specifier.
func strftimeGo(t time.Time, f string) (string, bool) {
	var b strings.Builder
	for i := 0; i < len(f); i++ {
		c := f[i]
		if c != '%' {
			b.WriteByte(c)
			continue
		}
		if i+1 >= len(f) {
			b.WriteByte('%')
			break
		}
		i++
		c = f[i]
		if c >= '1' && c <= '9' {
			n := int(c - '0')
			if i+1 < len(f) && f[i+1] == 'S' {
				i++
			}
			frac := t.Nanosecond()
			fs := fmt.Sprintf("%09d", frac)[:n]
			fmt.Fprintf(&b, "%02d.%s", t.Second(), fs)
			continue
		}
		switch c {
		case 'A':
			b.WriteString(weekdayNames[t.Weekday()])
		case 'a':
			b.WriteString(weekdayNames[t.Weekday()][:3])
		case 'B':
			b.WriteString(monthNames[t.Month()-1])
		case 'b', 'h':
			b.WriteString(monthNames[t.Month()-1][:3])
		case 'C':
			fmt.Fprintf(&b, "%02d", t.Year()/100)
		case 'c':
			fmt.Fprintf(&b, "%s %s %2d %02d:%02d:%02d %d", weekdayNames[t.Weekday()][:3], monthNames[t.Month()-1][:3], t.Day(), t.Hour(), t.Minute(), t.Second(), t.Year())
		case 'D':
			fmt.Fprintf(&b, "%02d/%02d/%02d", int(t.Month()), t.Day(), t.Year()%100)
		case 'd':
			fmt.Fprintf(&b, "%02d", t.Day())
		case 'e':
			fmt.Fprintf(&b, "%2d", t.Day())
		case 'F':
			fmt.Fprintf(&b, "%04d-%02d-%02d", t.Year(), int(t.Month()), t.Day())
		case 'G':
			y, _ := t.ISOWeek()
			fmt.Fprintf(&b, "%d", y)
		case 'g':
			y, _ := t.ISOWeek()
			fmt.Fprintf(&b, "%02d", y%100)
		case 'H':
			fmt.Fprintf(&b, "%02d", t.Hour())
		case 'I':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			fmt.Fprintf(&b, "%02d", h)
		case 'j':
			fmt.Fprintf(&b, "%03d", t.YearDay())
		case 'k':
			fmt.Fprintf(&b, "%2d", t.Hour())
		case 'l':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			fmt.Fprintf(&b, "%2d", h)
		case 'M':
			fmt.Fprintf(&b, "%02d", t.Minute())
		case 'm':
			fmt.Fprintf(&b, "%02d", int(t.Month()))
		case 'n':
			b.WriteByte('\n')
		case 'N':
			fmt.Fprintf(&b, "%09d", t.Nanosecond())
		case 'p':
			if t.Hour() < 12 {
				b.WriteString("AM")
			} else {
				b.WriteString("PM")
			}
		case 'R':
			fmt.Fprintf(&b, "%02d:%02d", t.Hour(), t.Minute())
		case 'r':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			ampm := "AM"
			if t.Hour() >= 12 {
				ampm = "PM"
			}
			fmt.Fprintf(&b, "%02d:%02d:%02d %s", h, t.Minute(), t.Second(), ampm)
		case 'S':
			fmt.Fprintf(&b, "%02d", t.Second())
		case 's':
			fmt.Fprintf(&b, "%d", t.Unix())
		case 'T':
			fmt.Fprintf(&b, "%02d:%02d:%02d", t.Hour(), t.Minute(), t.Second())
		case 't':
			b.WriteByte('\t')
		case 'U':
			wd := int(t.Weekday())
			fmt.Fprintf(&b, "%02d", (t.YearDay()+6-wd)/7)
		case 'u':
			wd := int(t.Weekday())
			if wd == 0 {
				wd = 7
			}
			fmt.Fprintf(&b, "%d", wd)
		case 'V':
			_, w := t.ISOWeek()
			fmt.Fprintf(&b, "%02d", w)
		case 'v':
			fmt.Fprintf(&b, "%2d-%s-%04d", t.Day(), monthNames[t.Month()-1][:3], t.Year())
		case 'W':
			wd := (int(t.Weekday()) + 6) % 7
			fmt.Fprintf(&b, "%02d", (t.YearDay()+6-wd)/7)
		case 'w':
			fmt.Fprintf(&b, "%d", int(t.Weekday()))
		case 'X':
			fmt.Fprintf(&b, "%02d:%02d:%02d", t.Hour(), t.Minute(), t.Second())
		case 'x':
			fmt.Fprintf(&b, "%02d/%02d/%02d", int(t.Month()), t.Day(), t.Year()%100)
		case 'Y':
			fmt.Fprintf(&b, "%04d", t.Year())
		case 'y':
			fmt.Fprintf(&b, "%02d", t.Year()%100)
		case 'Z':
			name, _ := t.Zone()
			b.WriteString(name)
		case 'z':
			_, off := t.Zone()
			sign := '+'
			if off < 0 {
				sign = '-'
				off = -off
			}
			fmt.Fprintf(&b, "%c%02d%02d", sign, off/3600, (off%3600)/60)
		case '%':
			b.WriteByte('%')
		default:
			return "", false
		}
	}
	return b.String(), true
}

