				return time.Time{}, false, false
			}
			if pos >= len(s) || s[pos] != c {
				return time.Time{}, false, false
			}
			pos++
			continue
		}
		i++
		if i >= len(f) {
			return time.Time{}, false, false
		}
		c = f[i]
		var ok bool
		switch c {
		case 'Y':
			year, ok = readInt(4, true)
		case 'y':
			var y int
			y, ok = readInt(2, false)
			if y < 69 {
				year = 2000 + y
			} else {
				year = 1900 + y
			}
		case 'm':
			month, ok = readInt(2, false)
		case 'd', 'e':
			for pos < len(s) && s[pos] == ' ' {
				pos++
			}
			day, ok = readInt(2, false)
		case 'H', 'k':
			for pos < len(s) && s[pos] == ' ' {
				pos++
			}
			hour, ok = readInt(2, false)
		case 'I', 'l':
			for pos < len(s) && s[pos] == ' ' {
				pos++
			}
			hour, ok = readInt(2, false)
		case 'M':
			min, ok = readInt(2, false)
		case 'S':
			sec, ok = readInt(2, false)
			if ok && pos < len(s) && s[pos] == '.' && i+1 < len(f) {
				// fractional seconds allowed if followed by non-digit format literal
				p0 := pos
				pos++
				ds := pos
				for pos < len(s) && isDecDigit(s[pos]) {
					pos++
				}
				if pos > ds {
					fs := s[ds:pos]
					for len(fs) < 9 {
						fs += "0"
					}
					nanos, _ = strconv.Atoi(fs[:9])
					hasFrac = true
				} else {
					pos = p0
				}
			}
		case 'j':
			yday, ok = readInt(3, false)
		case 'b', 'h':
			var m int
			m, ok = matchName(monthNames, true)
			month = m + 1
		case 'B':
			var m int
			m, ok = matchName(monthNames, false)
			if !ok {
				m, ok = matchName(monthNames, true)
			}
			month = m + 1
		case 'a':
			_, ok = matchName(weekdayNames, true)
		case 'A':
			_, ok = matchName(weekdayNames, false)
			if !ok {
				_, ok = matchName(weekdayNames, true)
			}
		case 'p':
			if pos+2 <= len(s) {
				ap := strings.ToUpper(s[pos : pos+2])
				if ap == "AM" {
					pm = 0
					ok = true
					pos += 2
				} else if ap == "PM" {
					pm = 1
					ok = true
					pos += 2
				}
			}
		case 'z':
			if pos < len(s) && (s[pos] == 'Z' || s[pos] == 'z') {
				pos++
				ok = true
				haveTZ = true
				tzOffset = 0
				break
			}
			if pos < len(s) && (s[pos] == '+' || s[pos] == '-') {
				neg := s[pos] == '-'
				pos++
				ds := pos
				for pos < len(s) && (isDecDigit(s[pos]) || s[pos] == ':') {
					pos++
				}
				digits := strings.ReplaceAll(s[ds:pos], ":", "")
				if len(digits) == 4 {
					h, _ := strconv.Atoi(digits[:2])
					m, _ := strconv.Atoi(digits[2:])
					tzOffset = h*3600 + m*60
					if neg {
						tzOffset = -tzOffset
					}
					ok = true
					haveTZ = true
				} else if len(digits) == 2 {
					h, _ := strconv.Atoi(digits)
					tzOffset = h * 3600
					if neg {
						tzOffset = -tzOffset
					}
					ok = true
					haveTZ = true
				}
			}
		case 'Z':
			start := pos
			for pos < len(s) && ((s[pos] >= 'A' && s[pos] <= 'Z') || (s[pos] >= 'a' && s[pos] <= 'z')) {
				pos++
			}
			ok = pos > start
			if ok && s[start:pos] == "UTC" || ok && s[start:pos] == "GMT" || ok && s[start:pos] == "Z" {
				haveTZ = true
				tzOffset = 0
			}
		case 's':
			start := pos
			if pos < len(s) && s[pos] == '-' {
				pos++
			}
			for pos < len(s) && isDecDigit(s[pos]) {
				pos++
			}
			if pos > start {
				epoch, _ = strconv.ParseInt(s[start:pos], 10, 64)
				ok = true
				haveEpoch = true
			}
		case 'T':
			hour, ok = readInt(2, false)
			if ok && pos < len(s) && s[pos] == ':' {
				pos++
				min, ok = readInt(2, false)
				if ok && pos < len(s) && s[pos] == ':' {
					pos++
					sec, ok = readInt(2, false)
				} else {
					ok = false
				}
			} else {
				ok = false
			}
		case 'F':
			year, ok = readInt(4, true)
			if ok && pos < len(s) && s[pos] == '-' {
				pos++
				month, ok = readInt(2, false)
				if ok && pos < len(s) && s[pos] == '-' {
					pos++
					day, ok = readInt(2, false)
				} else {
					ok = false
				}
			} else {
				ok = false
			}
		case 'D':
			month, ok = readInt(2, false)
			if ok && pos < len(s) && s[pos] == '/' {
				pos++
				day, ok = readInt(2, false)
				if ok && pos < len(s) && s[pos] == '/' {
					pos++
					var y int
					y, ok = readInt(2, false)
					if y < 69 {
						year = 2000 + y
					} else {
						year = 1900 + y
					}
				} else {
					ok = false
				}
			} else {
				ok = false
			}
		case '%':
			ok = pos < len(s) && s[pos] == '%'
			pos++
		case 'n', 't':
			for pos < len(s) && (s[pos] == ' ' || s[pos] == '\t' || s[pos] == '\n') {
				pos++
			}
			ok = true
		default:
			return time.Time{}, false, false
		}
		if !ok {
			return time.Time{}, false, false
		}
	}
	if pos != len(s) {
		return time.Time{}, false, false
	}
	if haveEpoch {
		return time.Unix(epoch, 0), true, false
	}
	if pm == 1 && hour < 12 {
		hour += 12
	} else if pm == 0 && hour == 12 {
		hour = 0
	}
	var t time.Time
	if haveTZ {
		t = time.Date(year, time.Month(month), day, hour, min, sec, nanos, time.UTC).Add(-time.Duration(tzOffset) * time.Second)
	} else {
		t = time.Date(year, time.Month(month), day, hour, min, sec, nanos, loc)
	}
	if yday > 0 {
		t = time.Date(year, 1, 1, hour, min, sec, nanos, loc).AddDate(0, 0, yday-1)
	}
	return t, true, hasFrac
}

func formatGMT(t time.Time, ndec int, layoutDate bool) string {
	t = t.UTC()
	if layoutDate {
		return fmt.Sprintf("%04d-%02d-%02d", t.Year(), int(t.Month()), t.Day())
	}
	s := fmt.Sprintf("%04d-%02d-%02dT%02d:%02d:%02d", t.Year(), int(t.Month()), t.Day(), t.Hour(), t.Minute(), t.Second())
	if ndec > 0 {
		fs := fmt.Sprintf("%09d", t.Nanosecond())[:ndec]
		s += "." + fs
	}
	return s + "Z"
}

func formatLocal(t time.Time, ndec int, loc *time.Location, dateOnly bool) string {
	t = t.In(loc)
	if dateOnly {
		return fmt.Sprintf("%04d-%02d-%02d", t.Year(), int(t.Month()), t.Day())
	}
	s := fmt.Sprintf("%04d-%02d-%02d %02d:%02d:%02d", t.Year(), int(t.Month()), t.Day(), t.Hour(), t.Minute(), t.Second())
	if ndec > 0 {
		fs := fmt.Sprintf("%09d", t.Nanosecond())[:ndec]
		s += "." + fs
	}
	return s
}

func sec2gmtFunc(v *Mlrval, ndec int) *Mlrval {
	t, ok := timeFromSeconds(v)
	if !ok {
		return v
	}
	return MlrvalFromString(formatGMT(t, ndec, false))
}

func parseGMTString(s string) (time.Time, bool) {
	layouts := []string{
		"2006-01-02T15:04:05Z",
		"2006-01-02T15:04:05.999999999Z",
	}
	for _, l := range layouts {
		t, err := time.Parse(l, s)
		if err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

func parseLocalString(s string, loc *time.Location) (time.Time, bool) {
	layouts := []string{
		"2006-01-02 15:04:05",
		"2006-01-02 15:04:05.999999999",
		"2006-01-02T15:04:05Z",
	}
	for _, l := range layouts {
		t, err := time.ParseInLocation(l, s, loc)
		if err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

func intOrDefault(args []*Mlrval, i int, d int) int {
	if i < len(args) {
		if v, ok := intArg(args[i]); ok {
			return int(v)
		}
	}
	return d
}

