		h, e1 := strconv.ParseInt(parts[0], 10, 64)
		m, e2 := strconv.ParseInt(parts[1], 10, 64)
		sec, e3 := strconv.ParseInt(parts[2], 10, 64)
		if e1 != nil || e2 != nil || e3 != nil {
			return ERROR()
		}
		r := h*3600 + m*60 + sec
		if neg {
			r = -r
