func parseDHMS(s string) (float64, bool) {
	if s == "" {
		return 0, false
	}
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	total := 0.0
	num := ""
	seen := false
	for _, c := range s {
		if (c >= '0' && c <= '9') || c == '.' {
			num += string(c)
			continue
		}
		if num == "" {
			return 0, false
		}
		v, err := strconv.ParseFloat(num, 64)
		if err != nil {
			return 0, false
		}
		switch c {
		case 'd':
			total += v * 86400
		case 'h':
			total += v * 3600
		case 'm':
			total += v * 60
		case 's':
			total += v
		default:
			return 0, false
		}
		num = ""
		seen = true
	}
	if num != "" || !seen {
		return 0, false
	}
	if neg {
		total = -total
	}
	return total, true
}
