		})
		registerVerb("gsub", func(args []string, i int, opts *Options) (Transformer, int) {
			return parseSubVerb(args, i, "gsub")
		})
		registerVerb("ssub", func(args []string, i int, opts *Options) (Transformer, int) {
			return parseSubVerb(args, i, "ssub")
		})
		registerVerb("clean-whitespace", parseCleanWhitespace)
		registerVerb("check", parseCheck)
	})
}

// ---------------------------------------------------------------- sort
type sortKey struct {
	field string
	kind  string // "f", "r", "c", "cr", "nf", "nr", "t", "tr"
}

type SortT struct {
	keys      []sortKey
	recs      []recctx
	missing   []recctx
	moveFirst bool
}

func parseSort(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("sort", args, i)
	t := &SortT{}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		kind := ""
		switch f {
		case "-f":
			kind = "f"
		case "-r":
			kind = "r"
		case "-c":
			kind = "c"
		case "-cr":
			kind = "cr"
		case "-nf", "-n":
			kind = "nf"
		case "-nr":
			kind = "nr"
		case "-t":
			kind = "t"
		case "-tr", "-rt":
			kind = "tr"
		case "-b":
			t.moveFirst = true
			continue
		default:
			fmt.Fprintf(os.Stderr, "mlr: mlr sort: option \"%s\" not recognized\n", f)
			os.Exit(1)
		}
		for _, fld := range va.list(f) {
			t.keys = append(t.keys, sortKey{fld, kind})
		}
	}
	if len(t.keys) == 0 {
		fmt.Fprintf(os.Stderr, "mlr: mlr sort: -f sort fields required\n")
		os.Exit(1)
	}
	return t, va.i
}

func (t *SortT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	for _, k := range t.keys {
		if !rec.Has(k.field) {
			t.missing = append(t.missing, recctx{rec, *ctx})
			return
		}
	}
	t.recs = append(t.recs, recctx{rec, *ctx})
}

func sortCompareValues(kind string, a, b *Mlrval) int {
	switch kind {
	case "f":
		return strings.Compare(a.String(), b.String())
	case "r":
		return strings.Compare(b.String(), a.String())
	case "c":
		return strings.Compare(strings.ToLower(a.String()), strings.ToLower(b.String()))
	case "cr":
		return strings.Compare(strings.ToLower(b.String()), strings.ToLower(a.String()))
	case "nf":
		return collateCompare(a, b)
	case "nr":
		return collateCompare(b, a)
	case "t":
		as, bs := a.String(), b.String()
		if naturalLess(as, bs) {
			return -1
		} else if naturalLess(bs, as) {
			return 1
		}
		return 0
	case "tr":
		as, bs := a.String(), b.String()
		if naturalLess(bs, as) {
			return -1
		} else if naturalLess(as, bs) {
			return 1
		}
		return 0
	}
	return 0
}

func (t *SortT) End(ctx *Context, next *ChainLink) {
	sort.SliceStable(t.recs, func(i, j int) bool {
		ri, rj := t.recs[i].rec, t.recs[j].rec
		for _, k := range t.keys {
			c := sortCompareValues(k.kind, ri.Get(k.field), rj.Get(k.field))
			if c != 0 {
				return c < 0
			}
		}
		return false
	})
	for _, rc := range t.recs {
		c := rc.ctx
		if t.moveFirst {
			for j := len(t.keys) - 1; j >= 0; j-- {
				v := rc.rec.Get(t.keys[j].field)
				rc.rec.PutAtStartMoving(t.keys[j].field, v)
			}
		}
		next.Put(rc.rec, &c)
	}
	for _, rc := range t.missing {
		c := rc.ctx
		next.Put(rc.rec, &c)
	}
}

// ---------------------------------------------------------------- uniq / count-distinct
type UniqT struct {
	groupBy    []string
	exclude    map[string]bool
	showCounts bool
	showNum    bool
	allFields  bool
	outName    string
	unlashed   bool
	counts     *lhmsi // key -> *uniqEntry
	isCountDistinct bool
	unlashedCounts []*lhmsi
}

type uniqEntry struct {
	rec   *Mlrmap
	count int64
	ctx   Context
}

func parseUniq(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("uniq", args, i)
	t := &UniqT{outName: "count", counts: newLhm()}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-g", "-f":
			t.groupBy = va.list(f)
		case "-x":
			t.exclude = stringSet(va.list(f))
		case "-c":
			t.showCounts = true
		case "-n":
			t.showNum = true
		case "-o":
			t.outName = va.str(f)
		case "-a":
			t.allFields = true
		default:
			fmt.Fprintf(os.Stderr, "mlr: mlr uniq: option \"%s\" not recognized\n", f)
			os.Exit(1)
		}
	}
	if t.groupBy == nil && t.exclude == nil && !t.allFields {
		fmt.Fprintf(os.Stderr, "mlr uniq: one of -g, -x, or -a is required.\n")
		os.Exit(1)
	}
	return t, va.i
}

func parseCountDistinct(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("count-distinct", args, i)
	t := &UniqT{outName: "count", counts: newLhm(), showCounts: true, isCountDistinct: true}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.groupBy = va.list(f)
		case "-x":
			t.exclude = stringSet(va.list(f))
		case "-n":
			t.showNum = true
		case "-u":
			t.unlashed = true
		case "-o":
			t.outName = va.str(f)
		default:
			fmt.Fprintf(os.Stderr, "mlr: mlr count-distinct: option \"%s\" not recognized\n", f)
			os.Exit(1)
		}
	}
	if t.groupBy == nil && t.exclude == nil {
		fmt.Fprintf(os.Stderr, "mlr count-distinct: option -f is required.\n")
		os.Exit(1)
	}
	if t.unlashed {
		for range t.groupBy {
			t.unlashedCounts = append(t.unlashedCounts, newLhm())
		}
	}
	return t, va.i
}

func (t *UniqT) selected(rec *Mlrmap) (*Mlrmap, bool) {
	out := NewMlrmap()
	if t.allFields {
		return rec, true
	}
	if t.exclude != nil {
		for i, k := range rec.keys {
			if !t.exclude[k] {
				out.PutNew(k, rec.vals[i])
			}
		}
		return out, true
	}
	for _, f := range t.groupBy {
		v := rec.Get(f)
		if v == nil {
			return nil, false
		}
		out.PutNew(f, v)
	}
	return out, true
}

func (t *UniqT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if t.unlashed {
		for j, f := range t.groupBy {
			v := rec.Get(f)
			if v == nil {
				continue
			}
			s := v.String()
			e, ok := t.unlashedCounts[j].get(s)
			if ok {
				e.(*uniqEntry).count++
			} else {
				t.unlashedCounts[j].put(s, &uniqEntry{rec: nil, count: 1})
			}
		}
		return
	}
	sel, ok := t.selected(rec)
	if !ok {
		return
	}
	var key string
	if t.allFields || t.exclude != nil {
		var b strings.Builder
		for i, k := range sel.keys {
			b.WriteString(k)
			b.WriteString("\x1f")
			b.WriteString(sel.vals[i].String())
			b.WriteString("\x1e")
		}
		key = b.String()
	} else {
		var b strings.Builder
		for _, v := range sel.vals {
			b.WriteString(v.String())
			b.WriteString("\x1f")
		}
		key = b.String()
	}
	e, ok := t.counts.get(key)
	if ok {
		e.(*uniqEntry).count++
		return
	}
	t.counts.put(key, &uniqEntry{rec: sel, count: 1, ctx: *ctx})
	if !t.showCounts && !t.showNum && !t.isCountDistinct {
		// streaming output of distinct records
		next.Put(sel.Copy(), ctx)
	}
}

func (t *UniqT) End(ctx *Context, next *ChainLink) {
	if t.unlashed {
		for j, f := range t.groupBy {
			for _, k := range t.unlashedCounts[j].keys {
				e, _ := t.unlashedCounts[j].get(k)
				out := NewMlrmap()
				out.PutNew("field", MlrvalFromString(f))
				out.PutNew("value", MlrvalFromInferred(k))
				out.PutNew("count", MlrvalFromInt(e.(*uniqEntry).count))
				next.Put(out, ctx)
			}
		}
		return
	}
	if t.showNum {
		out := NewMlrmap()
		out.PutNew(t.outName, MlrvalFromInt(int64(len(t.counts.keys))))
		if !t.isCountDistinct {
			out = NewMlrmap()
			out.PutNew("count", MlrvalFromInt(int64(len(t.counts.keys))))
		}
		next.Put(out, ctx)
		return
	}
	if !t.showCounts && !t.isCountDistinct {
		return
	}
	for _, k := range t.counts.keys {
		e, _ := t.counts.get(k)
		ue := e.(*uniqEntry)
		if t.allFields {
			out := NewMlrmap()
			out.PutNew(t.outName, MlrvalFromInt(ue.count))
			for i, kk := range ue.rec.keys {
				out.PutNew(kk, ue.rec.vals[i])
			}
			c := ue.ctx
			next.Put(out, &c)
			continue
		}
		out := ue.rec.Copy()
		out.Put(t.outName, MlrvalFromInt(ue.count))
		next.Put(out, ctx)
	}
}

// ---------------------------------------------------------------- count
type CountT struct {
	groupBy  []string
	showNum  bool
	outName  string
	count    int64
	groups   *lhmsi
}

func parseCount(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("count", args, i)
	t := &CountT{outName: "count", groups: newLhm()}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-g":
			t.groupBy = va.list(f)
		case "-n":
			t.showNum = true
		case "-o":
			t.outName = va.str(f)
		default:
			fmt.Fprintf(os.Stderr, "mlr: mlr count: option \"%s\" not recognized\n", f)
			os.Exit(1)
		}
	}
	return t, va.i
}

func (t *CountT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if t.groupBy == nil {
		t.count++
		return
	}
	key, ok := groupingKey(rec, t.groupBy)
	if !ok {
		return
	}
	e, ok := t.groups.get(key)
	if ok {
		e.(*uniqEntry).count++
		return
	}
	sel := NewMlrmap()
	for _, f := range t.groupBy {
		sel.PutNew(f, rec.Get(f))
	}
	t.groups.put(key, &uniqEntry{rec: sel, count: 1})
}

func (t *CountT) End(ctx *Context, next *ChainLink) {
	if t.groupBy == nil {
		out := NewMlrmap()
		out.PutNew(t.outName, MlrvalFromInt(t.count))
		next.Put(out, ctx)
		return
	}
	if t.showNum {
		out := NewMlrmap()
		out.PutNew(t.outName, MlrvalFromInt(int64(len(t.groups.keys))))
		next.Put(out, ctx)
		return
	}
	for _, k := range t.groups.keys {
		e, _ := t.groups.get(k)
		ue := e.(*uniqEntry)
		out := ue.rec.Copy()
		out.Put(t.outName, MlrvalFromInt(ue.count))
		next.Put(out, ctx)
	}
}

// ---------------------------------------------------------------- count-similar
type CountSimilarT struct {
	groupBy []string
	outName string
	groups  *lhmsi
}

func parseCountSimilar(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("count-similar", args, i)
	t := &CountSimilarT{outName: "count", groups: newLhm()}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-g":
			t.groupBy = va.list(f)
		case "-o":
			t.outName = va.str(f)
		default:
			va.unrecognized(f)
		}
	}
	if t.groupBy == nil {
		va.usageError("option -g is required.")
	}
	return t, va.i
}
func (t *CountSimilarT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	key, ok := groupingKey(rec, t.groupBy)
	if !ok {
		return
	}
	v, ok := t.groups.get(key)
	var list []recctx
	if ok {
		list = v.([]recctx)
	}
	t.groups.put(key, append(list, recctx{rec, *ctx}))
}
func (t *CountSimilarT) End(ctx *Context, next *ChainLink) {
	for _, k := range t.groups.keys {
		v, _ := t.groups.get(k)
		list := v.([]recctx)
		n := int64(len(list))
		for _, rc := range list {
			rc.rec.Put(t.outName, MlrvalFromInt(n))
			c := rc.ctx
			next.Put(rc.rec, &c)
		}
	}
}

// ---------------------------------------------------------------- most/least-frequent
type MostFrequentT struct {
	fields     []string
	n          int64
	brief      bool
	outName    string
	descending bool
	counts     *lhmsi
}

func parseMostFrequent(args []string, i int, descending bool) (Transformer, int) {
	name := "most-frequent"
	if !descending {
		name = "least-frequent"
	}
	va := newVargs(name, args, i)
	t := &MostFrequentT{n: 10, outName: "count", descending: descending, counts: newLhm()}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = va.list(f)
		case "-n":
			t.n = va.int(f)
		case "-b":
			t.brief = true
		case "-o":
			t.outName = va.str(f)
		default:
			va.unrecognized(f)
		}
	}
	if t.fields == nil {
		va.usageError("option -f is required.")
	}
	return t, va.i
}
func (t *MostFrequentT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	var vals []*Mlrval
	var b strings.Builder
	for _, f := range t.fields {
		v := rec.Get(f)
		if v == nil {
			return
		}
		vals = append(vals, v)
		b.WriteString(v.String())
		b.WriteString("\x1f")
	}
	key := b.String()
	e, ok := t.counts.get(key)
	if ok {
		e.(*uniqEntry).count++
		return
	}
	sel := NewMlrmap()
	for j, f := range t.fields {
		sel.PutNew(f, vals[j])
	}
	t.counts.put(key, &uniqEntry{rec: sel, count: 1})
}
func (t *MostFrequentT) End(ctx *Context, next *ChainLink) {
	entries := make([]*uniqEntry, 0, len(t.counts.keys))
	for _, k := range t.counts.keys {
		e, _ := t.counts.get(k)
		entries = append(entries, e.(*uniqEntry))
	}
	if t.descending {
		sort.Slice(entries, func(i, j int) bool { return entries[i].count > entries[j].count })
	} else {
		sort.Slice(entries, func(i, j int) bool { return entries[i].count < entries[j].count })
	}
	for j, e := range entries {
		if int64(j) >= t.n {
			break
		}
		out := e.rec.Copy()
		if !t.brief {
			out.Put(t.outName, MlrvalFromInt(e.count))
		}
		next.Put(out, ctx)
	}
}

// ---------------------------------------------------------------- sec2gmt
type Sec2GMTT struct {
	fields  []string
	ndec    int
	divisor int64
	dateOnly bool
}

func parseSec2GMT(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("sec2gmt", args, i)
	t := &Sec2GMTT{divisor: 1}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		if len(f) == 2 && f[1] >= '1' && f[1] <= '9' {
			t.ndec = int(f[1] - '0')
			continue
		}
		switch f {
		case "--millis":
			t.divisor = 1000
		case "--micros":
			t.divisor = 1000000
		case "--nanos":
			t.divisor = 1000000000
		default:
			va.unrecognized(f)
		}
	}
	t.fields = splitFieldNames(va.positional("field names"))
	return t, va.i
}
func (t *Sec2GMTT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	for _, f := range t.fields {
		v := rec.Get(f)
		if v == nil {
			continue
		}
		if !v.IsNumeric() {
			continue
		}
		var sv *Mlrval
		if t.divisor == 1 {
			sv = v
		} else {
			if v.Type() == MT_INT {
				sv = MlrvalFromFloat(float64(v.intval) / float64(t.divisor))
				if v.intval%t.divisor == 0 {
					sv = MlrvalFromInt(v.intval / t.divisor)
				}
			} else {
				sv = MlrvalFromFloat(v.floatval / float64(t.divisor))
			}
		}
		if t.dateOnly {
			tm, ok := timeFromSeconds(sv)
			if ok {
				rec.Put(f, MlrvalFromString(formatGMT(tm, 0, true)))
			}
		} else {
			rec.Put(f, sec2gmtFunc(sv, t.ndec))
		}
	}
	next.Put(rec, ctx)
}
func (t *Sec2GMTT) End(ctx *Context, next *ChainLink) {}

func parseSec2GMTDate(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("sec2gmtdate", args, i)
