		case "--jvstack":
			t.multiline = true
		case "--no-jvstack":
			t.multiline = false
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}
func (t *JSONStringifyT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	for i, k := range rec.keys {
		if t.fields != nil && !t.fields[k] {
			continue
		}
		v := rec.vals[i]
		var b strings.Builder
		if t.multiline {
			jsonEncodeMultiline(&b, v, 0, false)
		} else {
			jsonEncodeSingleLine(&b, v, false)
		}
		rec.vals[i] = MlrvalFromString(b.String())
	}
	next.Put(rec, ctx)
}
func (t *JSONStringifyT) End(ctx *Context, next *ChainLink) {}

