		}
	}
	return t, va.i
}
func (t *FlattenVerbT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	sep := t.sep
	if sep == "" {
		sep = t.opts.W.FlatSep
	}
	flattenRecord(rec, sep, t.fields)
	next.Put(rec, ctx)
}
func (t *FlattenVerbT) End(ctx *Context, next *ChainLink) {}

type UnflattenVerbT struct {
	sep    string
	fields map[string]bool
	opts   *Options
}

func parseUnflatten(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("unflatten", args, i)
	t := &UnflattenVerbT{opts: opts}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = stringSet(va.list(f))
		case "-s":
			t.sep = va.str(f)
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}
func (t *UnflattenVerbT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	sep := t.sep
	if sep == "" {
		sep = t.opts.W.FlatSep
	}
	if t.fields == nil {
		unflattenRecord(rec, sep, nil)
	} else {
		// only unflatten fields whose prefix (before first sep) is in the set
		out := NewMlrmap()
		for i, k := range rec.keys {
			v := rec.vals[i]
			parts := strings.Split(k, sep)
			if len(parts) > 1 && t.fields[parts[0]] {
				cur := out
				for j := 0; j < len(parts)-1; j++ {
					e := cur.Get(parts[j])
					if e == nil || e.mtype != MT_MAP {
						e = MlrvalEmptyMap()
						cur.Put(parts[j], e)
					}
					cur = e.mapval
				}
				cur.Put(parts[len(parts)-1], v)
			} else {
				out.Put(k, v)
			}
		}
		for i, v := range out.vals {
			out.vals[i] = arrayify(v)
		}
		rec.keys = out.keys
		rec.vals = out.vals
	}
	next.Put(rec, ctx)
}
func (t *UnflattenVerbT) End(ctx *Context, next *ChainLink) {}

