			t.keys = false
			t.values = true
		case "-f":
			t.fields = stringSet(va.list(f))
		case "-u":
			t.style = "u"
		case "-l":
			t.style = "l"
		case "-s":
			t.style = "s"
		case "-t":
			t.style = "t"
		default:
			va.unrecognized(f)
		}
	}
	if t.style == "" {
		fmt.Fprintf(os.Stderr, "mlr case: exactly one of -u, -l, -s, -t is required.\n")
		os.Exit(1)
	}
	return t, va.i
}

func caseString(s, style string) string {
	switch style {
	case "u":
		return strings.ToUpper(s)
	case "l":
		return strings.ToLower(s)
	case "s":
		r := []rune(strings.ToLower(s))
		if len(r) > 0 {
			r[0] = unicode.ToUpper(r[0])
		}
		return string(r)
	case "t":
		words := strings.Split(s, " ")
		for i, w := range words {
			r := []rune(strings.ToLower(w))
			if len(r) > 0 {
				r[0] = unicode.ToUpper(r[0])
			}
			words[i] = string(r)
		}
		return strings.Join(words, " ")
	}
	return s
}

func (t *CaseT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	out := NewMlrmap()
	for i, k := range rec.keys {
		v := rec.vals[i]
		if t.fields == nil || t.fields[k] {
			nk := k
			if t.keys {
				nk = caseString(k, t.style)
			}
			if t.values && v.Type() == MT_STRING {
				v = MlrvalFromString(caseString(v.printrep, t.style))
			}
			out.Put(nk, v)
		} else {
			out.Put(k, v)
		}
	}
	next.Put(out, ctx)
}
func (t *CaseT) End(ctx *Context, next *ChainLink) {}

// ---------------------------------------------------------------- format-values
type FormatValuesT struct {
	ifmt, ffmt, sfmt string
	coerce           bool
}

func parseFormatValues(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("format-values", args, i)
	t := &FormatValuesT{ifmt: "%d", ffmt: "%f", sfmt: "%s"}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-i":
			t.ifmt = va.str(f)
		case "-f":
			t.ffmt = va.str(f)
		case "-s":
			t.sfmt = va.str(f)
		case "-n":
			t.coerce = true
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}
func (t *FormatValuesT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	for i, v := range rec.vals {
		switch v.Type() {
		case MT_INT:
			if t.coerce {
				rec.vals[i] = GetFormatter(t.ffmt).Format(MlrvalFromFloat(float64(v.intval)))
			} else {
				rec.vals[i] = GetFormatter(t.ifmt).Format(v)
			}
		case MT_FLOAT:
			rec.vals[i] = GetFormatter(t.ffmt).Format(v)
		case MT_BOOLEAN, MT_STRING, MT_VOID:
			rec.vals[i] = MlrvalFromString(fmt.Sprintf(strings.ReplaceAll(t.sfmt, "%l", "%"), v.String()))
		}
	}
	next.Put(rec, ctx)
}
func (t *FormatValuesT) End(ctx *Context, next *ChainLink) {}

// ---------------------------------------------------------------- string mappers
type StringMapperT struct {
	f func(string) string
}

func parseStringMapper(args []string, i int, name string, f func(string) string) (Transformer, int) {
	va := newVargs(name, args, i)
	for va.hasFlag() {
		fl := va.next()
		va.checkHelp(fl)
		va.unrecognized(fl)
	}
	return &StringMapperT{f: f}, va.i
}
func (t *StringMapperT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	out := NewMlrmap()
	for i, k := range rec.keys {
		v := rec.vals[i]
		if v.Type() == MT_STRING {
			v = MlrvalFromString(t.f(v.printrep))
		}
		out.Put(t.f(k), v)
	}
	next.Put(out, ctx)
}
func (t *StringMapperT) End(ctx *Context, next *ChainLink) {}

// ---------------------------------------------------------------- sub/gsub/ssub verbs
type SubVerbT struct {
	kind    string
	fields  map[string]bool
	regexes []*regexp.Regexp
	all     bool
	old     string
	new     string
	re      *regexp.Regexp
}

func parseSubVerb(args []string, i int, kind string) (Transformer, int) {
	va := newVargs(kind, args, i)
	t := &SubVerbT{kind: kind}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = stringSet(va.list(f))
		case "-r":
			t.regexes = append(t.regexes, compileMillerRegex(va.str(f)))
		case "-a":
			t.all = true
		default:
			va.unrecognized(f)
		}
	}
	if t.fields == nil && t.regexes == nil && !t.all {
		fmt.Fprintf(os.Stderr, "mlr %s: one of -f, -r, or -a is required.\n", kind)
		os.Exit(1)
	}
	t.old = va.positional("old string")
	t.new = va.positional("new string")
	if kind != "ssub" {
		t.re = getRegex(t.old)
	}
	return t, va.i
}
func (t *SubVerbT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	for i, k := range rec.keys {
		match := t.all || (t.fields != nil && t.fields[k])
		if !match && t.regexes != nil {
			for _, re := range t.regexes {
				if re.MatchString(k) {
					match = true
					break
				}
			}
		}
		if !match {
			continue
		}
		v := rec.vals[i]
		if v.IsCollection() {
			continue
		}
		s := v.String()
		var r string
		switch t.kind {
		case "sub":
			r = regexSubOnce(t.re, s, t.new)
		case "gsub":
			r = t.re.ReplaceAllString(s, convertBackrefs(t.new))
		case "ssub":
			r = strings.Replace(s, t.old, t.new, 1)
		}
		rec.vals[i] = MlrvalFromInferred(r)
	}
	next.Put(rec, ctx)
}
func (t *SubVerbT) End(ctx *Context, next *ChainLink) {}

// ---------------------------------------------------------------- clean-whitespace
type CleanWhitespaceT struct {
	keys, values bool
}

func parseCleanWhitespace(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("clean-whitespace", args, i)
	t := &CleanWhitespaceT{keys: true, values: true}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-k", "--keys-only":
			t.values = false
		case "-v", "--values-only":
			t.keys = false
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}

func cleanWS(s string) string {
	return strings.Trim(whitespaceRun.ReplaceAllString(s, " "), " \t\n\r")
}

func (t *CleanWhitespaceT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	out := NewMlrmap()
	for i, k := range rec.keys {
		v := rec.vals[i]
		if t.keys {
			k = cleanWS(k)
		}
		if t.values && (v.Type() == MT_STRING) {
			v = MlrvalFromInferred(cleanWS(v.printrep))
		}
		out.Put(k, v)
	}
	next.Put(out, ctx)
}
func (t *CleanWhitespaceT) End(ctx *Context, next *ChainLink) {}

// ---------------------------------------------------------------- check
type CheckT struct{}

func parseCheck(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("check", args, i)
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		va.unrecognized(f)
	}
	return &CheckT{}, va.i
}
func (t *CheckT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	for _, k := range rec.keys {
		if k == "" {
			fmt.Fprintf(os.Stderr, "mlr: record %d has empty key\n", ctx.NR)
		}
	}
}
func (t *CheckT) End(ctx *Context, next *ChainLink) {}
