)

func init() {
	initVerbsList = append(initVerbsList, func() {
		registerVerb("sort", parseSort)
		registerVerb("uniq", parseUniq)
		registerVerb("count-distinct", parseCountDistinct)
		registerVerb("count", parseCount)
		registerVerb("count-similar", parseCountSimilar)
		registerVerb("most-frequent", func(args []string, i int, opts *Options) (Transformer, int) {
