}

func parseJSONParse(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs(jsonDecodeVerb, args, i)
	t := &JSONParseT{}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = stringSet(va.list(f))
		case "-k":
			t.keep = true
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}
func (t *JSONParseT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	for i, k := range rec.keys {
		if t.fields != nil && !t.fields[k] {
			continue
		}
		v := rec.vals[i]
		s := v.String()
		pv, err := jsonDecodeValue(s)
		if err != nil {
			if !t.keep {
				rec.vals[i] = ERROR()
			}
			continue
		}
		rec.vals[i] = pv
	}
	next.Put(rec, ctx)
}
