type UnflattenVerbT struct {
	sep    string
	fields map[string]bool
	opts   *Options
}

func parseUnflatten(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("unflatten", args, i)
	t := &UnflattenVerbT{opts: opts}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = stringSet(va.list(f))
		case "-s":
			t.sep = va.str(f)
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}
func (t *UnflattenVerbT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	sep := t.sep
	if sep == "" {
		sep = t.opts.W.FlatSep
	}
	if t.fields == nil {
		unflattenRecord(rec, sep, nil)
	} else {
		// only unflatten fields whose prefix (before first sep) is in the set
		out := NewMlrmap()
		for i, k := range rec.keys {
			v := rec.vals[i]
			parts := strings.Split(k, sep)
			if len(parts) > 1 && t.fields[parts[0]] {
				cur := out
				for j := 0; j < len(parts)-1; j++ {
					e := cur.Get(parts[j])
					if e == nil || e.mtype != MT_MAP {
						e = MlrvalEmptyMap()
						cur.Put(parts[j], e)
					}
					cur = e.mapval
				}
				cur.Put(parts[len(parts)-1], v)
			} else {
				out.Put(k, v)
			}
		}
		for i, v := range out.vals {
			out.vals[i] = arrayify(v)
		}
		rec.keys = out.keys
		rec.vals = out.vals
	}
	next.Put(rec, ctx)
}
func (t *UnflattenVerbT) End(ctx *Context, next *ChainLink) {}

// ---------------------------------------------------------------- case
type CaseT struct {
	fields map[string]bool
	keys   bool
	values bool
	style  string
}

func parseCase(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("case", args, i)
	t := &CaseT{keys: true, values: true}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-k":
			t.keys = true
			t.values = false
		case "-v":
			t.keys = false
			t.values = true
		case "-f":
			t.fields = stringSet(va.list(f))
		case "-u":
			t.style = "u"
		case "-l":
			t.style = "l"
		case "-s":
			t.style = "s"
		case "-t":
			t.style = "t"
		default:
			va.unrecognized(f)
		}
	}
	if t.style == "" {
		fmt.Fprintf(os.Stderr, "mlr case: exactly one of -u, -l, -s, -t is required.\n")
		os.Exit(1)
	}
	return t, va.i
}

func caseString(s, style string) string {
	switch style {
	case "u":
		return strings.ToUpper(s)
	case "l":
		return strings.ToLower(s)
	case "s":
		r := []rune(strings.ToLower(s))
		if len(r) > 0 {
			r[0] = unicode.ToUpper(r[0])
		}
		return string(r)
	case "t":
		words := strings.Split(s, " ")
		for i, w := range words {
			r := []rune(strings.ToLower(w))
			if len(r) > 0 {
				r[0] = unicode.ToUpper(r[0])
			}
			words[i] = string(r)
		}
		return strings.Join(words, " ")
	}
	return s
}

func (t *CaseT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	out := NewMlrmap()
	for i, k := range rec.keys {
		v := rec.vals[i]
		if t.fields == nil || t.fields[k] {
			nk := k
			if t.keys {
				nk = caseString(k, t.style)
			}
			if t.values && v.Type() == MT_STRING {
				v = MlrvalFromString(caseString(v.printrep, t.style))
			}
			out.Put(nk, v)
		} else {
			out.Put(k, v)
		}
	}
	next.Put(out, ctx)
}
func (t *CaseT) End(ctx *Context, next *ChainLink) {}

