	t := &FormatValuesT{ifmt: "%d", ffmt: "%f", sfmt: "%s"}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-i":
			t.ifmt = va.str(f)
		case "-f":
			t.ffmt = va.str(f)
		case "-s":
			t.sfmt = va.str(f)
		case "-n":
			t.coerce = true
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}
func (t *FormatValuesT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	for i, v := range rec.vals {
		switch v.Type() {
		case MT_INT:
			if t.coerce {
				rec.vals[i] = GetFormatter(t.ffmt).Format(MlrvalFromFloat(float64(v.intval)))
			} else {
				rec.vals[i] = GetFormatter(t.ifmt).Format(v)
			}
		case MT_FLOAT:
			rec.vals[i] = GetFormatter(t.ffmt).Format(v)
		case MT_BOOLEAN, MT_STRING, MT_VOID:
			rec.vals[i] = MlrvalFromString(fmt.Sprintf(strings.ReplaceAll(t.sfmt, "%l", "%"), v.String()))
		}
	}
	next.Put(rec, ctx)
}
