// ---------------------------------------------------------------- sub/gsub/ssub verbs
type SubVerbT struct {
	kind    string
	fields  map[string]bool
	regexes []*regexp.Regexp
	all     bool
	old     string
	new     string
	re      *regexp.Regexp
}

func parseSubVerb(args []string, i int, kind string) (Transformer, int) {
	va := newVargs(kind, args, i)
	t := &SubVerbT{kind: kind}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = stringSet(va.list(f))
		case "-r":
			t.regexes = append(t.regexes, compileMillerRegex(va.str(f)))
		case "-a":
			t.all = true
		default:
			va.unrecognized(f)
		}
	}
	if t.fields == nil && t.regexes == nil && !t.all {
		fmt.Fprintf(os.Stderr, "mlr %s: one of -f, -r, or -a is required.\n", kind)
		os.Exit(1)
	}
	t.old = va.positional("old string")
	t.new = va.positional("new string")
	if kind != "ssub" {
		t.re = getRegex(t.old)
	}
	return t, va.i
}
func (t *SubVerbT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	for i, k := range rec.keys {
		match := t.all || (t.fields != nil && t.fields[k])
		if !match && t.regexes != nil {
			for _, re := range t.regexes {
				if re.MatchString(k) {
					match = true
					break
				}
			}
		}
		if !match {
			continue
		}
		v := rec.vals[i]
		if v.IsCollection() {
			continue
		}
		s := v.String()
		var r string
		switch t.kind {
		case "sub":
			r = regexSubOnce(t.re, s, t.new)
		case "gsub":
			r = t.re.ReplaceAllString(s, convertBackrefs(t.new))
		case "ssub":
			r = strings.Replace(s, t.old, t.new, 1)
		}
		rec.vals[i] = MlrvalFromInferred(r)
	}
	next.Put(rec, ctx)
}
func (t *SubVerbT) End(ctx *Context, next *ChainLink) {}

