}

func (t *CleanWhitespaceT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	out := NewMlrmap()
	for i, k := range rec.keys {
		v := rec.vals[i]
		if t.keys {
			k = cleanWS(k)
		}
		if t.values && (v.Type() == MT_STRING) {
			v = MlrvalFromInferred(cleanWS(v.printrep))
		}
		out.Put(k, v)
	}
	next.Put(out, ctx)
}
func (t *CleanWhitespaceT) End(ctx *Context, next *ChainLink) {}

