type CheckT struct{}

func parseCheck(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("check", args, i)
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		va.unrecognized(f)
	}
	return &CheckT{}, va.i
}
func (t *CheckT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	for _, k := range rec.keys {
		if k == "" {
			fmt.Fprintf(os.Stderr, "mlr: record %d has empty key\n", ctx.NR)
		}
	}
}
func (t *CheckT) End(ctx *Context, next *ChainLink) {}
