cd /workspace/src && cat > verbs_stats.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

func init() {
	initVerbsList = append(initVerbsList, func() {
		registerVerb("stats1", parseStats1)
		registerVerb("merge-fields", parseMergeFields)
		registerVerb("step", parseStep)
		registerVerb("top", parseTop)
	})
}

// ---------------------------------------------------------------- univariate accumulator bag

type statsBag struct {
	accNames  []string
	interp    bool
	count     int64
	nullCount int64
	numCount  int64
	sum       *Mlrval
	sumf      float64
	sumx2     float64
	sumx3     float64
	sumx4     float64
	min       *Mlrval
	max       *Mlrval
	minlen    int64
	maxlen    int64
	haveLen   bool
	counts    map[string]int64
	order     []string
	values    []*Mlrval
	numvals   []float64
	needVals  bool
	needNums  bool
	needMode  bool
}

func newStatsBag(accNames []string, interp bool) *statsBag {
	b := &statsBag{accNames: accNames, interp: interp, sum: MlrvalFromInt(0)}
	for _, a := range accNames {
		switch {
		case a == "mode" || a == "antimode" || a == "distinct_count":
			b.needMode = true
		case a == "median" || isPercentileName(a):
			b.needVals = true
		case a == "mad":
			b.needNums = true
		}
	}
	if b.needMode {
		b.counts = map[string]int64{}
	}
	return b
}

func isPercentileName(a string) bool {
	if len(a) < 2 || a[0] != 'p' {
		return false
	}
	_, err := strconv.ParseFloat(a[1:], 64)
	return err == nil
}

var validStats1Accs = map[string]bool{
	"count": true, "mode": true, "antimode": true, "sum": true, "mean": true, "var": true, "stddev": true,
	"meaneb": true, "skewness": true, "kurtosis": true, "min": true, "max": true, "minlen": true, "maxlen": true,
	"null_count": true, "distinct_count": true, "median": true, "mad": true,
}

func validateAccName(verb, a string) {
	if validStats1Accs[a] || isPercentileName(a) {
		return
	}
	fmt.Fprintf(os.Stderr, "mlr %s: accumulator \"%s\" not found.\n", verb, a)
	os.Exit(1)
}

func (b *statsBag) ingest(v *Mlrval) {
	if v.Type() == MT_VOID {
		b.nullCount++
		return
	}
	if v.IsAbsent() {
		return
	}
	b.count++
	if b.needMode {
		s := v.String()
		if _, ok := b.counts[s]; !ok {
			b.order = append(b.order, s)
		}
		b.counts[s]++
	}
	if b.needVals {
		b.values = append(b.values, v)
	}
	s := v.String()
	l := int64(utf8.RuneCountInString(s))
	if !b.haveLen {
		b.minlen, b.maxlen = l, l
		b.haveLen = true
	} else {
		if l < b.minlen {
			b.minlen = l
		}
		if l > b.maxlen {
			b.maxlen = l
		}
	}
	if b.min == nil {
		b.min = v
		b.max = v
	} else {
		b.min = minMax2(b.min, v, false)
		b.max = minMax2(b.max, v, true)
	}
	if v.IsNumeric() {
		b.numCount++
		b.sum = BinaryPlus(b.sum, v)
		x := v.GetNumericToFloat()
		b.sumf += x
		b.sumx2 += x * x
		b.sumx3 += x * x * x
		b.sumx4 += x * x * x * x
		if b.needNums {
			b.numvals = append(b.numvals, x)
		}
	}
}

func (b *statsBag) emit(acc string) *Mlrval {
	switch acc {
	case "count":
		return MlrvalFromInt(b.count)
	case "null_count":
		return MlrvalFromInt(b.nullCount)
	case "distinct_count":
		return MlrvalFromInt(int64(len(b.order)))
	case "mode", "antimode":
		if len(b.order) == 0 {
			return ERROR()
		}
		best := b.order[0]
		for _, s := range b.order[1:] {
			if acc == "mode" && b.counts[s] > b.counts[best] {
				best = s
			}
			if acc == "antimode" && b.counts[s] < b.counts[best] {
				best = s
			}
		}
		return MlrvalFromString(best)
	case "sum":
		return b.sum
	case "mean":
		if b.numCount == 0 {
			return VOID
		}
		return BinaryDivide(b.sum, MlrvalFromInt(b.numCount))
	case "var", "stddev", "meaneb", "skewness", "kurtosis":
		return varianceFromSums(accVarKind(acc), b.numCount, b.sumf, b.sumx2, b.sumx3, b.sumx4)
	case "min":
		if b.min == nil {
			return VOID
		}
		return b.min
	case "max":
		if b.max == nil {
			return VOID
		}
		return b.max
	case "minlen":
		if !b.haveLen {
			return VOID
		}
		return MlrvalFromInt(b.minlen)
	case "maxlen":
		if !b.haveLen {
			return VOID
		}
		return MlrvalFromInt(b.maxlen)
	case "mad":
		n := len(b.numvals)
		if n == 0 {
			return VOID
		}
		mean := b.sumf / float64(n)
		acc := 0.0
		for _, x := range b.numvals {
			acc += math.Abs(x - mean)
		}
		return MlrvalFromFloat(acc / float64(n))
	}
	if acc == "median" || isPercentileName(acc) {
		p := 50.0
		if acc != "median" {
			p, _ = strconv.ParseFloat(acc[1:], 64)
		}
		s := make([]*Mlrval, len(b.values))
		copy(s, b.values)
		sort.SliceStable(s, func(i, j int) bool { return collateCompare(s[i], s[j]) < 0 })
		if len(s) == 0 {
			return VOID
		}
		return percentileOfSorted(s, p, b.interp)
	}
	return ERROR()
}

func accVarKind(acc string) string {
	if acc == "var" {
		return "var"
	}
	return acc
}

// ---------------------------------------------------------------- stats1
type Stats1T struct {
	accs       []string
	fields     []string
	groupBy    []string
	valueRegex *regexp.Regexp
	valueRegexInvert bool
	groupRegex *regexp.Regexp
	groupRegexInvert bool
	interp     bool
	iterative  bool
	groups     *lhmsi // groupkey -> *stats1Group
}

type stats1Group struct {
	groupVals *Mlrmap
	bags      *lhmsi // field -> *statsBag
}

func parseStats1(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("stats1", args, i)
	t := &Stats1T{groups: newLhm()}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-a":
			t.accs = va.list(f)
		case "-f":
			t.fields = va.list(f)
		case "-g":
			t.groupBy = va.list(f)
		case "--fr":
			t.valueRegex = compileMillerRegex(va.str(f))
		case "--fx":
			t.valueRegex = compileMillerRegex(va.str(f))
			t.valueRegexInvert = true
		case "--gr":
			t.groupRegex = compileMillerRegex(va.str(f))
		case "--gx":
			t.groupRegex = compileMillerRegex(va.str(f))
			t.groupRegexInvert = true
		case "--grfx":
			re := compileMillerRegex(va.str(f))
			t.groupRegex = re
			t.valueRegex = re
			t.valueRegexInvert = true
		case "-i":
			t.interp = true
		case "-s":
			t.iterative = true
		case "-F":
		default:
			va.unrecognized(f)
		}
	}
	if t.accs == nil {
		fmt.Fprintf(os.Stderr, "mlr stats1: -a option is required.\n")
		os.Exit(1)
	}
	if t.fields == nil && t.valueRegex == nil {
		fmt.Fprintf(os.Stderr, "mlr stats1: -f option is required.\n")
		os.Exit(1)
	}
	for _, a := range t.accs {
		validateAccName("stats1", a)
	}
	return t, va.i
}

func (t *Stats1T) groupFields(rec *Mlrmap) []string {
	if t.groupRegex != nil {
		var out []string
		for _, k := range rec.keys {
			if t.groupRegex.MatchString(k) != t.groupRegexInvert {
				out = append(out, k)
			}
		}
		return out
	}
	return t.groupBy
}

func (t *Stats1T) valueFields(rec *Mlrmap, groupFields []string) []string {
	if t.valueRegex != nil {
		gset := stringSet(groupFields)
		var out []string
		for _, k := range rec.keys {
			if gset[k] {
				continue
			}
			if t.valueRegex.MatchString(k) != t.valueRegexInvert {
				out = append(out, k)
			}
		}
		return out
	}
	return t.fields
}

func (t *Stats1T) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	gfields := t.groupFields(rec)
	key, ok := groupingKey(rec, gfields)
	if !ok {
		return
	}
	if t.groupRegex != nil {
		key = strings.Join(gfields, "\x1e") + "\x1d" + key
	}
	gv, ok := t.groups.get(key)
	var g *stats1Group
	if !ok {
		g = &stats1Group{groupVals: NewMlrmap(), bags: newLhm()}
		for _, f := range gfields {
			g.groupVals.PutNew(f, rec.Get(f))
		}
		t.groups.put(key, g)
	} else {
		g = gv.(*stats1Group)
	}
	for _, f := range t.valueFields(rec, gfields) {
		v := rec.Get(f)
		if v == nil {
			continue
		}
		bv, ok := g.bags.get(f)
		var b *statsBag
		if !ok {
			b = newStatsBag(t.accs, t.interp)
			g.bags.put(f, b)
		} else {
			b = bv.(*statsBag)
		}
		b.ingest(v)
	}
	if t.iterative {
		out := rec.Copy()
		for _, f := range g.bags.keys {
			bv, _ := g.bags.get(f)
			b := bv.(*statsBag)
			for _, a := range t.accs {
				out.Put(f+"_"+a, b.emit(a))
			}
		}
		next.Put(out, ctx)
	}
}

func (t *Stats1T) End(ctx *Context, next *ChainLink) {
	if t.iterative {
		return
	}
	for _, k := range t.groups.keys {
		gv, _ := t.groups.get(k)
		g := gv.(*stats1Group)
		out := g.groupVals.Copy()
		for _, f := range g.bags.keys {
			bv, _ := g.bags.get(f)
			b := bv.(*statsBag)
			for _, a := range t.accs {
				out.Put(f+"_"+a, b.emit(a))
			}
		}
		next.Put(out, ctx)
	}
}

// ---------------------------------------------------------------- merge-fields
type MergeFieldsT struct {
	accs     []string
	fields   []string
	regexes  []*regexp.Regexp
	collapse []string
	outName  string
	keep     bool
	interp   bool
	mode     string
}

func parseMergeFields(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("merge-fields", args, i)
	t := &MergeFieldsT{}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-a":
			t.accs = va.list(f)
		case "-f":
			t.fields = va.list(f)
			t.mode = "f"
		case "-r":
			for _, s := range va.list(f) {
				t.regexes = append(t.regexes, compileMillerRegex(s))
			}
			t.mode = "r"
		case "-c":
			t.collapse = va.list(f)
			t.mode = "c"
		case "-o":
			t.outName = va.str(f)
		case "-k":
			t.keep = true
		case "-i":
			t.interp = true
		case "-F":
		default:
			va.unrecognized(f)
		}
	}
	if t.accs == nil {
		fmt.Fprintf(os.Stderr, "mlr merge-fields: -a option is required.\n")
		os.Exit(1)
	}
	if t.mode == "" {
		fmt.Fprintf(os.Stderr, "mlr merge-fields: one of -f, -r, -c is required.\n")
		os.Exit(1)
	}
	if (t.mode == "f" || t.mode == "r") && t.outName == "" {
		fmt.Fprintf(os.Stderr, "mlr merge-fields: -o option is required with -f or -r.\n")
		os.Exit(1)
	}
	for _, a := range t.accs {
		validateAccName("merge-fields", a)
	}
	return t, va.i
}

func (t *MergeFieldsT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	switch t.mode {
	case "f":
		b := newStatsBag(t.accs, t.interp)
		for _, f := range t.fields {
			v := rec.Get(f)
			if v == nil {
				continue
			}
			b.ingest(v)
			if !t.keep {
				rec.Remove(f)
			}
		}
		for _, a := range t.accs {
			rec.Put(t.outName+"_"+a, b.emit(a))
		}
	case "r":
		b := newStatsBag(t.accs, t.interp)
		keys := rec.KeysCopy()
		for _, k := range keys {
			m := false
			for _, re := range t.regexes {
				if re.MatchString(k) {
					m = true
					break
				}
			}
			if !m {
				continue
			}
			b.ingest(rec.Get(k))
			if !t.keep {
				rec.Remove(k)
			}
		}
		for _, a := range t.accs {
			rec.Put(t.outName+"_"+a, b.emit(a))
		}
	case "c":
		bags := newLhm()
		keys := rec.KeysCopy()
		for _, k := range keys {
			for _, sub := range t.collapse {
				if strings.Contains(k, sub) {
					short := strings.Replace(k, sub, "", 1)
					bv, ok := bags.get(short)
					var b *statsBag
					if !ok {
						b = newStatsBag(t.accs, t.interp)
						bags.put(short, b)
					} else {
						b = bv.(*statsBag)
					}
					b.ingest(rec.Get(k))
					if !t.keep {
						rec.Remove(k)
					}
					break
				}
			}
		}
		for _, short := range bags.keys {
			bv, _ := bags.get(short)
			b := bv.(*statsBag)
			for _, a := range t.accs {
				rec.Put(short+"_"+a, b.emit(a))
			}
		}
	}
	next.Put(rec, ctx)
}
func (t *MergeFieldsT) End(ctx *Context, next *ChainLink) {}

// ---------------------------------------------------------------- step
type stepperState struct {
	havePrev  bool
	prev      *Mlrval
	first     *Mlrval
	counter   *Mlrval
	rsum      *Mlrval
	rprod     *Mlrval
	ewma      []*Mlrval
	haveEwma  bool
}

type StepT struct {
	steppers  []string
	fields    []string
	groupBy   []string
	alphas    []string
	suffixes  []string
	states    map[string]*stepperState
	// lookahead support
	needsLead bool
	maxBack   int
	maxFwd    int
	pending   *lhmsi // group -> []*pendingRec
}

type pendingRec struct {
	rec *Mlrmap
	ctx Context
}

type slwinSpec struct {
	back, fwd int
}

func parseStep(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("step", args, i)
	t := &StepT{states: map[string]*stepperState{}, pending: newLhm()}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-a":
			t.steppers = va.list(f)
		case "-f":
			t.fields = va.list(f)
		case "-g":
			t.groupBy = va.list(f)
		case "-d":
			t.alphas = va.list(f)
		case "-o":
			t.suffixes = va.list(f)
		case "-F":
		default:
			va.unrecognized(f)
		}
	}
	if t.steppers == nil || t.fields == nil {
		fmt.Fprintf(os.Stderr, "mlr step: -a and -f options are required.\n")
		os.Exit(1)
	}
	for _, s := range t.steppers {
		switch s {
		case "counter", "delta", "ratio", "rsum", "rprod", "shift", "shift_lag", "from-first", "ewma":
		case "shift_lead":
			t.needsLead = true
			if t.maxFwd < 1 {
				t.maxFwd = 1
			}
		default:
			if spec, ok := parseSlwin(s); ok {
				t.needsLead = true
				if spec.fwd > t.maxFwd {
					t.maxFwd = spec.fwd
				}
				if spec.back > t.maxBack {
					t.maxBack = spec.back
				}
			} else {
				fmt.Fprintf(os.Stderr, "mlr step: stepper \"%s\" not found.\n", s)
				os.Exit(1)
			}
		}
	}
	if t.suffixes != nil && len(t.suffixes) != len(t.alphas) {
		fmt.Fprintf(os.Stderr, "mlr step: -d and -o must have the same number of items.\n")
		os.Exit(1)
	}
	return t, va.i
}

func parseSlwin(s string) (slwinSpec, bool) {
	if !strings.HasPrefix(s, "slwin_") {
		return slwinSpec{}, false
	}
	parts := strings.Split(s[6:], "_")
	if len(parts) != 2 {
		return slwinSpec{}, false
	}
	b, e1 := strconv.Atoi(parts[0])
	f, e2 := strconv.Atoi(parts[1])
	if e1 != nil || e2 != nil {
		return slwinSpec{}, false
	}
	return slwinSpec{b, f}, true
}

func (t *StepT) applyStreaming(rec *Mlrmap, gkey string) {
	for _, f := range t.fields {
		v := rec.Get(f)
		if v == nil {
			continue
		}
		skey := gkey + "\x1d" + f
		st, ok := t.states[skey]
		if !ok {
			st = &stepperState{}
			t.states[skey] = st
		}
		for _, s := range t.steppers {
			switch s {
			case "counter":
				if st.counter == nil {
					st.counter = MlrvalFromInt(0)
				}
				if v.IsVoid() {
					rec.Put(f+"_counter", VOID)
				} else {
					st.counter = BinaryPlus(st.counter, MlrvalFromInt(1))
					rec.Put(f+"_counter", st.counter)
				}
			case "delta":
				if v.IsVoid() {
					rec.Put(f+"_delta", VOID)
				} else if !st.havePrev {
					rec.Put(f+"_delta", MlrvalFromInt(0))
				} else {
					rec.Put(f+"_delta", BinaryMinus(v, st.prev))
				}
			case "ratio":
				if v.IsVoid() {
					rec.Put(f+"_ratio", VOID)
				} else if !st.havePrev {
					rec.Put(f+"_ratio", MlrvalFromInt(0))
				} else {
					rec.Put(f+"_ratio", BinaryDivide(v, st.prev))
				}
			case "rsum":
				if st.rsum == nil {
					st.rsum = MlrvalFromInt(0)
				}
				if v.IsVoid() {
					rec.Put(f+"_rsum", VOID)
				} else {
					st.rsum = BinaryPlus(st.rsum, v)
					rec.Put(f+"_rsum", st.rsum)
				}
			case "rprod":
				if st.rprod == nil {
					st.rprod = MlrvalFromInt(1)
				}
				if v.IsVoid() {
					rec.Put(f+"_rprod", VOID)
				} else {
					st.rprod = BinaryTimes(st.rprod, v)
					rec.Put(f+"_rprod", st.rprod)
				}
			case "shift", "shift_lag":
				if !st.havePrev {
					rec.Put(f+"_"+s, VOID)
				} else {
					rec.Put(f+"_"+s, st.prev)
				}
			case "from-first":
				if st.first == nil {
					st.first = v
				}
				rec.Put(f+"_from_first", BinaryMinus(v, st.first))
			case "ewma":
				if len(t.alphas) == 0 {
					continue
				}
				if !st.haveEwma {
					st.ewma = make([]*Mlrval, len(t.alphas))
					for j := range t.alphas {
						st.ewma[j] = v
					}
					st.haveEwma = true
				} else {
					for j, as := range t.alphas {
						a := MlrvalFromInferred(as)
						oneMinus := BinaryMinus(MlrvalFromInt(1), a)
						st.ewma[j] = BinaryPlus(BinaryTimes(a, v), BinaryTimes(oneMinus, st.ewma[j]))
					}
				}
				for j, as := range t.alphas {
					suffix := as
					if t.suffixes != nil {
						suffix = t.suffixes[j]
					}
					rec.Put(f+"_ewma_"+suffix, st.ewma[j])
				}
			}
		}
		if !v.IsVoid() {
			st.prev = v
			st.havePrev = true
		} else {
			st.prev = v
			st.havePrev = true
		}
	}
}

func (t *StepT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	gkey := ""
	if t.groupBy != nil {
		k, ok := groupingKey(rec, t.groupBy)
		if !ok {
			next.Put(rec, ctx)
			return
		}
		gkey = k
	}
	t.applyStreaming(rec, gkey)
	if !t.needsLead {
		next.Put(rec, ctx)
		return
	}
	pv, ok := t.pending.get(gkey)
	var list []*pendingRec
	if ok {
		list = pv.([]*pendingRec)
	}
	list = append(list, &pendingRec{rec, *ctx})
	t.pending.put(gkey, list)
	t.flushReady(gkey, next, false)
}

// window processing: list holds history (up to maxBack emitted) + pending
type windowState struct {
	history []*Mlrmap
}

var stepWindows = map[*StepT]map[string]*windowState{}

func (t *StepT) flushReady(gkey string, next *ChainLink, atEnd bool) {
	pv, _ := t.pending.get(gkey)
	list := pv.([]*pendingRec)
	ws := stepWindows[t]
	if ws == nil {
		ws = map[string]*windowState{}
		stepWindows[t] = ws
	}
	w := ws[gkey]
	if w == nil {
		w = &windowState{}
		ws[gkey] = w
	}
	for len(list) > 0 {
		if !atEnd && len(list) <= t.maxFwd {
			break
		}
		cur := list[0]
		// compute lead-based steppers for cur
		for _, f := range t.fields {
			v := cur.rec.Get(f)
			if v == nil {
				continue
			}
			for _, s := range t.steppers {
				if s == "shift_lead" {
					if len(list) > 1 {
						nv := list[1].rec.Get(f)
						if nv == nil {
							cur.rec.Put(f+"_shift_lead", VOID)
						} else {
							cur.rec.Put(f+"_shift_lead", nv)
						}
					} else {
						cur.rec.Put(f+"_shift_lead", VOID)
					}
				} else if spec, ok := parseSlwin(s); ok {
					sum := 0.0
					n := 0
					hb := len(w.history) - spec.back
					if hb < 0 {
						hb = 0
					}
					for _, h := range w.history[hb:] {
						hv := h.Get(f)
						if hv != nil && hv.IsNumeric() {
							sum += hv.GetNumericToFloat()
							n++
						}
					}
					for j := 0; j <= spec.fwd && j < len(list); j++ {
						fv := list[j].rec.Get(f)
						if fv != nil && fv.IsNumeric() {
							sum += fv.GetNumericToFloat()
							n++
						}
					}
					if n > 0 {
						cur.rec.Put(fmt.Sprintf("%s_%d_%d", f, spec.back, spec.fwd), MlrvalFromFloat(sum/float64(n)))
					}
				}
			}
		}
		c := cur.ctx
		next.Put(cur.rec, &c)
		w.history = append(w.history, cur.rec)
		if len(w.history) > t.maxBack {
			w.history = w.history[len(w.history)-t.maxBack:]
		}
		list = list[1:]
	}
	t.pending.put(gkey, list)
}

func (t *StepT) End(ctx *Context, next *ChainLink) {
	if !t.needsLead {
		return
	}
	for _, k := range t.pending.keys {
		t.flushReady(k, next, true)
	}
}

// ---------------------------------------------------------------- top
type TopT struct {
	fields   []string
	groupBy  []string
	n        int64
	showAll  bool
	doMin    bool
	outName  string
	keepFloat bool
	groups   *lhmsi
}

type topGroup struct {
	groupVals *Mlrmap
	tops      map[string][]topEntry
}

type topEntry struct {
	val float64
	mv  *Mlrval
	rec *Mlrmap
}

func parseTop(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("top", args, i)
	t := &TopT{n: 1, outName: "top_idx", groups: newLhm()}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = va.list(f)
		case "-g":
			t.groupBy = va.list(f)
		case "-n":
			t.n = va.int(f)
		case "-a":
			t.showAll = true
		case "--min":
			t.doMin = true
		case "--max":
			t.doMin = false
		case "-F":
			t.keepFloat = true
		case "-o":
			t.outName = va.str(f)
		default:
			va.unrecognized(f)
		}
	}
	if t.fields == nil {
		fmt.Fprintf(os.Stderr, "mlr top: -f option is required.\n")
		os.Exit(1)
	}
	return t, va.i
}

func (t *TopT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	key := ""
	if t.groupBy != nil {
		k, ok := groupingKey(rec, t.groupBy)
		if !ok {
			return
		}
		key = k
	}
	gv, ok := t.groups.get(key)
	var g *topGroup
	if !ok {
		g = &topGroup{groupVals: NewMlrmap(), tops: map[string][]topEntry{}}
		for _, f := range t.groupBy {
			g.groupVals.PutNew(f, rec.Get(f))
		}
		t.groups.put(key, g)
	} else {
		g = gv.(*topGroup)
	}
	for _, f := range t.fields {
		v := rec.Get(f)
		if v == nil || v.IsVoid() {
			continue
		}
		if !v.IsNumeric() {
			continue
		}
		x := v.GetNumericToFloat()
		list := g.tops[f]
		// insert in sorted position
		pos := len(list)
		for j, e := range list {
			if (!t.doMin && x > e.val) || (t.doMin && x < e.val) {
				pos = j
				break
			}
		}
		if int64(pos) >= t.n {
			continue
		}
		var r *Mlrmap
		if t.showAll {
			r = rec.Copy()
		}
		entry := topEntry{val: x, mv: v, rec: r}
		list = append(list, topEntry{})
		copy(list[pos+1:], list[pos:])
		list[pos] = entry
		if int64(len(list)) > t.n {
			list = list[:t.n]
		}
		g.tops[f] = list
	}
}

func (t *TopT) End(ctx *Context, next *ChainLink) {
	for _, k := range t.groups.keys {
		gv, _ := t.groups.get(k)
		g := gv.(*topGroup)
		if t.showAll {
			f := t.fields[0]
			for _, e := range g.tops[f] {
				next.Put(e.rec, ctx)
			}
			continue
		}
		for j := int64(0); j < t.n; j++ {
			out := g.groupVals.Copy()
			out.Put(t.outName, MlrvalFromInt(j+1))
			for _, f := range t.fields {
				list := g.tops[f]
				if j < int64(len(list)) {
					e := list[j]
					var v *Mlrval
					if t.keepFloat {
						v = MlrvalFromFloat(e.val)
					} else if e.mv.Type() == MT_INT {
						v = MlrvalFromInt(e.mv.intval)
					} else {
						v = MlrvalFromFloat(e.val)
					}
					out.Put(f+"_top", v)
				} else {
					out.Put(f+"_top", VOID)
				}
			}
			next.Put(out, ctx)
		}
	}
}
EOF
