package main

import (
	"fmt"
	"math"
)

func pcaTest(n, sumx, sumy, sumxy, sumx2, sumy2 float64) {
	mx := sumx / n
	my := sumy / n
	for _, variant := range []string{"B", "A"} {
		var varx, vary, cov float64
		if variant == "B" {
			varx = (sumx2 - sumx*sumx/n) / (n - 1)
			vary = (sumy2 - sumy*sumy/n) / (n - 1)
			cov = (sumxy - sumx*sumy/n) / (n - 1)
		} else {
			varx = (sumx2 - mx*(2.0*sumx-n*mx)) / (n - 1)
			vary = (sumy2 - my*(2.0*sumy-n*my)) / (n - 1)
			cov = (sumxy - mx*sumy) / (n - 1)
		}
		// closed form
		tr := varx + vary
		det := varx*vary - cov*cov
		disc := math.Sqrt(tr*tr/4 - det)
		l1 := tr/2 + disc
		l2 := tr/2 - disc
		fmt.Println(variant, "closed", l1, l2)
		// jacobi
		a11, a12, a22 := varx, cov, vary
		theta := (a22 - a11) / (2 * a12)
		t := 1.0 / (math.Abs(theta) + math.Sqrt(theta*theta+1))
		if theta < 0 {
			t = -t
		}
		c := 1 / math.Sqrt(t*t+1)
		s := t * c
		j1 := a11 - t*a12
		j2 := a22 + t*a12
		fmt.Println(variant, "jacobi", j1, j2, c, s)
		// eigenvector for larger
		var ex, ey float64
		if j2 > j1 {
			ex, ey = s, c
		} else {
			ex, ey = c, -s
		}
		m := ey / ex
		fmt.Println(variant, "m", m, "b", my-m*mx, "q", j1/j2, 1-math.Min(j1, j2)/math.Max(j1, j2))
		// eigvec for closed-form
		vx, vy := cov, l1-varx
		norm := math.Hypot(vx, vy)
		fmt.Println(variant, "evec", vx/norm, vy/norm, "m", vy/vx, "b", my-(vy/vx)*mx)
		vx2, vy2 := l1-vary, cov
		norm2 := math.Hypot(vx2, vy2)
		fmt.Println(variant, "evec2", vx2/norm2, vy2/norm2, "m", vy2/vx2, "b", my-(vy2/vx2)*mx, "abs-l2/l1", math.Abs(l2/l1))
	}
}
