func randRange(lo, hi int64) int64 {
	return lo + rng.Int63()%(hi-lo)
}

// ---------------------------------------------------------------- nest
type NestT struct {
	explode   bool
	values    bool
	across    string // "records" or "fields"
	field     string
	fieldRe   *regexp.Regexp
	nestedFS  string
	nestedPS  string
	groups    *lhmsi
	otherKeys map[string]*Mlrmap
}

func parseNest(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("nest", args, i)
	t := &NestT{nestedFS: ";", nestedPS: ":", groups: newLhm()}
	haveEI, haveVP, haveRF := false, false, false
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "--explode":
			t.explode = true
			haveEI = true
		case "--implode":
			t.explode = false
			haveEI = true
		case "--values":
			t.values = true
			haveVP = true
		case "--pairs":
			t.values = false
			haveVP = true
		case "--across-records":
			t.across = "records"
			haveRF = true
		case "--across-fields":
			t.across = "fields"
			haveRF = true
		case "-f":
			t.field = va.str(f)
		case "-r":
			t.fieldRe = compileMillerRegex(va.str(f))
		case "--nested-fs":
			t.nestedFS = sepFromArg(va.str(f))
		case "--nested-ps":
			t.nestedPS = sepFromArg(va.str(f))
		case "--evar":
			t.nestedFS = sepFromArg(va.str(f))
			t.explode, t.values, t.across = true, true, "records"
			haveEI, haveVP, haveRF = true, true, true
		case "--ivar":
			t.nestedFS = sepFromArg(va.str(f))
			t.explode, t.values, t.across = false, true, "records"
			haveEI, haveVP, haveRF = true, true, true
		default:
			va.unrecognized(f)
		}
	}
	if !haveEI || !haveVP || !haveRF || (t.field == "" && t.fieldRe == nil) {
		fmt.Fprint(os.Stderr, verbUsage("nest"))
		os.Exit(1)
	}
	return t, va.i
}

func (t *NestT) matchFields(rec *Mlrmap) []string {
	if t.fieldRe != nil {
		var out []string
		for _, k := range rec.keys {
			if t.fieldRe.MatchString(k) {
				out = append(out, k)
			}
		}
		return out
	}
	if rec.Has(t.field) {
		return []string{t.field}
	}
	return nil
}

func (t *NestT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if t.explode {
		fields := t.matchFields(rec)
		if len(fields) == 0 {
			next.Put(rec, ctx)
			return
		}
		recs := []*Mlrmap{rec}
		for _, f := range fields {
			var out []*Mlrmap
			for _, r := range recs {
				out = append(out, t.explodeOne(r, f)...)
			}
			recs = out
		}
		for _, r := range recs {
			next.Put(r, ctx)
		}
		return
	}
	// implode
	if t.across == "fields" {
		t.implodeFields(rec)
		next.Put(rec, ctx)
		return
	}
	v := rec.Get(t.field)
	if v == nil {
		next.Put(rec, ctx)
		return
	}
	other := rec.Copy()
	other.Remove(t.field)
	var b strings.Builder
	for i, k := range other.keys {
		b.WriteString(k)
		b.WriteString("\x1f")
		b.WriteString(other.vals[i].String())
		b.WriteString("\x1e")
	}
	key := b.String()
	gv, ok := t.groups.get(key)
	if !ok {
		t.groups.put(key, &implodeGroup{first: rec, vals: []string{v.String()}})
	} else {
		g := gv.(*implodeGroup)
		g.vals = append(g.vals, v.String())
	}
}

type implodeGroup struct {
	first *Mlrmap
	vals  []string
}

func (t *NestT) explodeOne(rec *Mlrmap, f string) []*Mlrmap {
	v := rec.Get(f)
	s := v.String()
	parts := strings.Split(s, t.nestedFS)
	if t.across == "records" {
		var out []*Mlrmap
		for _, p := range parts {
			r := rec.Copy()
			if t.values {
				r.Put(f, MlrvalFromInferred(p))
			} else {
				idx := strings.Index(p, t.nestedPS)
				var k, val string
				if idx < 0 {
					k, val = f, p
				} else {
					k, val = p[:idx], p[idx+len(t.nestedPS):]
				}
				// replace field f with k at same position
				pos := r.find(f)
				r.removeAt(pos)
				if r.Has(k) {
					r.Put(k, MlrvalFromInferred(val))
				} else {
					r.InsertAt(pos, k, MlrvalFromInferred(val))
				}
			}
			out = append(out, r)
		}
		return out
	}
	// across fields
	r := NewMlrmap()
	for i, k := range rec.keys {
		if k != f {
			r.Put(k, rec.vals[i])
			continue
		}
		for j, p := range parts {
			if t.values {
				r.Put(f+"_"+strconv.Itoa(j+1), MlrvalFromInferred(p))
			} else {
				idx := strings.Index(p, t.nestedPS)
				var kk, val string
				if idx < 0 {
					kk, val = f, p
				} else {
					kk, val = p[:idx], p[idx+len(t.nestedPS):]
				}
				r.Put(kk, MlrvalFromInferred(val))
			}
		}
	}
	return []*Mlrmap{r}
}

func (t *NestT) implodeFields(rec *Mlrmap) {
	prefix := t.field + "_"
	var parts []string
	firstPos := -1
	out := NewMlrmap()
	for i, k := range rec.keys {
		if strings.HasPrefix(k, prefix) {
			if _, err := strconv.Atoi(k[len(prefix):]); err == nil {
				if firstPos < 0 {
					firstPos = out.Len()
					out.PutNew(t.field, VOID)
				}
				parts = append(parts, rec.vals[i].String())
				continue
			}
		}
		out.Put(k, rec.vals[i])
	}
	if firstPos >= 0 {
		out.vals[firstPos] = MlrvalFromInferred(strings.Join(parts, t.nestedFS))
	}
	rec.keys = out.keys
	rec.vals = out.vals
}

func (t *NestT) End(ctx *Context, next *ChainLink) {
	if t.explode || t.across == "fields" {
		return
	}
	for _, k := range t.groups.keys {
		gv, _ := t.groups.get(k)
		g := gv.(*implodeGroup)
		r := g.first
		r.Put(t.field, MlrvalFromInferred(strings.Join(g.vals, t.nestedFS)))
		next.Put(r, ctx)
	}
}

// ---------------------------------------------------------------- reshape
type ReshapeT struct {
	inputFields []string
	inputRegexes []*regexp.Regexp
	keyField, valueField string
	splitKey, splitValue string
	longToWide  bool
	groups      *lhmsi
	otherKeysUnion *lhmsi
}

type reshapeGroup struct {
	others *Mlrmap
	pairs  *Mlrmap
}

func parseReshape(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("reshape", args, i)
	t := &ReshapeT{groups: newLhm(), otherKeysUnion: newLhm()}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-i":
			t.inputFields = append(t.inputFields, va.list(f)...)
		case "-r":
			t.inputRegexes = append(t.inputRegexes, compileMillerRegex(va.str(f)))
		case "-o":
			l := va.list(f)
			if len(l) != 2 {
				va.usageError("-o requires two field names.")
			}
			t.keyField, t.valueField = l[0], l[1]
		case "-s":
			l := va.list(f)
			if len(l) != 2 {
				va.usageError("-s requires two field names.")
			}
			t.splitKey, t.splitValue = l[0], l[1]
			t.longToWide = true
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}

func (t *ReshapeT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if !t.longToWide {
		inset := stringSet(t.inputFields)
		others := NewMlrmap()
		pairs := NewMlrmap()
		for i, k := range rec.keys {
			m := inset[k]
			if !m {
				for _, re := range t.inputRegexes {
					if re.MatchString(k) {
						m = true
						break
					}
				}
			}
			if m {
				pairs.PutNew(k, rec.vals[i])
			} else {
				others.PutNew(k, rec.vals[i])
			}
		}
		if pairs.Len() == 0 {
			next.Put(rec, ctx)
			return
		}
		for i, k := range pairs.keys {
			r := others.Copy()
			r.Put(t.keyField, MlrvalFromString(k))
			r.Put(t.valueField, pairs.vals[i])
			next.Put(r, ctx)
		}
		return
	}
	kv := rec.Get(t.splitKey)
	vv := rec.Get(t.splitValue)
	if kv == nil || vv == nil {
		next.Put(rec, ctx)
		return
	}
	others := rec.Copy()
	others.Remove(t.splitKey)
	others.Remove(t.splitValue)
	var b strings.Builder
	for i, k := range others.keys {
		b.WriteString(k)
		b.WriteString("\x1f")
		b.WriteString(others.vals[i].String())
		b.WriteString("\x1e")
	}
	key := b.String()
	gv, ok := t.groups.get(key)
	var g *reshapeGroup
	if !ok {
		g = &reshapeGroup{others: others, pairs: NewMlrmap()}
		t.groups.put(key, g)
	} else {
		g = gv.(*reshapeGroup)
	}
	g.pairs.Put(kv.String(), vv)
	t.otherKeysUnion.put(kv.String(), true)
}

func (t *ReshapeT) End(ctx *Context, next *ChainLink) {
	if !t.longToWide {
		return
	}
	for _, k := range t.groups.keys {
		gv, _ := t.groups.get(k)
		g := gv.(*reshapeGroup)
		r := g.others.Copy()
		for _, pk := range t.otherKeysUnion.keys {
			v := g.pairs.Get(pk)
			if v == nil {
				r.Put(pk, VOID)
			} else {
				r.Put(pk, v)
			}
		}
		next.Put(r, ctx)
	}
}

// ---------------------------------------------------------------- join
type JoinT struct {
	leftFile    string
	leftFields  []string
	rightFields []string
	outFields   []string
	leftKeep    map[string]bool
	haveLeftKeep bool
	lp, rp      string
	emitPaired  bool
	emitUL      bool
	emitUR      bool
	ropts       ReaderOptions
	leftBuckets *lhmsi // key -> *joinBucket
	leftUnkeyed []*Mlrmap
	loaded      bool
	prepipe     string
}

type joinBucket struct {
	recs   []*Mlrmap
	paired bool
}

func parseJoin(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("join", args, i)
	t := &JoinT{emitPaired: true, leftBuckets: newLhm()}
	t.ropts = opts.R
	localR := opts.R
	formatSet := false
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.leftFile = va.str(f)
		case "-j":
			t.outFields = va.list(f)
		case "-l":
			t.leftFields = va.list(f)
		case "-r":
			t.rightFields = va.list(f)
		case "--lk", "--left-keep-field-names":
			t.leftKeep = stringSet(va.list(f))
			t.haveLeftKeep = true
		case "--lp":
			t.lp = va.str(f)
		case "--rp":
			t.rp = va.str(f)
		case "--np":
			t.emitPaired = false
		case "--ul":
			t.emitUL = true
		case "--ur":
			t.emitUR = true
		case "-u", "-s", "--sorted-input":
		case "-i":
			localR.InputFormat = formatAlias(va.str(f))
			formatSet = true
		case "--prepipe", "--prepipex":
			localR.Prepipe = va.str(f)
			localR.PrepipeIsRaw = f == "--prepipex"
		default:
			va.i--
			ni, ok := parseReaderFlag(va.args, va.i, &localR)
			if !ok {
				ni, ok = parseRWFlag(va.args, va.i, &localR, &WriterOptions{})
			}
			if !ok {
				va.i++
				va.unrecognized(f)
			}
			formatSet = true
			va.i = ni
		}
	}
	_ = formatSet
	if t.leftFile == "" {
		fmt.Fprintf(os.Stderr, "mlr join: left-file name must be specified.\n")
		os.Exit(1)
	}
	if t.outFields == nil {
		if t.leftFields != nil {
			t.outFields = t.leftFields
		} else if t.rightFields != nil {
			t.outFields = t.rightFields
		}
	}
	if t.outFields == nil {
		fmt.Fprintf(os.Stderr, "mlr: mlr join: need output field names\n")
		os.Exit(1)
	}
	if t.leftFields == nil {
		t.leftFields = t.outFields
	}
	if t.rightFields == nil {
		t.rightFields = t.outFields
	}
	if len(t.leftFields) != len(t.rightFields) || len(t.leftFields) != len(t.outFields) {
		fmt.Fprintf(os.Stderr, "mlr join: mismatched join-field-name lengths.\n")
		os.Exit(1)
	}
	if !localR.ifsSet || !localR.ipsSet || !localR.irsSet {
		// re-derive defaults for possibly different format
		tmp := localR
		if !opts.R.ifsSet {
			tmp.ifsSet = false
		}
		finalizeReaderOptions(&tmp)
		localR = tmp
	}
	t.ropts = localR
	return t, va.i
}

func (t *JoinT) loadLeft() {
	t.loaded = true
	ir := &InputReader{opts: &t.ropts}
	ir.passOut = func(s string) {}
	ir.sink = func(rec *Mlrmap, ctx *Context) {
		key, ok := groupingKey(rec, t.leftFields)
		if !ok {
			t.leftUnkeyed = append(t.leftUnkeyed, rec)
			return
		}
		bv, ok := t.leftBuckets.get(key)
		if !ok {
			t.leftBuckets.put(key, &joinBucket{recs: []*Mlrmap{rec}})
		} else {
			b := bv.(*joinBucket)
			b.recs = append(b.recs, rec)
		}
	}
	saveList := jsonInputHadList
	errmsg := ir.ReadAll([]string{t.leftFile})
	jsonInputHadList = saveList
	if errmsg != "" {
		fatalf("%s\n", errmsg)
	}
}

func (t *JoinT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if !t.loaded {
		t.loadLeft()
	}
	key, ok := groupingKey(rec, t.rightFields)
	if !ok {
		if t.emitUR {
			next.Put(rec, ctx)
		}
		return
	}
	bv, ok := t.leftBuckets.get(key)
	if !ok {
		if t.emitUR {
			next.Put(rec, ctx)
		}
		return
	}
	b := bv.(*joinBucket)
	b.paired = true
	if !t.emitPaired {
		return
	}
	for _, left := range b.recs {
		out := NewMlrmap()
		for j, of := range t.outFields {
			out.PutNew(of, left.Get(t.leftFields[j]))
		}
		leftJoinSet := stringSet(t.leftFields)
		for i, k := range left.keys {
			if leftJoinSet[k] {
				continue
			}
			if t.haveLeftKeep && !t.leftKeep[k] {
				continue
			}
			nk := k
			if t.lp != "" {
				nk = t.lp + k
			}
			out.Put(nk, left.vals[i])
		}
		rightJoinSet := stringSet(t.rightFields)
		for i, k := range rec.keys {
			if rightJoinSet[k] {
				continue
			}
			nk := k
			if t.rp != "" {
				nk = t.rp + k
			}
			out.Put(nk, rec.vals[i])
		}
		next.Put(out, ctx)
	}
}

func (t *JoinT) End(ctx *Context, next *ChainLink) {
	if !t.loaded {
		t.loadLeft()
	}
	if t.emitUL {
		for _, k := range t.leftBuckets.keys {
			bv, _ := t.leftBuckets.get(k)
			b := bv.(*joinBucket)
			if !b.paired {
				for _, r := range b.recs {
					next.Put(r, ctx)
				}
			}
		}
		for _, r := range t.leftUnkeyed {
			next.Put(r, ctx)
		}
	}
}

// ---------------------------------------------------------------- fraction
type FractionT struct {
	fields     []string
	groupBy    []string
	percent    bool
	cumulative bool
	recs       []recctx
	sums       map[string]map[string]*Mlrval
}

func parseFraction(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("fraction", args, i)
	t := &FractionT{sums: map[string]map[string]*Mlrval{}}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = va.list(f)
		case "-g":
			t.groupBy = va.list(f)
		case "-p":
			t.percent = true
		case "-c":
			t.cumulative = true
		default:
			va.unrecognized(f)
		}
	}
	if t.fields == nil {
		va.usageError("option -f is required.")
	}
	return t, va.i
}

func (t *FractionT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	t.recs = append(t.recs, recctx{rec, *ctx})
	key := ""
	if t.groupBy != nil {
		k, ok := groupingKey(rec, t.groupBy)
		if !ok {
			return
		}
		key = k
	}
	m := t.sums[key]
	if m == nil {
		m = map[string]*Mlrval{}
		t.sums[key] = m
	}
	for _, f := range t.fields {
		v := rec.Get(f)
		if v == nil || !v.IsNumeric() {
			continue
		}
		if m[f] == nil {
			m[f] = MlrvalFromInt(0)
		}
		m[f] = BinaryPlus(m[f], v)
	}
}

func (t *FractionT) End(ctx *Context, next *ChainLink) {
	cums := map[string]map[string]*Mlrval{}
	var multiplier *Mlrval
	suffix := "_fraction"
	if t.percent {
		multiplier = MlrvalFromInt(100)
		suffix = "_percent"
	} else {
		multiplier = MlrvalFromInt(1)
	}
	if t.cumulative {
		suffix = "_cumulative" + suffix
	}
	for _, rc := range t.recs {
		rec := rc.rec
		key := ""
		ok := true
		if t.groupBy != nil {
			key, ok = groupingKey(rec, t.groupBy)
		}
		if ok {
			m := t.sums[key]
			cm := cums[key]
			if cm == nil {
				cm = map[string]*Mlrval{}
				cums[key] = cm
			}
			for _, f := range t.fields {
				v := rec.Get(f)
				if v == nil || !v.IsNumeric() {
					continue
				}
				denom := m[f]
				var out *Mlrval
				if t.cumulative {
					if cm[f] == nil {
						cm[f] = MlrvalFromInt(0)
					}
					cm[f] = BinaryPlus(cm[f], v)
					out = BinaryDivide(BinaryTimes(multiplier, cm[f]), denom)
				} else {
					out = BinaryDivide(BinaryTimes(multiplier, v), denom)
				}
				rec.Put(f+suffix, out)
			}
		}
		c := rc.ctx
		next.Put(rec, &c)
	}
}

// ---------------------------------------------------------------- histogram
type HistogramT struct {
	fields  []string
	lo, hi  float64
	nbins   int
	auto    bool
	prefix  string
	counts  map[string][]int64
	values  map[string][]float64
	haveLo, haveHi bool
}

func parseHistogram(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("histogram", args, i)
	t := &HistogramT{nbins: 20, counts: map[string][]int64{}, values: map[string][]float64{}}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = va.list(f)
		case "--lo":
			t.lo = va.float(f)
			t.haveLo = true
		case "--hi":
			t.hi = va.float(f)
			t.haveHi = true
		case "--nbins":
			t.nbins = int(va.int(f))
		case "--auto":
			t.auto = true
		case "-o":
			t.prefix = va.str(f)
		default:
			va.unrecognized(f)
		}
	}
	if t.fields == nil {
		va.usageError("option -f is required.")
	}
	if !t.auto && (!t.haveLo || !t.haveHi) {
		fmt.Fprintf(os.Stderr, "mlr histogram: --lo and --hi must be specified unless --auto is used.\n")
		os.Exit(1)
	}
	for _, f := range t.fields {
		t.counts[f] = make([]int64, t.nbins)
	}
	return t, va.i
}

func (t *HistogramT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	for _, f := range t.fields {
		v := rec.Get(f)
		if v == nil || !v.IsNumeric() {
			continue
		}
		x := v.GetNumericToFloat()
		if t.auto {
			t.values[f] = append(t.values[f], x)
			continue
		}
		t.bin(f, x, t.lo, t.hi)
	}
}

func (t *HistogramT) bin(f string, x, lo, hi float64) {
	if x < lo || x > hi {
		return
	}
	mul := float64(t.nbins) / (hi - lo)
	idx := int((x - lo) * mul)
	if x == hi {
		idx = t.nbins - 1
	}
	if idx >= 0 && idx < t.nbins {
		t.counts[f][idx]++
	}
}

func (t *HistogramT) End(ctx *Context, next *ChainLink) {
	lo, hi := t.lo, t.hi
	if t.auto {
		first := true
		for _, f := range t.fields {
			for _, x := range t.values[f] {
				if first {
					lo, hi = x, x
					first = false
				} else {
					if x < lo {
						lo = x
					}
					if x > hi {
						hi = x
					}
				}
			}
		}
		for _, f := range t.fields {
			for _, x := range t.values[f] {
				t.bin(f, x, lo, hi)
			}
		}
	}
	binWidth := (hi - lo) / float64(t.nbins)
	for i := 0; i < t.nbins; i++ {
		out := NewMlrmap()
		out.PutNew(t.prefix+"bin_lo", MlrvalFromFloat(lo+binWidth*float64(i)))
		out.PutNew(t.prefix+"bin_hi", MlrvalFromFloat(lo+binWidth*float64(i+1)))
		for _, f := range t.fields {
			out.PutNew(t.prefix+f+"_count", MlrvalFromInt(t.counts[f][i]))
		}
		next.Put(out, ctx)
	}
}

// ---------------------------------------------------------------- bar
type BarT struct {
	fields          []string
	lo, hi          float64
	width           int
	auto            bool
	fillChar        string
	oobChar         string
	blankChar       string
	recs            []recctx
}

func parseBar(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("bar", args, i)
	t := &BarT{lo: 0, hi: 100, width: 40, fillChar: "*", oobChar: "#", blankChar: "."}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-f":
			t.fields = va.list(f)
		case "--lo":
			t.lo = va.float(f)
		case "--hi":
			t.hi = va.float(f)
		case "-w":
			t.width = int(va.int(f))
		case "--auto":
			t.auto = true
		case "-c":
			t.fillChar = va.str(f)
		case "-x":
			t.oobChar = va.str(f)
		case "-b":
			t.blankChar = va.str(f)
		default:
			va.unrecognized(f)
		}
	}
	if t.fields == nil {
		va.usageError("option -f is required.")
	}
	return t, va.i
}

func (t *BarT) barString(x, lo, hi float64) string {
	w := t.width
	idx := int(float64(w) * (x - lo) / (hi - lo))
	if idx < 0 {
		idx = 0
	}
	if idx > w {
		idx = w
	}
	if idx == 0 {
		return t.oobChar + strings.Repeat(t.blankChar, w-1)
	}
	if idx == w {
		return strings.Repeat(t.fillChar, w-1) + t.oobChar
	}
	return strings.Repeat(t.fillChar, idx) + strings.Repeat(t.blankChar, w-idx)
}

func (t *BarT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	if t.auto {
		t.recs = append(t.recs, recctx{rec, *ctx})
		return
	}
	for _, f := range t.fields {
		v := rec.Get(f)
		if v == nil || !v.IsNumeric() {
			continue
		}
		rec.Put(f, MlrvalFromString(t.barString(v.GetNumericToFloat(), t.lo, t.hi)))
	}
	next.Put(rec, ctx)
}

func (t *BarT) End(ctx *Context, next *ChainLink) {
	if !t.auto {
		return
	}
	for _, f := range t.fields {
		first := true
		var lo, hi float64
		for _, rc := range t.recs {
			v := rc.rec.Get(f)
			if v == nil || !v.IsNumeric() {
				continue
			}
			x := v.GetNumericToFloat()
			if first {
				lo, hi = x, x
				first = false
			} else {
				if x < lo {
					lo = x
				}
				if x > hi {
					hi = x
				}
			}
		}
		slo := formatFloat(lo)
		shi := formatFloat(hi)
		for _, rc := range t.recs {
			v := rc.rec.Get(f)
			if v == nil || !v.IsNumeric() {
				continue
			}
			s := "[" + slo + "]" + t.barString(v.GetNumericToFloat(), lo, hi) + "[" + shi + "]"
			rc.rec.Put(f, MlrvalFromString(s))
		}
	}
	for _, rc := range t.recs {
		c := rc.ctx
		next.Put(rc.rec, &c)
	}
}

// ---------------------------------------------------------------- bootstrap / sample / shuffle
type BootstrapT struct {
	n    int64
	recs []recctx
}

func parseBootstrap(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("bootstrap", args, i)
	t := &BootstrapT{n: -1}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-n":
			t.n = va.int(f)
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}
func (t *BootstrapT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	t.recs = append(t.recs, recctx{rec, *ctx})
}
func (t *BootstrapT) End(ctx *Context, next *ChainLink) {
	n := t.n
	nin := int64(len(t.recs))
	if n < 0 {
		n = nin
	}
	if nin == 0 {
		return
	}
	for j := int64(0); j < n; j++ {
		idx := randRange(0, nin)
		rc := t.recs[idx]
		c := rc.ctx
		next.Put(rc.rec.Copy(), &c)
	}
}

type SampleT struct {
	k       int64
	groupBy []string
	groups  *lhmsi
}

type sampleGroup struct {
	n    int64
	recs []recctx
}

func parseSample(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("sample", args, i)
	t := &SampleT{k: 1, groups: newLhm()}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-k":
			t.k = va.int(f)
		case "-g":
			t.groupBy = va.list(f)
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}
func (t *SampleT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	key := ""
	if t.groupBy != nil {
		k, ok := groupingKey(rec, t.groupBy)
		if !ok {
			return
		}
		key = k
	}
	gv, ok := t.groups.get(key)
	var g *sampleGroup
	if !ok {
		g = &sampleGroup{}
		t.groups.put(key, g)
	} else {
		g = gv.(*sampleGroup)
	}
	if g.n < t.k {
		g.recs = append(g.recs, recctx{rec, *ctx})
	} else {
		r := randRange(0, g.n+1)
		if r < t.k {
			g.recs[r] = recctx{rec, *ctx}
		}
	}
	g.n++
}
func (t *SampleT) End(ctx *Context, next *ChainLink) {
	for _, k := range t.groups.keys {
		gv, _ := t.groups.get(k)
		for _, rc := range gv.(*sampleGroup).recs {
			c := rc.ctx
			next.Put(rc.rec, &c)
		}
	}
}

type ShuffleT struct {
	recs []recctx
}

func parseShuffle(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("shuffle", args, i)
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		va.unrecognized(f)
	}
	return &ShuffleT{}, va.i
}
func (t *ShuffleT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	t.recs = append(t.recs, recctx{rec, *ctx})
}
func (t *ShuffleT) End(ctx *Context, next *ChainLink) {
	n := int64(len(t.recs))
	for i := int64(0); i < n-1; i++ {
		j := randRange(i, n)
		t.recs[i], t.recs[j] = t.recs[j], t.recs[i]
	}
	for _, rc := range t.recs {
		c := rc.ctx
		next.Put(rc.rec, &c)
	}
}

// ---------------------------------------------------------------- tee verb
type TeeVerbT struct {
	filename string
	appendMode bool
	pipe     bool
	wopts    WriterOptions
	writer   RecordWriter
	out      *bufio.Writer
	file     *os.File
	cmd      *exec.Cmd
	pipeIn   interface{ Close() error }
}

func parseWriterOptionsForVerb(va *vargs, f string, w *WriterOptions) bool {
	va.i--
	ni, ok := parseWriterFlag(va.args, va.i, w)
	if !ok {
		var r ReaderOptions
		ni, ok = parseRWFlag(va.args, va.i, &r, w)
	}
	if !ok {
		va.i++
		return false
	}
	va.i = ni
	return true
}

func parseTeeVerb(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("tee", args, i)
	t := &TeeVerbT{wopts: opts.W}
	t.wopts.ofsSet, t.wopts.opsSet, t.wopts.orsSet = false, false, false
	saveW := opts.W
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-a":
			t.appendMode = true
		case "-p":
			t.pipe = true
		default:
			if !parseWriterOptionsForVerb(va, f, &t.wopts) {
				va.unrecognized(f)
			}
		}
	}
	if t.wopts.OutputFormat == saveW.OutputFormat {
		if !t.wopts.ofsSet {
			t.wopts.OFS = saveW.OFS
		}
		if !t.wopts.opsSet {
			t.wopts.OPS = saveW.OPS
		}
		if !t.wopts.orsSet {
			t.wopts.ORS = saveW.ORS
		}
	} else {
		finalizeWriterOptions(&t.wopts)
	}
	t.filename = va.positional("filename")
	return t, va.i
}

func (t *TeeVerbT) open() {
	if t.out != nil {
		return
	}
	if t.pipe {
		stdoutWriter.Flush()
		cmd := exec.Command("/bin/sh", "-c", t.filename)
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		pw, _ := cmd.StdinPipe()
		cmd.Start()
		t.cmd = cmd
		t.pipeIn = pw
		t.out = bufio.NewWriter(pw)
	} else {
		flags := os.O_CREATE | os.O_WRONLY
		if t.appendMode {
			flags |= os.O_APPEND
		} else {
			flags |= os.O_TRUNC
		}
		f, err := os.OpenFile(t.filename, flags, 0644)
		if err != nil {
			fatalf("mlr: could not open \"%s\" for write.\n", t.filename)
		}
		t.file = f
		t.out = bufio.NewWriter(f)
	}
	t.writer = newRecordWriter(&t.wopts)
}

func (t *TeeVerbT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	t.open()
	r := rec.Copy()
	if !isJSONFormat(t.wopts.OutputFormat) {
		flattenRecord(r, t.wopts.FlatSep, nil)
	}
	t.writer.Write(r, t.out)
	next.Put(rec, ctx)
}
func (t *TeeVerbT) End(ctx *Context, next *ChainLink) {
	t.open()
	t.writer.Finish(t.out)
	t.out.Flush()
	if t.file != nil {
		t.file.Close()
	}
	if t.cmd != nil {
		t.pipeIn.Close()
		t.cmd.Wait()
	}
}

// ---------------------------------------------------------------- split
type SplitT struct {
	n, m       int64
	groupBy    []string
	prefix     string
	suffix     string
	folder     string
	appendMode bool
	passThru   bool
	noEscape   bool
	joiner     string
	wopts      WriterOptions
	count      int64
	outputs    map[string]*splitOut
	order      []string
}

type splitOut struct {
	f      *os.File
	w      *bufio.Writer
	writer RecordWriter
}

func parseSplit(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("split", args, i)
	t := &SplitT{prefix: "split", joiner: "_", wopts: opts.W, outputs: map[string]*splitOut{}}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-n":
			t.n = va.int(f)
		case "-m":
			t.m = va.int(f)
		case "-g":
			t.groupBy = va.list(f)
		case "--prefix":
			t.prefix = va.str(f)
		case "--suffix":
			t.suffix = va.str(f)
		case "--folder":
			t.folder = va.str(f)
		case "-a":
			t.appendMode = true
		case "-v":
			t.passThru = true
		case "-e":
			t.noEscape = true
		case "-j":
			t.joiner = va.str(f)
		default:
			if !parseWriterOptionsForVerb(va, f, &t.wopts) {
				va.unrecognized(f)
			}
		}
	}
	finalizeWriterOptions(&t.wopts)
	if t.suffix == "" {
		t.suffix = t.wopts.OutputFormat
		switch t.suffix {
		case "markdown":
			t.suffix = "md"
		}
	}
	nset := 0
	if t.n > 0 {
		nset++
	}
	if t.m > 0 {
		nset++
	}
	if t.groupBy != nil {
		nset++
	}
	if nset != 1 {
		fmt.Fprintf(os.Stderr, "mlr split: exactly one of -n, -m, -g is required.\n")
		os.Exit(1)
	}
	return t, va.i
}

func (t *SplitT) getOut(name string) *splitOut {
	if o, ok := t.outputs[name]; ok {
		return o
	}
	path := name
	if t.folder != "" {
		path = t.folder + "/" + name
	}
	flags := os.O_CREATE | os.O_WRONLY
	if t.appendMode {
		flags |= os.O_APPEND
	} else {
		flags |= os.O_TRUNC
	}
	f, err := os.OpenFile(path, flags, 0644)
	if err != nil {
		fatalf("mlr: could not open \"%s\" for write.\n", path)
	}
	o := &splitOut{f: f, w: bufio.NewWriter(f), writer: newRecordWriter(&t.wopts)}
	t.outputs[name] = o
	t.order = append(t.order, name)
	return o
}

func (t *SplitT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	var name string
	if t.n > 0 {
		name = t.prefix + t.joiner + strconv.FormatInt(t.count/t.n+1, 10) + "." + t.suffix
	} else if t.m > 0 {
		name = t.prefix + t.joiner + strconv.FormatInt(t.count%t.m+1, 10) + "." + t.suffix
	} else {
		var parts []string
		for _, g := range t.groupBy {
			v := rec.Get(g)
			if v == nil {
				if t.passThru {
					next.Put(rec, ctx)
				}
				return
			}
			s := v.String()
			if !t.noEscape {
				s = url.QueryEscape(s)
			}
			parts = append(parts, s)
		}
		name = t.prefix + t.joiner + strings.Join(parts, t.joiner) + "." + t.suffix
	}
	t.count++
	o := t.getOut(name)
	r := rec.Copy()
	if !isJSONFormat(t.wopts.OutputFormat) {
		flattenRecord(r, t.wopts.FlatSep, nil)
	}
	o.writer.Write(r, o.w)
	if t.passThru {
		next.Put(rec, ctx)
	}
}

func (t *SplitT) End(ctx *Context, next *ChainLink) {
	for _, name := range t.order {
		o := t.outputs[name]
		o.writer.Finish(o.w)
		o.w.Flush()
		o.f.Close()
	}
}

