package main

import (
	"fmt"
	"math"
)

func logireg(xs, ys []float64, variant int) (float64, float64, int) {
	m0 := -0.001
	b0 := 0.002
	tol := 1e-9
	maxits := 100
	its := 0
	for {
		var dldm, dldb, d2m2, d2mb, d2b2 float64
		for i := range xs {
			x, y := xs[i], ys[i]
			p := 1.0 / (1.0 + math.Exp(-m0*x-b0))
			dldm += (y - p) * x
			dldb += y - p
			q := p * (1 - p)
			d2m2 -= x * x * q
			d2mb -= x * q
			d2b2 -= q
		}
		D := d2m2*d2b2 - d2mb*d2mb
		ia := d2b2 / D
		ib := -d2mb / D
		id := d2m2 / D
		m := m0 - (ia*dldm + ib*dldb)
		b := b0 - (ib*dldm + id*dldb)
		its++
		var done bool
		switch variant {
		case 0:
			done = math.Abs(m-m0) < tol*math.Abs(m0) && math.Abs(b-b0) < tol*math.Abs(b0)
		case 1:
			done = math.Abs(m-m0) < tol && math.Abs(b-b0) < tol
		case 2:
			done = math.Abs((m-m0)/m0) < tol && math.Abs((b-b0)/b0) < tol
		}
		m0, b0 = m, b
		if done || its > maxits {
			return m, b, its
		}
	}
}

