{"command":"cd /workspace/src && cat > verbs_stats2.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"os"
	"sort"
	"strings"
	"unicode/utf8"
)

func init() {
	initVerbsList = append(initVerbsList, func() {
		registerVerb("stats2", parseStats2)
		registerVerb("summary", parseSummary)
		registerVerb("surv", parseSurv)
	})
}

// ---------------------------------------------------------------- stats2
type bivarAcc struct {
	n                                int64
	sumx, sumy, sumxy, sumx2, sumy2 float64
	xs, ys                           []float64
}

type Stats2T struct {
	accs      []string
	pairs     [][2]string
	groupBy   []string
	verbose   bool
	iterative bool
	fit       bool
	groups    *lhmsi
	recs      []recctx
}

type stats2Group struct {
	groupVals *Mlrmap
	accs      map[string]*bivarAcc
}

func parseStats2(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("stats2", args, i)
	t := &Stats2T{groups: newLhm()}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-a":
			t.accs = va.list(f)
		case "-f":
			l := va.list(f)
			if len(l)%2 != 0 {
				fmt.Fprintf(os.Stderr, "mlr stats2: argument to -f must have even number of fields.\n")
				os.Exit(1)
			}
			for j := 0; j < len(l); j += 2 {
				t.pairs = append(t.pairs, [2]string{l[j], l[j+1]})
			}
		case "-g":
			t.groupBy = va.list(f)
		case "-v":
			t.verbose = true
		case "-s":
			t.iterative = true
		case "--fit":
			t.fit = true
		default:
			va.unrecognized(f)
		}
	}
	if t.accs == nil || t.pairs == nil {
		fmt.Fprintf(os.Stderr, "mlr stats2: -a and -f are both required.\n")
		os.Exit(1)
	}
	for _, a := range t.accs {
		switch a {
		case "linreg-ols", "linreg-pca", "r2", "logireg", "corr", "cov", "covx":
		default:
			fmt.Fprintf(os.Stderr, "mlr stats2: accumulator \"%s\" not found.\n", a)
			os.Exit(1)
		}
	}
	return t, va.i
}

func (t *Stats2T) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	key := ""
	if t.groupBy != nil {
		k, ok := groupingKey(rec, t.groupBy)
		if !ok {
			return
		}
		key = k
	}
	gv, ok := t.groups.get(key)
	var g *stats2Group
	if !ok {
		g = &stats2Group{groupVals: NewMlrmap(), accs: map[string]*bivarAcc{}}
		for _, f := range t.groupBy {
			g.groupVals.PutNew(f, rec.Get(f))
		}
		t.groups.put(key, g)
	} else {
		g = gv.(*stats2Group)
	}
	if t.fit {
		t.recs = append(t.recs, recctx{rec, *ctx})
	}
	for _, p := range t.pairs {
		xv := rec.Get(p[0])
		yv := rec.Get(p[1])
		if xv == nil || yv == nil || xv.IsVoid() || yv.IsVoid() {
			continue
		}
		if !xv.IsNumeric() || !yv.IsNumeric() {
			continue
		}
		pk := p[0] + "_" + p[1]
		a := g.accs[pk]
		if a == nil {
			a = &bivarAcc{}
			g.accs[pk] = a
		}
		x := xv.GetNumericToFloat()
		y := yv.GetNumericToFloat()
		a.n++
		a.sumx += x
		a.sumy += y
		a.sumxy += x * y
		a.sumx2 += x * x
		a.sumy2 += y * y
		for _, acc := range t.accs {
			if acc == "logireg" {
				a.xs = append(a.xs, x)
				a.ys = append(a.ys, y)
				break
			}
		}
	}
	if t.iterative && !t.fit {
		out := rec.Copy()
		t.emitStats(out, g)
		next.Put(out, ctx)
	}
}

func olsFit(a *bivarAcc) (float64, float64) {
	n := float64(a.n)
	d := n*a.sumx2 - a.sumx*a.sumx
	m := (n*a.sumxy - a.sumx*a.sumy) / d
	b := (-a.sumx*a.sumxy + a.sumx2*a.sumy) / d
	return m, b
}

type pcaResult struct {
	m, b, quality      float64
	l1, l2             float64
	v1x, v1y, v2x, v2y float64
}

func pcaFit(a *bivarAcc) pcaResult {
	n := float64(a.n)
	varx := (a.sumx2 - a.sumx*a.sumx/n) / (n - 1)
	vary := (a.sumy2 - a.sumy*a.sumy/n) / (n - 1)
	cov := (a.sumxy - a.sumx*a.sumy/n) / (n - 1)
	a11, a12, a22 := varx, cov, vary
	var c, s float64
	if a12 == 0 {
		c, s = 1, 0
	} else {
		theta := (a22 - a11) / (2 * a12)
		t := 1.0 / (math.Abs(theta) + math.Sqrt(theta*theta+1))
		if theta < 0 {
			t = -t
		}
		c = 1 / math.Sqrt(t*t+1)
		s = t * c
	}
	av11 := a11*c + a12*(-s)
	av12 := a11*s + a12*c
	av21 := a12*c + a22*(-s)
	av22 := a12*s + a22*c
	d11 := c*av11 + (-s)*av21
	d22 := s*av12 + c*av22
	// eigenvectors: column1 = (c, -s) for d11; column2 = (s, c) for d22
	var r pcaResult
	if d22 >= d11 {
		r.l1, r.l2 = d22, d11
		r.v1x, r.v1y = s, c
		r.v2x, r.v2y = c, -s
	} else {
		r.l1, r.l2 = d11, d22
		r.v1x, r.v1y = c, -s
		r.v2x, r.v2y = s, c
	}
	xbar := a.sumx / n
	ybar := a.sumy / n
	r.m = r.v1y / r.v1x
	r.b = ybar - r.m*xbar
	if r.l1 == 0 {
		r.quality = 0
	} else {
		r.quality = 1 - r.l2/r.l1
	}
	return r
}

func logiregFit(a *bivarAcc) (float64, float64) {
	m0 := -0.001
	b0 := 0.002
	var dldm, dldb, d2m2, d2mb, d2b2 float64
	for i := range a.xs {
		x, y := a.xs[i], a.ys[i]
		p := 1.0 / (1.0 + math.Exp(-m0*x-b0))
		dldm += (y - p) * x
		dldb += y - p
		q := p * (1 - p)
		d2m2 -= x * x * q
		d2mb -= x * q
		d2b2 -= q
	}
	D := d2m2*d2b2 - d2mb*d2mb
	m := m0 - (d2b2*dldm-d2mb*dldb)/D
	b := b0 - (-d2mb*dldm+d2m2*dldb)/D
	return m, b
}

func (t *Stats2T) emitStats(out *Mlrmap, g *stats2Group) {
	for _, p := range t.pairs {
		pk := p[0] + "_" + p[1]
		a := g.accs[pk]
		if a == nil {
			continue
		}
		n := float64(a.n)
		for _, acc := range t.accs {
			switch acc {
			case "linreg-ols":
				if a.n < 2 {
					out.Put(pk+"_ols_m", VOID)
					out.Put(pk+"_ols_b", VOID)
				} else {
					m, b := olsFit(a)
					out.Put(pk+"_ols_m", MlrvalFromFloat(m))
					out.Put(pk+"_ols_b", MlrvalFromFloat(b))
				}
				out.Put(pk+"_ols_n", MlrvalFromInt(a.n))
			case "r2":
				if a.n < 2 {
					out.Put(pk+"_r2", VOID)
				} else {
					q := n*a.sumxy - a.sumx*a.sumy
					num := q * q
					den := (n*a.sumx2 - a.sumx*a.sumx) * (n*a.sumy2 - a.sumy*a.sumy)
					out.Put(pk+"_r2", MlrvalFromFloat(num/den))
				}
			case "corr":
				if a.n < 2 {
					out.Put(pk+"_corr", VOID)
				} else {
					mx := a.sumx / n
					my := a.sumy / n
					sigx := math.Sqrt((a.sumx2 - mx*(2.0*a.sumx-n*mx)) / (n - 1))
					sigy := math.Sqrt((a.sumy2 - my*(2.0*a.sumy-n*my)) / (n - 1))
					cov := (a.sumxy - mx*a.sumy) / (n - 1)
					out.Put(pk+"_corr", MlrvalFromFloat(cov/(sigx*sigy)))
				}
			case "cov":
				if a.n < 2 {
					out.Put(pk+"_cov", VOID)
				} else {
					mx := a.sumx / n
					out.Put(pk+"_cov", MlrvalFromFloat((a.sumxy-mx*a.sumy)/(n-1)))
				}
			case "covx":
				x, y := p[0], p[1]
				if a.n < 2 {
					out.Put(x+"_"+x+"_covx", VOID)
					out.Put(x+"_"+y+"_covx", VOID)
					out.Put(y+"_"+x+"_covx", VOID)
					out.Put(y+"_"+y+"_covx", VOID)
				} else {
					vx := (a.sumx2 - a.sumx*a.sumx/n) / (n - 1)
					vy := (a.sumy2 - a.sumy*a.sumy/n) / (n - 1)
					cxy := (a.sumxy - a.sumx*a.sumy/n) / (n - 1)
					out.Put(x+"_"+x+"_covx", MlrvalFromFloat(vx))
					out.Put(x+"_"+y+"_covx", MlrvalFromFloat(cxy))
					out.Put(y+"_"+x+"_covx", MlrvalFromFloat(cxy))
					out.Put(y+"_"+y+"_covx", MlrvalFromFloat(vy))
				}
			case "linreg-pca":
				if a.n < 2 {
					out.Put(pk+"_pca_m", VOID)
					out.Put(pk+"_pca_b", VOID)
					out.Put(pk+"_pca_n", MlrvalFromInt(a.n))
					out.Put(pk+"_pca_quality", VOID)
				} else {
					r := pcaFit(a)
					out.Put(pk+"_pca_m", MlrvalFromFloat(r.m))
					out.Put(pk+"_pca_b", MlrvalFromFloat(r.b))
					out.Put(pk+"_pca_n", MlrvalFromInt(a.n))
					out.Put(pk+"_pca_quality", MlrvalFromFloat(r.quality))
					if t.verbose {
						out.Put(pk+"_pca_eival1", MlrvalFromFloat(r.l1))
						out.Put(pk+"_pca_eival2", MlrvalFromFloat(r.l2))
						out.Put(pk+"_pca_eivec11", MlrvalFromFloat(r.v1x))
						out.Put(pk+"_pca_eivec12", MlrvalFromFloat(r.v1y))
						out.Put(pk+"_pca_eivec21", MlrvalFromFloat(r.v2x))
						out.Put(pk+"_pca_eivec22", MlrvalFromFloat(r.v2y))
					}
				}
			case "logireg":
				if a.n < 2 {
					out.Put(pk+"_logistic_m", VOID)
					out.Put(pk+"_logistic_b", VOID)
				} else {
					m, b := logiregFit(a)
					out.Put(pk+"_logistic_m", MlrvalFromFloat(m))
					out.Put(pk+"_logistic_b", MlrvalFromFloat(b))
				}
				out.Put(pk+"_logistic_n", MlrvalFromInt(a.n))
			}
		}
	}
}

func (t *Stats2T) End(ctx *Context, next *ChainLink) {
	if t.fit {
		for _, rc := range t.recs {
			rec := rc.rec
			key := ""
			if t.groupBy != nil {
				k, ok := groupingKey(rec, t.groupBy)
				if !ok {
					continue
				}
				key = k
			}
			gv, ok := t.groups.get(key)
			if !ok {
				continue
			}
			g := gv.(*stats2Group)
			for _, p := range t.pairs {
				pk := p[0] + "_" + p[1]
				a := g.accs[pk]
				if a == nil {
					continue
				}
				xv := rec.Get(p[0])
				if xv == nil || !xv.IsNumeric() {
					continue
				}
				x := xv.GetNumericToFloat()
				for _, acc := range t.accs {
					switch acc {
					case "linreg-ols":
						m, b := olsFit(a)
						rec.Put(pk+"_ols_fit", MlrvalFromFloat(m*x+b))
					case "linreg-pca":
						r := pcaFit(a)
						rec.Put(pk+"_pca_fit", MlrvalFromFloat(r.m*x+r.b))
					case "logireg":
						m, b := logiregFit(a)
						rec.Put(pk+"_logistic_fit", MlrvalFromFloat(1.0/(1.0+math.Exp(-m*x-b))))
					}
				}
			}
			c := rc.ctx
			next.Put(rec, &c)
		}
		return
	}
	if t.iterative {
		return
	}
	for _, k := range t.groups.keys {
		gv, _ := t.groups.get(k)
		g := gv.(*stats2Group)
		out := g.groupVals.Copy()
		t.emitStats(out, g)
		next.Put(out, ctx)
	}
}

// ---------------------------------------------------------------- summary
var allSummarizers = []string{"field_type", "count", "null_count", "distinct_count", "mode", "sum", "mean", "stddev", "var", "skewness",
	"minlen", "maxlen", "min", "p25", "median", "p75", "max", "iqr", "lof", "lif", "uif", "uof"}
var defaultSummarizers = map[string]bool{"field_type": true, "count": true, "mean": true, "min": true, "max": true, "null_count": true, "distinct_count": true}

type summaryField struct {
	types      []string
	typeSeen   map[string]bool
	count      int64
	nullCount  int64
	distinct   map[string]int64
	order      []string
	numCount   int64
	sum        *Mlrval
	sumf, sumx2, sumx3 float64
	minlen, maxlen int64
	haveLen    bool
	min, max   *Mlrval
	values     []*Mlrval
}

type SummaryT struct {
	selected  map[string]bool
	transpose bool
	fields    *lhmsi
}

func parseSummary(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("summary", args, i)
	t := &SummaryT{fields: newLhm(), selected: defaultSummarizers}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-a":
			t.selected = stringSet(va.list(f))
		case "-x":
			ex := stringSet(va.list(f))
			t.selected = map[string]bool{}
			for _, s := range allSummarizers {
				if !ex[s] {
					t.selected[s] = true
				}
			}
		case "--all":
			t.selected = stringSet(allSummarizers)
		case "--transpose":
			t.transpose = true
		default:
			va.unrecognized(f)
		}
	}
	return t, va.i
}

func summaryTypeName(v *Mlrval) string {
	return typeName(v)
}

func (t *SummaryT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	for i, k := range rec.keys {
		v := rec.vals[i]
		fv, ok := t.fields.get(k)
		var sf *summaryField
		if !ok {
			sf = &summaryField{typeSeen: map[string]bool{}, distinct: map[string]int64{}, sum: MlrvalFromInt(0)}
			t.fields.put(k, sf)
		} else {
			sf = fv.(*summaryField)
		}
		tn := summaryTypeName(v)
		if !sf.typeSeen[tn] {
			sf.typeSeen[tn] = true
			sf.types = append(sf.types, tn)
		}
		sf.count++
		if v.Type() == MT_VOID {
			sf.nullCount++
		}
		s := v.String()
		if _, ok := sf.distinct[s]; !ok {
			sf.order = append(sf.order, s)
		}
		sf.distinct[s]++
		l := int64(utf8.RuneCountInString(s))
		if !sf.haveLen {
			sf.minlen, sf.maxlen = l, l
			sf.haveLen = true
		} else {
			if l < sf.minlen {
				sf.minlen = l
			}
			if l > sf.maxlen {
				sf.maxlen = l
			}
		}
		if v.Type() == MT_VOID {
			continue
		}
		if sf.min == nil {
			sf.min, sf.max = v, v
		} else {
			sf.min = minMax2(sf.min, v, false)
			sf.max = minMax2(sf.max, v, true)
		}
		sf.values = append(sf.values, v)
		if v.IsNumeric() {
			sf.numCount++
			sf.sum = BinaryPlus(sf.sum, v)
			x := v.GetNumericToFloat()
			sf.sumf += x
			sf.sumx2 += x * x
			sf.sumx3 += x * x * x
		}
	}
}

func (t *SummaryT) compute(sf *summaryField) *Mlrmap {
	out := NewMlrmap()
	sorted := make([]*Mlrval, len(sf.values))
	copy(sorted, sf.values)
	sort.SliceStable(sorted, func(i, j int) bool { return collateCompare(sorted[i], sorted[j]) < 0 })
	pct := func(p float64) *Mlrval {
		if len(sorted) == 0 {
			return VOID
		}
		return percentileOfSorted(sorted, p, false)
	}
	numeric := func(v *Mlrval) bool { return v != nil && v.IsNumeric() }
	p25 := pct(25)
	p75 := pct(75)
	var iqr *Mlrval
	if numeric(p25) && numeric(p75) {
		iqr = BinaryMinus(p75, p25)
	}
	for _, s := range allSummarizers {
		if !t.selected[s] {
			continue
		}
		var v *Mlrval
		switch s {
		case "field_type":
			v = MlrvalFromString(strings.Join(sf.types, "-"))
		case "count":
			v = MlrvalFromInt(sf.count)
		case "null_count":
			v = MlrvalFromInt(sf.nullCount)
		case "distinct_count":
			v = MlrvalFromInt(int64(len(sf.order)))
		case "mode":
			if len(sf.order) == 0 {
				v = VOID
			} else {
				best := sf.order[0]
				for _, o := range sf.order[1:] {
					if sf.distinct[o] > sf.distinct[best] {
						best = o
					}
				}
				v = MlrvalFromInferred(best)
			}
		case "sum":
			v = sf.sum
		case "mean":
			if sf.numCount == 0 {
				v = VOID
			} else {
				v = BinaryDivide(sf.sum, MlrvalFromInt(sf.numCount))
			}
		case "stddev":
			v = varianceFromSums("stddev", sf.numCount, sf.sumf, sf.sumx2, sf.sumx3, 0)
		case "var":
			v = varianceFromSums("var", sf.numCount, sf.sumf, sf.sumx2, sf.sumx3, 0)
		case "skewness":
			v = varianceFromSums("skewness", sf.numCount, sf.sumf, sf.sumx2, sf.sumx3, 0)
		case "minlen":
			v = MlrvalFromInt(sf.minlen)
		case "maxlen":
			v = MlrvalFromInt(sf.maxlen)
		case "min":
			if sf.min == nil {
				v = VOID
			} else {
				v = sf.min
			}
		case "max":
			if sf.max == nil {
				v = VOID
			} else {
				v = sf.max
			}
		case "p25":
			v = p25
		case "median":
			v = pct(50)
		case "p75":
			v = p75
		case "iqr":
			if iqr == nil {
				v = VOID
			} else {
				v = iqr
			}
		case "lof":
			if iqr == nil {
				v = VOID
			} else {
				v = BinaryMinus(p25, BinaryTimes(MlrvalFromFloat(3.0), iqr))
			}
		case "lif":
			if iqr == nil {
				v = VOID
			} else {
				v = BinaryMinus(p25, BinaryTimes(MlrvalFromFloat(1.5), iqr))
			}
		case "uif":
			if iqr == nil {
				v = VOID
			} else {
				v = BinaryPlus(p75, BinaryTimes(MlrvalFromFloat(1.5), iqr))
			}
		case "uof":
			if iqr == nil {
				v = VOID
			} else {
				v = BinaryPlus(p75, BinaryTimes(MlrvalFromFloat(3.0), iqr))
			}
		}
		out.PutNew(s, v)
	}
	return out
}

func (t *SummaryT) End(ctx *Context, next *ChainLink) {
	if !t.transpose {
		for _, k := range t.fields.keys {
			fv, _ := t.fields.get(k)
			stats := t.compute(fv.(*summaryField))
			out := NewMlrmap()
			out.PutNew("field_name", MlrvalFromString(k))
			for i, sk := range stats.keys {
				out.PutNew(sk, stats.vals[i])
			}
			next.Put(out, ctx)
		}
		return
	}
	var all []*Mlrmap
	for _, k := range t.fields.keys {
		fv, _ := t.fields.get(k)
		all = append(all, t.compute(fv.(*summaryField)))
	}
	header := NewMlrmap()
	header.PutNew("field_name", MlrvalFromString("field_name"))
	for _, s := range allSummarizers {
		if !t.selected[s] {
			continue
		}
		out := NewMlrmap()
		out.PutNew("field_name", MlrvalFromString(s))
		for j, k := range t.fields.keys {
			out.PutNew(k, all[j].Get(s))
		}
		next.Put(out, ctx)
	}
}

// ---------------------------------------------------------------- surv
type SurvT struct {
	durField, statusField string
	times                 []float64
	timeVals              []*Mlrval
	statuses              []bool
}

func parseSurv(args []string, i int, opts *Options) (Transformer, int) {
	va := newVargs("surv", args, i)
	t := &SurvT{}
	for va.hasFlag() {
		f := va.next()
		va.checkHelp(f)
		switch f {
		case "-d":
			t.durField = va.str(f)
		case "-s":
			t.statusField = va.str(f)
		default:
			va.unrecognized(f)
		}
	}
	if t.durField == "" || t.statusField == "" {
		fmt.Fprint(os.Stderr, verbUsage("surv"))
		os.Exit(1)
	}
	return t, va.i
}
func (t *SurvT) Process(rec *Mlrmap, ctx *Context, next *ChainLink) {
	d := rec.Get(t.durField)
	s := rec.Get(t.statusField)
	if d == nil || s == nil || !d.IsNumeric() {
		return
	}
	t.times = append(t.times, d.GetNumericToFloat())
	t.timeVals = append(t.timeVals, d)
	t.statuses = append(t.statuses, s.GetNumericToFloat() != 0)
}
func (t *SurvT) End(ctx *Context, next *ChainLink) {
	n := len(t.times)
	idx := make([]int, n)
	for i := range idx {
		idx[i] = i
	}
	sort.SliceStable(idx, func(a, b int) bool { return t.times[idx[a]] < t.times[idx[b]] })
	surv := 1.0
	atRisk := n
	i := 0
	for i < n {
		tm := t.times[idx[i]]
		tv := t.timeVals[idx[i]]
		d := 0
		c := 0
		for i < n && t.times[idx[i]] == tm {
			if t.statuses[idx[i]] {
				d++
			} else {
				c++
			}
			i++
		}
		if d > 0 {
			surv = surv * (1 - float64(d)/float64(atRisk))
			out := NewMlrmap()
			out.PutNew("time", tv)
			out.PutNew("survival", MlrvalFromFloat(surv))
			next.Put(out, ctx)
		}
		atRisk -= d + c
	}
}
