//go:embed helpdata/*.txt
var helpFS embed.FS

func helpFile(name string) (string, bool) {
	data, err := helpFS.ReadFile("helpdata/" + name + ".txt")
	if err != nil {
		return "", false
	}
	return string(data), true
}

func parseHelpEntries(name, marker string) (map[string]string, []string) {
	data, _ := helpFile(name)
	m := map[string]string{}
	var order []string
	parts := strings.Split(data, marker)
	for _, p := range parts {
		if p == "" {
			continue
		}
		nl := strings.Index(p, "\n")
		if nl < 0 {
			continue
		}
		key := p[:nl]
		m[key] = p[nl+1:]
		order = append(order, key)
	}
	return m, order
}

var funcHelp map[string]string
var funcOrder []string
var kwHelp map[string]string
var kwOrder []string
var flagHelp map[string]string
var flagSearch map[string]string

func loadHelpTables() {
	if funcHelp != nil {
		return
	}
	funcHelp, funcOrder = parseHelpEntries("functions-help", "@@@@FUNC ")
	kwHelp, kwOrder = parseHelpEntries("keywords-help", "@@@@KW ")
	flagHelp, _ = parseHelpEntries("flag-help", "@@@@FLAG ")
	flagSearch, _ = parseHelpEntries("flag-search", "@@@@FLAG ")
}

var helpTopicFiles = map[string]string{
	"topics": "topics", "basic-examples": "basic-examples", "file-formats": "file-formats", "flags": "flags",
	"list-separator-aliases": "list-separator-aliases", "list-separator-regex-aliases": "list-separator-regex-aliases",
	"comments-in-data-flags": "comments-in-data-flags", "compressed-data-flags": "compressed-data-flags",
	"csv/tsv-only-flags": "csv_tsv-only-flags", "dkvp-only-flags": "dkvp-only-flags", "file-format-flags": "file-format-flags",
	"flatten-unflatten-flags": "flatten-unflatten-flags", "format-conversion-keystroke-saver-flags": "format-conversion-keystroke-saver-flags",
	"json-only-flags": "json-only-flags", "legacy-flags": "legacy-flags", "miscellaneous-flags": "miscellaneous-flags",
	"output-colorization-flags": "output-colorization-flags", "pprint-only-flags": "pprint-only-flags",
	"profiling-flags": "profiling-flags", "separator-flags": "separator-flags", "list-verbs": "list-verbs",
	"usage-verbs": "usage-verbs", "list-functions": "list-functions", "list-function-classes": "list-function-classes",
	"usage-functions": "usage-functions", "usage-functions-by-class": "usage-functions-by-class",
	"list-keywords": "list-keywords", "usage-keywords": "usage-keywords", "auxents": "auxents", "terminals": "terminals",
	"mlrrc": "mlrrc", "output-colorization": "output-colorization", "type-arithmetic-info": "type-arithmetic-info",
	"type-arithmetic-info-extended": "type-arithmetic-info-extended", "list-verbs-as-paragraph": "list-verbs-as-paragraph",
	"list-functions-as-paragraph": "list-functions-as-paragraph", "list-keywords-as-paragraph": "list-keywords-as-paragraph",
}

func printVerbHelpWithName(name string) bool {
	loadVerbUsages()
	u, ok := verbUsages[name]
	if !ok {
		return false
	}
	fmt.Print(name + "\n" + u)
	return true
}

func helpMain(args []string) {
	loadHelpTables()
	if len(args) == 0 {
		mainUsageShort(os.Stdout)
		return
	}
	cmd := args[0]
	rest := args[1:]
	if f, ok := helpTopicFiles[cmd]; ok {
		s, _ := helpFile(f)
		fmt.Print(s)
		return
	}
	switch cmd {
	case "verb":
		if len(rest) == 0 {
			fmt.Println("mlr help verb takes at least one required argument.")
			return
		}
		for _, v := range rest {
			if !printVerbHelpWithName(v) {
				fmt.Printf("mlr: verb \"%s\" not found. Please use \"mlr help list-verbs\" for a list.\n", v)
			}
		}
		return
	case "function":
		if len(rest) == 0 {
			fmt.Println("mlr help function takes at least one required argument.")
			return
		}
		for _, f := range rest {
			if h, ok := funcHelp[f]; ok {
				fmt.Print(h)
			} else {
				fmt.Printf("Function \"%s\" not found.\n", f)
			}
		}
		return
	case "keyword":
		if len(rest) == 0 {
			fmt.Println("mlr help keyword takes at least one required argument.")
			return
		}
		for _, k := range rest {
			if h, ok := kwHelp[k]; ok {
				fmt.Print(h)
			} else {
				fmt.Printf("mlr: unrecognized keyword \"%s\".\n", k)
			}
		}
		return
	case "flag":
		for _, f := range rest {
			if h, ok := flagHelp[f]; ok {
				fmt.Print(h)
			} else {
				fmt.Printf("%s:\nNot found.\n", f)
			}
		}
		return
	case "list-functions-in-class":
		for _, c := range rest {
			for _, fn := range funcOrder {
				h := funcHelp[fn]
				if strings.Contains(firstLine(h), "(class="+c+" ") {
					fmt.Println(fn)
				}
			}
		}
		return
	case "find":
		for _, term := range rest {
			helpFind(term)
		}
		return
	}
	for _, term := range args {
		found := false
		if printVerbHelpWithName(term) {
			found = true
		}
		if h, ok := funcHelp[term]; ok {
			fmt.Print(h)
			found = true
		}
		if h, ok := kwHelp[term]; ok {
			fmt.Print(h)
			found = true
		}
		if h, ok := flagSearch[term]; ok {
			fmt.Print(h)
			found = true
		}
		if !found {
			fmt.Printf("No help found for \"%s\". Please try 'mlr help find %s' for approximate match.\n", term, term)
			fmt.Printf("See also 'mlr help topics'.\n")
		}
	}
}

func firstLine(s string) string {
	if i := strings.Index(s, "\n"); i >= 0 {
		return s[:i]
	}
	return s
}

func helpFind(term string) {
	loadVerbUsages()
	found := false
	for _, v := range verbOrder {
