	"json-only-flags": "json-only-flags", "legacy-flags": "legacy-flags", "miscellaneous-flags": "miscellaneous-flags",
	"output-colorization-flags": "output-colorization-flags", "pprint-only-flags": "pprint-only-flags",
	"profiling-flags": "profiling-flags", "separator-flags": "separator-flags", "list-verbs": "list-verbs",
	"usage-verbs": "usage-verbs", "list-functions": "list-functions", "list-function-classes": "list-function-classes",
	"usage-functions": "usage-functions", "usage-functions-by-class": "usage-functions-by-class",
	"list-keywords": "list-keywords", "usage-keywords": "usage-keywords", "auxents": "auxents", "terminals": "terminals",
	"mlrrc": "mlrrc", "output-colorization": "output-colorization", "type-arithmetic-info": "type-arithmetic-info",
	"type-arithmetic-info-extended": "type-arithmetic-info-extended", "list-verbs-as-paragraph": "list-verbs-as-paragraph",
	"list-functions-as-paragraph": "list-functions-as-paragraph", "list-keywords-as-paragraph": "list-keywords-as-paragraph",
}

func printVerbHelpWithName(name string) bool {
	loadVerbUsages()
	u, ok := verbUsages[name]
	if !ok {
		return false
	}
	fmt.Print(name + "\n" + u)
	return true
}

func helpMain(args []string) {
	loadHelpTables()
	if len(args) == 0 {
		mainUsageShort(os.Stdout)
		return
	}
	cmd := args[0]
	rest := args[1:]
	if f, ok := helpTopicFiles[cmd]; ok {
		s, _ := helpFile(f)
		fmt.Print(s)
		return
	}
	switch cmd {
	case "verb":
		if len(rest) == 0 {
			fmt.Println("mlr help verb takes at least one required argument.")
			return
		}
		for _, v := range rest {
			if !printVerbHelpWithName(v) {
				fmt.Printf("mlr: verb \"%s\" not found. Please use \"mlr help list-verbs\" for a list.\n", v)
			}
		}
		return
	case "function":
		if len(rest) == 0 {
			fmt.Println("mlr help function takes at least one required argument.")
			return
		}
		for _, f := range rest {
			if h, ok := funcHelp[f]; ok {
				fmt.Print(h)
			} else {
				fmt.Printf("Function \"%s\" not found.\n", f)
			}
		}
		return
	case "keyword":
		if len(rest) == 0 {
			fmt.Println("mlr help keyword takes at least one required argument.")
			return
		}
		for _, k := range rest {
			if h, ok := kwHelp[k]; ok {
				fmt.Print(h)
			} else {
				fmt.Printf("mlr: unrecognized keyword \"%s\".\n", k)
			}
		}
		return
	case "flag":
		for _, f := range rest {
			if h, ok := flagHelp[f]; ok {
				fmt.Print(h)
			} else {
				fmt.Printf("%s:\nNot found.\n", f)
			}
		}
		return
	case "list-functions-in-class":
		for _, c := range rest {
			for _, fn := range funcOrder {
				h := funcHelp[fn]
				if strings.Contains(firstLine(h), "(class="+c+" ") {
					fmt.Println(fn)
				}
			}
		}
		return
	case "find":
		for _, term := range rest {
			helpFind(term)
		}
		return
	}
	for _, term := range args {
		found := false
		if printVerbHelpWithName(term) {
			found = true
		}
		if h, ok := funcHelp[term]; ok {
			fmt.Print(h)
			found = true
		}
		if h, ok := kwHelp[term]; ok {
			fmt.Print(h)
			found = true
		}
		if h, ok := flagSearch[term]; ok {
			fmt.Print(h)
			found = true
		}
		if !found {
			fmt.Printf("No help found for \"%s\". Please try 'mlr help find %s' for approximate match.\n", term, term)
			fmt.Printf("See also 'mlr help topics'.\n")
		}
	}
}

func firstLine(s string) string {
	if i := strings.Index(s, "\n"); i >= 0 {
		return s[:i]
	}
	return s
}

func helpFind(term string) {
	loadVerbUsages()
	found := false
	for _, v := range verbOrder {
		if strings.Contains(v, term) {
			printVerbHelpWithName(v)
			found = true
		}
	}
	for _, f := range funcOrder {
		if strings.Contains(f, term) {
			fmt.Print(funcHelp[f])
			found = true
		}
	}
	for _, k := range kwOrder {
		if strings.Contains(k, term) {
			fmt.Print(kwHelp[k])
			found = true
		}
	}
	if !found {
		fmt.Printf("No help found for \"%s\".\n", term)
	}
}

// Handles `mlr help ...`, `mlr version`, `mlr -l` etc. Returns true if handled.
func maybeAuxent(args []string) bool {
	if len(args) < 2 {
		return false
	}
