		return true
	case "-F":
		helpMain([]string{"usage-functions"})
		return true
	case "-k":
		helpMain([]string{"list-keywords"})
		return true
	case "-K":
		helpMain([]string{"usage-keywords"})
		return true
	case "-g":
		helpMain([]string{"flags"})
		return true
	}
	return false
}
